/* Parameter list handling */
#include "proj.h"
#include <stdarg.h>
#include <limits.h>

char *pj_strdup(const char *s) {
    size_t n = strlen(s) + 1;
    char *r = (char *)malloc(n);
    if (r) memcpy(r, s, n);
    return r;
}

paralist *pj_mkparam(const char *str) {
    paralist *newitem;
    if (*str == '+') ++str;
    newitem = (paralist *)malloc(sizeof(paralist) + strlen(str));
    if (!newitem) return NULL;
    newitem->used = 0;
    newitem->next = NULL;
    strcpy(newitem->param, str);
    return newitem;
}

/* find a parameter by key name */
paralist *pj_get_param(paralist *list, const char *name) {
    size_t l = strlen(name);
    for (; list; list = list->next) {
        if (!strncmp(list->param, name, l) &&
            (list->param[l] == '\0' || list->param[l] == '='))
            return list;
    }
    return NULL;
}

int pj_param_exists(paralist *list, const char *name) {
    return pj_get_param(list, name) != NULL;
}

const char *pj_param_value(paralist *list) {
    const char *p;
    if (!list) return NULL;
    p = strchr(list->param, '=');
    if (p) return p + 1;
