/* DMS <-> radians conversions */
#include "proj.h"

static const char *sym = "NnEeSsWw";
static const double vm[] = {DEG_TO_RAD, .0002908882086657216, .0000048481368110953599};

#define MAX_WORK 64

double dmstor(const char *is, char **rs) {
    int n, nl;
    char *s, work[MAX_WORK];
    const char *p;
    double v, tv;
    int sign;

    if (rs) *rs = (char *)is;
    /* copy string into work space */
    while (isspace((unsigned char)(sign = *is))) ++is;
    n = MAX_WORK;
    s = work;
    while (isgraph((unsigned char)*is) && --n) *s++ = *is++;
    *s = '\0';
    sign = *(s = work);
    if (sign == '+' || sign == '-') s++;
    else sign = '+';
    for (v = 0., nl = 0; nl < 3; nl = n + 1) {
        if (!(isdigit((unsigned char)*s) || *s == '.')) break;
        if ((tv = proj_strtod(s, &s)) == HUGE_VAL) return tv;
        switch (*s) {
        case 'D': case 'd':
            n = 0; break;
        case '\'':
            n = 1; break;
        case '"':
            n = 2; break;
        case 'r': case 'R':
            if (nl) {
                pj_ctx_set_errno(PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
                return HUGE_VAL;
            }
            ++s;
            v = tv;
            goto skip;
        default:
            v += tv * vm[nl];
        skip:
            n = 4;
            continue;
        }
        if (n < nl) {
            pj_ctx_set_errno(PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
            return HUGE_VAL;
        }
        v += tv * vm[n];
        ++s;
    }
    /* postfix sign */
    if (*s && (p = strchr(sym, *s))) {
        sign = (p - sym) >= 4 ? '-' : '+';
        ++s;
    }
    if (sign == '-') v = -v;
    if (rs) /* return point of next char after valid string */
        *rs = (char *)is + (s - work);
    return v;
}

static double RES = 1000., RES60 = 60000., CONV = 3600000.;
static char format[50] = "%dd%d'%.3f\"%c";
static int dolong = 0;

void set_rtodms(int fract, int con_w) {
    int i;
    if (fract >= 0 && fract < 9) {
        RES = 1.;
        for (i = 0; i < fract; ++i) RES *= 10.;
        RES60 = RES * 60.;
        CONV = RES60 * 60.;
        if (!con_w)
            (void)sprintf(format, "%%dd%%d'%%.%df\"%%c", fract);
        else
            (void)sprintf(format, "%%dd%%02d'%%0%d.%df\"%%c", fract + 2 + (fract ? 1 : 0), fract);
        dolong = con_w;
    }
}

