/* Ellipsoid parameter handling */
#include "proj.h"

#define SIXTH .1666666666666666667
#define RA4 .04722222222222222222
#define RA6 .02215608465608465608
#define RV4 .06944444444444444444
#define RV6 .04243827160493827160

int pj_calc_ellipsoid_params(PJ *P, double a, double es) {
    P->a = a;
    P->es = es;
    if (P->e == 0) P->e = sqrt(P->es);
    P->alpha = asin(P->e);
    P->e2 = tan(P->alpha);
    P->e2s = P->e2 * P->e2;
    P->e3 = (0 != P->alpha) ? sin(P->alpha) / sqrt(2 - sin(P->alpha) * sin(P->alpha)) : 0;
    P->e3s = P->e3 * P->e3;
    if (0 == P->f) P->f = 1 - cos(P->alpha);
    P->rf = P->f != 0.0 ? 1.0 / P->f : HUGE_VAL;
    P->f2 = (cos(P->alpha) != 0) ? 1 / cos(P->alpha) - 1 : 0;
    P->rf2 = P->f2 != 0.0 ? 1 / P->f2 : HUGE_VAL;
    P->n = pow(tan(P->alpha / 2), 2);
    P->rn = P->n != 0.0 ? 1 / P->n : HUGE_VAL;
    if (0 == P->b) P->b = (1 - P->f) * P->a;
    P->ra = 1 / P->a;
    P->rb = 1 / P->b;
    P->one_es = 1. - P->es;
    if (P->one_es == 0.) {
        return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    P->rone_es = 1. / P->one_es;
    return 0;
}

static int ellps_size(PJ *P) {
    paralist *par;
    int a_was_set = 0;
    if (P->a != 0) a_was_set = 1;
    par = pj_get_param(P->params, "R");
    if (!par) par = pj_get_param(P->params, "a");
    if (!par) return a_was_set ? 0 : proj_errno_set(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    par->used = 1;
    P->a = pj_atof(pj_param_value(par));
    if (P->a <= 0) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    if (HUGE_VAL == P->a) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    if ('R' == par->param[0]) {
        P->es = P->f = P->e = P->rf = 0;
        P->b = P->a;
    }
    return 0;
}

static int ellps_shape(PJ *P) {
    const char *keys[] = {"rf", "f", "es", "e", "b"};
    size_t len = 5, i;
    paralist *par = NULL;
    for (i = 0; i < len; i++) {
        par = pj_get_param(P->params, keys[i]);
        if (par) break;
    }
    if (i == len) return 0;
    P->es = P->f = P->b = P->e = P->rf = 0;
    par->used = 1;
    switch (i) {
    case 0:
        P->rf = pj_atof(pj_param_value(par));
        if (HUGE_VAL == P->rf) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        if (0 == P->rf) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        P->f = 1 / P->rf;
        P->es = 2 * P->f - P->f * P->f;
        break;
    case 1:
        P->f = pj_atof(pj_param_value(par));
        if (HUGE_VAL == P->f) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        P->rf = P->f != 0.0 ? 1.0 / P->f : HUGE_VAL;
        P->es = 2 * P->f - P->f * P->f;
        break;
    case 2:
        P->es = pj_atof(pj_param_value(par));
        if (HUGE_VAL == P->es) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        if (P->es >= 1) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        break;
    case 3:
        P->e = pj_atof(pj_param_value(par));
        if (HUGE_VAL == P->e) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        if (P->e < 0 || P->e >= 1) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        P->es = P->e * P->e;
        break;
    case 4:
        P->b = pj_atof(pj_param_value(par));
        if (HUGE_VAL == P->b) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        if (P->b <= 0) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        if (P->b == P->a) break;
        P->f = (P->a - P->b) / P->a;
        P->es = 2 * P->f - P->f * P->f;
        break;
    }
    if (P->es < 0) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    return 0;
}

static int ellps_ellps(PJ *P) {
    const PJ_ELLPS *ellps;
    paralist *par;
    const char *name;
    paralist *new_params, *old_params;
    int err;

    par = pj_get_param(P->params, "ellps");
    if (!par) return 0;
    if (strlen(par->param) < 7) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    name = par->param + 6;
    for (ellps = pj_ellps; ellps->id; ++ellps)
        if (!strcmp(ellps->id, name)) break;
    if (!ellps->id) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);

    err = proj_errno_reset(P);
    new_params = pj_mkparam(ellps->major);
    new_params->next = pj_mkparam(ellps->ell);
    old_params = P->params;
    P->params = new_params;
    /* reset ellipsoid definition */
    P->a = P->b = P->es = P->e = P->f = P->rf = 0;
    ellps_size(P);
    ellps_shape(P);
    P->params = old_params;
    free(new_params->next);
    free(new_params);
    if (proj_errno(P)) return proj_errno(P);
    par->used = 1;
    pj_ctx_set_errno(err);
    P->err = err;
    return 0;
}

static int ellps_spherification(PJ *P) {
    const char *keys[] = {"R_A", "R_V", "R_a", "R_g", "R_h", "R_lat_a", "R_lat_g"};
    size_t len = 7, i;
    paralist *par = NULL;
    double t;
    const char *v;
    char *endp;

    for (i = 0; i < len; i++) {
        par = pj_get_param(P->params, keys[i]);
        if (par) break;
    }
    if (i == len) return 0;
    par->used = 1;
    switch (i) {
    case 0:
        P->a *= 1. - P->es * (SIXTH + P->es * (RA4 + P->es * RA6));
        break;
    case 1:
        P->a *= 1. - P->es * (SIXTH + P->es * (RV4 + P->es * RV6));
        break;
    case 2:
        P->a = (P->a + P->b) / 2;
        break;
    case 3:
        P->a = sqrt(P->a * P->b);
        break;
    case 4:
        if (P->a + P->b == 0) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        P->a = (2 * P->a * P->b) / (P->a + P->b);
        break;
    case 5:
    case 6:
        v = pj_param_value(par);
        t = dmstor(v, &endp);
        if (fabs(t) > M_HALFPI) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        t = sin(t);
        t = 1 - P->es * t * t;
        if (t == 0.) return proj_errno_set(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        if (i == 5)
            P->a *= (1. - P->es + t) / (2 * t * sqrt(t));
        else
            P->a *= sqrt(1 - P->es) / t;
        break;
    }
