    PIN = pj_new();
    PIN->short_name = entry->id;
    PIN->descr = entry->descr;
    PIN->params = start;
    PIN->need_ellps = entry->needs_ellps;

    if (pj_datum_set(start, PIN))
        return pj_default_destructor(PIN, proj_errno(PIN));

    if (pj_ellipsoid(PIN)) {
        proj_log_error_ctx("pj_init_ctx: Must specify ellipsoid or sphere");
        return pj_default_destructor(PIN, proj_errno(PIN));
    }
    PIN->a_orig = PIN->a;
    PIN->es_orig = PIN->es;
    if (pj_calc_ellipsoid_params(PIN, PIN->a, PIN->es))
        return pj_default_destructor(PIN, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);

    PIN->geoc = (PIN->es != 0.0 && pj_param(start, "bgeoc").i);
    PIN->over = pj_param(start, "bover").i;
    (void)pj_param(start, "tgeoidgrids").i;

    PIN->is_long_wrap_set = pj_param(start, "tlon_wrap").i;
    if (PIN->is_long_wrap_set) {
        PIN->long_wrap_center = pj_param(start, "rlon_wrap").f;
        if (!(fabs(PIN->long_wrap_center) < 10 * M_TWOPI)) {
            proj_log_error(PIN, "Invalid value for lon_wrap");
            return pj_default_destructor(PIN, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    }

    if ((s = pj_param(start, "saxis").s) != NULL) {
        const char *axis_legal = "ewnsud";
        if (strlen(s) != 3 || !strchr(axis_legal, s[0]) || !strchr(axis_legal, s[1]) ||
            !strchr(axis_legal, s[2])) {
            proj_log_error(PIN, "Invalid value for axis");
            return pj_default_destructor(PIN, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        strcpy(PIN->axis, s);
        PIN->has_axis = strcmp(s, "enu") != 0;
    }

    PIN->lam0 = pj_param(start, "rlon_0").f;
    PIN->phi0 = pj_param(start, "rlat_0").f;
    if (fabs(PIN->phi0) > M_HALFPI) {
        proj_log_error(PIN, "Invalid value for lat_0: |lat_0| should be <= 90\xc2\xb0");
        return pj_default_destructor(PIN, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    PIN->x0 = pj_param(start, "dx_0").f;
    PIN->y0 = pj_param(start, "dy_0").f;
    PIN->z0 = pj_param(start, "dz_0").f;
    PIN->t0 = pj_param(start, "dt_0").f;

    if (pj_param(start, "tk_0").i)
        PIN->k0 = pj_param(start, "dk_0").f;
    else if (pj_param(start, "tk").i)
        PIN->k0 = pj_param(start, "dk").f;
    else
        PIN->k0 = 1.;
    if (PIN->k0 <= 0.) {
        proj_log_error(PIN, "Invalid value for k/k_0: it should be > 0");
        return pj_default_destructor(PIN, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }

    /* units */
    s = NULL;
    if ((name = pj_param(start, "sunits").s) != NULL) {
        for (i = 0; (s = pj_units[i].id) && strcmp(name, s); ++i) ;
        if (!s) {
            proj_log_error(PIN, "Invalid value for units");
            return pj_default_destructor(PIN, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        s = pj_units[i].to_meter;
    }
    if (s || (s = pj_param(start, "sto_meter").s)) {
        char *end;
        PIN->to_meter = proj_strtod(s, &end);
        s = end;
        if (*s == '/') {
            double denom;
            ++s;
            denom = proj_strtod(s, NULL);
            if (denom == 0.0) {
                proj_log_error(PIN, "Invalid value for to_meter donominator");
                return pj_default_destructor(PIN, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
            }
            PIN->to_meter /= denom;
        }
        if (PIN->to_meter <= 0.0) {
            proj_log_error(PIN, "Invalid value for to_meter");
            return pj_default_destructor(PIN, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        PIN->fr_meter = 1. / PIN->to_meter;
    } else
        PIN->to_meter = PIN->fr_meter = 1.;

    s = NULL;
    if ((name = pj_param(start, "svunits").s) != NULL) {
        for (i = 0; (s = pj_units[i].id) && strcmp(name, s); ++i) ;
        if (!s) {
            proj_log_error(PIN, "Invalid value for vunits");
            return pj_default_destructor(PIN, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        s = pj_units[i].to_meter;
    }
    if (s || (s = pj_param(start, "svto_meter").s)) {
        char *end;
        PIN->vto_meter = proj_strtod(s, &end);
        s = end;
        if (*s == '/') {
            double denom;
            ++s;
            denom = proj_strtod(s, NULL);
            if (denom == 0.0) {
                proj_log_error(PIN, "Invalid value for vto_meter donominator");
                return pj_default_destructor(PIN, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
            }
            PIN->vto_meter /= denom;
        }
        if (PIN->vto_meter <= 0.0) {
            proj_log_error(PIN, "Invalid value for vto_meter");
            return pj_default_destructor(PIN, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        PIN->vfr_meter = 1. / PIN->vto_meter;
    } else {
        PIN->vto_meter = PIN->to_meter;
        PIN->vfr_meter = PIN->fr_meter;
    }

    /* prime meridian */
    if ((name = pj_param(start, "spm").s) != NULL) {
        const char *value = NULL;
        for (i = 0; pj_prime_meridians[i].id != NULL; ++i) {
            if (strcmp(name, pj_prime_meridians[i].id) == 0) {
                value = pj_prime_meridians[i].defn;
                break;
            }
        }
        if (!value) {
            char *next_str = NULL;
            double v;
            if (*name == '\0') {
                proj_log_error(PIN, "Invalid value for pm");
                return pj_default_destructor(PIN, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
            }
            v = dmstor(name, &next_str);
            if (v == HUGE_VAL || (next_str != NULL && *next_str != '\0')) {
                proj_log_error(PIN, "Invalid value for pm");
                return pj_default_destructor(PIN, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
            }
            PIN->from_greenwich = v;
        } else
            PIN->from_greenwich = dmstor(value, NULL);
    } else
        PIN->from_greenwich = 0.0;

    /* projection specific setup */
    err = proj_errno_reset(PIN);
    PIN = entry->setup(PIN);
    if (!PIN) return NULL;
    if (proj_errno(PIN)) {
        int e = proj_errno(PIN);
        pj_free(PIN);
        pj_ctx_set_errno(e);
        return NULL;
    }
    if (pj_ctx_errno) {
        int e = pj_ctx_errno;
        pj_free(PIN);
        pj_ctx_set_errno(e);
        return NULL;
    }
    pj_ctx_set_errno(err);
    PIN->err = err;
    return PIN;
}

/* ---------------------------------------------------------------- */
/* Angular/degree input/output tests                                 */
/* ---------------------------------------------------------------- */
int proj_angular_input(PJ *P, int dir) {
    int units;
    if (P->inverted) dir = -dir;
    units = (dir == PJ_FWD) ? P->left : P->right;
    return units == PJ_IO_UNITS_RADIANS;
}
int proj_angular_output(PJ *P, int dir) {
    int units;
    if (P->inverted) dir = -dir;
    units = (dir == PJ_FWD) ? P->right : P->left;
    return units == PJ_IO_UNITS_RADIANS;
}
int proj_degree_input(PJ *P, int dir) {
    int units;
    if (P->inverted) dir = -dir;
    units = (dir == PJ_FWD) ? P->left : P->right;
    return units == PJ_IO_UNITS_DEGREES;
}
int proj_degree_output(PJ *P, int dir) {
    int units;
    if (P->inverted) dir = -dir;
    units = (dir == PJ_FWD) ? P->right : P->left;
    return units == PJ_IO_UNITS_DEGREES;
}

/* ---------------------------------------------------------------- */
/* Geocentric latitude                                               */
/* ---------------------------------------------------------------- */
PJ_COORD pj_geocentric_latitude(const PJ *P, int direction, PJ_COORD coord) {
    const double limit = M_HALFPI - 1e-9;
    PJ_COORD res = coord;
    if ((coord.lp.phi > limit) || (coord.lp.phi < -limit) || (P->es == 0)) return res;
    if (direction == PJ_FWD)
        res.lp.phi = atan(P->one_es * tan(coord.lp.phi));
    else
        res.lp.phi = atan(P->rone_es * tan(coord.lp.phi));
    return res;
}

/* ---------------------------------------------------------------- */
/* Forward                                                           */
/* ---------------------------------------------------------------- */
#define PJ_EPS_LAT 1e-12

static PJ_COORD fwd_prepare(PJ *P, PJ_COORD coo) {
    if (HUGE_VAL == coo.v[0] || HUGE_VAL == coo.v[1] || HUGE_VAL == coo.v[2]) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_INVALID_COORD);
        return proj_coord_error();
    }
    if (P->left == PJ_IO_UNITS_RADIANS) {
        double t;
        t = (coo.lp.phi < 0 ? -coo.lp.phi : coo.lp.phi) - M_HALFPI;
        if (t > PJ_EPS_LAT) {
            proj_log_error(P, "Invalid latitude");
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_INVALID_COORD);
            return proj_coord_error();
        }
        if (coo.lp.lam > 10 || coo.lp.lam < -10) {
            proj_log_error(P, "Invalid longitude");
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_INVALID_COORD);
            return proj_coord_error();
        }
        if (coo.lp.phi > M_HALFPI) coo.lp.phi = M_HALFPI;
        if (coo.lp.phi < -M_HALFPI) coo.lp.phi = -M_HALFPI;
        if (P->geoc) coo = pj_geocentric_latitude(P, PJ_INV, coo);
        if (0 == P->over) coo.lp.lam = adjlon(coo.lp.lam);
        if (coo.lp.lam == HUGE_VAL) return coo;
        coo.lp.lam = (coo.lp.lam - P->from_greenwich) - P->lam0;
        if (0 == P->over) coo.lp.lam = adjlon(coo.lp.lam);
        return coo;
    }
    return coo;
}

static PJ_COORD fwd_finalize(PJ *P, PJ_COORD coo) {
    switch (P->right) {
    case PJ_IO_UNITS_CARTESIAN:
        coo.xyz.x *= P->fr_meter;
        coo.xyz.y *= P->fr_meter;
        coo.xyz.z *= P->fr_meter;
        break;
    case PJ_IO_UNITS_CLASSIC:
        coo.xy.x *= P->a;
        coo.xy.y *= P->a;
        /* fall through */
    case PJ_IO_UNITS_PROJECTED:
        coo.xyz.x = P->fr_meter * (coo.xyz.x + P->x0);
        coo.xyz.y = P->fr_meter * (coo.xyz.y + P->y0);
        coo.xyz.z = P->vfr_meter * (coo.xyz.z + P->z0);
        break;
    case PJ_IO_UNITS_WHATEVER:
        break;
    case PJ_IO_UNITS_DEGREES:
        break;
    case PJ_IO_UNITS_RADIANS:
        coo.lpz.z = P->vfr_meter * (coo.lpz.z + P->z0);
        if (P->is_long_wrap_set) {
            if (coo.lp.lam != HUGE_VAL)
                coo.lp.lam = P->long_wrap_center + adjlon(coo.lp.lam - P->long_wrap_center);
        }
        break;
    }
    return coo;
}

static PJ_COORD error_or_coord(PJ *P, PJ_COORD coord, int last_errno) {
    if (proj_errno(P)) return proj_coord_error();
    (void)last_errno;
    return coord;
}

PJ_XY pj_fwd(PJ_LP lp, PJ *P) {
    PJ_COORD coo;
    int last_errno;
    PJ_XY err = {HUGE_VAL, HUGE_VAL};
    coo.v[0] = lp.lam; coo.v[1] = lp.phi; coo.v[2] = 0; coo.v[3] = 0;
    coo.lp = lp;
    coo.v[2] = 0; coo.v[3] = 0;

    last_errno = proj_errno_reset(P);
    if (!P->skip_fwd_prepare) coo = fwd_prepare(P, coo);
    if (HUGE_VAL == coo.v[0] || HUGE_VAL == coo.v[1]) return err;

    if (P->fwd)
        coo.xy = P->fwd(coo.lp, P);
    else if (P->fwd3d)
        coo.xyz = P->fwd3d(coo.lpz, P);
    else if (P->fwd4d)
        coo = P->fwd4d(coo, P);
    else {
        proj_errno_set(P, PROJ_ERR_OTHER_NO_INVERSE_OP);
        return err;
    }
    if (HUGE_VAL == coo.v[0]) return err;
    if (!P->skip_fwd_finalize) coo = fwd_finalize(P, coo);
    coo = error_or_coord(P, coo, last_errno);
    return coo.xy;
}

PJ_COORD pj_fwd4d(PJ_COORD coo, PJ *P) {
    int last_errno = proj_errno_reset(P);
    if (!P->skip_fwd_prepare) coo = fwd_prepare(P, coo);
    if (HUGE_VAL == coo.v[0]) return proj_coord_error();
    if (P->fwd4d)
        coo = P->fwd4d(coo, P);
    else if (P->fwd3d)
        coo.xyz = P->fwd3d(coo.lpz, P);
    else if (P->fwd)
        coo.xy = P->fwd(coo.lp, P);
    else {
        proj_errno_set(P, PROJ_ERR_OTHER_NO_INVERSE_OP);
        return proj_coord_error();
    }
    if (HUGE_VAL == coo.v[0]) return proj_coord_error();
    if (!P->skip_fwd_finalize) coo = fwd_finalize(P, coo);
    return error_or_coord(P, coo, last_errno);
}

/* ---------------------------------------------------------------- */
/* Inverse                                                           */
/* ---------------------------------------------------------------- */
static PJ_COORD inv_prepare(PJ *P, PJ_COORD coo) {
    if (coo.v[0] == HUGE_VAL || coo.v[1] == HUGE_VAL || coo.v[2] == HUGE_VAL) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_INVALID_COORD);
        return proj_coord_error();
    }
    switch (P->right) {
    case PJ_IO_UNITS_WHATEVER:
        break;
    case PJ_IO_UNITS_DEGREES:
        break;
    case PJ_IO_UNITS_CARTESIAN:
        coo.xyz.x *= P->to_meter;
        coo.xyz.y *= P->to_meter;
        coo.xyz.z *= P->to_meter;
        break;
    case PJ_IO_UNITS_PROJECTED:
    case PJ_IO_UNITS_CLASSIC:
        coo.xyz.x = P->to_meter * coo.xyz.x - P->x0;
        coo.xyz.y = P->to_meter * coo.xyz.y - P->y0;
        coo.xyz.z = P->vto_meter * coo.xyz.z - P->z0;
        if (P->right == PJ_IO_UNITS_PROJECTED) return coo;
        coo.xyz.x *= P->ra;
        coo.xyz.y *= P->ra;
        break;
    case PJ_IO_UNITS_RADIANS:
        coo.lpz.z = P->vto_meter * coo.lpz.z - P->z0;
        break;
    }
    return coo;
}

static PJ_COORD inv_finalize(PJ *P, PJ_COORD coo) {
    if (coo.xyz.x == HUGE_VAL) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_INVALID_COORD);
        return proj_coord_error();
    }
    if (P->left == PJ_IO_UNITS_RADIANS) {
        coo.lp.lam = coo.lp.lam + P->from_greenwich + P->lam0;
        if (0 == P->over) coo.lpz.lam = adjlon(coo.lpz.lam);
        if (coo.lp.lam == HUGE_VAL) return coo;
        if (P->geoc) coo = pj_geocentric_latitude(P, PJ_FWD, coo);
    }
    return coo;
}

PJ_LP pj_inv(PJ_XY xy, PJ *P) {
    PJ_COORD coo;
    int last_errno;
    PJ_LP err = {HUGE_VAL, HUGE_VAL};
    coo.v[0] = xy.x; coo.v[1] = xy.y; coo.v[2] = 0; coo.v[3] = 0;

    last_errno = proj_errno_reset(P);
    if (!P->skip_inv_prepare) coo = inv_prepare(P, coo);
    if (HUGE_VAL == coo.v[0]) return err;

    if (P->inv)
        coo.lp = P->inv(coo.xy, P);
    else if (P->inv3d)
        coo.lpz = P->inv3d(coo.xyz, P);
    else if (P->inv4d)
        coo = P->inv4d(coo, P);
    else {
        proj_errno_set(P, PROJ_ERR_OTHER_NO_INVERSE_OP);
        return err;
    }
    if (HUGE_VAL == coo.v[0]) return err;
    if (!P->skip_inv_finalize) coo = inv_finalize(P, coo);
    coo = error_or_coord(P, coo, last_errno);
    return coo.lp;
}

PJ_COORD pj_inv4d(PJ_COORD coo, PJ *P) {
    int last_errno = proj_errno_reset(P);
    if (!P->skip_inv_prepare) coo = inv_prepare(P, coo);
    if (HUGE_VAL == coo.v[0]) return proj_coord_error();
    if (P->inv4d)
        coo = P->inv4d(coo, P);
    else if (P->inv3d)
        coo.lpz = P->inv3d(coo.xyz, P);
    else if (P->inv)
        coo.lp = P->inv(coo.xy, P);
    else {
        proj_errno_set(P, PROJ_ERR_OTHER_NO_INVERSE_OP);
        return proj_coord_error();
    }
    if (HUGE_VAL == coo.v[0]) return proj_coord_error();
    if (!P->skip_inv_finalize) coo = inv_finalize(P, coo);
    return error_or_coord(P, coo, last_errno);
}

PJ_COORD proj_trans(PJ *P, int direction, PJ_COORD coo) {
    if (!P || direction == PJ_IDENT) return coo;
    if (P->inverted) direction = -direction;
    if (direction == PJ_FWD) return pj_fwd4d(coo, P);
    return pj_inv4d(coo, P);
}
EOF
echo ok"}

