/* Core: PJ creation, initialization, forward/inverse drivers */
#include "proj.h"

PJ *pj_new(void) {
    PJ *P = (PJ *)calloc(1, sizeof(PJ));
    if (!P) return NULL;
    P->left = PJ_IO_UNITS_RADIANS;
    P->right = PJ_IO_UNITS_CLASSIC;
    P->k0 = 1.0;
    P->to_meter = P->fr_meter = 1.0;
    P->vto_meter = P->vfr_meter = 1.0;
    strcpy(P->axis, "enu");
    return P;
}

void pj_free(PJ *P) {
    if (!P) return;
    if (P->destructor) {
        P->destructor(P, 0);
        return;
    }
    pj_default_destructor(P, 0);
}

PJ *pj_default_destructor(PJ *P, int errlev) {
    if (errlev) {
        pj_ctx_set_errno(errlev);
    }
    if (!P) return NULL;
    if (P->opaque) free(P->opaque);
    pj_dealloc_params(P->params);
    if (P->def_full) free(P->def_full);
    free(P);
    return NULL;
}

double adjlon(double lon) {
    const double SPI = 3.14159265359;
    if (fabs(lon) <= SPI) return lon;
    lon += M_PI;
    lon -= M_TWOPI * floor(lon / M_TWOPI);
    lon -= M_PI;
    return lon;
}

PJ_COORD proj_coord_error(void) {
    PJ_COORD c;
    c.v[0] = c.v[1] = c.v[2] = c.v[3] = HUGE_VAL;
    return c;
}

/* ---------------------------------------------------------------- */
/* Datum parameter expansion                                         */
/* ---------------------------------------------------------------- */
static int pj_datum_set(paralist *pl, PJ *P) {
    const char *name;
