#include "proj.h"
#include <stdarg.h>
#include "emess.h"

struct EMESS emess_dat = {NULL, NULL, 0};

void emess(int code, const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    /* prefix program name, if given */
    if (fmt != NULL) (void)fprintf(stderr, "%s\n<%s>: ", RELEASE_STRING, emess_dat.Prog_name ? emess_dat.Prog_name : "");
    /* print file name and line, if given */
    if (emess_dat.File_name != NULL && *emess_dat.File_name) {
        (void)fprintf(stderr, "while processing file: %s", emess_dat.File_name);
        if (emess_dat.File_line > 0)
            (void)fprintf(stderr, ", line %d\n", emess_dat.File_line);
        else
            (void)fputc('\n', stderr);
    } else
        putc('\n', stderr);
    /* if |code|==2, print errno code */
    if (code == 2 || code == -2)
        (void)fprintf(stderr, "Sys errno: %d: %s\n", errno, strerror(errno));
    /* post remainder of message */
    if (fmt != NULL) {
        (void)vfprintf(stderr, fmt, args);
        (void)fputc('\n', stderr);
    }
    va_end(args);
    if (code > 0) {
        (void)fputs("program abnormally terminated\n", stderr);
        exit(code);
    }
}
