                             facs.areal_scale, facs.angular_distortion * RAD_TO_DEG,
                             facs.tissot_semimajor, facs.tissot_semiminor);
            else
                (void)fputs("\t<* * * * * *>", stdout);
        }
        (void)fputs(bin_in ? "\n" : s, stdout);
        fflush(stdout);
    }
}

static void vprocess(FILE *fid) {
    char line[MAX_LINE + 3], *s, pline[40];
    PJ_LP dat_ll;
    PJ_XY dat_xy;
    int linvers;
    PJ_COORD coord;

    if (!oform) oform = "%.3f";
    if (bin_in || bin_out) emess(1, "binary I/O not available in -V option");

    for (;;) {
        proj_errno_reset(Proj);
        ++emess_dat.File_line;
        if (!(s = fgets(line, MAX_LINE, fid))) break;
        if (!strchr(s, '\n')) { /* overlong line */
            int c;
            (void)strcat(s, "\n");
            /* gobble up to newline */
            while ((c = fgetc(fid)) != EOF && c != '\n') ;
        }
        if (*s == tag) { /* pass on data */
            (void)fputs(s, stdout);
            continue;
        }
        /* check to override default input mode */
        if (*s == 'I' || *s == 'i') {
            linvers = 1;
            ++s;
        } else if (*s == 'F' || *s == 'f') {
            linvers = 0;
            ++s;
        } else
            linvers = inverse;

        if (linvers) {
            if (!pj_has_inverse(Proj)) {
                emess(-1, "inverse for this projection not avail.\n");
                continue;
            }
            dat_xy.x = strtod(s, &s);
            dat_xy.y = strtod(s, &s);
            if (dat_xy.x == HUGE_VAL || dat_xy.y == HUGE_VAL) {
                emess(-1, "lon-lat input conversion failure\n");
                continue;
            }
            if (prescale) {
                dat_xy.x *= fscale;
                dat_xy.y *= fscale;
            }
            if (reversein) {
                PJ_XY temp;
                temp.x = dat_xy.y;
                temp.y = dat_xy.x;
                dat_xy = temp;
            }
            dat_ll = pj_inv(dat_xy, Proj);
        } else {
            dat_ll.lam = dmstor(s, &s);
            dat_ll.phi = dmstor(s, &s);
            if (dat_ll.lam == HUGE_VAL || dat_ll.phi == HUGE_VAL) {
                emess(-1, "lon-lat input conversion failure\n");
                continue;
            }
            if (reversein) {
                PJ_LP temp;
                temp.lam = dat_ll.phi;
                temp.phi = dat_ll.lam;
                dat_ll = temp;
            }
            dat_xy = pj_fwd(dat_ll, Proj);
        }

        if (proj_errno(Proj)) {
            emess(-1, "%s", proj_errno_string(proj_errno(Proj)));
            continue;
        }

        if (!*s && (s > line)) --s; /* assumed we gobbled \n */
        if (*s != '\n') (void)fputs(s, stdout);

        coord.v[0] = dat_ll.lam; coord.v[1] = dat_ll.phi; coord.v[2] = 0; coord.v[3] = 0;
        facs_bad = proj_factors(Proj, coord, &facs);
        if (facs_bad) {
            emess(-1, "failed to compute factors\n\n");
            continue;
        }
        (void)printf("Longitude: %s [ %.11g ]\n", rtodms(pline, sizeof(pline), dat_ll.lam * RAD_TO_DEG, 'E', 'W'),
                     dat_ll.lam * RAD_TO_DEG);
        (void)printf("Latitude:  %s [ %.11g ]\n", rtodms(pline, sizeof(pline), dat_ll.phi * RAD_TO_DEG, 'N', 'S'),
                     dat_ll.phi * RAD_TO_DEG);
        (void)printf("Easting (x):   ");
        (void)printf(oform, dat_xy.x);
        (void)putchar('\n');
        (void)printf("Northing (y):  ");
        (void)printf(oform, dat_xy.y);
        (void)putchar('\n');
        (void)printf("Meridian scale (h) : %.8f  ( %.4g %% error )\n", facs.meridional_scale,
                     (facs.meridional_scale - 1.) * 100.);
        (void)printf("Parallel scale (k) : %.8f  ( %.4g %% error )\n", facs.parallel_scale,
                     (facs.parallel_scale - 1.) * 100.);
        (void)printf("Areal scale (s):     %.8f  ( %.4g %% error )\n", facs.areal_scale,
                     (facs.areal_scale - 1.) * 100.);
        (void)printf("Angular distortion (w): %.3f\n", facs.angular_distortion * RAD_TO_DEG);
        (void)printf("Meridian/Parallel angle: %.5f\n", facs.meridian_parallel_angle * RAD_TO_DEG);
        (void)printf("Convergence : %s [ %.8f ]\n",
                     rtodms(pline, sizeof(pline), facs.meridian_convergence * RAD_TO_DEG, 0, 0),
                     facs.meridian_convergence * RAD_TO_DEG);
        (void)printf("Max-min (Tissot axis a-b) scale error: %.5f %.5f\n\n", facs.tissot_semimajor,
                     facs.tissot_semiminor);
    }
}

extern void list_projections(int do_long);
extern void list_projection(const char *id);
extern void list_ellps(void);
extern void list_units(void);

int main(int argc, char **argv) {
    char *arg;
    char **eargv = argv;
    char *pargv[MAX_PARGS];
    FILE *fid;
    int pargc = 0, eargc = 0, c;
    int i;

    /* program name */
    {
        const char *p = strrchr(argv[0], '/');
        emess_dat.Prog_name = p ? p + 1 : argv[0];
        pj_prog_name = emess_dat.Prog_name;
    }

    if (argc == 1) {
        (void)fprintf(stderr, usage, RELEASE_STRING, emess_dat.Prog_name);
        exit(0);
    }

    for (i = 1; i < argc; ++i) {
        arg = argv[i];
        if (*arg == '-') {
            for (arg++; *arg; ++arg) {
                int done = 0;
                switch (*arg) {
                case 'b': bin_in = bin_out = 1; continue;
                case 'v': mon = 1; continue;
                case 'i': bin_in = 1; continue;
                case 'o': bin_out = 1; continue;
                case 'I': inverse = 1; continue;
                case 'E': echoin = 1; continue;
                case 'V': very_verbose = 1; mon = 1; continue;
                case 'S': dofactors = 1; continue;
                case 't':
                    if (arg[1]) tag = *++arg;
                    else emess(1, "missing -t col. 1 tag");
                    continue;
                case 'l':
                    if (!arg[1] || arg[1] == 'p' || arg[1] == 'P') {
                        list_projections(arg[1] == 'P');
                    } else if (arg[1] == '=') {
                        list_projection(arg + 2);
                    } else if (arg[1] == 'e') {
                        list_ellps();
                    } else if (arg[1] == 'u') {
                        list_units();
                    } else
                        emess(1, "invalid list option: l%c", arg[1]);
                    exit(0);
                case 'e':
                    if (i + 1 >= argc) emess(1, "missing argument for -%c", *arg);
                    oterr = argv[++i];
                    continue;
                case 'm':
                    if (i + 1 >= argc) emess(1, "missing argument for -%c", *arg);
                    postscale = 1;
                    ++i;
                    if (!strncmp("1/", argv[i], 2) || !strncmp("1:", argv[i], 2)) {
                        if ((fscale = atof(argv[i] + 2)) == 0.) emess(1, "invalid scale argument");
                        fscale = 1. / fscale;
                    } else if ((fscale = atof(argv[i])) == 0.)
                        emess(1, "invalid scale argument");
                    continue;
                case 'W':
                case 'w':
                    c = arg[1];
                    if (c != 0 && isdigit((unsigned char)c)) {
                        set_rtodms(c - '0', *arg == 'W');
                        ++arg;
                    } else
                        emess(1, "-W argument missing or non-digit");
                    continue;
                case 'f':
                    if (i + 1 >= argc) emess(1, "missing argument for -%c", *arg);
                    oform = argv[++i];
                    continue;
                case 'r': reversein = 1; continue;
                case 's': reverseout = 1; continue;
                case 'd':
                    if (i + 1 >= argc) emess(1, "missing argument for -%c", *arg);
                    sprintf(oform_buffer, "%%.%df", atoi(argv[++i]));
                    oform = oform_buffer;
                    done = 1;
                    break;
                default:
                    emess(1, "invalid option: -%c", *arg);
                    break;
                }
                if (done) break;
            }
        } else if (*arg == '+') {
            if (pargc < MAX_PARGS) pargv[pargc++] = arg + 1;
            else emess(1, "overflowed + argument table");
        } else
            eargv[eargc++] = arg;
    }

    /* done with parameter and control input */
    if (inverse && postscale) {
        prescale = 1;
        postscale = 0;
        fscale = 1. / fscale;
    }

    {
        int crs_err = 0;
        const char *crs_msg = NULL;
        if (pargc == 0 && eargc > 0) {
            /* CRS specified as first non-option argument */
            Proj = proj_create_from_args(0, eargv, &crs_err, &crs_msg);
            if (!Proj) {
                if (crs_msg) emess(3, "%s", crs_msg);
                emess(3, "projection initialization failure\ncause: %s", proj_errno_string(pj_ctx_errno));
            }
            /* remove the CRS argument from the file list */
            for (i = 1; i < eargc; ++i) eargv[i - 1] = eargv[i];
            eargc--;
        } else {
            Proj = proj_create_from_args(pargc, pargv, &crs_err, &crs_msg);
            if (!Proj) {
                if (crs_msg) emess(3, "%s", crs_msg);
                emess(3, "projection initialization failure\ncause: %s", proj_errno_string(pj_ctx_errno));
            }
        }
    }

    if (!proj_angular_input(Proj, PJ_FWD)) {
        emess(3, "can't initialize operations that take non-angular input coordinates. Try cct.");
    }
    if (proj_angular_output(Proj, PJ_FWD)) {
        emess(3, "can't initialize operations that produce angular output coordinates");
    }

    if (eargc == 0) /* if no specified files force sysin */
        eargv[eargc++] = (char *)"-";

    if (inverse) {
        if (!pj_has_inverse(Proj)) emess(3, "inverse projection not available");
    }

    if (oform) {
        if (!validate_form_string_for_numbers(oform)) emess(3, "invalid format string");
    } else if (!inverse) {
        oform = "%.2f";
    }

    if (mon) {
        pj_pr_list(Proj);
        if (very_verbose) {
            (void)printf("#Final Earth figure: ");
            if (Proj->es != 0.0) {
                (void)printf("ellipsoid\n#  Major axis (a): ");
                (void)printf("%.3f", Proj->a);
                (void)printf("\n#  1/flattening: %.6f\n", 1. / (1. - sqrt(1. - Proj->es)));
                (void)printf("#  squared eccentricity: %.12f\n", Proj->es);
            } else {
                (void)printf("sphere\n#  Radius: ");
                (void)printf("%.3f", Proj->a);
                (void)putchar('\n');
            }
        }
    }

    /* process input file list */
    for (i = 0; i < eargc; ++i) {
        if (!strcmp(eargv[i], "-")) {
            fid = stdin;
            emess_dat.File_name = "<stdin>";
        } else {
            if ((fid = fopen(eargv[i], "rb")) == NULL) {
                emess(-2, "input file: %s", eargv[i]);
                continue;
            }
            emess_dat.File_name = eargv[i];
        }
        emess_dat.File_line = 0;
        if (very_verbose)
            vprocess(fid);
        else
            process(fid);
        (void)fclose(fid);
        emess_dat.File_name = NULL;
    }
    if (Proj) pj_free(Proj);
    exit(0);
}
