/* Creation of PJ objects from user supplied argument strings */
#include "proj.h"

#define MAX_TOKENS 1024

/* Normalise a single user token: strip leading '+' signs and leading whitespace,
   remove whitespace right before the first '='. Returns malloc'ed string or NULL if empty. */
static char *normalise_token(const char *s) {
    char *r, *eq;
    while (*s == '+') ++s;
    while (isspace((unsigned char)*s)) ++s;
    if (*s == '\0') return NULL;
    r = pj_strdup(s);
    eq = strchr(r, '=');
    if (eq) {
        char *p = eq;
        while (p > r && isspace((unsigned char)p[-1])) --p;
        if (p != eq) memmove(p, eq, strlen(eq) + 1);
    }
    return r;
}

/* Build a parameter list from tokens, applying the '=' merge rules */
static paralist *build_paralist(char **tokens, int ntok) {
    paralist *start = NULL, *curr = NULL;
    int i;
    char buf[8192];
    i = 0;
    while (i < ntok) {
        size_t l;
        strncpy(buf, tokens[i], sizeof(buf) - 1);
        buf[sizeof(buf) - 1] = 0;
        i++;
        /* a token ending in '=' absorbs the following tokens */
        for (;;) {
            l = strlen(buf);
            if (l > 0 && buf[l - 1] == '=' && i < ntok) {
                strncat(buf, tokens[i], sizeof(buf) - 1 - l);
                i++;
                continue;
            }
            /* a following token starting with '=' is appended */
            if (i < ntok && tokens[i][0] == '=') {
                strncat(buf, tokens[i], sizeof(buf) - 1 - l);
                i++;
                continue;
            }
            break;
        }
        {
            paralist *n = pj_mkparam(buf);
            if (!start) start = curr = n;
            else { curr->next = n; curr = n; }
        }
    }
    return start;
}

static int has_proj_eq(const char *s) {
    return strstr(s, "proj=") != NULL;
}

static int is_key(const char *tok, const char *key) {
    size_t l = strlen(key);
    return !strncmp(tok, key, l) && (tok[l] == '=' || tok[l] == '\0');
}

/* Create a PJ from a list of tokens (already normalised), representing a single operation
   or a pipeline. is_user: user-provided string (append break_cs2cs_recursion). */
PJ *pj_create_from_tokens(char **tokens, int ntok, int append_break);

extern PJ *pj_pipeline_create(char **tokens, int ntok, int append_break);

PJ *pj_create_from_tokens(char **tokens, int ntok, int append_break) {
    char *ordered[MAX_TOKENS + 2];
    int n = 0, i, proj_idx = -1;
    paralist *pl;
    PJ *P;
    int inverted = 0;

    for (i = 0; i < ntok; ++i) {
        if (is_key(tokens[i], "proj") && strchr(tokens[i], '=')) {
            proj_idx = i;
            break;
        }
    }
    if (proj_idx >= 0 && !strcmp(tokens[proj_idx] + 5, "pipeline")) {
        return pj_pipeline_create(tokens, ntok, append_break);
    }
    if (proj_idx >= 0) ordered[n++] = tokens[proj_idx];
    for (i = 0; i < ntok; ++i) {
        if (i == proj_idx) continue;
        if (is_key(tokens[i], "title")) continue;
        if (!strcmp(tokens[i], "step")) continue;
        if (!strcmp(tokens[i], "inv")) { inverted = 1; continue; }
        ordered[n++] = tokens[i];
    }
    if (append_break) ordered[n++] = (char *)"break_cs2cs_recursion";
    pl = build_paralist(ordered, n);
    if (!pl) {
        pj_ctx_set_errno(PROJ_ERR_INVALID_OP_WRONG_SYNTAX);
        return NULL;
    }
    if (!pj_param_exists(pl, "proj")) {
        pj_dealloc_params(pl);
        proj_log_error_ctx("Missing proj");
        pj_ctx_set_errno(PROJ_ERR_INVALID_OP_MISSING_ARG);
        return NULL;
    }
    P = pj_create_internal_from_params(pl, 1);
    if (P) P->inverted = inverted;
    return P;
}

/* Entry point used by the CLI. pargc==0 means: eargv[0] is a CRS-like string */
PJ *proj_create_from_args(int pargc, char **pargv, int *is_crs_err, const char **crs_msg) {
    char *tokens[MAX_TOKENS];
    int ntok = 0, i;
    PJ *P = NULL;
    int any_proj = 0;
    const char *msg = NULL;
    int has_type_crs = 0, has_init = 0;

    *is_crs_err = 0;
    *crs_msg = NULL;
    pj_ctx_set_errno(0);

    if (pargc == 0) {
        /* CRS path */
        const char *s = pargv[0];
        const char *p;
        if (strstr(s, "proj=") == NULL) {
            if (!strncmp(s, "EPSG:", 5) || !strncmp(s, "epsg:", 5) || strstr(s, "urn:ogc:def:crs")) {
                extern PJ *pj_create_from_epsg(const char *s, const char **msg);
                P = pj_create_from_epsg(s, &msg);
                if (!P) {
                    if (msg) fprintf(stderr, "%s\n", msg);
                    *crs_msg = "CRS is not parseable";
                    pj_ctx_set_errno(0);
                    return NULL;
                }
                return P;
            }
            if (!strcmp(s, "WGS84") || !strcmp(s, "NAD27") || !strcmp(s, "NAD83")) {
                *crs_msg = "CRS must be projected";
                return NULL;
            }
            fprintf(stderr, "proj_create: unrecognized format / unknown name\n");
            *crs_msg = "CRS is not parseable";
            return NULL;
        }
        /* a PROJ string: tokenise on whitespace */
        {
            char *copy = pj_strdup(s);
            char *tok = strtok(copy, " \t\n");
            while (tok && ntok < MAX_TOKENS) {
                char *t = normalise_token(tok);
                if (t) tokens[ntok++] = t;
                tok = strtok(NULL, " \t\n");
            }
            free(copy);
        }
        for (i = 0; i < ntok; ++i) if (!strcmp(tokens[i], "type=crs")) has_type_crs = 1;
        if (!has_type_crs) {
            *crs_msg = "CRS must be projected";
            return NULL;
        }
        /* a projected CRS given as PROJ string: build the conversion */
        {
            char *t2[MAX_TOKENS];
            int n2 = 0;
            int has_ellps = 0;
            for (i = 0; i < ntok; ++i) {
                if (!strcmp(tokens[i], "type=crs")) continue;
                if (is_key(tokens[i], "ellps") || is_key(tokens[i], "datum") || is_key(tokens[i], "a") ||
                    is_key(tokens[i], "R") || is_key(tokens[i], "b") || is_key(tokens[i], "rf"))
                    has_ellps = 1;
                t2[n2++] = tokens[i];
            }
            if (!has_ellps) t2[n2++] = (char *)"ellps=WGS84";
            pj_log_capture_begin();
            P = pj_create_from_tokens(t2, n2, 0);
            {
                const char *m = pj_log_capture_end();
                if (!P) {
                    int e = pj_ctx_errno;
                    if (m) fprintf(stderr, "proj_create: Error %d (%s): %s\n", e, proj_errno_string(e), m);
                    else fprintf(stderr, "proj_create: Error %d (%s)\n", e, proj_errno_string(e));
                    pj_ctx_set_errno(e);
                    return NULL;
                }
            }
            if (P && proj_angular_output(P, PJ_FWD)) {
                pj_free(P);
                *crs_msg = "CRS must be projected";
                return NULL;
            }
            return P;
        }
    }

    for (i = 0; i < pargc && ntok < MAX_TOKENS; ++i) {
        char *t = normalise_token(pargv[i]);
        if (!t) continue;
        tokens[ntok++] = t;
    }
    for (i = 0; i < ntok; ++i) {
        if (has_proj_eq(tokens[i])) any_proj = 1;
        if (!strcmp(tokens[i], "type=crs")) has_type_crs = 1;
        if (is_key(tokens[i], "init") && strchr(tokens[i], '=')) has_init = 1;
    }
    if (!any_proj && !has_init) {
        fprintf(stderr, "proj_create: unrecognized format / unknown name\n");
        pj_ctx_set_errno(2);
        return NULL;
    }
    if (has_init) {
        /* +init= handling: EPSG codes are considered CRS, others cannot be opened */
        for (i = 0; i < ntok; ++i) {
            if (is_key(tokens[i], "init") && strchr(tokens[i], '=')) {
                const char *v = tokens[i] + 5;
                const char *colon = strchr(v, ':');
                char all[8192];
                int k;
                all[0] = 0;
                for (k = 0; k < ntok; ++k) {
                    if (k) strcat(all, " ");
                    strcat(all, tokens[k]);
                }
                strcat(all, " break_cs2cs_recursion");
                if (!colon) {
                    fprintf(stderr, "Missing colon in +init\n");
                    fprintf(stderr, "proj_create: cannot expand %s\n", all);
                    pj_ctx_set_errno(PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
                    return NULL;
                }
                if (!strncmp(v, "epsg:", 5) || !strncmp(v, "EPSG:", 5)) {
                    has_type_crs = 1;
                    break;
                }
                {
                    char fname[4096];
                    size_t l = (size_t)(colon - v);
                    if (l >= sizeof(fname)) l = sizeof(fname) - 1;
                    memcpy(fname, v, l);
                    fname[l] = 0;
                    fprintf(stderr, "Cannot open %s\n", fname);
                    fprintf(stderr, "proj_create: cannot expand %s\n", all);
                    pj_ctx_set_errno(PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
                    return NULL;
                }
            }
        }
    }
    if (has_type_crs) {
        /* A CRS object: not a coordinate operation */
        *is_crs_err = 1;
        *crs_msg = "can't initialize operations that take non-angular input coordinates. Try cct.";
        return NULL;
    }

    pj_log_capture_begin();
    P = pj_create_from_tokens(tokens, ntok, 1);
    {
        const char *m = pj_log_capture_end();
        if (!P) {
            int e = pj_ctx_errno;
            if (m) fprintf(stderr, "proj_create: Error %d (%s): %s\n", e, proj_errno_string(e), m);
            else fprintf(stderr, "proj_create: Error %d (%s)\n", e, proj_errno_string(e));
            pj_ctx_set_errno(e);
            return NULL;
        }
    }
    return P;
}

PJ *proj_create(const char *definition) {
    char *copy = pj_strdup(definition);
    char *tokens[MAX_TOKENS];
    int ntok = 0;
    char *tok = strtok(copy, " \t\n");
    PJ *P;
    while (tok && ntok < MAX_TOKENS) {
        char *t = normalise_token(tok);
        if (t) tokens[ntok++] = t;
        tok = strtok(NULL, " \t\n");
    }
    free(copy);
    P = pj_create_from_tokens(tokens, ntok, 0);
    return P;
}

PJ *proj_create_argv(int argc, char **argv) {
    char *tokens[MAX_TOKENS];
    int ntok = 0, i;
    for (i = 0; i < argc && ntok < MAX_TOKENS; ++i) {
        char *t = normalise_token(argv[i]);
        if (t) tokens[ntok++] = t;
    }
    return pj_create_from_tokens(tokens, ntok, 0);
}
