        if (!strcmp(s->tokens[i], p)) return 1;
    return 0;
}

static void remove_step(PipelineDef *d, int idx) {
    int i;
    for (i = idx; i + 1 < d->nsteps; ++i) d->steps[i] = d->steps[i + 1];
    d->nsteps--;
}

static void optimise(PipelineDef *d) {
    int changed = 1, i;
    while (changed) {
        changed = 0;
        /* remove noop steps */
        for (i = 0; i < d->nsteps; ++i) {
            const char *n = step_name(&d->steps[i]);
            if (n && !strcmp(n, "noop")) {
                remove_step(d, i);
                changed = 1;
                break;
            }
        }
        if (changed) continue;
        /* remove consecutive inverse pairs */
        for (i = 0; i + 1 < d->nsteps; ++i) {
            StepDef *a = &d->steps[i], *b = &d->steps[i + 1];
            if (a->inv != b->inv && !a->omit_fwd && !a->omit_inv && !b->omit_fwd && !b->omit_inv &&
                same_params(a, b)) {
                remove_step(d, i);
                remove_step(d, i);
                changed = 1;
                break;
            }
        }
        if (changed) continue;
        /* consecutive identical axisswap order=2,1 cancel */
        for (i = 0; i + 1 < d->nsteps; ++i) {
            StepDef *a = &d->steps[i], *b = &d->steps[i + 1];
            const char *na = step_name(a), *nb = step_name(b);
            if (na && nb && !strcmp(na, "axisswap") && !strcmp(nb, "axisswap") && a->inv == b->inv &&
                same_params(a, b) && has_param(a, "order=2,1") && a->ntok == 2 && !a->omit_fwd &&
                !a->omit_inv && !b->omit_fwd && !b->omit_inv) {
                remove_step(d, i);
                remove_step(d, i);
                changed = 1;
                break;
            }
        }
    }
}

/* ---- runtime ---- */
typedef struct {
    int nsteps;
    PJ *steps[MAX_STEPS];
    int omit_fwd[MAX_STEPS], omit_inv[MAX_STEPS];
} Pipeline;

static PJ_COORD pipeline_forward_4d(PJ_COORD point, PJ *P) {
    Pipeline *pl = (Pipeline *)P->opaque;
    int i;
    for (i = 0; i < pl->nsteps; ++i) {
        if (!pl->omit_fwd[i]) {
            point = proj_trans(pl->steps[i], PJ_FWD, point);
            if (point.v[0] == HUGE_VAL) break;
        }
    }
    return point;
}

static PJ_COORD pipeline_reverse_4d(PJ_COORD point, PJ *P) {
    Pipeline *pl = (Pipeline *)P->opaque;
    int i;
    for (i = pl->nsteps - 1; i >= 0; --i) {
        if (!pl->omit_inv[i]) {
            point = proj_trans(pl->steps[i], PJ_INV, point);
            if (point.v[0] == HUGE_VAL) break;
        }
    }
    return point;
}

static void pipeline_destructor(PJ *P, int errlev) {
    Pipeline *pl;
    int i;
    if (!P) return;
    pl = (Pipeline *)P->opaque;
    if (pl) {
        for (i = 0; i < pl->nsteps; ++i)
            if (pl->steps[i]) pj_free(pl->steps[i]);
        free(pl);
        P->opaque = NULL;
    }
    pj_default_destructor(P, errlev);
}

static int pj_left(PJ *P) { return P->inverted ? P->right : P->left; }
static int pj_right(PJ *P) { return P->inverted ? P->left : P->right; }

PJ *pj_pipeline_setup(PJ *P) {
    PipelineDef *d = pending;
    Pipeline *pl;
    int i, j;
    paralist *t;

    P->fwd4d = pipeline_forward_4d;
    P->inv4d = pipeline_reverse_4d;
    P->destructor = pipeline_destructor;
    P->left = PJ_IO_UNITS_WHATEVER;
    P->right = PJ_IO_UNITS_WHATEVER;
    P->skip_fwd_prepare = P->skip_fwd_finalize = 1;
    P->skip_inv_prepare = P->skip_inv_finalize = 1;
    P->is_pipeline = 1;

    for (t = P->params; t; t = t->next) t->used = 1;

    if (!d || d->nsteps == 0) {
        proj_errno_set(P, PROJ_ERR_INVALID_OP_WRONG_SYNTAX);
        return P;
    }
    pl = (Pipeline *)calloc(1, sizeof(Pipeline));
    P->opaque = pl;
    pl->nsteps = d->nsteps;
    for (i = 0; i < d->nsteps; ++i) {
        StepDef *s = &d->steps[i];
        char *toks[MAX_STEP_TOKENS * 2];
        int n = 0;
        PJ *step;
        for (j = 0; j < s->ntok; ++j) toks[n++] = s->tokens[j];
        if (s->inv) toks[n++] = (char *)"inv";
        for (j = 0; j < d->nglobals; ++j) toks[n++] = d->globals[j];
        pl->omit_fwd[i] = s->omit_fwd;
        pl->omit_inv[i] = s->omit_inv;
        step = pj_create_from_tokens(toks, n, 0);
        if (!step) {
            int e = pj_ctx_errno;
            const char *first = s->ntok > 0 ? s->tokens[0] : NULL;
            proj_log_error(P, "Pipeline: Bad step definition: %s (%s)", first ? first : "(null)",
                           proj_errno_string(e));
            proj_errno_set(P, e);
            return P;
        }
        pl->steps[i] = step;
    }
    /* units consistency */
    for (i = 0; i + 1 < pl->nsteps; ++i) {
        int out = pj_right(pl->steps[i]);
        int in = pj_left(pl->steps[i + 1]);
        if (out == PJ_IO_UNITS_WHATEVER || in == PJ_IO_UNITS_WHATEVER) continue;
        if (out != in) {
            proj_log_error(P, "Pipeline: Mismatched units between step %d and %d", i + 1, i + 2);
            proj_errno_set(P, PROJ_ERR_INVALID_OP_WRONG_SYNTAX);
            return P;
        }
    }
    P->left = pj_left(pl->steps[0]);
    P->right = pj_right(pl->steps[pl->nsteps - 1]);
    return P;
}

PJ *pj_pipeline_create(char **tokens, int ntok, int append_break) {
    PipelineDef *d = (PipelineDef *)calloc(1, sizeof(PipelineDef));
    int i, in_step = 0;
    PJ *P;

    for (i = 0; i < ntok; ++i) {
        char *tok = tokens[i];
        if (!strcmp(tok, "step")) {
            if (d->nsteps < MAX_STEPS) d->nsteps++;
            in_step = 1;
            continue;
        }
        if (!in_step) {
            if (!strncmp(tok, "proj=", 5) && !strcmp(tok + 5, "pipeline")) continue;
            if (!strcmp(tok, "inv")) { d->inv = 1; continue; }
            if (d->nglobals < MAX_STEP_TOKENS) d->globals[d->nglobals++] = tok;
        } else {
            StepDef *s = &d->steps[d->nsteps - 1];
            if (!strcmp(tok, "inv")) { s->inv = 1; continue; }
            if (!strcmp(tok, "omit_fwd")) { s->omit_fwd = 1; }
            if (!strcmp(tok, "omit_inv")) { s->omit_inv = 1; }
            if (s->ntok < MAX_STEP_TOKENS) s->tokens[s->ntok++] = tok;
        }
    }
    /* move proj= first within each step */
    for (i = 0; i < d->nsteps; ++i) {
        StepDef *s = &d->steps[i];
        int k;
        for (k = 0; k < s->ntok; ++k) {
            if (!strncmp(s->tokens[k], "proj=", 5)) {
                char *p = s->tokens[k];
                int m;
                for (m = k; m > 0; --m) s->tokens[m] = s->tokens[m - 1];
                s->tokens[0] = p;
                break;
            }
        }
    }
    if (append_break && d->nsteps > 0) {
        StepDef *s = &d->steps[d->nsteps - 1];
        if (s->ntok < MAX_STEP_TOKENS) s->tokens[s->ntok++] = (char *)"break_cs2cs_recursion";
    }

    optimise(d);

    if (d->nsteps == 0) {
        /* an empty pipeline is a no-operation */
        char *t[2];
        t[0] = (char *)"proj=noop";
        free(d);
        return pj_create_from_tokens(t, 1, 0);
    }
    if (d->nsteps == 1 && d->nglobals == 0 && !d->steps[0].omit_fwd && !d->steps[0].omit_inv) {
        StepDef *s = &d->steps[0];
        char *toks[MAX_STEP_TOKENS + 2];
        int n = 0, j;
        for (j = 0; j < s->ntok; ++j) toks[n++] = s->tokens[j];
        if (s->inv) toks[n++] = (char *)"inv";
        free(d);
        return pj_create_from_tokens(toks, n, 0);
    }

    /* build the flattened parameter list for the pipeline object */
    {
        char *flat[MAX_TOKENS_FLAT];
        int n = 0, j;
        paralist *pl = NULL, *curr = NULL;
        flat[n++] = (char *)"proj=pipeline";
        for (j = 0; j < d->nglobals && n < MAX_TOKENS_FLAT - 1; ++j) flat[n++] = d->globals[j];
        for (i = 0; i < d->nsteps; ++i) {
            StepDef *s = &d->steps[i];
            if (n < MAX_TOKENS_FLAT - 1) flat[n++] = (char *)"step";
            if (s->inv && n < MAX_TOKENS_FLAT - 1) flat[n++] = (char *)"inv";
            for (j = 0; j < s->ntok && n < MAX_TOKENS_FLAT - 1; ++j) flat[n++] = s->tokens[j];
        }
        for (j = 0; j < n; ++j) {
            paralist *np = pj_mkparam(flat[j]);
            if (!pl) pl = curr = np;
            else { curr->next = np; curr = np; }
        }
        pending = d;
        P = pj_create_internal_from_params(pl, 1);
        pending = NULL;
        if (P) P->inverted = d->inv;
        free(d);
        return P;
    }
}
