void *pj_gauss_ini(double e, double phi0, double *chi, double *rc) {
    double sphi, cphi, es;
    struct GAUSS *en;
    if ((en = (struct GAUSS *)malloc(sizeof(struct GAUSS))) == NULL) return NULL;
    es = e * e;
    en->e = e;
    sphi = sin(phi0);
    cphi = cos(phi0);
    cphi *= cphi;
    *rc = sqrt(1. - es) / (1. - es * sphi * sphi);
    en->C = sqrt(1. + es * cphi * cphi / (1. - es));
    if (en->C == 0.0) { free(en); return NULL; }
    *chi = asin(sphi / en->C);
    en->ratexp = 0.5 * en->C * e;
    if ((en->K = tan(.5 * *chi + M_FORTPI) / (pow(tan(.5 * phi0 + M_FORTPI), en->C) * srat(en->e * sphi, en->ratexp))) == 0.0) {
