    slp.phi = 2. * atan(en->K * pow(tan(.5 * elp.phi + M_FORTPI), en->C) * srat(en->e * sin(elp.phi), en->ratexp)) - M_HALFPI;
    slp.lam = en->C * (elp.lam);
