PJ_LP pj_inv_gauss(PJ_LP slp, const void *en_) {
    const struct GAUSS *en = (const struct GAUSS *)en_;
    PJ_LP elp;
    double num;
    int i;
    elp.lam = slp.lam / en->C;
    num = pow(tan(.5 * slp.phi + M_FORTPI) / en->K, 1. / en->C);
    for (i = GMAX_ITER; i; --i) {
        elp.phi = 2. * atan(num * srat(en->e * sin(slp.phi), -.5 * en->e)) - M_HALFPI;
        if (fabs(elp.phi - slp.phi) < DEL_TOL) break;
