/* Mercator family */
#include "proj.h"

static PJ_XY merc_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    xy.x = P->k0 * lp.lam;
    xy.y = -P->k0 * log(pj_tsfn(lp.phi, sin(lp.phi), P->e));
    return xy;
}

static PJ_XY merc_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    if (fabs(fabs(lp.phi) - M_HALFPI) <= EPS10) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return xy;
    }
    xy.x = P->k0 * lp.lam;
    xy.y = P->k0 * asinh(tan(lp.phi));
    return xy;
}

static PJ_LP merc_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    lp.phi = atan(pj_sinhpsi2tanphi(sinh(xy.y / P->k0), P->e));
    lp.lam = xy.x / P->k0;
    return lp;
}

static PJ_LP merc_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    lp.phi = atan(sinh(xy.y / P->k0));
    lp.lam = xy.x / P->k0;
    return lp;
}

PJ *pj_merc_setup(PJ *P) {
    double phits = 0.0;
    int is_phits;
    if ((is_phits = pj_param(P->params, "tlat_ts").i)) {
        phits = fabs(pj_param(P->params, "rlat_ts").f);
        if (phits >= M_HALFPI) {
            proj_log_error(P, "Invalid value for lat_ts: |lat_ts| should be <= 90\xc2\xb0");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    }
    if (P->es != 0.0) {
        if (is_phits) P->k0 = pj_msfn(sin(phits), cos(phits), P->es);
        P->inv = merc_e_inverse;
        P->fwd = merc_e_forward;
    } else {
        if (is_phits) P->k0 = cos(phits);
        P->inv = merc_s_inverse;
        P->fwd = merc_s_forward;
    }
    return P;
}

PJ *pj_webmerc_setup(PJ *P) {
    P->inv = merc_s_inverse;
    P->fwd = merc_s_forward;
    return P;
