/* Transverse Mercator: exact (Poder/Engsager) and approximate (Evenden/Snyder) */
#include "proj.h"

#define PROJ_ETMERC_ORDER 6

struct tmerc_approx { double esp, ml0, *en; };
struct tmerc_exact { double Qn, Zb, cgb[6], cbg[6], utg[6], gtu[6]; };
struct tmerc_data { struct tmerc_approx approx; struct tmerc_exact exact; };

#define FC1 1.
#define FC2 .5
#define FC3 .16666666666666666666
#define FC4 .08333333333333333333
#define FC5 .05
#define FC6 .03333333333333333333
#define FC7 .02380952380952380952
#define FC8 .01785714285714285714

static void tmerc_destructor(PJ *P, int errlev) {
    struct tmerc_data *Q;
    if (!P) return;
    Q = (struct tmerc_data *)P->opaque;
    if (Q && Q->approx.en) free(Q->approx.en);
    pj_default_destructor(P, errlev);
}

static PJ_XY approx_e_fwd(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    const struct tmerc_approx *Q = &((struct tmerc_data *)P->opaque)->approx;
    double al, als, n, cosphi, sinphi, t;
    if (lp.lam < -M_HALFPI || lp.lam > M_HALFPI) {
        xy.x = HUGE_VAL; xy.y = HUGE_VAL;
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return xy;
    }
    sinphi = sin(lp.phi);
    cosphi = cos(lp.phi);
    t = fabs(cosphi) > 1e-10 ? sinphi / cosphi : 0.;
    t *= t;
    al = cosphi * lp.lam;
    als = al * al;
    al /= sqrt(1. - P->es * sinphi * sinphi);
    n = Q->esp * cosphi * cosphi;
    xy.x = P->k0 * al * (FC1 + FC3 * als * (1. - t + n + FC5 * als * (5. + t * (t - 18.) + n * (14. - 58. * t) + FC7 * als * (61. + t * (t * (179. - t) - 479.)))));
    xy.y = P->k0 * (pj_mlfn(lp.phi, sinphi, cosphi, Q->en) - Q->ml0 +
                    sinphi * al * lp.lam * FC2 * (1. + FC4 * als * (5. - t + n * (9. + 4. * n) + FC6 * als * (61. + t * (t - 58.) + n * (270. - 330 * t) + FC8 * als * (1385. + t * (t * (543. - t) - 3111.))))));
    return xy;
}

static PJ_XY approx_s_fwd(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    const struct tmerc_approx *Q = &((struct tmerc_data *)P->opaque)->approx;
    double b, cosphi;
    if (lp.lam < -M_HALFPI || lp.lam > M_HALFPI) {
        xy.x = HUGE_VAL; xy.y = HUGE_VAL;
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return xy;
    }
    cosphi = cos(lp.phi);
    b = cosphi * sin(lp.lam);
    if (fabs(fabs(b) - 1.) <= EPS10) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return xy;
    }
    xy.x = Q->ml0 * log((1. + b) / (1. - b));
    xy.y = cosphi * cos(lp.lam) / sqrt(1. - b * b);
    b = fabs(xy.y);
    if (b >= 1.) {
        if ((b - 1.) > EPS10) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        } else
            xy.y = 0.;
    } else
        xy.y = acos(xy.y);
    if (lp.phi < 0.) xy.y = -xy.y;
    xy.y = Q->esp * (xy.y - P->phi0);
    return xy;
}

static PJ_LP approx_e_inv(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    const struct tmerc_approx *Q = &((struct tmerc_data *)P->opaque)->approx;
    double n, con, cosphi, d, ds, sinphi, t;
    lp.phi = pj_inv_mlfn(Q->ml0 + xy.y / P->k0, Q->en);
    if (fabs(lp.phi) >= M_HALFPI) {
        lp.phi = xy.y < 0. ? -M_HALFPI : M_HALFPI;
        lp.lam = 0.;
    } else {
        sinphi = sin(lp.phi);
        cosphi = cos(lp.phi);
        t = fabs(cosphi) > 1e-10 ? sinphi / cosphi : 0.;
        n = Q->esp * cosphi * cosphi;
        d = xy.x * sqrt(con = 1. - P->es * sinphi * sinphi) / P->k0;
        con *= t;
        t *= t;
        ds = d * d;
        lp.phi -= (con * ds / (1. - P->es)) * FC2 * (1. - ds * FC4 * (5. + t * (3. - 9. * n) + n * (1. - 4 * n) - ds * FC6 * (61. + t * (90. - 252. * n + 45. * t) + 46. * n - ds * FC8 * (1385. + t * (3633. + t * (4095. + 1575. * t))))));
        lp.lam = d * (FC1 - ds * FC3 * (1. + 2. * t + n - ds * FC5 * (5. + t * (28. + 24. * t + 8. * n) + 6. * n - ds * FC7 * (61. + t * (662. + t * (1320. + 720. * t)))))) / cosphi;
    }
    return lp;
}

static PJ_LP approx_s_inv(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    const struct tmerc_approx *Q = &((struct tmerc_data *)P->opaque)->approx;
    double h, g;
    h = exp(xy.x / Q->esp);
    if (h == 0) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    g = .5 * (h - 1. / h);
    h = cos(P->phi0 + xy.y / Q->esp);
    lp.phi = asin(sqrt((1. - h * h) / (1. + g * g)));
    if (xy.y < 0. && -lp.phi + P->phi0 < 0.0) lp.phi = -lp.phi;
    lp.lam = (g != 0.0 || h != 0.0) ? atan2(g, h) : 0.;
    return lp;
}

static double gatg(const double *p1, int len_p1, double B, double cos_2B, double sin_2B) {
    double h = 0, h1, h2 = 0;
    const double two_cos_2B = 2 * cos_2B;
    const double *p = p1 + len_p1;
    h1 = *--p;
    while (p - p1) {
        h = -h2 + two_cos_2B * h1 + *--p;
        h2 = h1;
        h1 = h;
    }
    return (B + h * sin_2B);
}

static double clenS(const double *a, int size, double sin_arg_r, double cos_arg_r, double sinh_arg_i,
                    double cosh_arg_i, double *R, double *I) {
    double r, i, hr, hr1, hr2, hi, hi1, hi2;
    const double *p = a + size;
    r = 2 * cos_arg_r * cosh_arg_i;
    i = -2 * sin_arg_r * sinh_arg_i;
    hi1 = hr1 = hi = 0;
    hr = *--p;
    for (; a - p;) {
        hr2 = hr1;
        hi2 = hi1;
        hr1 = hr;
        hi1 = hi;
        hr = -hr2 + r * hr1 - i * hi1 + *--p;
        hi = -hi2 + i * hr1 + r * hi1;
    }
    r = sin_arg_r * cosh_arg_i;
    i = cos_arg_r * sinh_arg_i;
    *R = r * hr - i * hi;
    *I = r * hi + i * hr;
    return *R;
}

static double clens(const double *a, int size, double arg_r) {
    double r, hr, hr1, hr2, cos_arg_r;
    const double *p = a + size;
    cos_arg_r = cos(arg_r);
    r = 2 * cos_arg_r;
    hr1 = 0;
    hr = *--p;
    for (; a - p;) {
        hr2 = hr1;
        hr1 = hr;
        hr = -hr2 + r * hr1 + *--p;
    }
    return sin(arg_r) * hr;
}

static PJ_XY exact_e_fwd(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    const struct tmerc_exact *Q = &((struct tmerc_data *)P->opaque)->exact;
    double Cn = gatg(Q->cbg, PROJ_ETMERC_ORDER, lp.phi, cos(2 * lp.phi), sin(2 * lp.phi));
    const double sin_Cn = sin(Cn);
    const double cos_Cn = cos(Cn);
    const double sin_Ce = sin(lp.lam);
    const double cos_Ce = cos(lp.lam);
    const double cos_Cn_cos_Ce = cos_Cn * cos_Ce;
    double inv_denom_tan_Ce, tan_Ce, Ce, two_inv_denom_tan_Ce, two_inv_denom_tan_Ce_square, tmp_r,
        sin_arg_r, cos_arg_r, sinh_arg_i, cosh_arg_i, dCn, dCe;
    Cn = atan2(sin_Cn, cos_Cn_cos_Ce);
    inv_denom_tan_Ce = 1. / hypot(sin_Cn, cos_Cn_cos_Ce);
    tan_Ce = sin_Ce * cos_Cn * inv_denom_tan_Ce;
    Ce = asinh(tan_Ce);
    two_inv_denom_tan_Ce = 2 * inv_denom_tan_Ce;
    two_inv_denom_tan_Ce_square = two_inv_denom_tan_Ce * inv_denom_tan_Ce;
    tmp_r = cos_Cn_cos_Ce * two_inv_denom_tan_Ce_square;
    sin_arg_r = sin_Cn * tmp_r;
    cos_arg_r = cos_Cn_cos_Ce * tmp_r - 1;
    sinh_arg_i = tan_Ce * two_inv_denom_tan_Ce;
    cosh_arg_i = two_inv_denom_tan_Ce_square - 1;
    Cn += clenS(Q->gtu, PROJ_ETMERC_ORDER, sin_arg_r, cos_arg_r, sinh_arg_i, cosh_arg_i, &dCn, &dCe);
    Ce += dCe;
    if (fabs(Ce) <= 2.623395162778) {
        xy.y = Q->Qn * Cn + Q->Zb;
        xy.x = Q->Qn * Ce;
    } else {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        xy.x = xy.y = HUGE_VAL;
    }
    return xy;
}

static PJ_LP exact_e_inv(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    const struct tmerc_exact *Q = &((struct tmerc_data *)P->opaque)->exact;
    double Cn = (xy.y - Q->Zb) / Q->Qn;
    double Ce = xy.x / Q->Qn;
    if (fabs(Ce) <= 2.623395162778) {
        const double sin_arg_r = sin(2 * Cn);
        const double cos_arg_r = cos(2 * Cn);
        const double exp_2_Ce = exp(2 * Ce);
        const double half_inv_exp_2_Ce = 0.5 / exp_2_Ce;
        const double sinh_arg_i = 0.5 * exp_2_Ce - half_inv_exp_2_Ce;
        const double cosh_arg_i = 0.5 * exp_2_Ce + half_inv_exp_2_Ce;
        double dCn_ignored, dCe, sin_Cn, cos_Cn, sinhCe, modulus_Ce, tmp, sin_2_Cn, cos_2_Cn;
        Cn += clenS(Q->utg, PROJ_ETMERC_ORDER, sin_arg_r, cos_arg_r, sinh_arg_i, cosh_arg_i, &dCn_ignored, &dCe);
        Ce += dCe;
        sin_Cn = sin(Cn);
        cos_Cn = cos(Cn);
        sinhCe = sinh(Ce);
        Ce = atan2(sinhCe, cos_Cn);
        modulus_Ce = hypot(sinhCe, cos_Cn);
        Cn = atan2(sin_Cn, modulus_Ce);
        tmp = 2 * modulus_Ce / (sinhCe * sinhCe + 1);
        sin_2_Cn = sin_Cn * tmp;
        cos_2_Cn = tmp * modulus_Ce - 1.;
        lp.phi = gatg(Q->cgb, PROJ_ETMERC_ORDER, Cn, cos_2_Cn, sin_2_Cn);
        lp.lam = Ce;
    } else {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        lp.phi = lp.lam = HUGE_VAL;
    }
    return lp;
}

static PJ_XY auto_e_fwd(PJ_LP lp, PJ *P) {
    if (fabs(lp.lam) > 3 * DEG_TO_RAD) return exact_e_fwd(lp, P);
    return approx_e_fwd(lp, P);
}
static PJ_LP auto_e_inv(PJ_XY xy, PJ *P) {
    if (fabs(xy.x) > 334000 * (P->k0 / 0.9996)) return exact_e_inv(xy, P);
    return approx_e_inv(xy, P);
}

static PJ *setup_approx(PJ *P) {
    struct tmerc_approx *Q = &((struct tmerc_data *)P->opaque)->approx;
    if (P->es != 0.0) {
        if (!(Q->en = pj_enfn(P->n))) return pj_default_destructor(P, PROJ_ERR_OTHER);
        Q->ml0 = pj_mlfn(P->phi0, sin(P->phi0), cos(P->phi0), Q->en);
        Q->esp = P->es / (1. - P->es);
        P->inv = approx_e_inv;
        P->fwd = approx_e_fwd;
    } else {
        Q->esp = P->k0;
        Q->ml0 = .5 * Q->esp;
        P->inv = approx_s_inv;
        P->fwd = approx_s_fwd;
    }
    return P;
}

static PJ *setup_exact(PJ *P) {
