    Q->Qn = P->k0 / (1 + n) * (1 + np * (1 / 4.0 + np * (1 / 64.0 + np / 256.0)));
    Q->utg[0] = n * (-0.5 + n * (2 / 3.0 + n * (-37 / 96.0 + n * (1 / 360.0 + n * (81 / 512.0 + n * (-96199 / 604800.0))))));
    Q->gtu[0] = n * (0.5 + n * (-2 / 3.0 + n * (5 / 16.0 + n * (41 / 180.0 + n * (-127 / 288.0 + n * (7891 / 37800.0))))));
    Q->utg[1] = np * (-1 / 48.0 + n * (-1 / 15.0 + n * (437 / 1440.0 + n * (-46 / 105.0 + n * (1118711 / 3870720.0)))));
    Q->gtu[1] = np * (13 / 48.0 + n * (-3 / 5.0 + n * (557 / 1440.0 + n * (281 / 630.0 + n * (-1983433 / 1935360.0)))));
    np *= n;
    Q->utg[2] = np * (-17 / 480.0 + n * (37 / 840.0 + n * (209 / 4480.0 + n * (-5569 / 90720.0))));
    Q->gtu[2] = np * (61 / 240.0 + n * (-103 / 140.0 + n * (15061 / 26880.0 + n * (167603 / 181440.0))));
    np *= n;
    Q->utg[3] = np * (-4397 / 161280.0 + n * (11 / 504.0 + n * (830251 / 7257600.0)));
    Q->gtu[3] = np * (49561 / 161280.0 + n * (-179 / 168.0 + n * (6601661 / 7257600.0)));
    np *= n;
    Q->utg[4] = np * (-4583 / 161280.0 + n * (108847 / 3991680.0));
    Q->gtu[4] = np * (34729 / 80640.0 + n * (-3418889 / 1995840.0));
    np *= n;
    Q->utg[5] = np * (-20648693 / 638668800.0);
    Q->gtu[5] = np * (212378941 / 319334400.0);

    Z = gatg(Q->cbg, PROJ_ETMERC_ORDER, P->phi0, cos(2 * P->phi0), sin(2 * P->phi0));
    Q->Zb = -Q->Qn * (Z + clens(Q->gtu, PROJ_ETMERC_ORDER, 2 * Z));
    P->fwd = exact_e_fwd;
    P->inv = exact_e_inv;
    return P;
}

enum TMercAlgo { TM_AUTO, TM_EVENDEN_SNYDER, TM_PODER_ENGSAGER };

static PJ *tmerc_setup_common(PJ *P, enum TMercAlgo alg) {
    struct tmerc_data *Q = (struct tmerc_data *)calloc(1, sizeof(struct tmerc_data));
    if (!Q) return pj_default_destructor(P, PROJ_ERR_OTHER);
    P->opaque = Q;
    P->destructor = tmerc_destructor;
    if (P->es == 0) alg = TM_EVENDEN_SNYDER;
    switch (alg) {
    case TM_EVENDEN_SNYDER:
        return setup_approx(P);
    case TM_PODER_ENGSAGER:
        return setup_exact(P);
    case TM_AUTO:
        if (!setup_approx(P)) return NULL;
        if (!setup_exact(P)) return NULL;
        P->fwd = auto_e_fwd;
        P->inv = auto_e_inv;
        return P;
    }
    return P;
}

static int get_algo(PJ *P, enum TMercAlgo *alg) {
    *alg = TM_PODER_ENGSAGER;
    if (pj_param(P->params, "bapprox").i)
        *alg = TM_EVENDEN_SNYDER;
    else {
        const char *algo_name = pj_param(P->params, "salgo").s;
        if (algo_name) {
            if (strcmp(algo_name, "evenden_snyder") == 0) *alg = TM_EVENDEN_SNYDER;
            else if (strcmp(algo_name, "poder_engsager") == 0) *alg = TM_PODER_ENGSAGER;
            else if (strcmp(algo_name, "auto") == 0) *alg = TM_AUTO;
            else {
                proj_log_error(P, "unknown value for +algo");
                return 1;
            }
        }
    }
    return 0;
}

PJ *pj_tmerc_setup(PJ *P) {
    enum TMercAlgo alg;
    if (get_algo(P, &alg)) return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    return tmerc_setup_common(P, alg);
}

PJ *pj_etmerc_setup(PJ *P) {
    if (P->es == 0.0) {
        proj_log_error(P, "Invalid value for eccentricity: it should not be zero");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    return tmerc_setup_common(P, TM_PODER_ENGSAGER);
}

PJ *pj_utm_setup(PJ *P) {
    long zone;
    enum TMercAlgo alg;
    if (P->es == 0.0) {
        proj_log_error(P, "Invalid value for eccentricity: it should not be zero");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    if (P->lam0 < -1000.0 || P->lam0 > 1000.0) {
        proj_log_error(P, "Invalid value for lon_0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    P->y0 = pj_param(P->params, "bsouth").i ? 10000000. : 0.;
    P->x0 = 500000.;
    if (pj_param(P->params, "tzone").i) {
        zone = pj_param(P->params, "izone").i;
        if (zone > 0 && zone <= 60)
            --zone;
        else {
            proj_log_error(P, "Invalid value for zone");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    } else {
        zone = lround((floor((adjlon(P->lam0) + M_PI) * 30. / M_PI)));
        if (zone < 0) zone = 0;
        else if (zone >= 60) zone = 59;
    }
    P->lam0 = (zone + .5) * M_PI / 30. - M_PI;
    P->k0 = 0.9996;
    P->phi0 = 0.;
    if (get_algo(P, &alg)) return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    return tmerc_setup_common(P, alg);
}
