/* Scale factor computations */
#include "proj.h"

#define DEFAULT_H 1e-5
#define FEPS 1.0e-12

struct DERIVS { double x_l, x_p, y_l, y_p; };

static int pj_deriv(PJ_LP lp, double h, PJ *P, struct DERIVS *der) {
    PJ_XY t;
    double scale = P->to_meter / P->a;
    lp.lam += h;
    lp.phi += h;
    if (fabs(lp.phi) > M_HALFPI) return 1;
    h += h;
    t = pj_fwd(lp, P);
    if (t.x == HUGE_VAL) return 1;
    der->x_l = t.x; der->y_p = t.y; der->x_p = -t.x; der->y_l = -t.y;
    lp.phi -= h;
    if (fabs(lp.phi) > M_HALFPI) return 1;
    t = pj_fwd(lp, P);
    if (t.x == HUGE_VAL) return 1;
    der->x_l += t.x; der->y_p -= t.y; der->x_p += t.x; der->y_l -= t.y;
    lp.lam -= h;
    t = pj_fwd(lp, P);
    if (t.x == HUGE_VAL) return 1;
    der->x_l -= t.x; der->y_p -= t.y; der->x_p += t.x; der->y_l += t.y;
    lp.phi += h;
    t = pj_fwd(lp, P);
    if (t.x == HUGE_VAL) return 1;
    der->x_l -= t.x; der->y_p += t.y; der->x_p -= t.x; der->y_l += t.y;
    der->x_l /= (h += h);
    der->y_p /= h;
    der->x_p /= h;
    der->y_l /= h;
    der->x_l *= scale; der->y_p *= scale; der->x_p *= scale; der->y_l *= scale;
    return 0;
}

int proj_factors(PJ *P, PJ_COORD coo, PJ_FACTORS *fac) {
    double cosphi, t, n, r, h = DEFAULT_H;
    double hh, k, s, thetap, conv, a, b, omega;
    struct DERIVS der;
    PJ_LP lp = coo.lp;
    PJ_COORD c2;

    memset(fac, 0, sizeof(*fac));
    if (!P) return 1;
    if (HUGE_VAL == lp.lam) return 1;

    /* geocentric latitude input: convert to geographic */
    c2 = coo;
    if (P->geoc) lp = pj_geocentric_latitude(P, PJ_INV, c2).lp;

    if (fabs(lp.phi) > (M_HALFPI - h))
        lp.phi = lp.phi < 0 ? -(M_HALFPI - h) : (M_HALFPI - h);

    if (pj_deriv(lp, h, P, &der)) {
        if (!proj_errno(P)) proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return 1;
    }

    cosphi = cos(lp.phi);
    hh = hypot(der.x_p, der.y_p);
    k = hypot(der.x_l, der.y_l) / cosphi;
    if (P->es != 0.0) {
        t = sin(lp.phi);
        t = 1. - P->es * t * t;
        n = sqrt(t);
        hh *= t * n / P->one_es;
        k *= n;
        r = t * t / P->one_es;
    } else
        r = 1.;

    conv = -atan2(der.x_p, der.y_p);
    s = (der.y_p * der.x_l - der.x_p * der.y_l) * r / cosphi;
    thetap = aasin(s / (hh * k));
    t = k * k + hh * hh;
    a = sqrt(t + 2. * s);
    t = t - 2. * s;
    t = t > 0 ? sqrt(t) : 0;
    b = 0.5 * (a - t);
    a = 0.5 * (a + t);
    omega = 2. * aasin((a - b) / (a + b));

    fac->meridional_scale = hh;
    fac->parallel_scale = k;
    fac->areal_scale = s;
    fac->angular_distortion = omega;
    fac->meridian_parallel_angle = thetap;
    fac->meridian_convergence = conv;
    fac->tissot_semimajor = a;
    fac->tissot_semiminor = b;
    fac->dx_dlam = der.x_l;
    fac->dx_dphi = der.x_p;
    fac->dy_dlam = der.y_l;
    fac->dy_dphi = der.y_p;
    return 0;
}
