        R00 = cg * ch; R01 = cf * sh + sf * sg * ch; R02 = sf * sh - cf * sg * ch;
        R10 = -cg * sh; R11 = cf * ch - sf * sg * sh; R12 = sf * ch + cf * sg * sh;
        R20 = sg; R21 = -sf * cg; R22 = cf * cg;
        /* position vector: transpose */
        {
            double t;
            t = R01; R01 = R10; R10 = t;
            t = R02; R02 = R20; R20 = t;
            t = R12; R12 = R21; R21 = t;
        }
        scale = d[6];
    }
    if (direction == PJ_FWD) {
        out.xyz.x = scale * (R00 * x + R01 * y + R02 * z) + d[0];
        out.xyz.y = scale * (R10 * x + R11 * y + R12 * z) + d[1];
        out.xyz.z = scale * (R20 * x + R21 * y + R22 * z) + d[2];
    } else {
        x = (x - d[0]) / scale;
        y = (y - d[1]) / scale;
        z = (z - d[2]) / scale;
        out.xyz.x = R00 * x + R10 * y + R20 * z;
        out.xyz.y = R01 * x + R11 * y + R21 * z;
        out.xyz.z = R02 * x + R12 * y + R22 * z;
    }
    return out;
}

static PJ_COORD datum_to_local(PJ *P, PJ_COORD coo) {
    /* WGS84 angular -> local angular */
    PJ_COORD c = coo;
    c.xyz = pj_geodetic_to_geocentric(coo.lpz, WGS84_A, WGS84_ES);
    c = helmert_apply(P, PJ_INV, c);
    c.lpz = pj_geocentric_to_geodetic(c.xyz, P->a, P->es);
    return c;
}

static PJ_COORD datum_to_wgs84(PJ *P, PJ_COORD coo) {
    PJ_COORD c = coo;
    c.xyz = pj_geodetic_to_geocentric(coo.lpz, P->a, P->es);
    c = helmert_apply(P, PJ_FWD, c);
    c.lpz = pj_geocentric_to_geodetic(c.xyz, WGS84_A, WGS84_ES);
    return c;
}

PJ_COORD pj_axisswap_apply(const char *axis, int direction, PJ_COORD coo) {
    int i, order[3];
