        case 'n': order[i] = 1; sign[i] = 1; break;
        case 's': order[i] = 1; sign[i] = -1; break;
        case 'u': order[i] = 2; sign[i] = 1; break;
        case 'd': order[i] = 2; sign[i] = -1; break;
        default: order[i] = i; sign[i] = 1; break;
        }
