    out = coo;
    if (direction == PJ_FWD) {
        for (i = 0; i < 3; ++i) out.v[i] = coo.v[order[i]] * sign[i];
    } else {
        for (i = 0; i < 3; ++i) out.v[order[i]] = coo.v[i] * sign[i];
    }
    return out;
}

