/* Geodetic <-> geocentric conversions, and the cart, latlong, noop, axisswap, unitconvert operations */
#include "proj.h"

static double normal_radius_of_curvature(double a, double es, double sinphi) {
    if (es == 0) return a;
    return a / sqrt(1 - es * sinphi * sinphi);
}

static double geocentric_radius(double a, double b, double cosphi, double sinphi) {
    return hypot(a * a * cosphi, b * b * sinphi) / hypot(a * cosphi, b * sinphi);
}

PJ_XYZ pj_geodetic_to_geocentric(PJ_LPZ geod, double a, double es) {
    PJ_XYZ xyz;
    const double cosphi = cos(geod.phi);
    const double sinphi = sin(geod.phi);
    const double N = normal_radius_of_curvature(a, es, sinphi);
    xyz.x = (N + geod.z) * cosphi * cos(geod.lam);
    xyz.y = (N + geod.z) * cosphi * sin(geod.lam);
    xyz.z = (N * (1 - es) + geod.z) * sinphi;
    return xyz;
}

PJ_LPZ pj_geocentric_to_geodetic(PJ_XYZ cart, double a, double es) {
    PJ_LPZ lpz;
    const double b = a * sqrt(1 - es);
    const double e2s = es / (1 - es);
    const double p = hypot(cart.x, cart.y);
    const double theta = atan2(cart.z * a, p * b);
    const double c = cos(theta);
    const double s = sin(theta);
    double N, cosphi;
    lpz.phi = atan2(cart.z + e2s * b * s * s * s, p - es * a * c * c * c);
    lpz.lam = atan2(cart.y, cart.x);
    N = normal_radius_of_curvature(a, es, sin(lpz.phi));
    cosphi = cos(lpz.phi);
    if (fabs(cosphi) < 1e-6) {
        const double r = geocentric_radius(a, b, cosphi, sin(lpz.phi));
        lpz.z = fabs(cart.z) - r;
    } else
        lpz.z = p / cosphi - N;
    return lpz;
}

/* ---- cart ---- */
static PJ_XYZ cart_forward(PJ_LPZ lpz, PJ *P) { return pj_geodetic_to_geocentric(lpz, P->a, P->es); }
static PJ_LPZ cart_inverse(PJ_XYZ xyz, PJ *P) { return pj_geocentric_to_geodetic(xyz, P->a, P->es); }

PJ *pj_cart_setup(PJ *P) {
    P->fwd3d = cart_forward;
    P->inv3d = cart_inverse;
    P->left = PJ_IO_UNITS_RADIANS;
    P->right = PJ_IO_UNITS_CARTESIAN;
    return P;
}

/* ---- latlong family ---- */
static PJ_XY latlong_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    (void)P;
    xy.x = lp.lam;
    xy.y = lp.phi;
    return xy;
}
static PJ_LP latlong_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    (void)P;
    lp.lam = xy.x;
    lp.phi = xy.y;
    return lp;
}
static PJ *latlong_setup(PJ *P) {
    P->x0 = 0;
    P->y0 = 0;
    P->fwd = latlong_forward;
    P->inv = latlong_inverse;
    P->left = PJ_IO_UNITS_RADIANS;
    P->right = PJ_IO_UNITS_RADIANS;
    return P;
}
PJ *pj_latlong_setup(PJ *P) { return latlong_setup(P); }
PJ *pj_longlat_setup(PJ *P) { return latlong_setup(P); }
PJ *pj_latlon_setup(PJ *P) { return latlong_setup(P); }
PJ *pj_lonlat_setup(PJ *P) { return latlong_setup(P); }

/* ---- noop ---- */
static PJ_COORD noop_op(PJ_COORD c, PJ *P) { (void)P; return c; }
PJ *pj_noop_setup(PJ *P) {
    P->fwd4d = noop_op;
    P->inv4d = noop_op;
    P->left = PJ_IO_UNITS_WHATEVER;
    P->right = PJ_IO_UNITS_WHATEVER;
    return P;
}

/* ---- axisswap ---- */
struct axisswap_data { int axis[4]; double sign[4]; };

static int sign_of(int x) { return (x > 0) - (x < 0); }

static PJ_COORD axisswap_forward_4d(PJ_COORD coo, PJ *P) {
    struct axisswap_data *Q = (struct axisswap_data *)P->opaque;
    PJ_COORD out;
    int i;
    for (i = 0; i < 4; ++i) out.v[i] = coo.v[Q->axis[i]] * Q->sign[i];
    return out;
}
static PJ_COORD axisswap_reverse_4d(PJ_COORD coo, PJ *P) {
    struct axisswap_data *Q = (struct axisswap_data *)P->opaque;
    PJ_COORD out;
    int i;
    for (i = 0; i < 4; ++i) out.v[Q->axis[i]] = coo.v[i] * Q->sign[i];
    return out;
}

PJ *pj_axisswap_setup(PJ *P) {
    struct axisswap_data *Q = (struct axisswap_data *)calloc(1, sizeof(struct axisswap_data));
    const char *s;
    int i, n = 0;
    P->opaque = Q;
    P->left = PJ_IO_UNITS_WHATEVER;
    P->right = PJ_IO_UNITS_WHATEVER;
    P->skip_fwd_prepare = P->skip_fwd_finalize = 1;
    P->skip_inv_prepare = P->skip_inv_finalize = 1;
    for (i = 0; i < 4; ++i) { Q->axis[i] = i; Q->sign[i] = 1; }

    if ((s = pj_param(P->params, "saxis").s) != NULL) {
        n = (int)strlen(s);
        if (n < 2 || n > 3) {
            proj_log_error(P, "axisswap: Invalid value for axis");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        for (i = 0; i < n; ++i) {
            switch (s[i]) {
            case 'w': Q->sign[i] = -1; /* fall through */
            case 'e': Q->axis[i] = 0; break;
            case 's': Q->sign[i] = -1; /* fall through */
            case 'n': Q->axis[i] = 1; break;
            case 'd': Q->sign[i] = -1; /* fall through */
            case 'u': Q->axis[i] = 2; break;
            default:
                proj_log_error(P, "axisswap: Invalid value for axis");
                return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
            }
        }
        if (pj_param_exists(P->params, "order")) {
            proj_log_error(P, "axisswap: must provide EITHER 'order' OR 'axis' parameter.");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MUTUALLY_EXCLUSIVE_ARGS);
        }
    } else if ((s = pj_param(P->params, "sorder").s) != NULL) {
        char *str = pj_strdup(s), *tok, *save;
        n = 0;
        tok = str;
        for (save = str; *save; ++save) ;
        tok = strtok(str, ",");
        while (tok && n < 4) {
            int v = atoi(tok);
            if (v == 0 || v > 4 || v < -4) {
                free(str);
                proj_log_error(P, "axisswap: Invalid value for order");
                return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
            }
            Q->axis[n] = abs(v) - 1;
            Q->sign[n] = sign_of(v);
            n++;
            tok = strtok(NULL, ",");
        }
        free(str);
        if (n < 2 || n > 4) {
            proj_log_error(P, "axisswap: Invalid value for order");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        /* check that all axes are unique */
        for (i = 0; i < n; ++i) {
            int j;
            for (j = i + 1; j < n; ++j)
                if (Q->axis[i] == Q->axis[j]) {
                    proj_log_error(P, "axisswap: Invalid value for order");
                    return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
                }
        }
    } else {
        proj_log_error(P, "axisswap: must provide EITHER 'order' OR 'axis' parameter.");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MUTUALLY_EXCLUSIVE_ARGS);
    }
    for (i = n; i < 4; ++i) { Q->axis[i] = i; Q->sign[i] = 1; }
    P->fwd4d = axisswap_forward_4d;
    P->inv4d = axisswap_reverse_4d;
    return P;
}
