/* unitconvert operation */
#include "proj.h"

struct unitconvert_data { double xy_factor, z_factor; int xy_in_is_linear, xy_out_is_linear; };

static const PJ_UNITS pj_angular_units[] = {
    {"rad", "1.0", "Radian", 1.0},
    {"deg", "0.017453292519943296", "Degree", 0.017453292519943296},
    {"grad", "0.015707963267948967", "Grad", 0.015707963267948967},
    {NULL, NULL, NULL, 0.0}
};

/* returns factor to convert to base unit (metre / radian); sets *is_linear; returns 0 if unknown */
static double get_unit_factor(const char *name, int *is_linear, int *is_angular) {
    int i;
    char *end;
    double v;
    *is_linear = 0; *is_angular = 0;
    for (i = 0; pj_units[i].id; ++i) {
        if (!strcmp(pj_units[i].id, name)) {
            *is_linear = 1;
            return pj_units[i].factor;
        }
    }
    for (i = 0; pj_angular_units[i].id; ++i) {
        if (!strcmp(pj_angular_units[i].id, name)) {
            *is_angular = 1;
            return pj_angular_units[i].factor;
        }
    }
    v = strtod(name, &end);
    if (end != name && *end == '\0' && v > 0) {
        *is_linear = 1;
        return v;
    }
    return 0.0;
}

static PJ_COORD unitconvert_forward(PJ_COORD c, PJ *P) {
    struct unitconvert_data *Q = (struct unitconvert_data *)P->opaque;
    c.xyz.x *= Q->xy_factor;
    c.xyz.y *= Q->xy_factor;
    c.xyz.z *= Q->z_factor;
    return c;
}
static PJ_COORD unitconvert_reverse(PJ_COORD c, PJ *P) {
    struct unitconvert_data *Q = (struct unitconvert_data *)P->opaque;
    c.xyz.x /= Q->xy_factor;
    c.xyz.y /= Q->xy_factor;
    c.xyz.z /= Q->z_factor;
    return c;
}

PJ *pj_unitconvert_setup(PJ *P) {
    struct unitconvert_data *Q = (struct unitconvert_data *)calloc(1, sizeof(struct unitconvert_data));
    const char *name;
    double f_in = 1.0, f_out = 1.0;
    int lin_in = 1, lin_out = 1, ang_in = 0, ang_out = 0;
    P->opaque = Q;
    P->fwd4d = unitconvert_forward;
    P->inv4d = unitconvert_reverse;
    P->left = PJ_IO_UNITS_WHATEVER;
    P->right = PJ_IO_UNITS_WHATEVER;
    P->skip_fwd_prepare = P->skip_fwd_finalize = 1;
    P->skip_inv_prepare = P->skip_inv_finalize = 1;
    Q->xy_factor = 1.0;
    Q->z_factor = 1.0;

    if ((name = pj_param(P->params, "sxy_in").s) != NULL) {
        f_in = get_unit_factor(name, &lin_in, &ang_in);
        if (f_in == 0.0) {
            proj_log_error(P, "unknown xy_in unit");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        if (ang_in) P->left = !strcmp(name, "rad") ? PJ_IO_UNITS_RADIANS : PJ_IO_UNITS_DEGREES;
    }
    if ((name = pj_param(P->params, "sxy_out").s) != NULL) {
        f_out = get_unit_factor(name, &lin_out, &ang_out);
        if (f_out == 0.0) {
            proj_log_error(P, "unknown xy_out unit");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        if (ang_out) P->right = !strcmp(name, "rad") ? PJ_IO_UNITS_RADIANS : PJ_IO_UNITS_DEGREES;
    }
    if (ang_in != ang_out && pj_param_exists(P->params, "xy_in") && pj_param_exists(P->params, "xy_out")) {
        proj_log_error(P, "Inconsistent unit type between input and output");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MUTUALLY_EXCLUSIVE_ARGS);
    }
    Q->xy_factor = f_in / f_out;
    if (fabs(Q->xy_factor - 1.0) < 1e-15) Q->xy_factor = 1.0;

    f_in = f_out = 1.0;
    if ((name = pj_param(P->params, "sz_in").s) != NULL) {
        f_in = get_unit_factor(name, &lin_in, &ang_in);
        if (f_in == 0.0 || !lin_in) {
            proj_log_error(P, "unknown z_in unit");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    }
    if ((name = pj_param(P->params, "sz_out").s) != NULL) {
        f_out = get_unit_factor(name, &lin_out, &ang_out);
        if (f_out == 0.0 || !lin_out) {
            proj_log_error(P, "unknown z_out unit");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    }
    Q->z_factor = f_in / f_out;
    if (fabs(Q->z_factor - 1.0) < 1e-15) Q->z_factor = 1.0;
    return P;
}
