    sinphi = sin(lp.phi);
    cosphi = cos(lp.phi);
    xy.y = pj_mlfn(lp.phi, sinphi, cosphi, Q->en);
    n = 1. / sqrt(1. - P->es * sinphi * sinphi);
    tanphi = tan(lp.phi);
    t = tanphi * tanphi;
    a1 = lp.lam * cosphi;
    c = cosphi * cosphi * P->es / (1 - P->es);
    a2 = a1 * a1;
    tn = tanphi * n;
    xy.x = n * a1 * (1. - a2 * t * (CASS_C1 - (8. - t + 8. * c) * a2 * CASS_C2));
    xy.y -= Q->m0 - tn * a2 * (.5 + (5. - t + 6. * c) * a2 * CASS_C3);
    if (Q->hyperbolic) xy.y -= tn * a2 * a1 * a1 * a1 * a1 / 6.0 * 0 ; /* placeholder, replaced below */
    return xy;
}
static PJ_XY cass_e_forward_full(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct cass_data *Q = (struct cass_data *)P->opaque;
    double sinphi, cosphi, n, tanphi, t, a1, c, a2, tn, rho;
    sinphi = sin(lp.phi);
    cosphi = cos(lp.phi);
    xy.y = pj_mlfn(lp.phi, sinphi, cosphi, Q->en);
    n = 1. / sqrt(1. - P->es * sinphi * sinphi);
    tanphi = tan(lp.phi);
    t = tanphi * tanphi;
    a1 = lp.lam * cosphi;
    c = cosphi * cosphi * P->es / (1 - P->es);
    a2 = a1 * a1;
    tn = tanphi * n;
    xy.x = n * a1 * (1. - a2 * t * (CASS_C1 - (8. - t + 8. * c) * a2 * CASS_C2));
    xy.y -= Q->m0 - tn * a2 * (.5 + (5. - t + 6. * c) * a2 * CASS_C3);
    if (Q->hyperbolic) {
        rho = n * (1. - P->es) / (1. - P->es * sinphi * sinphi);
