}
static PJ_XY cass_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    xy.x = asin(cos(lp.phi) * sin(lp.lam));
    xy.y = atan2(tan(lp.phi), cos(lp.lam)) - P->phi0;
    return xy;
}
static PJ_LP cass_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct cass_data *Q = (struct cass_data *)P->opaque;
    double n, t, r, dd, d2, tn, ph1, sinph1, cosph1;
    ph1 = pj_inv_mlfn(Q->m0 + xy.y, Q->en);
    sinph1 = sin(ph1);
    cosph1 = cos(ph1);
    tn = tan(ph1);
    t = tn * tn;
    n = sin(ph1);
    r = 1. / (1. - P->es * n * n);
    n = sqrt(r);
    r *= (1. - P->es) * n;
    dd = xy.x / n;
    d2 = dd * dd;
    lp.phi = ph1 - (n * tn / r) * d2 * (.5 - (1. + 3. * t) * d2 * CASS_C3);
    lp.lam = dd * (1. + t * d2 * (-CASS_C4 + (1. + 3. * t) * d2 * CASS_C5)) / cosph1;
    (void)sinph1;
    return lp;
}
static PJ_LP cass_e_inverse_full(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct cass_data *Q = (struct cass_data *)P->opaque;
    double n, t, r, dd, d2, tn, ph1, cosph1, rho;
    ph1 = pj_inv_mlfn(Q->m0 + xy.y, Q->en);
    cosph1 = cos(ph1);
    tn = tan(ph1);
    t = tn * tn;
    n = sin(ph1);
    r = 1. / (1. - P->es * n * n);
    n = sqrt(r);
    r *= (1. - P->es) * n;
    dd = xy.x / n;
    if (Q->hyperbolic) {
        rho = r;
        /* hyperbolic correction (Vincenty) */
        {
            double y = xy.y + (xy.x * xy.x * xy.x) / (6 * rho * n);
            ph1 = pj_inv_mlfn(Q->m0 + y, Q->en);
            cosph1 = cos(ph1);
            tn = tan(ph1);
            t = tn * tn;
            n = sin(ph1);
            r = 1. / (1. - P->es * n * n);
            n = sqrt(r);
            r *= (1. - P->es) * n;
            dd = xy.x / n;
        }
    }
    d2 = dd * dd;
    lp.phi = ph1 - (n * tn / r) * d2 * (.5 - (1. + 3. * t) * d2 * CASS_C3);
    lp.lam = dd * (1. + t * d2 * (-CASS_C4 + (1. + 3. * t) * d2 * CASS_C5)) / cosph1;
