}
static PJ_LP cass_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    double dd;
    dd = xy.y + P->phi0;
    lp.phi = asin(sin(dd) * cos(xy.x));
    lp.lam = atan2(tan(xy.x), cos(dd));
    return lp;
}
PJ *pj_cass_setup(PJ *P) {
    struct cass_data *Q = (struct cass_data *)calloc(1, sizeof(struct cass_data));
    P->opaque = Q;
    P->destructor = cass_destructor;
    if (P->es != 0.0) {
        if (!(Q->en = pj_enfn(P->n))) return pj_default_destructor(P, PROJ_ERR_OTHER);
        Q->m0 = pj_mlfn(P->phi0, sin(P->phi0), cos(P->phi0), Q->en);
        Q->hyperbolic = pj_param(P->params, "bhyperbolic").i;
        P->inv = cass_e_inverse_full;
        P->fwd = cass_e_forward_full;
    } else {
        P->inv = cass_s_inverse;
        P->fwd = cass_s_forward;
    }
    (void)cass_e_forward; (void)cass_e_inverse;
    return P;
}
