/* ---------------- times ---------------- */
static PJ_XY times_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    double T, S, S2;
    (void)P;
    T = tan(lp.phi / 2.0);
    S = sin(M_FORTPI * T);
    S2 = S * S;
    xy.x = lp.lam * (0.74482 - 0.34588 * S2);
    xy.y = 1.70711 * T;
    return xy;
}
static PJ_LP times_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    double T, S, S2;
    (void)P;
    T = xy.y / 1.70711;
    S = sin(M_FORTPI * T);
    S2 = S * S;
    lp.lam = xy.x / (0.74482 - 0.34588 * S2);
