}

/* ---------------- somerc ---------------- */
struct somerc_data { double K, c, hlf_e, kR, cosp0, sinp0; };
#define SOMERC_NITER 6
static PJ_XY somerc_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct somerc_data *Q = (struct somerc_data *)P->opaque;
    double phip, lamp, phipp, lampp, sp, cp;
    sp = P->e * sin(lp.phi);
    phip = 2. * atan(exp(Q->c * (log(tan(M_FORTPI + 0.5 * lp.phi)) - Q->hlf_e * log((1. + sp) / (1. - sp))) + Q->K)) - M_HALFPI;
    lamp = Q->c * lp.lam;
    cp = cos(phip);
