    lampp = aasin(cp * sin(lamp) / cos(phipp));
    xy.x = Q->kR * lampp;
    xy.y = Q->kR * log(tan(M_FORTPI + 0.5 * phipp));
    return xy;
}
static PJ_LP somerc_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct somerc_data *Q = (struct somerc_data *)P->opaque;
    double phip, lamp, phipp, lampp, cp, esp, con, delp;
    int i;
    phipp = 2. * (atan(exp(xy.y / Q->kR)) - M_FORTPI);
    lampp = xy.x / Q->kR;
    cp = cos(phipp);
    phip = aasin(Q->cosp0 * sin(phipp) + Q->sinp0 * cp * cos(lampp));
    lamp = aasin(cp * sin(lampp) / cos(phip));
    con = (Q->K - log(tan(M_FORTPI + 0.5 * phip))) / Q->c;
    for (i = SOMERC_NITER; i; --i) {
        esp = P->e * sin(phip);
        delp = (con + log(tan(M_FORTPI + 0.5 * phip)) - Q->hlf_e * log((1. + esp) / (1. - esp))) * (1. - esp * esp) * cos(phip) * P->rone_es;
        phip -= delp;
        if (fabs(delp) < EPS10) break;
    }
    if (i) {
        lp.phi = phip;
        lp.lam = lamp / Q->c;
    } else {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    return lp;
}
PJ *pj_somerc_setup(PJ *P) {
    double cp, phip0, sp;
    struct somerc_data *Q = (struct somerc_data *)calloc(1, sizeof(struct somerc_data));
    P->opaque = Q;
    Q->hlf_e = 0.5 * P->e;
    cp = cos(P->phi0);
    cp *= cp;
    Q->c = sqrt(1 + P->es * cp * cp * P->rone_es);
    sp = sin(P->phi0);
    Q->cosp0 = cos(phip0 = aasin(Q->sinp0 = sp / Q->c));
    sp *= P->e;
    Q->K = log(tan(M_FORTPI + 0.5 * phip0)) - Q->c * (log(tan(M_FORTPI + 0.5 * P->phi0)) - Q->hlf_e * log((1. + sp) / (1. - sp)));
    Q->kR = P->k0 * sqrt(P->one_es) / (1. - sp * sp);
    P->inv = somerc_e_inverse;
    P->fwd = somerc_e_forward;
    return P;
}

/* ---------------- gstmerc ---------------- */
struct gstmerc_data { double lamc, phic, c, n1, n2, XS, YS; };
static PJ_XY gstmerc_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct gstmerc_data *Q = (struct gstmerc_data *)P->opaque;
    double L, Ls, sinLs1, Ls1;
    L = Q->n1 * lp.lam;
    Ls = Q->c + Q->n1 * log(pj_tsfn(-1.0 * lp.phi, -1.0 * sin(lp.phi), P->e));
    sinLs1 = sin(L) / cosh(Ls);
    Ls1 = log(pj_tsfn(-1.0 * asin(sinLs1), -1.0 * sinLs1, 0.0));
    xy.x = (Q->XS + Q->n2 * Ls1) * P->ra;
    xy.y = (Q->YS + Q->n2 * atan(sinh(Ls) / cos(L))) * P->ra;
    return xy;
}
static PJ_LP gstmerc_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct gstmerc_data *Q = (struct gstmerc_data *)P->opaque;
    double L, LC, sinC;
    L = atan(sinh((xy.x * P->a - Q->XS) / Q->n2) / cos((xy.y * P->a - Q->YS) / Q->n2));
    sinC = sin((xy.y * P->a - Q->YS) / Q->n2) / cosh((xy.x * P->a - Q->XS) / Q->n2);
    LC = log(pj_tsfn(-1.0 * asin(sinC), -1.0 * sinC, 0.0));
    lp.lam = L / Q->n1;
    lp.phi = -1.0 * pj_phi2(exp((LC - Q->c) / Q->n1), P->e);
    return lp;
}
PJ *pj_gstmerc_setup(PJ *P) {
    struct gstmerc_data *Q = (struct gstmerc_data *)calloc(1, sizeof(struct gstmerc_data));
    P->opaque = Q;
    Q->lamc = P->lam0;
    Q->n1 = sqrt(1 + P->es * pow(cos(P->phi0), 4.0) / (1 - P->es));
    Q->phic = asin(sin(P->phi0) / Q->n1);
    Q->c = log(pj_tsfn(-1.0 * Q->phic, -1.0 * sin(Q->phic), 0.0)) - Q->n1 * log(pj_tsfn(-1.0 * P->phi0, -1.0 * sin(P->phi0), P->e));
    Q->n2 = P->k0 * P->a * sqrt(1 - P->es) / (1 - P->es * sin(P->phi0) * sin(P->phi0));
    Q->XS = 0;
    Q->YS = -1.0 * Q->n2 * Q->phic;
    P->inv = gstmerc_s_inverse;
    P->fwd = gstmerc_s_forward;
    return P;
}

/* ---------------- cass ---------------- */
struct cass_data { double m0; double *en; int hyperbolic; };
#define CASS_C1 .16666666666666666666
#define CASS_C2 .00833333333333333333
#define CASS_C3 .04166666666666666666
#define CASS_C4 .33333333333333333333
#define CASS_C5 .06666666666666666666
static void cass_destructor(PJ *P, int e) {
    if (P && P->opaque) { struct cass_data *Q = (struct cass_data *)P->opaque; if (Q->en) free(Q->en); }
    pj_default_destructor(P, e);
}
static PJ_XY cass_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct cass_data *Q = (struct cass_data *)P->opaque;
