static PJ_LP lcc_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct lcc_data *Q = (struct lcc_data *)P->opaque;
    double rho;
    xy.x /= P->k0;
    xy.y /= P->k0;
    xy.y = Q->rho0 - xy.y;
    rho = hypot(xy.x, xy.y);
    if (rho != 0.0) {
        if (Q->n < 0.) {
            rho = -rho;
            xy.x = -xy.x;
            xy.y = -xy.y;
