cat > /workspace/src/pj_conic.c <<'EOF'
/* Conic projections */
#include "proj.h"

/* ---------------- lcc ---------------- */
struct lcc_data { double phi1, phi2, n, rho0, c; int ellips; };
static PJ_XY lcc_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct lcc_data *Q = (struct lcc_data *)P->opaque;
    double rho;
    if (fabs(fabs(lp.phi) - M_HALFPI) < EPS10) {
        if ((lp.phi * Q->n) <= 0.) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
        rho = 0.;
    } else {
        rho = Q->c * (Q->ellips ? pow(pj_tsfn(lp.phi, sin(lp.phi), P->e), Q->n) : pow(tan(M_FORTPI + .5 * lp.phi), -Q->n));
    }
    lp.lam *= Q->n;
    xy.x = P->k0 * (rho * sin(lp.lam));
    xy.y = P->k0 * (Q->rho0 - rho * cos(lp.lam));
    return xy;
}
static PJ_LP lcc_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct lcc_data *Q = (struct lcc_data *)P->opaque;
    double rho;
    xy.x /= P->k0;
    xy.y /= P->k0;
    xy.y = Q->rho0 - xy.y;
    rho = hypot(xy.x, xy.y);
    if (rho != 0.0) {
        if (Q->n < 0.) {
            rho = -rho;
            xy.x = -xy.x;
            xy.y = -xy.y;
        }
        if (Q->ellips) {
            lp.phi = pj_phi2(pow(rho / Q->c, 1. / Q->n), P->e);
            if (lp.phi == HUGE_VAL) {
                proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
                return lp;
            }
        } else
            lp.phi = 2. * atan(pow(Q->c / rho, 1. / Q->n)) - M_HALFPI;
        lp.lam = atan2(xy.x, xy.y) / Q->n;
    } else {
        lp.lam = 0.;
        lp.phi = Q->n > 0. ? M_HALFPI : -M_HALFPI;
    }
    return lp;
}
PJ *pj_lcc_setup(PJ *P) {
    double cosphi, sinphi;
    int secant;
    struct lcc_data *Q = (struct lcc_data *)calloc(1, sizeof(struct lcc_data));
    P->opaque = Q;
    Q->phi1 = pj_param(P->params, "rlat_1").f;
    if (pj_param(P->params, "tlat_2").i)
        Q->phi2 = pj_param(P->params, "rlat_2").f;
    else {
        Q->phi2 = Q->phi1;
        if (!pj_param(P->params, "tlat_0").i) P->phi0 = Q->phi1;
    }
    if (fabs(Q->phi1 + Q->phi2) < EPS10) {
        proj_log_error(P, "Invalid value for lat_1 and lat_2: |lat_1 + lat_2| should be > 0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    Q->n = sinphi = sin(Q->phi1);
    cosphi = cos(Q->phi1);
    secant = fabs(Q->phi1 - Q->phi2) >= EPS10;
    if ((Q->ellips = (P->es != 0.))) {
        double ml1, m1;
        P->e = sqrt(P->es);
        m1 = pj_msfn(sinphi, cosphi, P->es);
        ml1 = pj_tsfn(Q->phi1, sinphi, P->e);
        if (secant) {
            double ml2, denom;
            sinphi = sin(Q->phi2);
            Q->n = log(m1 / pj_msfn(sinphi, cos(Q->phi2), P->es));
            if (Q->n == 0) {
                proj_log_error(P, "Invalid value for eccentricity");
                return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
            }
            ml2 = pj_tsfn(Q->phi2, sinphi, P->e);
            denom = log(ml1 / ml2);
            if (denom == 0) {
                proj_log_error(P, "Invalid value for eccentricity");
                return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
            }
            Q->n /= denom;
        }
        Q->c = (Q->rho0 = m1 * pow(ml1, -Q->n) / Q->n);
        Q->rho0 *= (fabs(fabs(P->phi0) - M_HALFPI) < EPS10) ? 0. : pow(pj_tsfn(P->phi0, sin(P->phi0), P->e), Q->n);
    } else {
        if (secant)
            Q->n = log(cosphi / cos(Q->phi2)) / log(tan(M_FORTPI + .5 * Q->phi2) / tan(M_FORTPI + .5 * Q->phi1));
        Q->c = cosphi * pow(tan(M_FORTPI + .5 * Q->phi1), Q->n) / Q->n;
        Q->rho0 = (fabs(fabs(P->phi0) - M_HALFPI) < EPS10) ? 0. : Q->c * pow(tan(M_FORTPI + .5 * P->phi0), -Q->n);
    }
    P->inv = lcc_e_inverse;
    P->fwd = lcc_e_forward;
    return P;
}

/* ---------------- lcca ---------------- */
#define LCCA_MAX_ITER 10
#define LCCA_DEL_TOL 1e-12
struct lcca_data { double *en; double r0, l, M0; double C; };
static void lcca_destructor(PJ *P, int e) {
    if (P && P->opaque) { struct lcca_data *Q = (struct lcca_data *)P->opaque; if (Q->en) free(Q->en); }
    pj_default_destructor(P, e);
}
static double lcca_fS(double S, double C) { return (S * (1. + S * S * C)); }
static double lcca_fSp(double S, double C) { return (1. + 3. * S * S * C); }
static PJ_XY lcca_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct lcca_data *Q = (struct lcca_data *)P->opaque;
    double S, r, dr;
    S = pj_mlfn(lp.phi, sin(lp.phi), cos(lp.phi), Q->en) - Q->M0;
    dr = lcca_fS(S, Q->C);
    r = Q->r0 - dr;
    xy.x = P->k0 * (r * sin(lp.lam *= Q->l));
    xy.y = P->k0 * (Q->r0 - r * cos(lp.lam));
    return xy;
}
static PJ_LP lcca_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct lcca_data *Q = (struct lcca_data *)P->opaque;
    double theta, dr, S, dif;
    int i;
    xy.x /= P->k0;
    xy.y /= P->k0;
    theta = atan2(xy.x, Q->r0 - xy.y);
    dr = xy.y - xy.x * tan(0.5 * theta);
    lp.lam = theta / Q->l;
    S = dr;
    for (i = LCCA_MAX_ITER; i; --i) {
        S -= (dif = (lcca_fS(S, Q->C) - dr) / lcca_fSp(S, Q->C));
        if (fabs(dif) < LCCA_DEL_TOL) break;
    }
    if (!i) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    lp.phi = pj_inv_mlfn(S + Q->M0, Q->en);
    return lp;
}
PJ *pj_lcca_setup(PJ *P) {
    double s2p0, N0, R0, tan0;
    struct lcca_data *Q = (struct lcca_data *)calloc(1, sizeof(struct lcca_data));
    P->opaque = Q;
    P->destructor = lcca_destructor;
    (Q->en = pj_enfn(P->n));
    if (!Q->en) return pj_default_destructor(P, PROJ_ERR_OTHER);
    if (P->phi0 == 0.) {
        proj_log_error(P, "Invalid value for lat_0: it should be different from 0.");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    Q->l = sin(P->phi0);
    Q->M0 = pj_mlfn(P->phi0, Q->l, cos(P->phi0), Q->en);
    s2p0 = Q->l * Q->l;
    R0 = 1. / (1. - P->es * s2p0);
    N0 = sqrt(R0);
    R0 *= P->one_es * N0;
    tan0 = tan(P->phi0);
    Q->r0 = N0 / tan0;
    Q->C = 1. / (6. * R0 * N0);
    P->inv = lcca_e_inverse;
    P->fwd = lcca_e_forward;
    return P;
}

/* ---------------- aea / leac ---------------- */
struct aea_data { double ec, n, c, dd, n2, rho0, rho, phi1, phi2; int ellips; };
#define AEA_N_ITER 15
#define AEA_EPSILON 1.0e-7
#define AEA_TOL 1.0e-10
#define AEA_TOL7 1.e-7
static double aea_phi1_(double qs, double Te, double Tone_es) {
    int i;
    double Phi, sinpi, cospi, con, com, dphi;
    Phi = asin(.5 * qs);
    if (Te < AEA_EPSILON) return (Phi);
    i = AEA_N_ITER;
    do {
        sinpi = sin(Phi);
        cospi = cos(Phi);
        con = Te * sinpi;
        com = 1. - con * con;
        dphi = .5 * com * com / cospi * (qs / Tone_es - sinpi / com + .5 / Te * log((1. - con) / (1. + con)));
        Phi += dphi;
    } while (fabs(dphi) > AEA_TOL && --i);
    return (i ? Phi : HUGE_VAL);
}
static PJ_XY aea_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct aea_data *Q = (struct aea_data *)P->opaque;
    Q->rho = Q->c - (Q->ellips ? Q->n * pj_qsfn(sin(lp.phi), P->e, P->one_es) : Q->n2 * sin(lp.phi));
    if (Q->rho < 0.) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return xy;
    }
    Q->rho = Q->dd * sqrt(Q->rho);
    lp.lam *= Q->n;
    xy.x = Q->rho * sin(lp.lam);
    xy.y = Q->rho0 - Q->rho * cos(lp.lam);
    return xy;
}
static PJ_LP aea_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct aea_data *Q = (struct aea_data *)P->opaque;
    xy.y = Q->rho0 - xy.y;
    Q->rho = hypot(xy.x, xy.y);
    if (Q->rho != 0.0) {
        if (Q->n < 0.) {
            Q->rho = -Q->rho;
            xy.x = -xy.x;
            xy.y = -xy.y;
        }
        lp.phi = Q->rho / Q->dd;
        if (Q->ellips) {
            lp.phi = (Q->c - lp.phi * lp.phi) / Q->n;
            if (fabs(Q->ec - fabs(lp.phi)) > AEA_TOL7) {
                if ((lp.phi = aea_phi1_(lp.phi, P->e, P->one_es)) == HUGE_VAL) {
                    proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
                    return lp;
