        Q->rho0 = Q->dd * sqrt(Q->c - Q->n2 * sin(P->phi0));
    }
    return P;
}
PJ *pj_aea_setup(PJ *P) {
    struct aea_data *Q = (struct aea_data *)calloc(1, sizeof(struct aea_data));
    P->opaque = Q;
    Q->phi1 = pj_param(P->params, "rlat_1").f;
    Q->phi2 = pj_param(P->params, "rlat_2").f;
    return aea_setup(P);
}
PJ *pj_leac_setup(PJ *P) {
    struct aea_data *Q = (struct aea_data *)calloc(1, sizeof(struct aea_data));
    P->opaque = Q;
    Q->phi2 = pj_param(P->params, "rlat_1").f;
    Q->phi1 = pj_param(P->params, "bsouth").i ? -M_HALFPI : M_HALFPI;
    return aea_setup(P);
}

/* ---------------- eqdc ---------------- */
struct eqdc_data { double phi1, phi2, n, rho, rho0, c; double *en; int ellips; };
static void eqdc_destructor(PJ *P, int e) {
    if (P && P->opaque) { struct eqdc_data *Q = (struct eqdc_data *)P->opaque; if (Q->en) free(Q->en); }
    pj_default_destructor(P, e);
}
static PJ_XY eqdc_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct eqdc_data *Q = (struct eqdc_data *)P->opaque;
    Q->rho = Q->c - (Q->ellips ? pj_mlfn(lp.phi, sin(lp.phi), cos(lp.phi), Q->en) : lp.phi);
    xy.x = Q->rho * sin(lp.lam *= Q->n);
    xy.y = Q->rho0 - Q->rho * cos(lp.lam);
    return xy;
}
static PJ_LP eqdc_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct eqdc_data *Q = (struct eqdc_data *)P->opaque;
    if ((Q->rho = hypot(xy.x, xy.y = Q->rho0 - xy.y)) != 0.0) {
        if (Q->n < 0.) {
            Q->rho = -Q->rho;
            xy.x = -xy.x;
            xy.y = -xy.y;
        }
        lp.phi = Q->c - Q->rho;
        if (Q->ellips) lp.phi = pj_inv_mlfn(lp.phi, Q->en);
        lp.lam = atan2(xy.x, xy.y) / Q->n;
    } else {
        lp.lam = 0.;
        lp.phi = Q->n > 0. ? M_HALFPI : -M_HALFPI;
    }
    return lp;
}
PJ *pj_eqdc_setup(PJ *P) {
    double cosphi, sinphi;
    int secant;
    struct eqdc_data *Q = (struct eqdc_data *)calloc(1, sizeof(struct eqdc_data));
    P->opaque = Q;
    P->destructor = eqdc_destructor;
    Q->phi1 = pj_param(P->params, "rlat_1").f;
    Q->phi2 = pj_param(P->params, "rlat_2").f;
    if (fabs(Q->phi1 + Q->phi2) < EPS10) {
        proj_log_error(P, "Invalid value for lat_1 and lat_2: |lat_1 + lat_2| should be > 0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    if (!(Q->en = pj_enfn(P->n))) return pj_default_destructor(P, PROJ_ERR_OTHER);
    Q->n = sinphi = sin(Q->phi1);
    cosphi = cos(Q->phi1);
    secant = fabs(Q->phi1 - Q->phi2) >= EPS10;
    if ((Q->ellips = (P->es > 0.))) {
        double ml1, m1;
        m1 = pj_msfn(sinphi, cosphi, P->es);
        ml1 = pj_mlfn(Q->phi1, sinphi, cosphi, Q->en);
        if (secant) {
            sinphi = sin(Q->phi2);
            cosphi = cos(Q->phi2);
            Q->n = (m1 - pj_msfn(sinphi, cosphi, P->es)) / (pj_mlfn(Q->phi2, sinphi, cosphi, Q->en) - ml1);
            if (Q->n == 0) {
                proj_log_error(P, "Invalid value for eccentricity");
                return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
            }
        }
        Q->c = ml1 + m1 / Q->n;
        Q->rho0 = Q->c - pj_mlfn(P->phi0, sin(P->phi0), cos(P->phi0), Q->en);
    } else {
        if (secant) Q->n = (cosphi - cos(Q->phi2)) / (Q->phi2 - Q->phi1);
        if (Q->n == 0) {
            proj_log_error(P, "Invalid value for lat_1 and lat_2: lat_1 should be different from lat_2");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        Q->c = Q->phi1 + cos(Q->phi1) / Q->n;
        Q->rho0 = Q->c - P->phi0;
    }
    P->inv = eqdc_e_inverse;
    P->fwd = eqdc_e_forward;
    return P;
}

/* ---------------- bonne ---------------- */
struct bonne_data { double phi1, cphi1, am1, m1; double *en; };
static void bonne_destructor(PJ *P, int e) {
    if (P && P->opaque) { struct bonne_data *Q = (struct bonne_data *)P->opaque; if (Q->en) free(Q->en); }
    pj_default_destructor(P, e);
}
static PJ_XY bonne_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct bonne_data *Q = (struct bonne_data *)P->opaque;
    double rh, E, c;
    E = sin(lp.phi);
    c = cos(lp.phi);
    rh = Q->am1 + Q->m1 - pj_mlfn(lp.phi, E, c, Q->en);
    if (fabs(rh) > EPS10) {
        E = c * lp.lam / (rh * sqrt(1. - P->es * E * E));
        xy.x = rh * sin(E);
        xy.y = Q->am1 - rh * cos(E);
    } else {
        xy.x = 0.;
        xy.y = 0.;
    }
    return xy;
}
static PJ_XY bonne_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct bonne_data *Q = (struct bonne_data *)P->opaque;
    double E, rh;
    rh = Q->cphi1 + Q->phi1 - lp.phi;
    if (fabs(rh) > EPS10) {
        E = lp.lam * cos(lp.phi) / rh;
        xy.x = rh * sin(E);
        xy.y = Q->cphi1 - rh * cos(E);
    } else
        xy.x = xy.y = 0.;
    return xy;
}
static PJ_LP bonne_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct bonne_data *Q = (struct bonne_data *)P->opaque;
    double rh;
    xy.y = Q->cphi1 - xy.y;
    rh = hypot(xy.x, xy.y);
    lp.phi = Q->cphi1 + Q->phi1 - rh;
    if (fabs(lp.phi) > M_HALFPI) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    if (fabs(fabs(lp.phi) - M_HALFPI) <= EPS10)
        lp.lam = 0.;
    else
        lp.lam = rh * atan2(xy.x, xy.y) / cos(lp.phi);
    return lp;
}
static PJ_LP bonne_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct bonne_data *Q = (struct bonne_data *)P->opaque;
    double s, rh;
    xy.y = Q->am1 - xy.y;
    rh = hypot(xy.x, xy.y);
    lp.phi = pj_inv_mlfn(Q->am1 + Q->m1 - rh, Q->en);
    if ((s = fabs(lp.phi)) < M_HALFPI) {
        s = sin(lp.phi);
        lp.lam = rh * atan2(xy.x, xy.y) * sqrt(1. - P->es * s * s) / cos(lp.phi);
    } else if (fabs(s - M_HALFPI) <= EPS10)
        lp.lam = 0.;
    else {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    return lp;
}
PJ *pj_bonne_setup(PJ *P) {
    double c;
    struct bonne_data *Q = (struct bonne_data *)calloc(1, sizeof(struct bonne_data));
    P->opaque = Q;
    P->destructor = bonne_destructor;
    Q->phi1 = pj_param(P->params, "rlat_1").f;
    if (fabs(Q->phi1) < EPS10) {
        proj_log_error(P, "Invalid value for lat_1: |lat_1| should be > 0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    if (P->es != 0.0) {
        if (!(Q->en = pj_enfn(P->n))) return pj_default_destructor(P, PROJ_ERR_OTHER);
        Q->am1 = sin(Q->phi1);
        c = cos(Q->phi1);
        Q->m1 = pj_mlfn(Q->phi1, Q->am1, c, Q->en);
        Q->am1 = c / (sqrt(1. - P->es * Q->am1 * Q->am1) * Q->am1);
        P->inv = bonne_e_inverse;
        P->fwd = bonne_e_forward;
    } else {
        if (fabs(Q->phi1) + EPS10 >= M_HALFPI)
            Q->cphi1 = 0.;
        else
            Q->cphi1 = 1. / tan(Q->phi1);
        P->inv = bonne_s_inverse;
        P->fwd = bonne_s_forward;
    }
    return P;
}

/* ---------------- ccon ---------------- */
struct ccon_data { double phi1, ctgphi1, sinphi1, cosphi1; };
static PJ_XY ccon_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct ccon_data *Q = (struct ccon_data *)P->opaque;
    double r;
    r = Q->ctgphi1 - tan(lp.phi - Q->phi1);
    xy.x = r * sin(lp.lam * Q->sinphi1);
    xy.y = Q->ctgphi1 - r * cos(lp.lam * Q->sinphi1);
    return xy;
}
static PJ_LP ccon_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct ccon_data *Q = (struct ccon_data *)P->opaque;
    xy.y = Q->ctgphi1 - xy.y;
    lp.phi = Q->phi1 - atan(hypot(xy.x, xy.y) - Q->ctgphi1);
    lp.lam = atan2(xy.x, xy.y) / Q->sinphi1;
    return lp;
}
PJ *pj_ccon_setup(PJ *P) {
    struct ccon_data *Q = (struct ccon_data *)calloc(1, sizeof(struct ccon_data));
    P->opaque = Q;
    Q->phi1 = pj_param(P->params, "rlat_1").f;
    if (fabs(Q->phi1) < EPS10) {
        proj_log_error(P, "Invalid value for lat_1: |lat_1| should be > 0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    Q->sinphi1 = sin(Q->phi1);
    Q->cosphi1 = cos(Q->phi1);
    Q->ctgphi1 = Q->cosphi1 / Q->sinphi1;
    P->fwd = ccon_forward;
    P->inv = ccon_inverse;
    P->es = 0;
    return P;
}

/* ---------------- simple conics ---------------- */
enum sconic_type { EULER = 0, MURD1, MURD2, MURD3, PCONIC, TISSOT, VITK1 };
struct sconic_data { double n, rho_c, rho_0, sig, c1, c2; enum sconic_type type; };
#define SC_EPS 1e-10
static int sconic_phi12(PJ *P, double *del) {
    struct sconic_data *Q = (struct sconic_data *)P->opaque;
    double p1, p2;
    if (!pj_param(P->params, "tlat_1").i) {
        proj_log_error(P, "Missing parameter: lat_1 should be specified");
        return PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE;
    }
    if (!pj_param(P->params, "tlat_2").i) {
        proj_log_error(P, "Missing parameter: lat_2 should be specified");
        return PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE;
    }
    p1 = pj_param(P->params, "rlat_1").f;
    p2 = pj_param(P->params, "rlat_2").f;
    *del = 0.5 * (p2 - p1);
    Q->sig = 0.5 * (p2 + p1);
    if (fabs(*del) < SC_EPS || fabs(Q->sig) < SC_EPS) {
        proj_log_error(P, "Invalid value for lat_1 and lat_2: lat_1 should be different from lat_2 and lat_1 + lat_2 should be different from 0");
        return PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE;
    }
    return 0;
}
static PJ_XY sconic_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct sconic_data *Q = (struct sconic_data *)P->opaque;
    double rho;
    switch (Q->type) {
    case MURD2: rho = Q->rho_c + tan(Q->sig - lp.phi); break;
    case PCONIC: rho = Q->c2 * (Q->c1 - tan(lp.phi - Q->sig)); break;
    default: rho = Q->rho_c - lp.phi; break;
    }
    xy.x = rho * sin(lp.lam *= Q->n);
    xy.y = Q->rho_0 - rho * cos(lp.lam);
    return xy;
}
static PJ_LP sconic_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct sconic_data *Q = (struct sconic_data *)P->opaque;
    double rho;
    rho = hypot(xy.x, xy.y = Q->rho_0 - xy.y);
    if (Q->n < 0.) {
        rho = -rho;
        xy.x = -xy.x;
        xy.y = -xy.y;
    }
    lp.lam = atan2(xy.x, xy.y) / Q->n;
    switch (Q->type) {
    case PCONIC: lp.phi = atan(Q->c1 - rho / Q->c2) + Q->sig; break;
    case MURD2: lp.phi = Q->sig - atan(rho - Q->rho_c); break;
    default: lp.phi = Q->rho_c - rho;
    }
    return lp;
}
static PJ *sconic_setup(PJ *P, enum sconic_type type) {
    double del, cs;
    int err;
    struct sconic_data *Q = (struct sconic_data *)calloc(1, sizeof(struct sconic_data));
    P->opaque = Q;
    Q->type = type;
    err = sconic_phi12(P, &del);
    if (err) return pj_default_destructor(P, err);
    switch (Q->type) {
    case TISSOT:
        Q->n = sin(Q->sig);
        cs = cos(del);
        Q->rho_c = Q->n / cs + cs / Q->n;
        Q->rho_0 = sqrt((Q->rho_c - 2 * sin(P->phi0)) / Q->n);
        break;
    case MURD1:
        Q->rho_c = sin(del) / (del * tan(Q->sig)) + Q->sig;
        Q->rho_0 = Q->rho_c - P->phi0;
        Q->n = sin(Q->sig);
        break;
    case MURD2:
        Q->rho_c = (cs = sqrt(cos(del))) / tan(Q->sig);
        Q->rho_0 = Q->rho_c + tan(Q->sig - P->phi0);
        Q->n = sin(Q->sig) * cs;
        break;
    case MURD3:
        Q->rho_c = del / (tan(Q->sig) * tan(del)) + Q->sig;
        Q->rho_0 = Q->rho_c - P->phi0;
        Q->n = sin(Q->sig) * sin(del) * tan(del) / (del * del);
        break;
    case EULER:
        Q->n = sin(Q->sig) * sin(del) / del;
        del *= 0.5;
        Q->rho_c = del / (tan(del) * tan(Q->sig)) + Q->sig;
        Q->rho_0 = Q->rho_c - P->phi0;
        break;
    case PCONIC:
        Q->n = sin(Q->sig);
        Q->c2 = cos(del);
        Q->c1 = 1. / tan(Q->sig);
        if (fabs(del = P->phi0 - Q->sig) - EPS10 >= M_HALFPI) {
            proj_log_error(P, "Invalid value for lat_0: |lat_0 - (lat_1 + lat_2) / 2| should be < 90\xc2\xb0");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        Q->rho_0 = Q->c2 * (Q->c1 - tan(del));
        break;
    case VITK1:
        Q->n = (cs = tan(del)) * sin(Q->sig) / del;
        Q->rho_c = del / (cs * tan(Q->sig)) + Q->sig;
        Q->rho_0 = Q->rho_c - P->phi0;
        break;
    }
    P->inv = sconic_s_inverse;
    P->fwd = sconic_s_forward;
    P->es = 0;
    return P;
}
PJ *pj_euler_setup(PJ *P) { return sconic_setup(P, EULER); }
PJ *pj_tissot_setup(PJ *P) { return sconic_setup(P, TISSOT); }
PJ *pj_murd1_setup(PJ *P) { return sconic_setup(P, MURD1); }
PJ *pj_murd2_setup(PJ *P) { return sconic_setup(P, MURD2); }
PJ *pj_murd3_setup(PJ *P) { return sconic_setup(P, MURD3); }
PJ *pj_pconic_setup(PJ *P) { return sconic_setup(P, PCONIC); }
PJ *pj_vitk1_setup(PJ *P) { return sconic_setup(P, VITK1); }

/* ---------------- poly ---------------- */
struct poly_data { double ml0; double *en; };
#define POLY_TOL 1e-10
#define POLY_CONV 1e-10
#define POLY_N_ITER 10
#define POLY_I_ITER 20
#define POLY_ITOL 1.e-12
static void poly_destructor(PJ *P, int e) {
    if (P && P->opaque) { struct poly_data *Q = (struct poly_data *)P->opaque; if (Q->en) free(Q->en); }
    pj_default_destructor(P, e);
}
static PJ_XY poly_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct poly_data *Q = (struct poly_data *)P->opaque;
    double ms, sp, cp;
    if (fabs(lp.phi) <= POLY_TOL) {
        xy.x = lp.lam;
        xy.y = -Q->ml0;
    } else {
        sp = sin(lp.phi);
        ms = fabs(cp = cos(lp.phi)) > POLY_TOL ? pj_msfn(sp, cp, P->es) / sp : 0.;
        xy.x = ms * sin(lp.lam *= sp);
        xy.y = (pj_mlfn(lp.phi, sp, cp, Q->en) - Q->ml0) + ms * (1. - cos(lp.lam));
    }
    return xy;
}
static PJ_XY poly_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct poly_data *Q = (struct poly_data *)P->opaque;
    double cot, E;
    if (fabs(lp.phi) <= POLY_TOL) {
        xy.x = lp.lam;
        xy.y = Q->ml0;
    } else {
        cot = 1. / tan(lp.phi);
        xy.x = sin(E = lp.lam * sin(lp.phi)) * cot;
        xy.y = lp.phi - P->phi0 + cot * (1. - cos(E));
    }
    return xy;
}
static PJ_LP poly_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct poly_data *Q = (struct poly_data *)P->opaque;
    xy.y += Q->ml0;
    if (fabs(xy.y) <= POLY_TOL) {
        lp.lam = xy.x;
        lp.phi = 0.;
    } else {
        double r, c, sp, cp, s2ph, ml, mlb, mlp, dPhi;
        int i;
        r = xy.y * xy.y + xy.x * xy.x;
        for (lp.phi = xy.y, i = POLY_I_ITER; i; --i) {
            sp = sin(lp.phi);
            s2ph = sp * (cp = cos(lp.phi));
            if (fabs(cp) < POLY_ITOL) {
                proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
                return lp;
            }
            c = sp * (mlp = sqrt(1. - P->es * sp * sp)) / cp;
            ml = pj_mlfn(lp.phi, sp, cp, Q->en);
            mlb = ml * ml + r;
            mlp = P->one_es / (mlp * mlp * mlp);
            lp.phi += (dPhi = (ml + ml + c * mlb - 2. * xy.y * (c * ml + 1.)) / (P->es * s2ph * (mlb - 2. * xy.y * ml) / c + 2. * (xy.y - ml) * (c * mlp - 1. / s2ph) - mlp - mlp));
            if (fabs(dPhi) <= POLY_ITOL) break;
        }
        if (!i) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return lp;
        }
        c = sin(lp.phi);
        lp.lam = asin(xy.x * tan(lp.phi) * sqrt(1. - P->es * c * c)) / sin(lp.phi);
    }
    return lp;
}
static PJ_LP poly_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    double B, dphi, tp;
    int i;
    if (fabs(xy.y = P->phi0 + xy.y) <= POLY_TOL) {
        lp.lam = xy.x;
        lp.phi = 0.;
    } else {
        lp.phi = xy.y;
        B = xy.x * xy.x + xy.y * xy.y;
        i = POLY_N_ITER;
        do {
            tp = tan(lp.phi);
            lp.phi -= (dphi = (xy.y * (lp.phi * tp + 1.) - lp.phi - .5 * (lp.phi * lp.phi + B) * tp) / ((lp.phi - xy.y) / tp - 1.));
        } while (fabs(dphi) > POLY_CONV && --i);
        if (!i) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return lp;
        }
        lp.lam = asin(xy.x * tan(lp.phi)) / sin(lp.phi);
    }
    return lp;
}
PJ *pj_poly_setup(PJ *P) {
    struct poly_data *Q = (struct poly_data *)calloc(1, sizeof(struct poly_data));
    P->opaque = Q;
    P->destructor = poly_destructor;
    if (P->es != 0.0) {
        if (!(Q->en = pj_enfn(P->n))) return pj_default_destructor(P, PROJ_ERR_OTHER);
        Q->ml0 = pj_mlfn(P->phi0, sin(P->phi0), cos(P->phi0), Q->en);
        P->inv = poly_e_inverse;
        P->fwd = poly_e_forward;
    } else {
        Q->ml0 = -P->phi0;
        P->inv = poly_s_inverse;
        P->fwd = poly_s_forward;
    }
    return P;
}

/* ---------------- rpoly ---------------- */
struct rpoly_data { double phi1, fxa, fxb; int mode; };
#define RPOLY_EPS 1e-9
static PJ_XY rpoly_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct rpoly_data *Q = (struct rpoly_data *)P->opaque;
    double fa;
    if (Q->mode)
        fa = tan(lp.lam * Q->fxb) * Q->fxa;
    else
        fa = 0.5 * lp.lam;
    if (fabs(lp.phi) < RPOLY_EPS) {
        xy.x = fa + fa;
        xy.y = -P->phi0;
    } else {
        xy.y = 1. / tan(lp.phi);
        xy.x = sin(fa = 2. * atan(fa * sin(lp.phi))) * xy.y;
        xy.y = lp.phi - P->phi0 + (1. - cos(fa)) * xy.y;
    }
    return xy;
}
PJ *pj_rpoly_setup(PJ *P) {
    struct rpoly_data *Q = (struct rpoly_data *)calloc(1, sizeof(struct rpoly_data));
    P->opaque = Q;
    if ((Q->mode = (Q->phi1 = fabs(pj_param(P->params, "rlat_ts").f)) > RPOLY_EPS)) {
        Q->fxb = 0.5 * sin(Q->phi1);
        Q->fxa = 0.5 / Q->fxb;
    }
    P->es = 0.;
