    Az = Av - Az / bn;
    lp.phi = asin(s * cos(z) + c * sin(z) * cos(Az));
    lp.lam = atan2(sin(Az), c / tan(z) - s * cos(Az));
    if (neg)
        lp.lam -= R110;
    else
        lp.lam = lamB - lp.lam;
    return lp;
}

PJ *pj_bipc_setup(PJ *P) {
    struct bipc_data *Q = (struct bipc_data *)calloc(1, sizeof(struct bipc_data));
    P->opaque = Q;
    Q->noskew = pj_param(P->params, "bns").i;
    P->inv = bipc_s_inverse;
    P->fwd = bipc_s_forward;
    P->es = 0.;
    return P;
}

/* ---------------- imw_p ---------------- */
#define IMW_TOL 1e-10
#define IMW_EPS 1e-10
struct imw_p_data { double P, Pp, Q, Qp, R_1, R_2, sphi_1, sphi_2, C2; double phi_1, phi_2, lam_1; double *en; int mode; };

static void imw_destructor(PJ *P, int e) {
    if (P && P->opaque) { struct imw_p_data *Q = (struct imw_p_data *)P->opaque; if (Q->en) free(Q->en); }
    pj_default_destructor(P, e);
}
static int imw_phi12(PJ *P, double *del, double *sig) {
    struct imw_p_data *Q = (struct imw_p_data *)P->opaque;
    if (!pj_param(P->params, "tlat_1").i) {
        proj_log_error(P, "Missing parameter: lat_1 should be specified");
        return PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE;
    }
    if (!pj_param(P->params, "tlat_2").i) {
        proj_log_error(P, "Missing parameter: lat_2 should be specified");
        return PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE;
    }
    Q->phi_1 = pj_param(P->params, "rlat_1").f;
    Q->phi_2 = pj_param(P->params, "rlat_2").f;
    *del = 0.5 * (Q->phi_2 - Q->phi_1);
    *sig = 0.5 * (Q->phi_2 + Q->phi_1);
    if (fabs(*del) < IMW_EPS || fabs(*sig) < IMW_EPS) {
        proj_log_error(P, "Invalid value for lat_1 and lat_2: lat_1 should be different from lat_2 and lat_1 + lat_2 should be different from 0");
        return PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE;
    }
    return 0;
}
static PJ_XY imw_loc_for(PJ_LP lp, PJ *P, double *yc) {
    PJ_XY xy;
    struct imw_p_data *Q = (struct imw_p_data *)P->opaque;
    if (lp.phi == 0.0) {
        xy.x = lp.lam;
        xy.y = 0.;
    } else {
        double xa, ya, xb, yb, xc, D, B, m, sp, t, R, C;
        sp = sin(lp.phi);
        m = pj_mlfn(lp.phi, sp, cos(lp.phi), Q->en);
        xa = Q->Pp + Q->Qp * m;
        ya = Q->P + Q->Q * m;
        R = 1. / (tan(lp.phi) * sqrt(1. - P->es * sp * sp));
        C = sqrt(R * R - xa * xa);
        if (lp.phi < 0.) C = -C;
        C += ya - R;
        if (Q->mode < 0) {
            xb = lp.lam;
            yb = Q->C2;
        } else {
            t = lp.lam * Q->sphi_2;
            xb = Q->R_2 * sin(t);
            yb = Q->C2 + Q->R_2 * (1. - cos(t));
        }
        if (Q->mode > 0) {
            xc = lp.lam;
            *yc = 0.;
        } else {
            t = lp.lam * Q->sphi_1;
            xc = Q->R_1 * sin(t);
            *yc = Q->R_1 * (1. - cos(t));
        }
        D = (xb - xc) / (yb - *yc);
        B = xc + D * (C + R - *yc);
        xy.x = D * sqrt(R * R * (1 + D * D) - B * B);
        if (lp.phi > 0) xy.x = -xy.x;
        xy.x = (B + xy.x) / (1. + D * D);
        xy.y = sqrt(R * R - xy.x * xy.x);
        if (lp.phi > 0) xy.y = -xy.y;
        xy.y += C + R;
    }
    return xy;
}
static PJ_XY imw_p_e_forward(PJ_LP lp, PJ *P) {
    double yc = 0;
    return imw_loc_for(lp, P, &yc);
}
static PJ_LP imw_p_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct imw_p_data *Q = (struct imw_p_data *)P->opaque;
    PJ_XY t;
    double yc = 0.0;
    int i = 0;
    const int N_MAX_ITER = 1000;
    lp.phi = Q->phi_2;
    lp.lam = xy.x / cos(lp.phi);
    do {
        t = imw_loc_for(lp, P, &yc);
        lp.phi = ((lp.phi - Q->phi_1) * (xy.y - yc) / (t.y - yc)) + Q->phi_1;
        lp.lam = lp.lam * xy.x / t.x;
        i++;
    } while (i < N_MAX_ITER && (fabs(t.x - xy.x) > IMW_TOL || fabs(t.y - xy.y) > IMW_TOL));
    if (i == N_MAX_ITER) proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
    return lp;
}
static void imw_xy(PJ *P, double phi, double *x, double *y, double *sp, double *R) {
    struct imw_p_data *Q = (struct imw_p_data *)P->opaque;
    double F;
    *sp = sin(phi);
    *R = 1. / (tan(phi) * sqrt(1. - P->es * *sp * *sp));
    F = Q->lam_1 * *sp;
    *y = *R * (1 - cos(F));
    *x = *R * sin(F);
}
PJ *pj_imw_p_setup(PJ *P) {
    double del, sig, s, t, x1, x2, T2, y1, m1, m2, y2;
    int err;
    struct imw_p_data *Q = (struct imw_p_data *)calloc(1, sizeof(struct imw_p_data));
    P->opaque = Q;
    P->destructor = imw_destructor;
    if (!(Q->en = pj_enfn(P->n))) return pj_default_destructor(P, PROJ_ERR_OTHER);
    if ((err = imw_phi12(P, &del, &sig)) != 0) return pj_default_destructor(P, err);
    if (Q->phi_2 < Q->phi_1) {
        del = Q->phi_1;
        Q->phi_1 = Q->phi_2;
        Q->phi_2 = del;
    }
    if (pj_param(P->params, "tlon_1").i)
        Q->lam_1 = pj_param(P->params, "rlon_1").f;
    else {
        sig = fabs(sig * RAD_TO_DEG);
        if (sig <= 60) sig = 2.;
        else if (sig <= 76) sig = 4.;
        else sig = 8.;
        Q->lam_1 = sig * DEG_TO_RAD;
    }
    Q->mode = 0;
    if (Q->phi_1 != 0.0)
        imw_xy(P, Q->phi_1, &x1, &y1, &Q->sphi_1, &Q->R_1);
    else {
        Q->mode = 1;
        y1 = 0.;
        x1 = Q->lam_1;
    }
    if (Q->phi_2 != 0.0)
        imw_xy(P, Q->phi_2, &x2, &T2, &Q->sphi_2, &Q->R_2);
    else {
        Q->mode = -1;
        T2 = 0.;
        x2 = Q->lam_1;
    }
    m1 = pj_mlfn(Q->phi_1, Q->sphi_1, cos(Q->phi_1), Q->en);
    m2 = pj_mlfn(Q->phi_2, Q->sphi_2, cos(Q->phi_2), Q->en);
    t = m2 - m1;
    s = x2 - x1;
    y2 = sqrt(t * t - s * s) + y1;
    Q->C2 = y2 - T2;
    t = 1. / t;
    Q->P = (m2 * y1 - m1 * y2) * t;
    Q->Q = (y2 - y1) * t;
    Q->Pp = (m2 * x1 - m1 * x2) * t;
    Q->Qp = (x2 - x1) * t;
    P->fwd = imw_p_e_forward;
    P->inv = imw_p_e_inverse;
    return P;
}
