/* Azimuthal projections */
#include "proj.h"

enum Mode { N_POLE = 0, S_POLE = 1, EQUIT = 2, OBLIQ = 3 };

/* ---------------- laea ---------------- */
struct laea_data { double sinb1, cosb1, xmf, ymf, mmf, qp, dd, rq; double *apa; enum Mode mode; };
static void laea_destructor(PJ *P, int e) {
    if (P && P->opaque) { struct laea_data *Q = (struct laea_data *)P->opaque; if (Q->apa) free(Q->apa); }
    pj_default_destructor(P, e);
}
static PJ_XY laea_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct laea_data *Q = (struct laea_data *)P->opaque;
    double coslam, sinlam, sinphi, q, sinb = 0.0, cosb = 0.0, b = 0.0;
    coslam = cos(lp.lam);
    sinlam = sin(lp.lam);
    sinphi = sin(lp.phi);
    q = pj_qsfn(sinphi, P->e, P->one_es);
    if (Q->mode == OBLIQ || Q->mode == EQUIT) {
        sinb = q / Q->qp;
        cosb = sqrt(1. - sinb * sinb);
    }
    switch (Q->mode) {
    case OBLIQ: b = 1. + Q->sinb1 * sinb + Q->cosb1 * cosb * coslam; break;
    case EQUIT: b = 1. + cosb * coslam; break;
    case N_POLE: b = M_HALFPI + lp.phi; q = Q->qp - q; break;
    case S_POLE: b = lp.phi - M_HALFPI; q = Q->qp + q; break;
    }
    if (fabs(b) < EPS10) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return xy;
    }
    switch (Q->mode) {
    case OBLIQ:
        b = sqrt(2. / b);
        xy.y = Q->ymf * b * (Q->cosb1 * sinb - Q->sinb1 * cosb * coslam);
        goto eqcon;
    case EQUIT:
        b = sqrt(2. / (1. + cosb * coslam));
        xy.y = b * sinb * Q->ymf;
    eqcon:
        xy.x = Q->xmf * b * cosb * sinlam;
        break;
    case N_POLE:
    case S_POLE:
        if (q >= 0.) {
            b = sqrt(q);
            xy.x = b * sinlam;
            xy.y = coslam * (Q->mode == S_POLE ? b : -b);
        } else
            xy.x = xy.y = 0.;
        break;
    }
    return xy;
}
static PJ_XY laea_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct laea_data *Q = (struct laea_data *)P->opaque;
    double coslam, cosphi, sinphi;
    sinphi = sin(lp.phi);
    cosphi = cos(lp.phi);
    coslam = cos(lp.lam);
    switch (Q->mode) {
    case EQUIT:
        xy.y = 1. + cosphi * coslam;
        goto oblcon;
    case OBLIQ:
        xy.y = 1. + Q->sinb1 * sinphi + Q->cosb1 * cosphi * coslam;
    oblcon:
        if (xy.y <= EPS10) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
        xy.y = sqrt(2. / xy.y);
        xy.x = xy.y * cosphi * sin(lp.lam);
        xy.y *= Q->mode == EQUIT ? sinphi : Q->cosb1 * sinphi - Q->sinb1 * cosphi * coslam;
        break;
    case N_POLE:
        coslam = -coslam;
        /* fall through */
    case S_POLE:
        if (fabs(lp.phi + P->phi0) < EPS10) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
        xy.y = M_FORTPI - lp.phi * .5;
        xy.y = 2. * (Q->mode == S_POLE ? cos(xy.y) : sin(xy.y));
        xy.x = xy.y * sin(lp.lam);
        xy.y *= coslam;
        break;
    }
    return xy;
}
static PJ_LP laea_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct laea_data *Q = (struct laea_data *)P->opaque;
    double cCe, sCe, q, rho, ab = 0.0;
    switch (Q->mode) {
    case EQUIT:
    case OBLIQ:
        xy.x /= Q->dd;
        xy.y *= Q->dd;
        rho = hypot(xy.x, xy.y);
        if (rho < EPS10) {
            lp.lam = 0.;
            lp.phi = P->phi0;
            return lp;
        }
        sCe = 2. * asin(.5 * rho / Q->rq);
        cCe = cos(sCe);
        sCe = sin(sCe);
        xy.x *= sCe;
        if (Q->mode == OBLIQ) {
            ab = cCe * Q->sinb1 + xy.y * sCe * Q->cosb1 / rho;
            xy.y = rho * Q->cosb1 * cCe - xy.y * Q->sinb1 * sCe;
        } else {
            ab = xy.y * sCe / rho;
            xy.y = rho * cCe;
        }
        break;
    case N_POLE:
        xy.y = -xy.y;
        /* fall through */
    case S_POLE:
        q = (xy.x * xy.x + xy.y * xy.y);
        if (q == 0.0) {
            lp.lam = 0.;
            lp.phi = P->phi0;
            return (lp);
        }
        ab = 1. - q / Q->qp;
        if (Q->mode == S_POLE) ab = -ab;
        break;
    }
    lp.lam = atan2(xy.x, xy.y);
    lp.phi = pj_authlat(asin(ab), Q->apa);
    return lp;
}
static PJ_LP laea_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct laea_data *Q = (struct laea_data *)P->opaque;
    double cosz = 0.0, rh, sinz = 0.0;
    rh = hypot(xy.x, xy.y);
    if ((lp.phi = rh * .5) > 1.) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    lp.phi = 2. * asin(lp.phi);
    if (Q->mode == OBLIQ || Q->mode == EQUIT) {
        sinz = sin(lp.phi);
        cosz = cos(lp.phi);
    }
    switch (Q->mode) {
    case EQUIT:
        lp.phi = fabs(rh) <= EPS10 ? 0. : asin(xy.y * sinz / rh);
        xy.x *= sinz;
        xy.y = cosz * rh;
        break;
    case OBLIQ:
        lp.phi = fabs(rh) <= EPS10 ? P->phi0 : asin(cosz * Q->sinb1 + xy.y * sinz * Q->cosb1 / rh);
        xy.x *= sinz * Q->cosb1;
        xy.y = (cosz - sin(lp.phi) * Q->sinb1) * rh;
        break;
    case N_POLE:
        xy.y = -xy.y;
        lp.phi = M_HALFPI - lp.phi;
        break;
    case S_POLE:
        lp.phi -= M_HALFPI;
        break;
    }
    lp.lam = (xy.y == 0. && (Q->mode == EQUIT || Q->mode == OBLIQ)) ? 0. : atan2(xy.x, xy.y);
    return lp;
}
PJ *pj_laea_setup(PJ *P) {
    double t;
    struct laea_data *Q = (struct laea_data *)calloc(1, sizeof(struct laea_data));
    P->opaque = Q;
    P->destructor = laea_destructor;
    t = fabs(P->phi0);
    if (t > M_HALFPI + EPS10) {
        proj_log_error(P, "Invalid value for lat_0: |lat_0| should be <= 90\xc2\xb0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    if (fabs(t - M_HALFPI) < EPS10)
        Q->mode = P->phi0 < 0. ? S_POLE : N_POLE;
    else if (fabs(t) < EPS10)
        Q->mode = EQUIT;
    else
        Q->mode = OBLIQ;
    if (P->es != 0.0) {
        double sinphi;
        P->e = sqrt(P->es);
        Q->qp = pj_qsfn(1., P->e, P->one_es);
        Q->mmf = .5 / (1. - P->es);
        Q->apa = pj_authset(P->es);
        if (!Q->apa) return pj_default_destructor(P, PROJ_ERR_OTHER);
        switch (Q->mode) {
        case N_POLE:
        case S_POLE:
            Q->dd = 1.;
            break;
        case EQUIT:
            Q->dd = 1. / (Q->rq = sqrt(.5 * Q->qp));
            Q->xmf = 1.;
            Q->ymf = .5 * Q->qp;
            break;
        case OBLIQ:
            Q->rq = sqrt(.5 * Q->qp);
            sinphi = sin(P->phi0);
            Q->sinb1 = pj_qsfn(sinphi, P->e, P->one_es) / Q->qp;
            Q->cosb1 = sqrt(1. - Q->sinb1 * Q->sinb1);
            Q->dd = cos(P->phi0) / (sqrt(1. - P->es * sinphi * sinphi) * Q->rq * Q->cosb1);
            Q->ymf = (Q->xmf = Q->rq) / Q->dd;
            Q->xmf *= Q->dd;
            break;
        }
        P->inv = laea_e_inverse;
        P->fwd = laea_e_forward;
    } else {
        if (Q->mode == OBLIQ) {
            Q->sinb1 = sin(P->phi0);
            Q->cosb1 = cos(P->phi0);
        }
        P->inv = laea_s_inverse;
        P->fwd = laea_s_forward;
    }
    return P;
}

/* ---------------- stere / ups ---------------- */
struct stere_data { double phits, sinX1, cosX1, akm1; enum Mode mode; };
#define STERE_NITER 8
#define STERE_CONV 1.e-10
static double stere_ssfn_(double phit, double sinphi, double eccen) {
    sinphi *= eccen;
    return (tan(.5 * (M_HALFPI + phit)) * pow((1. - sinphi) / (1. + sinphi), .5 * eccen));
}
static PJ_XY stere_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct stere_data *Q = (struct stere_data *)P->opaque;
    double coslam, sinlam, sinX = 0.0, cosX = 0.0, X, A = 0.0, sinphi;
    coslam = cos(lp.lam);
    sinlam = sin(lp.lam);
    sinphi = sin(lp.phi);
    if (Q->mode == OBLIQ || Q->mode == EQUIT) {
        sinX = sin(X = 2. * atan(stere_ssfn_(lp.phi, sinphi, P->e)) - M_HALFPI);
        cosX = cos(X);
    }
    switch (Q->mode) {
    case OBLIQ: {
        const double denom = Q->cosX1 * (1. + Q->sinX1 * sinX + Q->cosX1 * cosX * coslam);
        if (denom == 0) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
        A = Q->akm1 / denom;
        xy.y = A * (Q->cosX1 * sinX - Q->sinX1 * cosX * coslam);
        xy.x = A * cosX;
        break;
    }
    case EQUIT:
        if (1. + cosX * coslam == 0.0) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
        A = Q->akm1 / (1. + cosX * coslam);
        xy.y = A * sinX;
        xy.x = A * cosX;
        break;
    case S_POLE:
        lp.phi = -lp.phi;
        coslam = -coslam;
        sinphi = -sinphi;
        /* fall through */
    case N_POLE:
        xy.x = Q->akm1 * pj_tsfn(lp.phi, sinphi, P->e);
        xy.y = -xy.x * coslam;
        break;
    }
    xy.x = xy.x * sinlam;
    return xy;
}
static PJ_XY stere_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct stere_data *Q = (struct stere_data *)P->opaque;
    double sinphi, cosphi, coslam, sinlam;
    sinphi = sin(lp.phi);
    cosphi = cos(lp.phi);
    coslam = cos(lp.lam);
    sinlam = sin(lp.lam);
    switch (Q->mode) {
    case EQUIT:
        xy.y = 1. + cosphi * coslam;
        goto oblcon;
    case OBLIQ:
        xy.y = 1. + Q->sinX1 * sinphi + Q->cosX1 * cosphi * coslam;
    oblcon:
        if (xy.y <= EPS10) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
        xy.x = (xy.y = Q->akm1 / xy.y) * cosphi * sinlam;
        xy.y *= (Q->mode == EQUIT) ? sinphi : Q->cosX1 * sinphi - Q->sinX1 * cosphi * coslam;
        break;
    case S_POLE:
        lp.phi = -lp.phi;
        coslam = -coslam;
        sinphi = -sinphi;
        /* fall through */
    case N_POLE:
        if (fabs(lp.phi - M_HALFPI) < 1.e-8) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
        xy.x = Q->akm1 * tan(M_FORTPI + .5 * lp.phi);
        xy.y = -xy.x * coslam;
        xy.x *= sinlam;
        break;
    }
    return xy;
}
static PJ_LP stere_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct stere_data *Q = (struct stere_data *)P->opaque;
    double cosphi, sinphi, tp = 0.0, phi_l = 0.0, rho, halfe = 0.0, halfpi = 0.0;
    int i;
    rho = hypot(xy.x, xy.y);
    switch (Q->mode) {
    case OBLIQ:
    case EQUIT:
        tp = 2. * atan2(rho * Q->cosX1, Q->akm1);
        cosphi = cos(tp);
        sinphi = sin(tp);
        if (rho == 0.0)
            phi_l = asin(cosphi * Q->sinX1);
        else
            phi_l = asin(cosphi * Q->sinX1 + (xy.y * sinphi * Q->cosX1 / rho));
        tp = tan(.5 * (M_HALFPI + phi_l));
        xy.x *= sinphi;
        xy.y = rho * Q->cosX1 * cosphi - xy.y * Q->sinX1 * sinphi;
        halfpi = M_HALFPI;
        halfe = .5 * P->e;
        break;
    case N_POLE:
        xy.y = -xy.y;
        /* fall through */
    case S_POLE:
        tp = -rho / Q->akm1;
        phi_l = M_HALFPI - 2. * atan(tp);
        halfpi = -M_HALFPI;
        halfe = -.5 * P->e;
        break;
    }
    for (i = STERE_NITER; i--; phi_l = lp.phi) {
        sinphi = P->e * sin(phi_l);
        lp.phi = 2. * atan(tp * pow((1. + sinphi) / (1. - sinphi), halfe)) - halfpi;
        if (fabs(phi_l - lp.phi) < STERE_CONV) {
            if (Q->mode == S_POLE) lp.phi = -lp.phi;
            lp.lam = (xy.x == 0. && xy.y == 0.) ? 0. : atan2(xy.x, xy.y);
            return lp;
        }
    }
    proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
    return lp;
}
static PJ_LP stere_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct stere_data *Q = (struct stere_data *)P->opaque;
    double c, rh, sinc, cosc;
    sinc = sin(c = 2. * atan((rh = hypot(xy.x, xy.y)) / Q->akm1));
    cosc = cos(c);
    lp.lam = 0.;
    switch (Q->mode) {
    case EQUIT:
        if (fabs(rh) <= EPS10)
            lp.phi = 0.;
        else
            lp.phi = asin(xy.y * sinc / rh);
        if (cosc != 0. || xy.x != 0.) lp.lam = atan2(xy.x * sinc, cosc * rh);
        break;
    case OBLIQ:
        if (fabs(rh) <= EPS10)
            lp.phi = P->phi0;
        else
            lp.phi = asin(cosc * Q->sinX1 + xy.y * sinc * Q->cosX1 / rh);
        if ((c = cosc - Q->sinX1 * sin(lp.phi)) != 0. || xy.x != 0.)
            lp.lam = atan2(xy.x * sinc * Q->cosX1, c * rh);
        break;
    case N_POLE:
        xy.y = -xy.y;
        /* fall through */
    case S_POLE:
        if (fabs(rh) <= EPS10)
            lp.phi = P->phi0;
        else
            lp.phi = asin(Q->mode == S_POLE ? -cosc : cosc);
        lp.lam = (xy.x == 0. && xy.y == 0.) ? 0. : atan2(xy.x, xy.y);
        break;
    }
    return lp;
}
static PJ *stere_setup(PJ *P) {
    struct stere_data *Q = (struct stere_data *)P->opaque;
    double t;
    if (fabs((t = fabs(P->phi0)) - M_HALFPI) < EPS10)
        Q->mode = P->phi0 < 0. ? S_POLE : N_POLE;
    else
        Q->mode = t > EPS10 ? OBLIQ : EQUIT;
    Q->phits = fabs(Q->phits);
    if (P->es != 0.0) {
        double X;
        switch (Q->mode) {
        case N_POLE:
        case S_POLE:
            if (fabs(Q->phits - M_HALFPI) < EPS10)
                Q->akm1 = 2. * P->k0 / sqrt(pow(1 + P->e, 1 + P->e) * pow(1 - P->e, 1 - P->e));
            else {
                t = sin(Q->phits);
                Q->akm1 = cos(Q->phits) / pj_tsfn(Q->phits, t, P->e);
                t *= P->e;
                Q->akm1 /= sqrt(1. - t * t);
            }
            break;
        case EQUIT:
        case OBLIQ:
            t = sin(P->phi0);
            X = 2. * atan(stere_ssfn_(P->phi0, t, P->e)) - M_HALFPI;
            t *= P->e;
            Q->akm1 = 2. * P->k0 * cos(P->phi0) / sqrt(1. - t * t);
            Q->sinX1 = sin(X);
            Q->cosX1 = cos(X);
            break;
        }
        P->inv = stere_e_inverse;
        P->fwd = stere_e_forward;
    } else {
        switch (Q->mode) {
        case OBLIQ:
            Q->sinX1 = sin(P->phi0);
            Q->cosX1 = cos(P->phi0);
            /* fall through */
        case EQUIT:
            Q->akm1 = 2. * P->k0;
            break;
        case S_POLE:
        case N_POLE:
            Q->akm1 = fabs(Q->phits - M_HALFPI) >= EPS10 ? cos(Q->phits) / tan(M_FORTPI - .5 * Q->phits) : 2. * P->k0;
            break;
        }
        P->inv = stere_s_inverse;
        P->fwd = stere_s_forward;
    }
    return P;
}
PJ *pj_stere_setup(PJ *P) {
    struct stere_data *Q = (struct stere_data *)calloc(1, sizeof(struct stere_data));
    P->opaque = Q;
    Q->phits = pj_param(P->params, "tlat_ts").i ? pj_param(P->params, "rlat_ts").f : M_HALFPI;
    return stere_setup(P);
}
PJ *pj_ups_setup(PJ *P) {
    struct stere_data *Q = (struct stere_data *)calloc(1, sizeof(struct stere_data));
    P->opaque = Q;
    P->phi0 = pj_param(P->params, "bsouth").i ? -M_HALFPI : M_HALFPI;
    if (P->es == 0.0) {
        proj_log_error(P, "Invalid value for es: only ellipsoidal formulation supported");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    P->k0 = .994;
    P->x0 = 2000000.;
    P->y0 = 2000000.;
    Q->phits = M_HALFPI;
    P->lam0 = 0.;
    return stere_setup(P);
}

/* ---------------- sterea ---------------- */
struct sterea_data { double phic0, cosc0, sinc0, R2; void *en; };
static void sterea_destructor(PJ *P, int e) {
    if (P && P->opaque) { struct sterea_data *Q = (struct sterea_data *)P->opaque; if (Q->en) free(Q->en); }
    pj_default_destructor(P, e);
}
static PJ_XY sterea_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct sterea_data *Q = (struct sterea_data *)P->opaque;
    double cosc, sinc, cosl_, k;
    lp = pj_gauss(lp, Q->en);
    sinc = sin(lp.phi);
    cosc = cos(lp.phi);
    cosl_ = cos(lp.lam);
    k = P->k0 * Q->R2 / (1. + Q->sinc0 * sinc + Q->cosc0 * cosc * cosl_);
    xy.x = k * cosc * sin(lp.lam);
    xy.y = k * (Q->cosc0 * sinc - Q->sinc0 * cosc * cosl_);
    return xy;
}
static PJ_LP sterea_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct sterea_data *Q = (struct sterea_data *)P->opaque;
    double rho, c, sinc, cosc;
    xy.x /= P->k0;
    xy.y /= P->k0;
    if ((rho = hypot(xy.x, xy.y)) != 0.0) {
        c = 2. * atan2(rho, Q->R2);
        sinc = sin(c);
        cosc = cos(c);
        lp.phi = asin(cosc * Q->sinc0 + xy.y * sinc * Q->cosc0 / rho);
        lp.lam = atan2(xy.x * sinc, rho * Q->cosc0 * cosc - xy.y * Q->sinc0 * sinc);
    } else {
        lp.phi = Q->phic0;
        lp.lam = 0.;
    }
    return pj_inv_gauss(lp, Q->en);
}
PJ *pj_sterea_setup(PJ *P) {
    double R;
    struct sterea_data *Q = (struct sterea_data *)calloc(1, sizeof(struct sterea_data));
    P->opaque = Q;
    P->destructor = sterea_destructor;
    Q->en = pj_gauss_ini(P->e, P->phi0, &(Q->phic0), &R);
    if (!Q->en) return pj_default_destructor(P, PROJ_ERR_OTHER);
    Q->sinc0 = sin(Q->phic0);
    Q->cosc0 = cos(Q->phic0);
    Q->R2 = 2. * R;
    P->inv = sterea_e_inverse;
    P->fwd = sterea_e_forward;
    return P;
}

/* ---------------- ortho ---------------- */
struct ortho_data { double sinph0, cosph0, nu0, y_shift, y_scale; enum Mode mode; };
static PJ_XY ortho_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct ortho_data *Q = (struct ortho_data *)P->opaque;
    double coslam, cosphi, sinphi;
    xy.x = HUGE_VAL; xy.y = HUGE_VAL;
    cosphi = cos(lp.phi);
    coslam = cos(lp.lam);
    switch (Q->mode) {
    case EQUIT:
        if (cosphi * coslam < -EPS10) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
        xy.y = sin(lp.phi);
        break;
    case OBLIQ:
        sinphi = sin(lp.phi);
        if (Q->sinph0 * sinphi + Q->cosph0 * cosphi * coslam < -EPS10) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
        xy.y = Q->cosph0 * sinphi - Q->sinph0 * cosphi * coslam;
        break;
    case N_POLE:
        coslam = -coslam;
        /* fall through */
    case S_POLE:
        if (fabs(lp.phi - P->phi0) - EPS10 > M_HALFPI) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
        xy.y = cosphi * coslam;
        break;
    }
    xy.x = cosphi * sin(lp.lam);
    return xy;
}
static PJ_LP ortho_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {HUGE_VAL, HUGE_VAL};
    struct ortho_data *Q = (struct ortho_data *)P->opaque;
    double rh, cosc, sinc;
    if ((sinc = (rh = hypot(xy.x, xy.y))) > 1.) {
        if ((sinc - 1.) > EPS10) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return lp;
        }
        sinc = 1.;
    }
    cosc = sqrt(1. - sinc * sinc);
    if (fabs(rh) <= EPS10) {
        lp.phi = P->phi0;
        lp.lam = 0.0;
    } else {
        switch (Q->mode) {
        case N_POLE:
            xy.y = -xy.y;
            lp.phi = acos(sinc);
            break;
        case S_POLE:
            lp.phi = -acos(sinc);
            break;
        case EQUIT:
            lp.phi = xy.y * sinc / rh;
            xy.x *= sinc;
            xy.y = cosc * rh;
            goto sinchk;
        case OBLIQ:
            lp.phi = cosc * Q->sinph0 + xy.y * sinc * Q->cosph0 / rh;
            xy.y = (cosc - Q->sinph0 * lp.phi) * rh;
            xy.x *= sinc * Q->cosph0;
        sinchk:
            if (fabs(lp.phi) >= 1.)
                lp.phi = lp.phi < 0. ? -M_HALFPI : M_HALFPI;
            else
                lp.phi = asin(lp.phi);
            break;
        }
        lp.lam = (xy.y == 0. && (Q->mode == OBLIQ || Q->mode == EQUIT)) ? (xy.x == 0. ? 0. : xy.x < 0. ? -M_HALFPI : M_HALFPI) : atan2(xy.x, xy.y);
    }
    return lp;
}
static PJ_XY ortho_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct ortho_data *Q = (struct ortho_data *)P->opaque;
    const double cosphi = cos(lp.phi);
    const double sinphi = sin(lp.phi);
    const double coslam = cos(lp.lam);
    const double sinlam = sin(lp.lam);
    const double nu = 1.0 / sqrt(1.0 - P->es * sinphi * sinphi);
    double x, y;
    xy.x = HUGE_VAL; xy.y = HUGE_VAL;
    if (Q->sinph0 * sinphi + Q->cosph0 * cosphi * coslam < -EPS10) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return xy;
    }
    x = nu * cosphi * sinlam;
    y = nu * (sinphi * Q->cosph0 - cosphi * Q->sinph0 * coslam) + P->es * (Q->nu0 * Q->sinph0 - nu * sinphi) * Q->cosph0;
    xy.x = x;
    xy.y = y;
    return xy;
}
static PJ_LP ortho_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {HUGE_VAL, HUGE_VAL};
    struct ortho_data *Q = (struct ortho_data *)P->opaque;
    double x, y, z, rh, sinphi, cosphi, lam, phi;
    int i;
    const double SC_TOL = 1e-9 * 0 + 1e-12;
    /* initial guess with the spherical inverse, then Newton iterations */
    {
        double rh2;
        x = xy.x; y = xy.y;
        rh = hypot(x, y);
        rh2 = rh;
        if (rh2 > 1.0 + 1e-10) {
            /* allow slightly outside due to ellipsoid */
        }
    }
    if (fabs(Q->sinph0) > 1 - 1e-13) {
        /* polar case */
        double r2 = xy.x * xy.x + xy.y * xy.y;
        const double sign = Q->sinph0 > 0 ? 1.0 : -1.0;
        if (r2 > 1.0 + 1e-10) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return lp;
        }
        /* iterate on phi: rho = nu*cosphi */
        phi = sign * acos(r2 > 1 ? 1 : sqrt(r2));
        for (i = 0; i < 20; ++i) {
            double s = sin(phi), c = cos(phi), nu = 1.0 / sqrt(1.0 - P->es * s * s);
            double f = nu * c - sqrt(r2);
            double df = -nu * s + c * (P->es * s * c) * nu * nu * nu;
            double d = f / df;
            phi -= d;
            if (fabs(d) < 1e-15) break;
        }
        lp.phi = phi;
        lp.lam = atan2(xy.x, sign > 0 ? -xy.y : xy.y);
        return lp;
    }
    /* oblique/equatorial: Newton on (lam, phi) */
    {
        double rh0 = hypot(xy.x, xy.y);
        double sinc, cosc;
        if (rh0 > 1.0) rh0 = 1.0;
        sinc = rh0;
        cosc = sqrt(1.0 - sinc * sinc);
        if (rh0 <= EPS10) {
            phi = P->phi0; lam = 0.0;
        } else {
            phi = cosc * Q->sinph0 + xy.y * sinc * Q->cosph0 / rh0;
            if (phi >= 1.) phi = M_HALFPI; else if (phi <= -1.) phi = -M_HALFPI; else phi = asin(phi);
            y = (cosc - Q->sinph0 * sin(phi)) * rh0;
            x = xy.x * sinc * Q->cosph0;
            lam = atan2(x, y);
        }
    }
    for (i = 0; i < 20; ++i) {
        PJ_LP t; PJ_XY f;
        double dxdl, dxdp, dydl, dydp, det, dl, dp, h = 1e-7;
        t.lam = lam; t.phi = phi;
        f = ortho_e_forward(t, P);
        if (f.x == HUGE_VAL) break;
        {
            PJ_LP t2 = t; PJ_XY f2;
            t2.lam += h; f2 = ortho_e_forward(t2, P); dxdl = (f2.x - f.x) / h; dydl = (f2.y - f.y) / h;
            t2 = t; t2.phi += h; f2 = ortho_e_forward(t2, P); dxdp = (f2.x - f.x) / h; dydp = (f2.y - f.y) / h;
        }
        det = dxdl * dydp - dxdp * dydl;
        if (det == 0) break;
        dl = ((xy.x - f.x) * dydp - (xy.y - f.y) * dxdp) / det;
        dp = ((xy.y - f.y) * dxdl - (xy.x - f.x) * dydl) / det;
        lam += dl; phi += dp;
        if (fabs(dl) < SC_TOL && fabs(dp) < SC_TOL) break;
    }
    (void)z; (void)sinphi; (void)cosphi;
    lp.lam = lam;
    lp.phi = phi;
    return lp;
}
PJ *pj_ortho_setup(PJ *P) {
    struct ortho_data *Q = (struct ortho_data *)calloc(1, sizeof(struct ortho_data));
    P->opaque = Q;
    Q->sinph0 = sin(P->phi0);
    Q->cosph0 = cos(P->phi0);
    if (fabs(fabs(P->phi0) - M_HALFPI) <= EPS10)
        Q->mode = P->phi0 < 0. ? S_POLE : N_POLE;
    else if (fabs(P->phi0) > EPS10) {
        Q->mode = OBLIQ;
    } else
        Q->mode = EQUIT;
    if (P->es == 0) {
        P->inv = ortho_s_inverse;
        P->fwd = ortho_s_forward;
    } else {
        Q->nu0 = 1.0 / sqrt(1.0 - P->es * Q->sinph0 * Q->sinph0);
        P->inv = ortho_e_inverse;
        P->fwd = ortho_e_forward;
    }
    return P;
}

/* ---------------- gnom ---------------- */
struct gnom_data { double sinph0, cosph0; enum Mode mode; };
static PJ_XY gnom_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct gnom_data *Q = (struct gnom_data *)P->opaque;
    double coslam, cosphi, sinphi;
    sinphi = sin(lp.phi);
    cosphi = cos(lp.phi);
    coslam = cos(lp.lam);
    switch (Q->mode) {
    case EQUIT: xy.y = cosphi * coslam; break;
    case OBLIQ: xy.y = Q->sinph0 * sinphi + Q->cosph0 * cosphi * coslam; break;
    case S_POLE: xy.y = -sinphi; break;
    case N_POLE: xy.y = sinphi; break;
    }
    if (xy.y <= EPS10) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return xy;
    }
    xy.x = (xy.y = 1. / xy.y) * cosphi * sin(lp.lam);
    switch (Q->mode) {
    case EQUIT: xy.y *= sinphi; break;
    case OBLIQ: xy.y *= Q->cosph0 * sinphi - Q->sinph0 * cosphi * coslam; break;
    case N_POLE: coslam = -coslam; /* fall through */
    case S_POLE: xy.y *= cosphi * coslam; break;
    }
    return xy;
}
static PJ_LP gnom_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct gnom_data *Q = (struct gnom_data *)P->opaque;
    double rh, cosz, sinz;
    rh = hypot(xy.x, xy.y);
    sinz = sin(lp.phi = atan(rh));
    cosz = sqrt(1. - sinz * sinz);
    if (fabs(rh) <= EPS10) {
        lp.phi = P->phi0;
        lp.lam = 0.;
    } else {
        switch (Q->mode) {
        case OBLIQ:
            lp.phi = cosz * Q->sinph0 + xy.y * sinz * Q->cosph0 / rh;
            if (fabs(lp.phi) >= 1.)
                lp.phi = lp.phi > 0. ? M_HALFPI : -M_HALFPI;
            else
                lp.phi = asin(lp.phi);
            xy.y = (cosz - Q->sinph0 * sin(lp.phi)) * rh;
            xy.x *= sinz * Q->cosph0;
            break;
        case EQUIT:
            lp.phi = xy.y * sinz / rh;
            if (fabs(lp.phi) >= 1.)
                lp.phi = lp.phi > 0. ? M_HALFPI : -M_HALFPI;
            else
                lp.phi = asin(lp.phi);
            xy.y = cosz * rh;
            xy.x *= sinz;
            break;
        case S_POLE:
            lp.phi -= M_HALFPI;
            break;
        case N_POLE:
            lp.phi = M_HALFPI - lp.phi;
            xy.y = -xy.y;
            break;
        }
        lp.lam = atan2(xy.x, xy.y);
    }
    return lp;
}
PJ *pj_gnom_setup(PJ *P) {
    struct gnom_data *Q = (struct gnom_data *)calloc(1, sizeof(struct gnom_data));
    P->opaque = Q;
    if (fabs(fabs(P->phi0) - M_HALFPI) < EPS10) {
        Q->mode = P->phi0 < 0. ? S_POLE : N_POLE;
    } else if (fabs(P->phi0) < EPS10) {
        Q->mode = EQUIT;
    } else {
        Q->mode = OBLIQ;
        Q->sinph0 = sin(P->phi0);
        Q->cosph0 = cos(P->phi0);
    }
    P->inv = gnom_s_inverse;
    P->fwd = gnom_s_forward;
    P->es = 0.;
    return P;
}

/* ---------------- nsper / tpers ---------------- */
struct nsper_data { double height, sinph0, cosph0, p, rp, pn1, pfact, h, cg, sg, sw, cw; enum Mode mode; int tilt; };
static PJ_XY nsper_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct nsper_data *Q = (struct nsper_data *)P->opaque;
    double coslam, cosphi, sinphi;
    sinphi = sin(lp.phi);
    cosphi = cos(lp.phi);
    coslam = cos(lp.lam);
    switch (Q->mode) {
    case OBLIQ: xy.y = Q->sinph0 * sinphi + Q->cosph0 * cosphi * coslam; break;
    case EQUIT: xy.y = cosphi * coslam; break;
    case S_POLE: xy.y = -sinphi; break;
    case N_POLE: xy.y = sinphi; break;
    }
    if (xy.y < Q->rp) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return xy;
    }
    xy.y = Q->pn1 / (Q->p - xy.y);
    xy.x = xy.y * cosphi * sin(lp.lam);
    switch (Q->mode) {
    case OBLIQ: xy.y *= (Q->cosph0 * sinphi - Q->sinph0 * cosphi * coslam); break;
    case EQUIT: xy.y *= sinphi; break;
    case N_POLE: coslam = -coslam; /* fall through */
    case S_POLE: xy.y *= cosphi * coslam; break;
    }
    if (Q->tilt) {
        double yt, ba;
        yt = xy.y * Q->cg + xy.x * Q->sg;
        ba = 1. / (yt * Q->sw * Q->h + Q->cw);
        xy.x = (xy.x * Q->cg - xy.y * Q->sg) * Q->cw * ba;
        xy.y = yt * ba;
    }
    return xy;
}
static PJ_LP nsper_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct nsper_data *Q = (struct nsper_data *)P->opaque;
    double rh, cosz, sinz;
    if (Q->tilt) {
        double bm, bq, yt;
        yt = 1. / (Q->pn1 - xy.y * Q->sw);
        bm = Q->pn1 * xy.x * yt;
        bq = Q->pn1 * xy.y * Q->cw * yt;
        xy.x = bm * Q->cg + bq * Q->sg;
        xy.y = bq * Q->cg - bm * Q->sg;
    }
    rh = hypot(xy.x, xy.y);
    if ((sinz = 1. - rh * rh * Q->pfact) < 0.) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    sinz = (Q->p - sqrt(sinz)) / (Q->pn1 / rh + rh / Q->pn1);
    cosz = sqrt(1. - sinz * sinz);
    if (fabs(rh) <= EPS10) {
        lp.lam = 0.;
        lp.phi = P->phi0;
    } else {
        switch (Q->mode) {
        case OBLIQ:
            lp.phi = asin(cosz * Q->sinph0 + xy.y * sinz * Q->cosph0 / rh);
            xy.y = (cosz - Q->sinph0 * sin(lp.phi)) * rh;
            xy.x *= sinz * Q->cosph0;
            break;
        case EQUIT:
            lp.phi = asin(xy.y * sinz / rh);
            xy.y = cosz * rh;
            xy.x *= sinz;
            break;
        case N_POLE:
            lp.phi = asin(cosz);
            xy.y = -xy.y;
            break;
        case S_POLE:
            lp.phi = -asin(cosz);
            break;
        }
        lp.lam = atan2(xy.x, xy.y);
    }
    return lp;
}
static PJ *nsper_setup(PJ *P) {
    struct nsper_data *Q = (struct nsper_data *)P->opaque;
    Q->height = pj_param(P->params, "dh").f;
    if (Q->height <= 0.) {
        proj_log_error(P, "Invalid value for h");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    if (fabs(fabs(P->phi0) - M_HALFPI) < EPS10)
        Q->mode = P->phi0 < 0. ? S_POLE : N_POLE;
    else if (fabs(P->phi0) < EPS10)
        Q->mode = EQUIT;
    else {
        Q->mode = OBLIQ;
        Q->sinph0 = sin(P->phi0);
        Q->cosph0 = cos(P->phi0);
    }
    Q->pn1 = Q->height / P->a;
    Q->p = 1. + Q->pn1;
    Q->rp = 1. / Q->p;
    Q->h = 1. / Q->pn1;
    Q->pfact = (Q->p + 1.) * Q->h;
    P->inv = nsper_s_inverse;
    P->fwd = nsper_s_forward;
    P->es = 0.;
    return P;
}
PJ *pj_nsper_setup(PJ *P) {
    struct nsper_data *Q = (struct nsper_data *)calloc(1, sizeof(struct nsper_data));
    P->opaque = Q;
    Q->tilt = 0;
    return nsper_setup(P);
}
PJ *pj_tpers_setup(PJ *P) {
    double omega, gamma;
    struct nsper_data *Q = (struct nsper_data *)calloc(1, sizeof(struct nsper_data));
    P->opaque = Q;
    omega = pj_param(P->params, "dtilt").f * DEG_TO_RAD;
    gamma = pj_param(P->params, "dazi").f * DEG_TO_RAD;
    Q->tilt = 1;
    Q->cg = cos(gamma);
    Q->sg = sin(gamma);
    Q->cw = cos(omega);
    Q->sw = sin(omega);
    return nsper_setup(P);
}

/* ---------------- geos ---------------- */
struct geos_data { double h, radius_p, radius_p2, radius_p_inv2, radius_g, radius_g_1, C; int flip_axis; };
static PJ_XY geos_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct geos_data *Q = (struct geos_data *)P->opaque;
    double Vx, Vy, Vz, tmp;
    tmp = Q->radius_g_1 * cos(lp.phi);
    Vx = tmp * cos(lp.lam);
    Vy = tmp * sin(lp.lam);
    Vz = Q->radius_g_1 * sin(lp.phi);
    if (((Q->radius_g - Vx) * Vx - Vy * Vy - Vz * Vz) < 0.) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return xy;
    }
    tmp = Q->radius_g - Vx;
    if (Q->flip_axis) {
        xy.x = Q->radius_g_1 * atan(Vy / hypot(Vz, tmp));
        xy.y = Q->radius_g_1 * atan(Vz / tmp);
    } else {
        xy.x = Q->radius_g_1 * atan(Vy / tmp);
        xy.y = Q->radius_g_1 * atan(Vz / hypot(Vy, tmp));
    }
    return xy;
}
static PJ_XY geos_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct geos_data *Q = (struct geos_data *)P->opaque;
    double r, Vx, Vy, Vz, tmp;
    lp.phi = atan(Q->radius_p2 * tan(lp.phi));
    r = Q->radius_p / hypot(Q->radius_p * cos(lp.phi), sin(lp.phi));
    Vx = r * cos(lp.lam) * cos(lp.phi);
    Vy = r * sin(lp.lam) * cos(lp.phi);
    Vz = r * sin(lp.phi);
    if (((Q->radius_g - Vx) * Vx - Vy * Vy - Vz * Vz * Q->radius_p_inv2) < 0.) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return xy;
    }
    tmp = Q->radius_g - Vx;
    if (Q->flip_axis) {
        xy.x = Q->radius_g_1 * atan(Vy / hypot(Vz, tmp));
        xy.y = Q->radius_g_1 * atan(Vz / tmp);
    } else {
        xy.x = Q->radius_g_1 * atan(Vy / tmp);
        xy.y = Q->radius_g_1 * atan(Vz / hypot(Vy, tmp));
    }
    return xy;
}
static PJ_LP geos_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct geos_data *Q = (struct geos_data *)P->opaque;
    double Vx, Vy, Vz, a, b, det, k;
    Vx = -1.0;
    if (Q->flip_axis) {
        Vz = tan(xy.y / Q->radius_g_1);
        Vy = tan(xy.x / Q->radius_g_1) * sqrt(1.0 + Vz * Vz);
    } else {
        Vy = tan(xy.x / Q->radius_g_1);
        Vz = tan(xy.y / Q->radius_g_1) * sqrt(1.0 + Vy * Vy);
    }
    a = Vy * Vy + Vz * Vz + Vx * Vx;
    b = 2 * Q->radius_g * Vx;
    if ((det = (b * b) - 4 * a * Q->C) < 0.) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    k = (-b - sqrt(det)) / (2 * a);
    Vx = Q->radius_g + k * Vx;
    Vy *= k;
    Vz *= k;
    lp.lam = atan2(Vy, Vx);
    lp.phi = atan(Vz * cos(lp.lam) / Vx);
    return lp;
}
static PJ_LP geos_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct geos_data *Q = (struct geos_data *)P->opaque;
    double Vx, Vy, Vz, a, b, det, k;
    Vx = -1.0;
    if (Q->flip_axis) {
        Vz = tan(xy.y / Q->radius_g_1);
        Vy = tan(xy.x / Q->radius_g_1) * hypot(1.0, Vz);
    } else {
        Vy = tan(xy.x / Q->radius_g_1);
        Vz = tan(xy.y / Q->radius_g_1) * hypot(1.0, Vy);
    }
    a = Vz / Q->radius_p;
    a = Vy * Vy + a * a + Vx * Vx;
    b = 2 * Q->radius_g * Vx;
    if ((det = (b * b) - 4 * a * Q->C) < 0.) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    k = (-b - sqrt(det)) / (2. * a);
    Vx = Q->radius_g + k * Vx;
    Vy *= k;
    Vz *= k;
    lp.lam = atan2(Vy, Vx);
    lp.phi = atan(Vz * cos(lp.lam) / Vx);
    lp.phi = atan(Q->radius_p_inv2 * tan(lp.phi));
    return lp;
}
PJ *pj_geos_setup(PJ *P) {
    const char *sweep_axis;
    struct geos_data *Q = (struct geos_data *)calloc(1, sizeof(struct geos_data));
    P->opaque = Q;
    Q->h = pj_param(P->params, "dh").f;
    if (Q->h <= 0.) {
        proj_log_error(P, "Invalid value for h.");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    if (P->phi0 != 0.0) {
        proj_log_error(P, "Invalid value for lat_0: it should be 0.");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    sweep_axis = pj_param(P->params, "ssweep").s;
    if (sweep_axis == NULL)
        Q->flip_axis = 0;
    else {
        if ((sweep_axis[0] != 'x' && sweep_axis[0] != 'y') || sweep_axis[1] != '\0') {
            proj_log_error(P, "Invalid value for sweep: it should be x or y.");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        if (sweep_axis[0] == 'x')
            Q->flip_axis = 1;
        else
            Q->flip_axis = 0;
    }
    Q->radius_g_1 = Q->h / P->a;
