}
PJ *pj_stere_setup(PJ *P) {
    struct stere_data *Q = (struct stere_data *)calloc(1, sizeof(struct stere_data));
    P->opaque = Q;
    Q->phits = pj_param(P->params, "tlat_ts").i ? pj_param(P->params, "rlat_ts").f : M_HALFPI;
    return stere_setup(P);
}
PJ *pj_ups_setup(PJ *P) {
    struct stere_data *Q = (struct stere_data *)calloc(1, sizeof(struct stere_data));
    P->opaque = Q;
    P->phi0 = pj_param(P->params, "bsouth").i ? -M_HALFPI : M_HALFPI;
    if (P->es == 0.0) {
        proj_log_error(P, "Invalid value for es: only ellipsoidal formulation supported");
