            B12 = SinCosSeries(TRUE, ssig2_, csig2_, l->C1a, nC1);
            serr = (1 + l->A1m1) * (sig12 + (B12 - l->B11)) - s12_a12 / l->b;
            sig12 = sig12 - serr / sqrt(1 + l->k2 * sq(ssig2_));
            ssig12 = sin(sig12);
            csig12 = cos(sig12);
        }
    }
    ssig2 = l->ssig1 * csig12 + l->csig1 * ssig12;
    csig2 = l->csig1 * csig12 - l->ssig1 * ssig12;
    dn2 = sqrt(1 + l->k2 * sq(ssig2));
    if (outmask & (GEOD_DISTANCE | GEOD_REDUCEDLENGTH | GEOD_GEODESICSCALE)) {
        if ((flags & GEOD_ARCMODE) || fabs(l->f) > 0.01) B12 = SinCosSeries(TRUE, ssig2, csig2, l->C1a, nC1);
        AB1 = (1 + l->A1m1) * (B12 - l->B11);
    }
    sbet2 = l->calp0 * ssig2;
    cbet2 = hypot(l->salp0, l->calp0 * csig2);
    if (cbet2 == 0) cbet2 = csig2 = tiny;
    salp2 = l->salp0;
    calp2 = l->calp0 * csig2;
    if (outmask & GEOD_DISTANCE) s12 = (flags & GEOD_ARCMODE) ? l->b * ((1 + l->A1m1) * sig12 + AB1) : s12_a12;
    if (outmask & GEOD_LONGITUDE) {
        real E = copysign(1, l->salp0);
        somg2 = l->salp0 * ssig2;
        comg2 = csig2;
        omg12 = (flags & GEOD_LONG_UNROLL)
                    ? E * (sig12 - (atan2(ssig2, csig2) - atan2(l->ssig1, l->csig1)) + (atan2(E * somg2, comg2) - atan2(E * l->somg1, l->comg1)))
                    : atan2(somg2 * l->comg1 - comg2 * l->somg1, comg2 * l->comg1 + somg2 * l->somg1);
        lam12 = omg12 + l->A3c * (sig12 + (SinCosSeries(TRUE, ssig2, csig2, l->C3a, nC3 - 1) - l->B31));
        lon12 = lam12 / degree;
        lon2 = (flags & GEOD_LONG_UNROLL) ? l->lon1 + lon12 : AngNormalize(AngNormalize(l->lon1) + AngNormalize(lon12));
    }
    if (outmask & GEOD_LATITUDE) lat2 = atan2dx(sbet2, l->f1 * cbet2);
    if (outmask & GEOD_AZIMUTH) azi2 = atan2dx(salp2, calp2);
    if (outmask & (GEOD_REDUCEDLENGTH | GEOD_GEODESICSCALE)) {
        real B22 = SinCosSeries(TRUE, ssig2, csig2, l->C2a, nC2), AB2 = (1 + l->A2m1) * (B22 - l->B21),
             J12 = (l->A1m1 - l->A2m1) * sig12 + (AB1 - AB2);
        if (outmask & GEOD_REDUCEDLENGTH)
            m12 = l->b * ((dn2 * (l->csig1 * ssig2) - l->dn1 * (l->ssig1 * csig2)) - l->csig1 * csig2 * J12);
        if (outmask & GEOD_GEODESICSCALE) {
            real t = l->k2 * (ssig2 - l->ssig1) * (ssig2 + l->ssig1) / (l->dn1 + dn2);
            M12 = csig12 + (t * ssig2 - csig2 * J12) * l->ssig1 / l->dn1;
            M21 = csig12 - (t * l->ssig1 - l->csig1 * J12) * ssig2 / dn2;
        }
    }
    if (outmask & GEOD_AREA) {
        real B42 = SinCosSeries(FALSE, ssig2, csig2, l->C4a, nC4);
        real salp12, calp12;
        if (l->calp0 == 0 || l->salp0 == 0) {
            salp12 = salp2 * l->calp1 - calp2 * l->salp1;
            calp12 = calp2 * l->calp1 + salp2 * l->salp1;
        } else {
            salp12 = l->calp0 * l->salp0 * (csig12 <= 0 ? l->csig1 * (1 - csig12) + ssig12 * l->ssig1 : ssig12 * (l->csig1 * ssig12 / (1 + csig12) + l->ssig1));
            calp12 = sq(l->salp0) + sq(l->calp0) * l->csig1 * csig2;
        }
        S12 = l->c2 * atan2(salp12, calp12) + l->A4 * (B42 - l->B41);
        (void)S12;
    }
    if (outmask & GEOD_LATITUDE) *plat2 = lat2;
    if (outmask & GEOD_LONGITUDE) *plon2 = lon2;
    if (outmask & GEOD_AZIMUTH) *pazi2 = azi2;
    if (outmask & GEOD_DISTANCE) *ps12 = s12;
    if (outmask & GEOD_REDUCEDLENGTH) *pm12 = m12;
    if (outmask & GEOD_GEODESICSCALE) {
        if (pM12) *pM12 = M12;
        if (pM21) *pM21 = M21;
    }
    if (outmask & GEOD_AREA) *pS12 = S12;
    return (flags & GEOD_ARCMODE) ? s12_a12 : sig12 / degree;
}

real geod_gendirect(const struct geod_geodesic *g, real lat1, real lon1, real azi1, unsigned flags, real s12_a12,
                    real *plat2, real *plon2, real *pazi2, real *ps12, real *pm12, real *pM12, real *pM21, real *pS12) {
    struct geod_geodesicline l;
    unsigned outmask = (plat2 ? GEOD_LATITUDE : GEOD_NONE) | (plon2 ? GEOD_LONGITUDE : GEOD_NONE) |
                       (pazi2 ? GEOD_AZIMUTH : GEOD_NONE) | (ps12 ? GEOD_DISTANCE : GEOD_NONE) |
                       (pm12 ? GEOD_REDUCEDLENGTH : GEOD_NONE) | (pM12 || pM21 ? GEOD_GEODESICSCALE : GEOD_NONE) |
                       (pS12 ? GEOD_AREA : GEOD_NONE);
    geod_lineinit(&l, g, lat1, lon1, azi1, outmask | ((flags & GEOD_ARCMODE) ? GEOD_NONE : GEOD_DISTANCE_IN));
    return geod_genposition(&l, flags, s12_a12, plat2, plon2, pazi2, ps12, pm12, pM12, pM21, pS12);
}

void geod_direct(const struct geod_geodesic *g, real lat1, real lon1, real azi1, real s12, real *plat2, real *plon2,
                 real *pazi2) {
    geod_gendirect(g, lat1, lon1, azi1, GEOD_NOFLAGS, s12, plat2, plon2, pazi2, 0, 0, 0, 0, 0);
}

static real geod_geninverse_int(const struct geod_geodesic *g, real lat1, real lon1, real lat2, real lon2, real *ps12,
                                real *psalp1, real *pcalp1, real *psalp2, real *pcalp2, real *pm12, real *pM12,
                                real *pM21, real *pS12) {
    real s12 = 0, m12 = 0, M12 = 0, M21 = 0, S12 = 0;
    real lon12, lon12s;
    int latsign, lonsign, swapp;
    real sbet1, cbet1, sbet2, cbet2, s12x = 0, m12x = 0;
    real dn1, dn2, lam12, slam12, clam12;
    real a12 = 0, sig12, calp1 = 0, salp1 = 0, calp2 = 0, salp2 = 0;
    real Ca[nC];
    boolx meridian;
    real omg12 = 0, somg12 = 2, comg12 = 0;
    unsigned outmask = (ps12 ? GEOD_DISTANCE : GEOD_NONE) | (pm12 ? GEOD_REDUCEDLENGTH : GEOD_NONE) |
                       (pM12 || pM21 ? GEOD_GEODESICSCALE : GEOD_NONE) | (pS12 ? GEOD_AREA : GEOD_NONE);
    outmask &= OUT_ALL;
    lon12 = AngDiff(lon1, lon2, &lon12s);
    lonsign = signbit(lon12) ? -1 : 1;
    lon12 = lonsign * AngRound(lon12);
    lon12s = AngRound((180 - lon12) - lonsign * lon12s);
    lam12 = lon12 * degree;
    if (lon12 > 90) {
        sincosdx(lon12s, &slam12, &clam12);
        clam12 = -clam12;
    } else
        sincosdx(lon12, &slam12, &clam12);
    lat1 = AngRound(LatFix(lat1));
    lat2 = AngRound(LatFix(lat2));
    swapp = fabs(lat1) < fabs(lat2) || lat2 != lat2 ? -1 : 1;
    if (swapp < 0) {
        lonsign *= -1;
        swapx(&lat1, &lat2);
    }
    latsign = signbit(lat1) ? -1 : 1;
    lat1 *= latsign;
    lat2 *= latsign;
    sincosdx(lat1, &sbet1, &cbet1);
    sbet1 *= g->f1;
    norm2(&sbet1, &cbet1);
    cbet1 = fmax(tiny, cbet1);
    sincosdx(lat2, &sbet2, &cbet2);
    sbet2 *= g->f1;
    norm2(&sbet2, &cbet2);
    cbet2 = fmax(tiny, cbet2);
    if (cbet1 < -sbet1) {
        if (cbet2 == cbet1) sbet2 = copysign(sbet1, sbet2);
    } else {
        if (fabs(sbet2) == -sbet1) cbet2 = cbet1;
    }
    dn1 = sqrt(1 + g->ep2 * sq(sbet1));
    dn2 = sqrt(1 + g->ep2 * sq(sbet2));
    meridian = lat1 == -90 || slam12 == 0;
    if (meridian) {
        real ssig1, csig1, ssig2, csig2;
        calp1 = clam12;
        salp1 = slam12;
        calp2 = 1;
        salp2 = 0;
        ssig1 = sbet1;
        csig1 = calp1 * cbet1;
        ssig2 = sbet2;
        csig2 = calp2 * cbet2;
        sig12 = atan2(fmax((real)(0), csig1 * ssig2 - ssig1 * csig2) + 0, csig1 * csig2 + ssig1 * ssig2);
        Lengths(g, g->n, sig12, ssig1, csig1, dn1, ssig2, csig2, dn2, cbet1, cbet2, &s12x, &m12x, 0,
                (outmask & GEOD_GEODESICSCALE) ? &M12 : 0, (outmask & GEOD_GEODESICSCALE) ? &M21 : 0, Ca);
        if (sig12 < 1 || m12x >= 0) {
            if (sig12 < 3 * tiny || (sig12 < tol0 && (s12x < 0 || m12x < 0))) sig12 = m12x = s12x = 0;
            m12x *= g->b;
            s12x *= g->b;
            a12 = sig12 / degree;
        } else
            meridian = FALSE;
    }
    if (!meridian && sbet1 == 0 && (g->f <= 0 || lon12s >= g->f * 180)) {
        calp1 = calp2 = 0;
        salp1 = salp2 = 1;
        s12x = g->a * lam12;
        sig12 = omg12 = lam12 / g->f1;
        m12x = g->b * sin(sig12);
        if (outmask & GEOD_GEODESICSCALE) M12 = M21 = cos(sig12);
        a12 = lon12 / g->f1;
    } else if (!meridian) {
        real dnm = 0;
        sig12 = InverseStart(g, sbet1, cbet1, dn1, sbet2, cbet2, dn2, lam12, slam12, clam12, &salp1, &calp1, &salp2,
                             &calp2, &dnm, Ca);
        if (sig12 >= 0) {
            s12x = sig12 * g->b * dnm;
            m12x = sq(dnm) * g->b * sin(sig12 / dnm);
            if (outmask & GEOD_GEODESICSCALE) M12 = M21 = cos(sig12 / dnm);
            a12 = sig12 / degree;
            omg12 = lam12 / (g->f1 * dnm);
        } else {
            real ssig1 = 0, csig1 = 0, ssig2 = 0, csig2 = 0, eps = 0, domg12 = 0;
            unsigned numit = 0;
            real salp1a = tiny, calp1a = 1, salp1b = tiny, calp1b = -1;
            boolx tripn = FALSE;
            boolx tripb = FALSE;
            for (;; ++numit) {
                real dv = 0, v = Lambda12(g, sbet1, cbet1, dn1, sbet2, cbet2, dn2, salp1, calp1, slam12, clam12, &salp2,
                                          &calp2, &sig12, &ssig1, &csig1, &ssig2, &csig2, &eps, &domg12, numit < maxit1,
                                          &dv, Ca);
                if (tripb || !(fabs(v) >= (tripn ? 8 : 1) * tol0) || numit == maxit2) break;
                if (v > 0 ? (numit > maxit1 || calp1 / salp1 > calp1b / salp1b) : (numit > maxit1 || calp1 / salp1 < calp1a / salp1a))
                    ;
                if (v > 0) {
                    if (!(numit > maxit1 || calp1 / salp1 > calp1b / salp1b)) {
                        salp1b = salp1;
                        calp1b = calp1;
                    }
                } else {
                    if (!(numit > maxit1 || calp1 / salp1 < calp1a / salp1a)) {
                        salp1a = salp1;
                        calp1a = calp1;
                    }
                }
                if (numit < maxit1 && dv > 0) {
                    real dalp1 = -v / dv;
                    if (fabs(dalp1) < pi) {
                        real sdalp1 = sin(dalp1), cdalp1 = cos(dalp1), nsalp1 = salp1 * cdalp1 + calp1 * sdalp1;
                        if (nsalp1 > 0) {
                            calp1 = calp1 * cdalp1 - salp1 * sdalp1;
                            salp1 = nsalp1;
                            norm2(&salp1, &calp1);
                            tripn = fabs(v) <= 16 * tol0;
                            continue;
                        }
                    }
                }
                salp1 = (salp1a + salp1b) / 2;
                calp1 = (calp1a + calp1b) / 2;
                norm2(&salp1, &calp1);
                tripn = FALSE;
                tripb = (fabs(salp1a - salp1) + (calp1a - calp1) < tolb || fabs(salp1 - salp1b) + (calp1 - calp1b) < tolb);
            }
            Lengths(g, eps, sig12, ssig1, csig1, dn1, ssig2, csig2, dn2, cbet1, cbet2, &s12x, &m12x, 0,
                    (outmask & GEOD_GEODESICSCALE) ? &M12 : 0, (outmask & GEOD_GEODESICSCALE) ? &M21 : 0, Ca);
            m12x *= g->b;
            s12x *= g->b;
            a12 = sig12 / degree;
            if (outmask & GEOD_AREA) {
                real sdomg12 = sin(domg12), cdomg12 = cos(domg12);
                somg12 = slam12 * cdomg12 - clam12 * sdomg12;
                comg12 = clam12 * cdomg12 + slam12 * sdomg12;
            }
        }
    }
    if (outmask & GEOD_DISTANCE) s12 = 0 + s12x;
    if (outmask & GEOD_REDUCEDLENGTH) m12 = 0 + m12x;
    if (outmask & GEOD_AREA) {
        real salp0 = salp1 * cbet1, calp0 = hypot(calp1, salp1 * sbet1);
        real alp12;
        if (calp0 != 0 && salp0 != 0) {
            real ssig1 = sbet1, csig1 = calp1 * cbet1, ssig2 = sbet2, csig2 = calp2 * cbet2, k2 = sq(calp0) * g->ep2,
                 eps = k2 / (2 * (1 + sqrt(1 + k2)) + k2), A4 = sq(g->a) * calp0 * salp0 * g->e2, B41, B42;
            norm2(&ssig1, &csig1);
            norm2(&ssig2, &csig2);
            C4f(g, eps, Ca);
            B41 = SinCosSeries(FALSE, ssig1, csig1, Ca, nC4);
            B42 = SinCosSeries(FALSE, ssig2, csig2, Ca, nC4);
            S12 = A4 * (B42 - B41);
        } else
            S12 = 0;
        if (!meridian && somg12 == 2) {
            somg12 = sin(omg12);
            comg12 = cos(omg12);
        }
        if (!meridian && comg12 > -(real)(0.7071) && sbet2 - sbet1 < (real)(1.75)) {
            real domg12 = 1 + somg12, dbet1 = 1 + cbet1, dbet2 = 1 + cbet2;
            alp12 = 2 * atan2(somg12 * (sbet1 * dbet2 + sbet2 * dbet1), domg12 * (sbet1 * sbet2 + dbet1 * dbet2));
        } else {
            real salp12 = salp2 * calp1 - calp2 * salp1, calp12 = calp2 * calp1 + salp2 * salp1;
            if (salp12 == 0 && calp12 < 0) {
                salp12 = tiny * calp1;
                calp12 = -1;
            }
            alp12 = atan2(salp12, calp12);
        }
        S12 += g->c2 * alp12;
        S12 *= swapp * lonsign * latsign;
        S12 += 0;
    }
    if (swapp < 0) {
        swapx(&salp1, &salp2);
        swapx(&calp1, &calp2);
        if (outmask & GEOD_GEODESICSCALE) swapx(&M12, &M21);
    }
    salp1 *= swapp * lonsign;
    calp1 *= swapp * latsign;
    salp2 *= swapp * lonsign;
    calp2 *= swapp * latsign;
    if (psalp1) *psalp1 = salp1;
    if (pcalp1) *pcalp1 = calp1;
    if (psalp2) *psalp2 = salp2;
    if (pcalp2) *pcalp2 = calp2;
    if (outmask & GEOD_DISTANCE) *ps12 = s12;
    if (outmask & GEOD_REDUCEDLENGTH) *pm12 = m12;
    if (outmask & GEOD_GEODESICSCALE) {
        if (pM12) *pM12 = M12;
        if (pM21) *pM21 = M21;
    }
    if (outmask & GEOD_AREA) *pS12 = S12;
    return a12;
}

real geod_geninverse(const struct geod_geodesic *g, real lat1, real lon1, real lat2, real lon2, real *ps12,
                     real *pazi1, real *pazi2, real *pm12, real *pM12, real *pM21, real *pS12) {
    real salp1, calp1, salp2, calp2, a12 = geod_geninverse_int(g, lat1, lon1, lat2, lon2, ps12, &salp1, &calp1,
                                                                &salp2, &calp2, pm12, pM12, pM21, pS12);
    if (pazi1) *pazi1 = atan2dx(salp1, calp1);
    if (pazi2) *pazi2 = atan2dx(salp2, calp2);
    return a12;
}

void geod_inverse(const struct geod_geodesic *g, real lat1, real lon1, real lat2, real lon2, real *ps12, real *pazi1,
                  real *pazi2) {
    geod_geninverse(g, lat1, lon1, lat2, lon2, ps12, pazi1, pazi2, 0, 0, 0, 0);
}

static real SinCosSeries(boolx sinp, real sinx, real cosx, const real c[], int n) {
    real ar, y0, y1;
    c += (n + sinp);
    ar = 2 * (cosx - sinx) * (cosx + sinx);
    y0 = (n & 1) ? *--c : 0;
    y1 = 0;
    n /= 2;
    while (n--) {
        y1 = ar * y0 - y1 + *--c;
        y0 = ar * y1 - y0 + *--c;
    }
    return sinp ? 2 * sinx * cosx * y0 : cosx * (y0 - y1);
}

static void Lengths(const struct geod_geodesic *g, real eps, real sig12, real ssig1, real csig1, real dn1, real ssig2,
                    real csig2, real dn2, real cbet1, real cbet2, real *ps12b, real *pm12b, real *pm0, real *pM12,
                    real *pM21, real Ca[]) {
    real m0 = 0, J12 = 0, A1 = 0, A2 = 0;
    real Cb[nC];
    boolx redlp = pm12b || pm0 || pM12 || pM21;
    if (ps12b || redlp) {
        A1 = A1m1f(eps);
        C1f(eps, Ca);
        if (redlp) {
            A2 = A2m1f(eps);
            C2f(eps, Cb);
            m0 = A1 - A2;
            A2 = 1 + A2;
        }
        A1 = 1 + A1;
    }
    if (ps12b) {
        real B1 = SinCosSeries(TRUE, ssig2, csig2, Ca, nC1) - SinCosSeries(TRUE, ssig1, csig1, Ca, nC1);
        *ps12b = A1 * (sig12 + B1);
        if (redlp) {
            real B2 = SinCosSeries(TRUE, ssig2, csig2, Cb, nC2) - SinCosSeries(TRUE, ssig1, csig1, Cb, nC2);
            J12 = m0 * sig12 + (A1 * B1 - A2 * B2);
        }
    } else if (redlp) {
        int l;
        for (l = 1; l <= nC2; ++l) Cb[l] = A1 * Ca[l] - A2 * Cb[l];
        J12 = m0 * sig12 + (SinCosSeries(TRUE, ssig2, csig2, Cb, nC2) - SinCosSeries(TRUE, ssig1, csig1, Cb, nC2));
    }
    if (pm0) *pm0 = m0;
    if (pm12b) *pm12b = dn2 * (csig1 * ssig2) - dn1 * (ssig1 * csig2) - csig1 * csig2 * J12;
    if (pM12 || pM21) {
        real csig12 = csig1 * csig2 + ssig1 * ssig2;
        real t = g->ep2 * (cbet1 - cbet2) * (cbet1 + cbet2) / (dn1 + dn2);
        if (pM12) *pM12 = csig12 + (t * ssig2 - csig2 * J12) * ssig1 / dn1;
        if (pM21) *pM21 = csig12 - (t * ssig1 - csig1 * J12) * ssig2 / dn2;
    }
}

static real Astroid(real x, real y) {
    real k;
    real p = sq(x), q = sq(y), r = (p + q - 1) / 6;
    if (!(q == 0 && r <= 0)) {
        real S = p * q / 4, r2 = sq(r), r3 = r * r2, disc = S * (S + 2 * r3);
        real u = r;
        real v, uv, w;
        if (disc >= 0) {
            real T3 = S + r3, T;
            T3 += T3 < 0 ? -sqrt(disc) : sqrt(disc);
            T = cbrt(T3);
            u += T + (T != 0 ? r2 / T : 0);
        } else {
            real ang = atan2(sqrt(-disc), -(S + r3));
            u += 2 * r * cos(ang / 3);
        }
        v = sqrt(sq(u) + q);
        uv = u < 0 ? q / (v - u) : u + v;
        w = (uv - q) / (2 * v);
        k = uv / (sqrt(uv + sq(w)) + w);
    } else {
        k = 0;
    }
    return k;
}

static real InverseStart(const struct geod_geodesic *g, real sbet1, real cbet1, real dn1, real sbet2, real cbet2,
                         real dn2, real lam12, real slam12, real clam12, real *psalp1, real *pcalp1, real *psalp2,
                         real *pcalp2, real *pdnm, real Ca[]) {
    real salp1 = 0, calp1 = 0, salp2 = 0, calp2 = 0, dnm = 0;
    real sig12 = -1;
    real sbet12 = sbet2 * cbet1 - cbet2 * sbet1, cbet12 = cbet2 * cbet1 + sbet2 * sbet1;
    real sbet12a;
    boolx shortline = cbet12 >= 0 && sbet12 < (real)(0.5) && cbet2 * lam12 < (real)(0.5);
    real somg12, comg12, ssig12, csig12;
    sbet12a = sbet2 * cbet1 + cbet2 * sbet1;
    if (shortline) {
        real sbetm2 = sq(sbet1 + sbet2), omg12;
        sbetm2 /= sbetm2 + sq(cbet1 + cbet2);
        dnm = sqrt(1 + g->ep2 * sbetm2);
        omg12 = lam12 / (g->f1 * dnm);
        somg12 = sin(omg12);
        comg12 = cos(omg12);
    } else {
        somg12 = slam12;
        comg12 = clam12;
    }
    salp1 = cbet2 * somg12;
    calp1 = comg12 >= 0 ? sbet12 + cbet2 * sbet1 * sq(somg12) / (1 + comg12) : sbet12a - cbet2 * sbet1 * sq(somg12) / (1 - comg12);
    ssig12 = hypot(salp1, calp1);
    csig12 = sbet1 * sbet2 + cbet1 * cbet2 * comg12;
    if (shortline && ssig12 < g->etol2) {
