    } else if (fabs(g->n) > (real)(0.1) || csig12 >= 0 || ssig12 >= 6 * fabs(g->n) * pi * sq(cbet1)) {
    } else {
        real x, y, lamscale, betscale;
        real lam12x = atan2(-slam12, -clam12);
        if (g->f >= 0) {
            real k2 = sq(sbet1) * g->ep2, eps = k2 / (2 * (1 + sqrt(1 + k2)) + k2);
            lamscale = g->f * cbet1 * A3f(g, eps) * pi;
            betscale = lamscale * cbet1;
            x = lam12x / lamscale;
            y = sbet12a / betscale;
        } else {
            real cbet12a = cbet2 * cbet1 - sbet2 * sbet1, bet12a = atan2(sbet12a, cbet12a);
            real m12b, m0;
