/* Pseudocylindrical and miscellaneous spherical projections */
#include "proj.h"

/* helper: create an internal spherical unit-radius sub projection */
PJ *pj_sub_create(const char *name) {
    const PJ_LIST_ENTRY *e;
    PJ *S;
    for (e = pj_list; e->id; ++e)
        if (!strcmp(e->id, name)) break;
    if (!e->id) return NULL;
    S = pj_new();
    S->short_name = e->id;
    S->descr = e->descr;
    S->params = pj_mkparam("proj=");
