    S->es = 0.0;
    pj_calc_ellipsoid_params(S, 1.0, 0.0);
    S->k0 = 1.0;
    S = e->setup(S);
    return S;
}

/* ---------------- gn_sinu family: sinu, eck6, mbtfps, gn_sinu ---------------- */
struct gn_sinu_data { double *en; double m, n, C_x, C_y; };
#define SINU_MAX_ITER 8
#define SINU_LOOP_TOL 1e-7
static void gn_sinu_destructor(PJ *P, int e) {
    if (P && P->opaque) { struct gn_sinu_data *Q = (struct gn_sinu_data *)P->opaque; if (Q->en) free(Q->en); }
    pj_default_destructor(P, e);
}
static PJ_XY gn_sinu_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct gn_sinu_data *Q = (struct gn_sinu_data *)P->opaque;
    double s, c;
    xy.y = pj_mlfn(lp.phi, s = sin(lp.phi), c = cos(lp.phi), Q->en);
    xy.x = lp.lam * c / sqrt(1. - P->es * s * s);
    return xy;
}
static PJ_LP gn_sinu_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct gn_sinu_data *Q = (struct gn_sinu_data *)P->opaque;
    double s;
    if ((s = fabs(lp.phi = pj_inv_mlfn(xy.y, Q->en))) < M_HALFPI) {
        s = sin(lp.phi);
        lp.lam = xy.x * sqrt(1. - P->es * s * s) / cos(lp.phi);
    } else if ((s - EPS10) < M_HALFPI)
        lp.lam = 0.;
    else {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    return lp;
}
static PJ_XY gn_sinu_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct gn_sinu_data *Q = (struct gn_sinu_data *)P->opaque;
    if (Q->m == 0.0)
        lp.phi = Q->n != 1. ? aasin(Q->n * sin(lp.phi)) : lp.phi;
    else {
        double k, V;
        int i;
        k = Q->n * sin(lp.phi);
        for (i = SINU_MAX_ITER; i; --i) {
            lp.phi -= V = (Q->m * lp.phi + sin(lp.phi) - k) / (Q->m + cos(lp.phi));
            if (fabs(V) < SINU_LOOP_TOL) break;
        }
        if (!i) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
    }
    xy.x = Q->C_x * lp.lam * (Q->m + cos(lp.phi));
    xy.y = Q->C_y * lp.phi;
    return xy;
}
static PJ_LP gn_sinu_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct gn_sinu_data *Q = (struct gn_sinu_data *)P->opaque;
    xy.y /= Q->C_y;
    lp.phi = (Q->m != 0.0) ? aasin((Q->m * xy.y + sin(xy.y)) / Q->n) : (Q->n != 1. ? aasin(sin(xy.y) / Q->n) : xy.y);
    lp.lam = xy.x / (Q->C_x * (Q->m + cos(xy.y)));
    return lp;
}
static void gn_sinu_sphere_setup(PJ *P) {
    struct gn_sinu_data *Q = (struct gn_sinu_data *)P->opaque;
    P->es = 0;
    P->inv = gn_sinu_s_inverse;
    P->fwd = gn_sinu_s_forward;
    Q->C_y = sqrt((Q->m + 1.) / Q->n);
    Q->C_x = Q->C_y / (Q->m + 1.);
}
static struct gn_sinu_data *gn_sinu_alloc(PJ *P) {
    struct gn_sinu_data *Q = (struct gn_sinu_data *)calloc(1, sizeof(struct gn_sinu_data));
    P->opaque = Q;
    P->destructor = gn_sinu_destructor;
    return Q;
}
PJ *pj_sinu_setup(PJ *P) {
    struct gn_sinu_data *Q = gn_sinu_alloc(P);
    if (!(Q->en = pj_enfn(P->n))) return pj_default_destructor(P, PROJ_ERR_OTHER);
    if (P->es != 0.0) {
        P->inv = gn_sinu_e_inverse;
        P->fwd = gn_sinu_e_forward;
    } else {
        Q->n = 1.;
        Q->m = 0.;
        gn_sinu_sphere_setup(P);
    }
    return P;
}
PJ *pj_eck6_setup(PJ *P) {
    struct gn_sinu_data *Q = gn_sinu_alloc(P);
    Q->m = 1.;
    Q->n = 2.570796326794896619231321691;
    gn_sinu_sphere_setup(P);
    return P;
}
PJ *pj_mbtfps_setup(PJ *P) {
    struct gn_sinu_data *Q = gn_sinu_alloc(P);
    Q->m = 0.5;
