    gn_sinu_sphere_setup(P);
    return P;
}
PJ *pj_gn_sinu_setup(PJ *P) {
    struct gn_sinu_data *Q = gn_sinu_alloc(P);
    if (!pj_param(P->params, "tn").i) {
        proj_log_error(P, "Missing parameter n.");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    if (!pj_param(P->params, "tm").i) {
        proj_log_error(P, "Missing parameter m.");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    Q->n = pj_param(P->params, "dn").f;
    Q->m = pj_param(P->params, "dm").f;
    if (Q->n <= 0 || Q->m < 0) {
        proj_log_error(P, "Invalid value for n or m: n should be > 0 and m >= 0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    gn_sinu_sphere_setup(P);
    return P;
}

/* ---------------- moll family ---------------- */
struct moll_data { double C_x, C_y, C_p; };
#define MOLL_MAX_ITER 10
#define MOLL_LOOP_TOL 1e-7
static PJ_XY moll_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct moll_data *Q = (struct moll_data *)P->opaque;
    double k, V;
    int i;
    k = Q->C_p * sin(lp.phi);
    for (i = MOLL_MAX_ITER; i; --i) {
        lp.phi -= V = (lp.phi + sin(lp.phi) - k) / (1. + cos(lp.phi));
        if (fabs(V) < MOLL_LOOP_TOL) break;
    }
    if (!i)
        lp.phi = (lp.phi < 0.) ? -M_HALFPI : M_HALFPI;
    else
        lp.phi *= 0.5;
    xy.x = Q->C_x * lp.lam * cos(lp.phi);
    xy.y = Q->C_y * sin(lp.phi);
    return xy;
}
static PJ_LP moll_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct moll_data *Q = (struct moll_data *)P->opaque;
    lp.phi = aasin(xy.y / Q->C_y);
    lp.lam = xy.x / (Q->C_x * cos(lp.phi));
    if (fabs(lp.lam) < M_PI) {
        lp.phi += lp.phi;
        lp.phi = aasin((lp.phi + sin(lp.phi)) / Q->C_p);
    } else {
        lp.lam = lp.phi = HUGE_VAL;
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
    }
    return lp;
}
static PJ *moll_setup(PJ *P, double p) {
    struct moll_data *Q = (struct moll_data *)calloc(1, sizeof(struct moll_data));
    double r, sp, p2 = p + p;
    P->opaque = Q;
    P->es = 0;
    sp = sin(p);
    r = sqrt(M_TWOPI * sp / (p2 + sin(p2)));
    Q->C_x = 2. * r / M_PI;
    Q->C_y = r / sp;
    Q->C_p = p2 + sin(p2);
    P->inv = moll_s_inverse;
    P->fwd = moll_s_forward;
    return P;
}
PJ *pj_moll_setup(PJ *P) { return moll_setup(P, M_HALFPI); }
PJ *pj_wag4_setup(PJ *P) { return moll_setup(P, M_PI / 3.); }
PJ *pj_wag5_setup(PJ *P) {
