/* ---------------- goode ---------------- */
struct goode_data { PJ *sinu, *moll; };
#define GOODE_Y_COR 0.05280
#define GOODE_PHI_LIM .71093078197902358062
static void goode_destructor(PJ *P, int e) {
    if (P && P->opaque) {
        struct goode_data *Q = (struct goode_data *)P->opaque;
        if (Q->sinu) pj_free(Q->sinu);
        if (Q->moll) pj_free(Q->moll);
    }
    pj_default_destructor(P, e);
}
static PJ_XY goode_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct goode_data *Q = (struct goode_data *)P->opaque;
    if (fabs(lp.phi) <= GOODE_PHI_LIM)
        xy = Q->sinu->fwd(lp, Q->sinu);
    else {
        xy = Q->moll->fwd(lp, Q->moll);
        xy.y -= lp.phi >= 0.0 ? GOODE_Y_COR : -GOODE_Y_COR;
    }
    return xy;
}
static PJ_LP goode_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct goode_data *Q = (struct goode_data *)P->opaque;
    if (fabs(xy.y) <= GOODE_PHI_LIM)
        lp = Q->sinu->inv(xy, Q->sinu);
    else {
        xy.y += xy.y >= 0.0 ? GOODE_Y_COR : -GOODE_Y_COR;
        lp = Q->moll->inv(xy, Q->moll);
    }
    return lp;
}
PJ *pj_goode_setup(PJ *P) {
    struct goode_data *Q = (struct goode_data *)calloc(1, sizeof(struct goode_data));
    P->opaque = Q;
    P->destructor = goode_destructor;
    P->es = 0.;
    Q->sinu = pj_sub_create("sinu");
    Q->moll = pj_sub_create("moll");
    if (!Q->sinu || !Q->moll) return pj_default_destructor(P, PROJ_ERR_OTHER);
    P->fwd = goode_s_forward;
    P->inv = goode_s_inverse;
    return P;
}

/* ---------------- igh / igh_o / imoll / imoll_o ---------------- */
struct igh_data { PJ *pj[12]; double dy0; int n; };
static const double d4044118 = (40 + 44 / 60. + 11.8 / 3600.) * DEG_TO_RAD;
#define IGH_EPSLN 1.e-10
#define Dg(x) ((x) * DEG_TO_RAD)
static void igh_destructor(PJ *P, int e) {
    int i;
    if (P && P->opaque) {
        struct igh_data *Q = (struct igh_data *)P->opaque;
        for (i = 0; i < 12; ++i)
            if (Q->pj[i]) pj_free(Q->pj[i]);
    }
    pj_default_destructor(P, e);
}
static int igh_setup_zone(struct igh_data *Q, int n, const char *proj, double x_0, double y_0, double lon_0) {
    PJ *S = pj_sub_create(proj);
    if (!S) return 1;
    S->x0 = x_0;
    S->y0 = y_0;
    S->lam0 = lon_0;
    Q->pj[n - 1] = S;
    return 0;
}
static PJ_XY igh_apply(struct igh_data *Q, int z, PJ_LP lp) {
    PJ_XY xy;
    PJ *S = Q->pj[z - 1];
    lp.lam -= S->lam0;
    xy = S->fwd(lp, S);
    xy.x += S->x0;
    xy.y += S->y0;
    return xy;
}
static PJ_LP igh_unapply(struct igh_data *Q, int z, PJ_XY xy) {
    PJ_LP lp;
    PJ *S = Q->pj[z - 1];
    xy.x -= S->x0;
    xy.y -= S->y0;
    lp = S->inv(xy, S);
    lp.lam += S->lam0;
    return lp;
}
static PJ_XY igh_s_forward(PJ_LP lp, PJ *P) {
    struct igh_data *Q = (struct igh_data *)P->opaque;
    int z;
    if (lp.phi >= d4044118)
        z = (lp.lam <= -Dg(40) ? 1 : 2);
    else if (lp.phi >= 0)
        z = (lp.lam <= -Dg(40) ? 3 : 4);
    else if (lp.phi >= -d4044118) {
        if (lp.lam <= -Dg(100)) z = 5;
        else if (lp.lam <= -Dg(20)) z = 6;
        else if (lp.lam <= Dg(80)) z = 7;
        else z = 8;
    } else {
        if (lp.lam <= -Dg(100)) z = 9;
        else if (lp.lam <= -Dg(20)) z = 10;
        else if (lp.lam <= Dg(80)) z = 11;
        else z = 12;
    }
    return igh_apply(Q, z, lp);
}
static PJ_LP igh_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {HUGE_VAL, HUGE_VAL};
    struct igh_data *Q = (struct igh_data *)P->opaque;
    const double y90 = Q->dy0 + sqrt(2.0);
    int z = 0;
    if (xy.y > y90 + IGH_EPSLN || xy.y < -y90 + IGH_EPSLN) z = 0;
    else if (xy.y >= d4044118) z = (xy.x <= -Dg(40) ? 1 : 2);
    else if (xy.y >= 0) z = (xy.x <= -Dg(40) ? 3 : 4);
    else if (xy.y >= -d4044118) {
        if (xy.x <= -Dg(100)) z = 5;
        else if (xy.x <= -Dg(20)) z = 6;
        else if (xy.x <= Dg(80)) z = 7;
        else z = 8;
    } else {
        if (xy.x <= -Dg(100)) z = 9;
        else if (xy.x <= -Dg(20)) z = 10;
        else if (xy.x <= Dg(80)) z = 11;
        else z = 12;
    }
    if (z) {
        int ok = 0;
        lp = igh_unapply(Q, z, xy);
        switch (z) {
        case 1: ok = (lp.lam >= -Dg(180) - IGH_EPSLN && lp.lam <= -Dg(40) + IGH_EPSLN) || ((lp.lam >= -Dg(40) - IGH_EPSLN && lp.lam <= -Dg(10) + IGH_EPSLN) && (lp.phi >= Dg(60) - IGH_EPSLN && lp.phi <= Dg(90) + IGH_EPSLN)); break;
        case 2: ok = (lp.lam >= -Dg(40) - IGH_EPSLN && lp.lam <= Dg(180) + IGH_EPSLN) || ((lp.lam >= -Dg(180) - IGH_EPSLN && lp.lam <= -Dg(160) + IGH_EPSLN) && (lp.phi >= Dg(50) - IGH_EPSLN && lp.phi <= Dg(90) + IGH_EPSLN)) || ((lp.lam >= -Dg(50) - IGH_EPSLN && lp.lam <= -Dg(40) + IGH_EPSLN) && (lp.phi >= Dg(60) - IGH_EPSLN && lp.phi <= Dg(90) + IGH_EPSLN)); break;
        case 3: ok = (lp.lam >= -Dg(180) - IGH_EPSLN && lp.lam <= -Dg(40) + IGH_EPSLN); break;
        case 4: ok = (lp.lam >= -Dg(40) - IGH_EPSLN && lp.lam <= Dg(180) + IGH_EPSLN); break;
        case 5: ok = (lp.lam >= -Dg(180) - IGH_EPSLN && lp.lam <= -Dg(100) + IGH_EPSLN); break;
        case 6: ok = (lp.lam >= -Dg(100) - IGH_EPSLN && lp.lam <= -Dg(20) + IGH_EPSLN); break;
        case 7: ok = (lp.lam >= -Dg(20) - IGH_EPSLN && lp.lam <= Dg(80) + IGH_EPSLN); break;
        case 8: ok = (lp.lam >= Dg(80) - IGH_EPSLN && lp.lam <= Dg(180) + IGH_EPSLN); break;
        case 9: ok = (lp.lam >= -Dg(180) - IGH_EPSLN && lp.lam <= -Dg(100) + IGH_EPSLN); break;
        case 10: ok = (lp.lam >= -Dg(100) - IGH_EPSLN && lp.lam <= -Dg(20) + IGH_EPSLN); break;
        case 11: ok = (lp.lam >= -Dg(20) - IGH_EPSLN && lp.lam <= Dg(80) + IGH_EPSLN); break;
        case 12: ok = (lp.lam >= Dg(80) - IGH_EPSLN && lp.lam <= Dg(180) + IGH_EPSLN); break;
        }
        z = (!ok ? 0 : z);
    }
    if (!z) {
        lp.lam = HUGE_VAL;
        lp.phi = HUGE_VAL;
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
    }
    return lp;
