PJ *pj_igh_setup(PJ *P) {
    PJ_XY xy1, xy3;
    PJ_LP lp;
    struct igh_data *Q = (struct igh_data *)calloc(1, sizeof(struct igh_data));
    P->opaque = Q;
    P->destructor = igh_destructor;
    lp.lam = 0;
    lp.phi = d4044118;
    if (igh_setup_zone(Q, 3, "sinu", -Dg(100), 0, -Dg(100)) || igh_setup_zone(Q, 4, "sinu", Dg(30), 0, Dg(30)) ||
        igh_setup_zone(Q, 5, "sinu", -Dg(160), 0, -Dg(160)) || igh_setup_zone(Q, 6, "sinu", -Dg(60), 0, -Dg(60)) ||
        igh_setup_zone(Q, 7, "sinu", Dg(20), 0, Dg(20)) || igh_setup_zone(Q, 8, "sinu", Dg(140), 0, Dg(140)) ||
        igh_setup_zone(Q, 1, "moll", -Dg(100), 0, -Dg(100)))
        return pj_default_destructor(P, PROJ_ERR_OTHER);
    xy1 = Q->pj[0]->fwd(lp, Q->pj[0]);
    xy3 = Q->pj[2]->fwd(lp, Q->pj[2]);
    Q->dy0 = xy3.y - xy1.y;
    Q->pj[0]->y0 = Q->dy0;
    if (igh_setup_zone(Q, 2, "moll", Dg(30), Q->dy0, Dg(30)) || igh_setup_zone(Q, 9, "moll", -Dg(160), -Q->dy0, -Dg(160)) ||
        igh_setup_zone(Q, 10, "moll", -Dg(60), -Q->dy0, -Dg(60)) || igh_setup_zone(Q, 11, "moll", Dg(20), -Q->dy0, Dg(20)) ||
        igh_setup_zone(Q, 12, "moll", Dg(140), -Q->dy0, Dg(140)))
        return pj_default_destructor(P, PROJ_ERR_OTHER);
    P->inv = igh_s_inverse;
    P->fwd = igh_s_forward;
    P->es = 0.;
    return P;
}

/* igh_o: oceanic view (approximation of the zone layout) */
static PJ_XY igh_o_s_forward(PJ_LP lp, PJ *P) {
    struct igh_data *Q = (struct igh_data *)P->opaque;
    int z;
    if (lp.phi >= d4044118)
        z = (lp.lam <= -Dg(90) ? 1 : 2);
    else if (lp.phi >= 0)
        z = (lp.lam <= -Dg(90) ? 3 : 4);
    else if (lp.phi >= -d4044118) {
        if (lp.lam <= -Dg(60)) z = 5;
        else if (lp.lam <= Dg(90)) z = 6;
        else z = 7;
    } else {
        if (lp.lam <= -Dg(60)) z = 8;
        else if (lp.lam <= Dg(90)) z = 9;
        else z = 10;
    }
    return igh_apply(Q, z, lp);
}
static PJ_LP igh_o_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {HUGE_VAL, HUGE_VAL};
    struct igh_data *Q = (struct igh_data *)P->opaque;
    const double y90 = Q->dy0 + sqrt(2.0);
    int z = 0;
    if (xy.y > y90 + IGH_EPSLN || xy.y < -y90 + IGH_EPSLN) z = 0;
    else if (xy.y >= d4044118) z = (xy.x <= -Dg(90) ? 1 : 2);
    else if (xy.y >= 0) z = (xy.x <= -Dg(90) ? 3 : 4);
    else if (xy.y >= -d4044118) {
        if (xy.x <= -Dg(60)) z = 5;
        else if (xy.x <= Dg(90)) z = 6;
        else z = 7;
    } else {
        if (xy.x <= -Dg(60)) z = 8;
        else if (xy.x <= Dg(90)) z = 9;
        else z = 10;
    }
    if (z) {
        lp = igh_unapply(Q, z, xy);
        if (lp.lam < -M_PI - IGH_EPSLN || lp.lam > M_PI + IGH_EPSLN) z = 0;
    }
    if (!z) {
        lp.lam = HUGE_VAL;
        lp.phi = HUGE_VAL;
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
    }
    return lp;
}
PJ *pj_igh_o_setup(PJ *P) {
    PJ_XY xy1, xy3;
