#define N2_C2 (11 * N2_B2)
#define N2_C3 (13 * N2_B3)
#define N2_EPS 1e-11
#define N2_MAX_Y (0.84719 * 0.535117535153096 * M_PI)
static PJ_XY natearth2_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    double phi2, phi4, phi6;
