#define E4_C_p 3.57079632679489661922
#define E4_RC_p .28004957675577868795
#define E4_NITER 6
#define E4_EPS 1e-7
static PJ_XY eck4_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    double p, V, s, c;
    int i;
    (void)P;
    p = E4_C_p * sin(lp.phi);
    V = lp.phi * lp.phi;
    lp.phi *= 0.895168 + V * (0.0218849 + V * 0.00826809);
    for (i = E4_NITER; i; --i) {
        c = cos(lp.phi);
        s = sin(lp.phi);
        lp.phi -= V = (lp.phi + s * (c + 2.) - p) / (1. + c * (c + 2.) - s * s);
        if (fabs(V) < E4_EPS) break;
