static PJ_XY urmfps_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct urmfps_data *Q = (struct urmfps_data *)P->opaque;
    lp.phi = aasin(Q->n * sin(lp.phi));
