static PJ_XY wag3_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct wag3_data *Q = (struct wag3_data *)P->opaque;
    xy.x = Q->C_x * lp.lam * cos(W3_TWOTHIRD * lp.phi);
    xy.y = lp.phi;
