/* ---------------- wag7 ---------------- */
static PJ_XY wag7_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    double theta, ct, D;
    (void)P;
    theta = asin(xy.y = 0.90630778703664996 * sin(lp.phi));
    xy.x = 2.66723 * (ct = cos(theta)) * sin(lp.lam /= 3.);
    xy.y *= 1.24104 * (D = 1 / (sqrt(0.5 * (1 + ct * cos(lp.lam)))));
    xy.x *= D;
    return xy;
}
PJ *pj_wag7_setup(PJ *P) { P->fwd = wag7_s_forward; P->inv = NULL; P->es = 0.; return P; }

/* ---------------- sts family: kav5, qua_aut, mbt_s, fouc ---------------- */
struct sts_data { double C_x, C_y, C_p; int tan_mode; };
static PJ_XY sts_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct sts_data *Q = (struct sts_data *)P->opaque;
    double c;
    xy.x = Q->C_x * lp.lam * cos(lp.phi);
    xy.y = Q->C_y;
    lp.phi *= Q->C_p;
    c = cos(lp.phi);
    if (Q->tan_mode) {
        xy.x *= c * c;
        xy.y *= tan(lp.phi);
    } else {
        xy.x /= c;
        xy.y *= sin(lp.phi);
    }
    return xy;
}
static PJ_LP sts_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct sts_data *Q = (struct sts_data *)P->opaque;
    double c;
    xy.y /= Q->C_y;
    c = cos(lp.phi = Q->tan_mode ? atan(xy.y) : aasin(xy.y));
    lp.phi /= Q->C_p;
    lp.lam = xy.x / (Q->C_x * cos(lp.phi));
    if (Q->tan_mode)
        lp.lam /= c * c;
    else
        lp.lam *= c;
    return lp;
}
static PJ *sts_setup(PJ *P, double p, double q, int mode) {
    struct sts_data *Q = (struct sts_data *)calloc(1, sizeof(struct sts_data));
    P->opaque = Q;
    P->es = 0.;
    P->inv = sts_s_inverse;
    P->fwd = sts_s_forward;
    Q->C_x = q / p;
    Q->C_y = p;
    Q->C_p = 1 / q;
    Q->tan_mode = mode;
    return P;
}
PJ *pj_fouc_setup(PJ *P) { return sts_setup(P, 2., 2., 1); }
PJ *pj_kav5_setup(PJ *P) { return sts_setup(P, 1.50488, 1.35439, 0); }
PJ *pj_qua_aut_setup(PJ *P) { return sts_setup(P, 2., 2., 0); }
PJ *pj_mbt_s_setup(PJ *P) { return sts_setup(P, 1.48875, 1.36509, 0); }

/* ---------------- mbt_fps ---------------- */
#define MF_MAX_ITER 10
#define MF_LOOP_TOL 1e-7
#define MF_C1 0.45503
#define MF_C2 1.36509
#define MF_C3 1.41546
#define MF_C_x 0.22248
#define MF_C_y 1.44492
#define MF_C1_2 0.33333333333333333333333333
static PJ_XY mbt_fps_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    double k, V, t;
    int i;
    (void)P;
    k = MF_C3 * sin(lp.phi);
    for (i = MF_MAX_ITER; i; --i) {
        t = lp.phi / MF_C2;
        lp.phi -= V = (MF_C1 * sin(t) + sin(lp.phi) - k) / (MF_C1_2 * cos(t) + cos(lp.phi));
        if (fabs(V) < MF_LOOP_TOL) break;
    }
    t = lp.phi / MF_C2;
    xy.x = MF_C_x * lp.lam * (1. + 3. * cos(lp.phi) / cos(t));
    xy.y = MF_C_y * sin(t);
    return xy;
}
static PJ_LP mbt_fps_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    double t;
    (void)P;
    lp.phi = MF_C2 * (t = aasin(xy.y / MF_C_y));
    lp.lam = xy.x / (MF_C_x * (1. + 3. * cos(lp.phi) / cos(t)));
    lp.phi = aasin((MF_C1 * sin(t) + sin(lp.phi)) / MF_C3);
    return lp;
}
PJ *pj_mbt_fps_setup(PJ *P) { P->es = 0; P->inv = mbt_fps_s_inverse; P->fwd = mbt_fps_s_forward; return P; }

/* ---------------- mbtfpp ---------------- */
#define MPP_CS .95257934441568037152
#define MPP_FXC .92582009977255146156
#define MPP_FYC 3.40168025708304504493
#define MPP_C23 .66666666666666666666
#define MPP_C13 .33333333333333333333
#define MPP_ONEEPS 1.0000001
static PJ_XY mbtfpp_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    (void)P;
    lp.phi = asin(MPP_CS * sin(lp.phi));
    xy.x = MPP_FXC * lp.lam * (2. * cos(MPP_C23 * lp.phi) - 1.);
    xy.y = MPP_FYC * sin(MPP_C13 * lp.phi);
    return xy;
}
static PJ_LP mbtfpp_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    lp.phi = xy.y / MPP_FYC;
    if (fabs(lp.phi) >= 1.) {
        if (fabs(lp.phi) > MPP_ONEEPS) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return lp;
        } else
            lp.phi = (lp.phi < 0.) ? -M_HALFPI : M_HALFPI;
    } else
        lp.phi = asin(lp.phi);
    lp.lam = xy.x / (MPP_FXC * (2. * cos(MPP_C23 * (lp.phi *= 3.)) - 1.));
    if (fabs(lp.phi = sin(lp.phi) / MPP_CS) >= 1.) {
        if (fabs(lp.phi) > MPP_ONEEPS) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return lp;
        } else
            lp.phi = (lp.phi < 0.) ? -M_HALFPI : M_HALFPI;
    } else
        lp.phi = asin(lp.phi);
    return lp;
}
PJ *pj_mbtfpp_setup(PJ *P) { P->es = 0; P->inv = mbtfpp_s_inverse; P->fwd = mbtfpp_s_forward; return P; }

/* ---------------- mbtfpq ---------------- */
#define MQ_NITER 20
#define MQ_EPS 1e-7
#define MQ_ONETOL 1.000001
#define MQ_C 1.70710678118654752440
#define MQ_RC 0.58578643762690495119
#define MQ_FYC 1.87475828462269495505
#define MQ_RYC 0.53340209679417701685
#define MQ_FXC 0.31245971410378249250
#define MQ_RXC 3.20041258076506210122
static PJ_XY mbtfpq_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    double th1, c;
    int i;
    (void)P;
    c = MQ_C * sin(lp.phi);
    for (i = MQ_NITER; i; --i) {
        lp.phi -= th1 = (sin(.5 * lp.phi) + sin(lp.phi) - c) / (.5 * cos(.5 * lp.phi) + cos(lp.phi));
        if (fabs(th1) < MQ_EPS) break;
    }
    xy.x = MQ_FXC * lp.lam * (1.0 + 2. * cos(lp.phi) / cos(0.5 * lp.phi));
    xy.y = MQ_FYC * sin(0.5 * lp.phi);
    return xy;
}
static PJ_LP mbtfpq_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    double t;
    lp.phi = MQ_RYC * xy.y;
    if (fabs(lp.phi) > 1.) {
        if (fabs(lp.phi) > MQ_ONETOL) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return lp;
        } else if (lp.phi < 0.) {
            t = -1.;
            lp.phi = -M_PI;
        } else {
            t = 1.;
            lp.phi = M_PI;
        }
    } else
        lp.phi = 2. * asin(t = lp.phi);
    lp.lam = MQ_RXC * xy.x / (1. + 2. * cos(lp.phi) / cos(0.5 * lp.phi));
    lp.phi = MQ_RC * (t + sin(lp.phi));
    if (fabs(lp.phi) > 1.) {
        if (fabs(lp.phi) > MQ_ONETOL) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return lp;
        } else
            lp.phi = lp.phi < 0. ? -M_HALFPI : M_HALFPI;
    } else
        lp.phi = asin(lp.phi);
    return lp;
}
PJ *pj_mbtfpq_setup(PJ *P) { P->es = 0; P->inv = mbtfpq_s_inverse; P->fwd = mbtfpq_s_forward; return P; }

/* ---------------- putp2 ---------------- */
#define P2_C_x 1.89490
#define P2_C_y 1.71848
#define P2_C_p 0.6141848493043784
#define P2_EPS 1e-10
#define P2_NITER 10
#define P2_PI_DIV_3 1.0471975511965977
static PJ_XY putp2_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    double p, c, s, V;
    int i;
    (void)P;
    p = P2_C_p * sin(lp.phi);
    s = lp.phi * lp.phi;
    lp.phi *= 0.615709 + s * (0.00909953 + s * 0.0046292);
    for (i = P2_NITER; i; --i) {
        c = cos(lp.phi);
        s = sin(lp.phi);
        lp.phi -= V = (lp.phi + s * (c - 1.) - p) / (1. + c * (c - 1.) - s * s);
        if (fabs(V) < P2_EPS) break;
    }
    if (!i) lp.phi = P2_PI_DIV_3;
    xy.x = P2_C_x * lp.lam * (cos(lp.phi) - 0.5);
    xy.y = P2_C_y * sin(lp.phi);
    return xy;
}
static PJ_LP putp2_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    double c;
    (void)P;
    lp.phi = aasin(xy.y / P2_C_y);
    lp.lam = xy.x / (P2_C_x * ((c = cos(lp.phi)) - 0.5));
    lp.phi = aasin((lp.phi + sin(lp.phi) * (c - 1.)) / P2_C_p);
    return lp;
}
PJ *pj_putp2_setup(PJ *P) { P->es = 0.; P->inv = putp2_s_inverse; P->fwd = putp2_s_forward; return P; }

/* ---------------- putp3 / putp3p ---------------- */
struct putp3_data { double A; };
#define P3_C 0.79788456
#define P3_RPISQ 0.1013211836
static PJ_XY putp3_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct putp3_data *Q = (struct putp3_data *)P->opaque;
    xy.x = P3_C * lp.lam * (1. - Q->A * lp.phi * lp.phi);
    xy.y = P3_C * lp.phi;
    return xy;
}
static PJ_LP putp3_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct putp3_data *Q = (struct putp3_data *)P->opaque;
    lp.phi = xy.y / P3_C;
    lp.lam = xy.x / (P3_C * (1. - Q->A * lp.phi * lp.phi));
    return lp;
}
static PJ *putp3_common(PJ *P, double A) {
    struct putp3_data *Q = (struct putp3_data *)calloc(1, sizeof(struct putp3_data));
    P->opaque = Q;
    Q->A = A;
    P->es = 0.;
    P->inv = putp3_s_inverse;
    P->fwd = putp3_s_forward;
    return P;
}
PJ *pj_putp3_setup(PJ *P) { return putp3_common(P, 4. * P3_RPISQ); }
PJ *pj_putp3p_setup(PJ *P) { return putp3_common(P, 2. * P3_RPISQ); }

/* ---------------- putp4p / weren ---------------- */
struct putp4p_data { double C_x, C_y; };
static PJ_XY putp4p_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct putp4p_data *Q = (struct putp4p_data *)P->opaque;
    lp.phi = aasin(0.883883476 * sin(lp.phi));
    xy.x = Q->C_x * lp.lam * cos(lp.phi);
    xy.x /= cos(lp.phi *= 0.333333333333333);
    xy.y = Q->C_y * sin(lp.phi);
    return xy;
}
static PJ_LP putp4p_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct putp4p_data *Q = (struct putp4p_data *)P->opaque;
    lp.phi = aasin(xy.y / Q->C_y);
    lp.lam = xy.x * cos(lp.phi) / Q->C_x;
    lp.phi *= 3.;
    lp.lam /= cos(lp.phi);
    lp.phi = aasin(1.13137085 * sin(lp.phi));
    return lp;
}
static PJ *putp4p_common(PJ *P, double cx, double cy) {
    struct putp4p_data *Q = (struct putp4p_data *)calloc(1, sizeof(struct putp4p_data));
    P->opaque = Q;
    Q->C_x = cx; Q->C_y = cy;
    P->es = 0.;
    P->inv = putp4p_s_inverse;
    P->fwd = putp4p_s_forward;
    return P;
}
PJ *pj_putp4p_setup(PJ *P) { return putp4p_common(P, 0.874038744, 3.883251825); }
PJ *pj_weren_setup(PJ *P) { return putp4p_common(P, 1., 4.442882938); }

/* ---------------- putp5 / putp5p ---------------- */
struct putp5_data { double A, B; };
#define P5_C 1.01346
#define P5_D 1.2158542
static PJ_XY putp5_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct putp5_data *Q = (struct putp5_data *)P->opaque;
    xy.x = P5_C * lp.lam * (Q->A - Q->B * sqrt(1. + P5_D * lp.phi * lp.phi));
    xy.y = P5_C * lp.phi;
    return xy;
}
static PJ_LP putp5_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct putp5_data *Q = (struct putp5_data *)P->opaque;
    lp.phi = xy.y / P5_C;
    lp.lam = xy.x / (P5_C * (Q->A - Q->B * sqrt(1. + P5_D * lp.phi * lp.phi)));
    return lp;
}
static PJ *putp5_common(PJ *P, double A, double B) {
    struct putp5_data *Q = (struct putp5_data *)calloc(1, sizeof(struct putp5_data));
    P->opaque = Q;
    Q->A = A; Q->B = B;
    P->es = 0.;
    P->inv = putp5_s_inverse;
    P->fwd = putp5_s_forward;
    return P;
}
PJ *pj_putp5_setup(PJ *P) { return putp5_common(P, 2., 1.); }
PJ *pj_putp5p_setup(PJ *P) { return putp5_common(P, 1.5, 0.5); }

/* ---------------- putp6 / putp6p ---------------- */
struct putp6_data { double C_x, C_y, A, B, D; };
#define P6_EPS 1e-10
#define P6_NITER 10
#define P6_CON_POLE 1.732050807568877
static PJ_XY putp6_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct putp6_data *Q = (struct putp6_data *)P->opaque;
    double p, r, V;
    int i;
    p = Q->B * sin(lp.phi);
    lp.phi *= 1.10265779;
    for (i = P6_NITER; i; --i) {
        r = sqrt(1. + lp.phi * lp.phi);
        lp.phi -= V = ((Q->A - r) * lp.phi - log(lp.phi + r) - p) / (Q->A - 2. * r);
        if (fabs(V) < P6_EPS) break;
    }
    if (!i) lp.phi = p < 0. ? -P6_CON_POLE : P6_CON_POLE;
    xy.x = Q->C_x * lp.lam * (Q->D - sqrt(1. + lp.phi * lp.phi));
    xy.y = Q->C_y * lp.phi;
    return xy;
}
static PJ_LP putp6_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct putp6_data *Q = (struct putp6_data *)P->opaque;
    double r;
    lp.phi = xy.y / Q->C_y;
    r = sqrt(1. + lp.phi * lp.phi);
    lp.lam = xy.x / (Q->C_x * (Q->D - r));
    lp.phi = aasin(((Q->A - r) * lp.phi - log(lp.phi + r)) / Q->B);
    return lp;
}
static PJ *putp6_common(PJ *P, double cx, double cy, double A, double B, double D) {
    struct putp6_data *Q = (struct putp6_data *)calloc(1, sizeof(struct putp6_data));
    P->opaque = Q;
    Q->C_x = cx; Q->C_y = cy; Q->A = A; Q->B = B; Q->D = D;
    P->es = 0.;
    P->inv = putp6_s_inverse;
    P->fwd = putp6_s_forward;
    return P;
}
PJ *pj_putp6_setup(PJ *P) { return putp6_common(P, 1.01346, 0.91910, 4., 2.1471437182129378784, 2.); }
PJ *pj_putp6p_setup(PJ *P) { return putp6_common(P, 0.44329, 0.80404, 6., 5.61125, 3.); }

/* ---------------- hatano ---------------- */
#define HT_NITER 20
#define HT_EPS 1e-7
#define HT_ONETOL 1.000001
#define HT_CN 2.67595
#define HT_CS 2.43763
#define HT_RCN 0.37369906014686373063
#define HT_RCS 0.41023453108141924738
#define HT_FYCN 1.75859
#define HT_FYCS 1.93052
#define HT_RYCN 0.56863737426006061674
#define HT_RYCS 0.51799515156538134803
#define HT_FXC 0.85
#define HT_RXC 1.17647058823529411764
static PJ_XY hatano_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    double th1, c;
    int i;
    (void)P;
    c = sin(lp.phi) * (lp.phi < 0. ? HT_CS : HT_CN);
    for (i = HT_NITER; i; --i) {
        lp.phi -= th1 = (lp.phi + sin(lp.phi) - c) / (1. + cos(lp.phi));
        if (fabs(th1) < HT_EPS) break;
    }
    xy.x = HT_FXC * lp.lam * cos(lp.phi *= .5);
    xy.y = sin(lp.phi) * (lp.phi < 0. ? HT_FYCS : HT_FYCN);
    return xy;
}
static PJ_LP hatano_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    double th;
    th = xy.y * (xy.y < 0. ? HT_RYCS : HT_RYCN);
    if (fabs(th) > 1.) {
        if (fabs(th) > HT_ONETOL) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return lp;
        } else
            th = th > 0. ? M_HALFPI : -M_HALFPI;
    } else
        th = asin(th);
    lp.lam = HT_RXC * xy.x / cos(th);
    th += th;
    lp.phi = (th + sin(th)) * (xy.y < 0. ? HT_RCS : HT_RCN);
    if (fabs(lp.phi) > 1.) {
        if (fabs(lp.phi) > HT_ONETOL) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return lp;
        } else
            lp.phi = lp.phi > 0. ? M_HALFPI : -M_HALFPI;
    } else
        lp.phi = asin(lp.phi);
    return lp;
}
PJ *pj_hatano_setup(PJ *P) { P->es = 0.; P->inv = hatano_s_inverse; P->fwd = hatano_s_forward; return P; }

/* ---------------- natearth ---------------- */
#define NE_A0 0.8707
#define NE_A1 -0.131979
#define NE_A2 -0.013791
#define NE_A3 0.003971
#define NE_A4 -0.001529
#define NE_B0 1.007226
#define NE_B1 0.015085
#define NE_B2 -0.044475
#define NE_B3 0.028874
#define NE_B4 -0.005916
#define NE_C0 NE_B0
#define NE_C1 (3 * NE_B1)
#define NE_C2 (7 * NE_B2)
#define NE_C3 (9 * NE_B3)
#define NE_C4 (11 * NE_B4)
#define NE_EPS 1e-11
#define NE_MAX_Y (0.8707 * 0.52 * M_PI)
static PJ_XY natearth_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    double phi2, phi4;
    (void)P;
    phi2 = lp.phi * lp.phi;
    phi4 = phi2 * phi2;
    xy.x = lp.lam * (NE_A0 + phi2 * (NE_A1 + phi2 * (NE_A2 + phi4 * phi2 * (NE_A3 + phi2 * NE_A4))));
    xy.y = lp.phi * (NE_B0 + phi2 * (NE_B1 + phi4 * (NE_B2 + NE_B3 * phi2 + NE_B4 * phi4)));
    return xy;
}
static PJ_LP natearth_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    double yc, tol, y2, y4, f, fder;
    int i;
    (void)P;
    yc = xy.y;
    if (yc > NE_MAX_Y) yc = NE_MAX_Y;
    else if (yc < -NE_MAX_Y) yc = -NE_MAX_Y;
    for (i = 100; i; --i) {
        y2 = yc * yc;
        y4 = y2 * y2;
        f = (yc * (NE_B0 + y2 * (NE_B1 + y4 * (NE_B2 + NE_B3 * y2 + NE_B4 * y4)))) - xy.y;
        fder = NE_C0 + y2 * (NE_C1 + y4 * (NE_C2 + NE_C3 * y2 + NE_C4 * y4));
        tol = f / fder;
        yc -= tol;
        if (fabs(tol) < NE_EPS) break;
    }
    lp.phi = yc;
    y2 = yc * yc;
    y4 = y2 * y2;
    lp.lam = xy.x / (NE_A0 + y2 * (NE_A1 + y2 * (NE_A2 + y4 * y2 * (NE_A3 + y2 * NE_A4))));
    return lp;
}
PJ *pj_natearth_setup(PJ *P) { P->es = 0; P->inv = natearth_s_inverse; P->fwd = natearth_s_forward; return P; }

/* ---------------- natearth2 ---------------- */
#define N2_A0 0.84719
#define N2_A1 -0.13063
#define N2_A2 -0.04515
#define N2_A3 0.05494
#define N2_A4 -0.02326
#define N2_A5 0.00331
#define N2_B0 1.01183
#define N2_B1 -0.02625
#define N2_B2 0.01926
#define N2_B3 -0.00396
#define N2_C0 N2_B0
#define N2_C1 (9 * N2_B1)
#define N2_C2 (11 * N2_B2)
#define N2_C3 (13 * N2_B3)
#define N2_EPS 1e-11
#define N2_MAX_Y (0.84719 * 0.535117535153096 * M_PI)
static PJ_XY natearth2_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    double phi2, phi4, phi6;
    (void)P;
    phi2 = lp.phi * lp.phi;
    phi4 = phi2 * phi2;
    phi6 = phi2 * phi4;
    xy.x = lp.lam * (N2_A0 + N2_A1 * phi2 + phi6 * phi6 * (N2_A2 + N2_A3 * phi2 + N2_A4 * phi4 + N2_A5 * phi6));
    xy.y = lp.phi * (N2_B0 + phi4 * phi4 * (N2_B1 + N2_B2 * phi2 + N2_B3 * phi4));
    return xy;
}
static PJ_LP natearth2_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    double yc, tol, y2, y4, y6, f, fder;
    int i;
    (void)P;
    yc = xy.y;
    if (yc > N2_MAX_Y) yc = N2_MAX_Y;
    else if (yc < -N2_MAX_Y) yc = -N2_MAX_Y;
    for (i = 100; i; --i) {
        y2 = yc * yc;
        y4 = y2 * y2;
        f = (yc * (N2_B0 + y4 * y4 * (N2_B1 + N2_B2 * y2 + N2_B3 * y4))) - xy.y;
        fder = N2_C0 + y4 * y4 * (N2_C1 + N2_C2 * y2 + N2_C3 * y4);
        tol = f / fder;
        yc -= tol;
        if (fabs(tol) < N2_EPS) break;
    }
    lp.phi = yc;
    y2 = yc * yc;
    y4 = y2 * y2;
    y6 = y2 * y4;
    lp.lam = xy.x / (N2_A0 + N2_A1 * y2 + y6 * y6 * (N2_A2 + N2_A3 * y2 + N2_A4 * y4 + N2_A5 * y6));
    return lp;
}
PJ *pj_natearth2_setup(PJ *P) { P->es = 0; P->inv = natearth2_s_inverse; P->fwd = natearth2_s_forward; return P; }

/* ---------------- boggs ---------------- */
#define BG_NITER 20
#define BG_EPSLN 1e-7
#define BG_FXC 2.00276
#define BG_FXC2 1.11072
#define BG_FYC 0.49931
static PJ_XY boggs_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    double theta, th1, c;
    int i;
    (void)P;
    theta = lp.phi;
    if (fabs(fabs(lp.phi) - M_HALFPI) < BG_EPSLN)
        xy.x = 0.;
    else {
        c = sin(theta) * M_PI;
        for (i = BG_NITER; i; --i) {
            theta -= th1 = (theta + sin(theta) - c) / (1. + cos(theta));
            if (fabs(th1) < BG_EPSLN) break;
        }
        theta *= 0.5;
        xy.x = BG_FXC * lp.lam / (1. / cos(lp.phi) + BG_FXC2 / cos(theta));
    }
    xy.y = BG_FYC * (lp.phi + M_SQRT2 * sin(theta));
    return xy;
}
PJ *pj_boggs_setup(PJ *P) { P->es = 0.; P->fwd = boggs_s_forward; P->inv = NULL; return P; }

/* ---------------- collg ---------------- */
#define CG_FXC 1.12837916709551257390
#define CG_FYC 1.77245385090551602729
#define CG_ONEEPS 1.0000001
static PJ_XY collg_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    (void)P;
    if ((xy.y = 1. - sin(lp.phi)) <= 0.)
        xy.y = 0.;
    else
        xy.y = sqrt(xy.y);
    xy.x = CG_FXC * lp.lam * xy.y;
    xy.y = CG_FYC * (1. - xy.y);
    return xy;
}
static PJ_LP collg_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    lp.phi = xy.y / CG_FYC - 1.;
    if (fabs(lp.phi = 1. - lp.phi * lp.phi) < 1.)
        lp.phi = asin(lp.phi);
    else if (fabs(lp.phi) > CG_ONEEPS) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    } else
        lp.phi = lp.phi < 0. ? -M_HALFPI : M_HALFPI;
    if ((lp.lam = 1. - sin(lp.phi)) <= 0.)
        lp.lam = 0.;
    else
        lp.lam = xy.x / (CG_FXC * sqrt(lp.lam));
    return lp;
}
PJ *pj_collg_setup(PJ *P) { P->es = 0.; P->inv = collg_s_inverse; P->fwd = collg_s_forward; return P; }

/* ---------------- crast ---------------- */
#define CR_XM 0.97720502380583984317
#define CR_RXM 1.02332670794648848847
#define CR_YM 3.06998012383946546542
#define CR_RYM 0.32573500793527994772
#define CR_THIRD 0.333333333333333333
static PJ_XY crast_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    (void)P;
    lp.phi *= CR_THIRD;
    xy.x = CR_XM * lp.lam * (2. * cos(lp.phi + lp.phi) - 1.);
    xy.y = CR_YM * sin(lp.phi);
    return xy;
}
static PJ_LP crast_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    (void)P;
    lp.phi = 3. * asin(xy.y * CR_RYM);
    lp.lam = xy.x * CR_RXM / (2. * cos((lp.phi + lp.phi) * CR_THIRD) - 1);
    return lp;
}
PJ *pj_crast_setup(PJ *P) { P->es = 0.; P->inv = crast_s_inverse; P->fwd = crast_s_forward; return P; }

/* ---------------- denoy ---------------- */
#define DN_C0 0.95
#define DN_C1 -.08333333333333333333
#define DN_C3 .00166666666666666666
#define DN_D1 0.9
#define DN_D5 0.03
static PJ_XY denoy_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    (void)P;
    xy.y = lp.phi;
    xy.x = lp.lam;
    lp.lam = fabs(lp.lam);
    xy.x *= cos((DN_C0 + lp.lam * (DN_C1 + lp.lam * lp.lam * DN_C3)) * (lp.phi * (DN_D1 + DN_D5 * lp.phi * lp.phi * lp.phi * lp.phi)));
    return xy;
}
PJ *pj_denoy_setup(PJ *P) { P->es = 0.; P->fwd = denoy_s_forward; P->inv = NULL; return P; }

/* ---------------- fahey ---------------- */
#define FH_TOL 1e-6
static PJ_XY fahey_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    (void)P;
    xy.y = 1.819152 * (xy.x = tan(0.5 * lp.phi));
    xy.x = 0.819152 * lp.lam * asqrt(1 - xy.x * xy.x);
    return xy;
}
static PJ_LP fahey_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    (void)P;
    xy.y /= 1.819152;
    lp.phi = 2. * atan(xy.y);
    xy.y = 1. - xy.y * xy.y;
    lp.lam = fabs(xy.y) < FH_TOL ? 0. : xy.x / (0.819152 * sqrt(xy.y));
    return lp;
}
PJ *pj_fahey_setup(PJ *P) { P->es = 0.; P->inv = fahey_s_inverse; P->fwd = fahey_s_forward; return P; }

/* ---------------- fouc_s ---------------- */
struct fouc_s_data { double n, n1; };
#define FS_MAX_ITER 10
#define FS_LOOP_TOL 1e-7
static PJ_XY fouc_s_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct fouc_s_data *Q = (struct fouc_s_data *)P->opaque;
    double t;
    t = cos(lp.phi);
    xy.x = lp.lam * t / (Q->n + Q->n1 * t);
    xy.y = Q->n * lp.phi + Q->n1 * sin(lp.phi);
    return xy;
}
static PJ_LP fouc_s_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct fouc_s_data *Q = (struct fouc_s_data *)P->opaque;
    double V;
    int i;
    if (Q->n != 0.0) {
        lp.phi = xy.y;
        for (i = FS_MAX_ITER; i; --i) {
            lp.phi -= V = (Q->n * lp.phi + Q->n1 * sin(lp.phi) - xy.y) / (Q->n + Q->n1 * cos(lp.phi));
            if (fabs(V) < FS_LOOP_TOL) break;
        }
        if (!i) lp.phi = xy.y < 0. ? -M_HALFPI : M_HALFPI;
    } else
        lp.phi = aasin(xy.y);
    V = cos(lp.phi);
    lp.lam = xy.x * (Q->n + Q->n1 * V) / V;
    return lp;
}
PJ *pj_fouc_s_setup(PJ *P) {
    struct fouc_s_data *Q = (struct fouc_s_data *)calloc(1, sizeof(struct fouc_s_data));
    P->opaque = Q;
    Q->n = pj_param(P->params, "dn").f;
    if (Q->n < 0. || Q->n > 1.) {
        proj_log_error(P, "Invalid value for n: it should be in [0,1] range");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    Q->n1 = 1. - Q->n;
    P->es = 0;
    P->inv = fouc_s_s_inverse;
    P->fwd = fouc_s_s_forward;
    return P;
}

/* ---------------- gins8 ---------------- */
#define G8_Cl 0.000952426
#define G8_Cp 0.162388
#define G8_C12 0.08333333333333333
static PJ_XY gins8_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    double t;
    (void)P;
    t = lp.phi * lp.phi;
    xy.y = lp.phi * (1. + t * G8_C12);
    xy.x = lp.lam * (1. - G8_Cp * t);
    t = lp.lam * lp.lam;
    xy.x *= (0.87 - G8_Cl * t * t);
    return xy;
}
PJ *pj_gins8_setup(PJ *P) { P->es = 0.; P->fwd = gins8_s_forward; P->inv = NULL; return P; }

/* ---------------- loxim ---------------- */
struct loxim_data { double phi1, cosphi1, tanphi1; };
#define LX_EPS 1e-8
static PJ_XY loxim_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct loxim_data *Q = (struct loxim_data *)P->opaque;
    xy.y = lp.phi - Q->phi1;
    if (fabs(xy.y) < LX_EPS)
        xy.x = lp.lam * Q->cosphi1;
    else {
        xy.x = M_FORTPI + 0.5 * lp.phi;
        if (fabs(xy.x) < LX_EPS || fabs(fabs(xy.x) - M_HALFPI) < LX_EPS)
            xy.x = 0.;
        else
            xy.x = lp.lam * xy.y / log(tan(xy.x) / Q->tanphi1);
    }
    return xy;
}
static PJ_LP loxim_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct loxim_data *Q = (struct loxim_data *)P->opaque;
    lp.phi = xy.y + Q->phi1;
    if (fabs(xy.y) < LX_EPS) {
        lp.lam = xy.x / Q->cosphi1;
    } else {
        lp.lam = M_FORTPI + 0.5 * lp.phi;
        if (fabs(lp.lam) < LX_EPS || fabs(fabs(lp.lam) - M_HALFPI) < LX_EPS)
            lp.lam = 0.;
        else
            lp.lam = xy.x * log(tan(lp.lam) / Q->tanphi1) / xy.y;
    }
    return lp;
}
PJ *pj_loxim_setup(PJ *P) {
    struct loxim_data *Q = (struct loxim_data *)calloc(1, sizeof(struct loxim_data));
    P->opaque = Q;
    Q->phi1 = pj_param(P->params, "rlat_1").f;
    Q->cosphi1 = cos(Q->phi1);
    if (Q->cosphi1 < LX_EPS) {
        proj_log_error(P, "Invalid value for lat_1: |lat_1| should be < 90\xc2\xb0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    Q->tanphi1 = tan(M_FORTPI + 0.5 * Q->phi1);
    P->inv = loxim_s_inverse;
    P->fwd = loxim_s_forward;
    P->es = 0.;
    return P;
}

/* ---------------- nell ---------------- */
#define NL_MAX_ITER 10
#define NL_LOOP_TOL 1e-7
static PJ_XY nell_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    double k, V;
    int i;
    (void)P;
    k = 2. * sin(lp.phi);
    V = lp.phi * lp.phi;
    lp.phi *= 1.00371 + V * (-0.0935382 + V * -0.011412);
    for (i = NL_MAX_ITER; i; --i) {
        lp.phi -= V = (lp.phi + sin(lp.phi) - k) / (1. + cos(lp.phi));
        if (fabs(V) < NL_LOOP_TOL) break;
    }
    xy.x = 0.5 * lp.lam * (1. + cos(lp.phi));
    xy.y = lp.phi;
    return xy;
}
static PJ_LP nell_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    (void)P;
    lp.lam = 2. * xy.x / (1. + cos(xy.y));
    lp.phi = aasin(0.5 * (xy.y + sin(xy.y)));
    return lp;
}
PJ *pj_nell_setup(PJ *P) { P->es = 0; P->inv = nell_s_inverse; P->fwd = nell_s_forward; return P; }

/* ---------------- nell_h ---------------- */
#define NH_NITER 9
#define NH_EPS 1e-7
static PJ_XY nell_h_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    (void)P;
    xy.x = 0.5 * lp.lam * (1. + cos(lp.phi));
    xy.y = 2.0 * (lp.phi - tan(0.5 * lp.phi));
    return xy;
}
static PJ_LP nell_h_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    double V, c, p;
    int i;
    (void)P;
    p = 0.5 * xy.y;
    for (i = NH_NITER; i; --i) {
        c = cos(0.5 * lp.phi);
        lp.phi -= V = (lp.phi - tan(lp.phi / 2) - p) / (1. - 0.5 / (c * c));
        if (fabs(V) < NH_EPS) break;
    }
    if (!i) {
        lp.phi = p < 0. ? -M_HALFPI : M_HALFPI;
        lp.lam = 2. * xy.x;
    } else
        lp.lam = 2. * xy.x / (1. + cos(lp.phi));
    return lp;
}
PJ *pj_nell_h_setup(PJ *P) { P->es = 0.; P->inv = nell_h_s_inverse; P->fwd = nell_h_s_forward; return P; }

/* ---------------- nicol ---------------- */
#define NC_EPS 1e-10
static PJ_XY nicol_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    (void)P;
    if (fabs(lp.lam) < NC_EPS) {
        xy.x = 0;
        xy.y = lp.phi;
    } else if (fabs(lp.phi) < NC_EPS) {
        xy.x = lp.lam;
        xy.y = 0.;
    } else if (fabs(fabs(lp.lam) - M_HALFPI) < NC_EPS) {
        xy.x = lp.lam * cos(lp.phi);
        xy.y = M_HALFPI * sin(lp.phi);
    } else if (fabs(fabs(lp.phi) - M_HALFPI) < NC_EPS) {
        xy.x = 0;
        xy.y = lp.phi;
    } else {
        double tb, c, d, m, n, r2, sp;
        tb = M_HALFPI / lp.lam - lp.lam / M_HALFPI;
        c = lp.phi / M_HALFPI;
        d = (1 - c * c) / ((sp = sin(lp.phi)) - c);
        r2 = tb / d;
        r2 *= r2;
        m = (tb * sp / d - 0.5 * tb) / (1. + r2);
        n = (sp / r2 + 0.5 * d) / (1. + 1. / r2);
        xy.x = cos(lp.phi);
        xy.x = sqrt(m * m + xy.x * xy.x / (1. + r2));
        xy.x = M_HALFPI * (m + (lp.lam < 0. ? -xy.x : xy.x));
        xy.y = sqrt(n * n - (sp * sp / r2 + d * sp - 1.) / (1. + 1. / r2));
        xy.y = M_HALFPI * (n + (lp.phi < 0. ? xy.y : -xy.y));
    }
    return xy;
}
PJ *pj_nicol_setup(PJ *P) { P->es = 0.; P->fwd = nicol_s_forward; P->inv = NULL; return P; }

/* ---------------- bacon / apian / ortel ---------------- */
struct bacon_data { int bacn, ortl; };
#define BC_HLFPI2 2.46740110027233965467
#define BC_EPS 1e-10
static PJ_XY bacon_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct bacon_data *Q = (struct bacon_data *)P->opaque;
    double ax, f;
    xy.y = Q->bacn ? M_HALFPI * sin(lp.phi) : lp.phi;
    if ((ax = fabs(lp.lam)) >= BC_EPS) {
        if (Q->ortl && ax >= M_HALFPI)
            xy.x = sqrt(BC_HLFPI2 - lp.phi * lp.phi + BC_EPS) + ax - M_HALFPI;
        else {
            f = 0.5 * (BC_HLFPI2 / ax + ax);
            xy.x = ax - f + sqrt(f * f - xy.y * xy.y);
        }
        if (lp.lam < 0.) xy.x = -xy.x;
    } else
        xy.x = 0.;
    return xy;
}
static PJ *bacon_common(PJ *P, int bacn, int ortl) {
    struct bacon_data *Q = (struct bacon_data *)calloc(1, sizeof(struct bacon_data));
    P->opaque = Q;
    Q->bacn = bacn;
    Q->ortl = ortl;
    P->es = 0.;
    P->fwd = bacon_s_forward;
    P->inv = NULL;
    return P;
}
PJ *pj_bacon_setup(PJ *P) { return bacon_common(P, 1, 0); }
PJ *pj_apian_setup(PJ *P) { return bacon_common(P, 0, 0); }
PJ *pj_ortel_setup(PJ *P) { return bacon_common(P, 0, 1); }

/* ---------------- august ---------------- */
#define AU_M 1.333333333333333
static PJ_XY august_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    double t, c1, c, x1, x, y1, y;
    (void)P;
    t = tan(.5 * lp.phi);
    c1 = sqrt(1. - t * t);
    c = 1. + c1 * cos(lp.lam *= .5);
    x1 = sin(lp.lam) * c1 / c;
    y1 = t / c;
    xy.x = AU_M * x1 * (3. + (x = x1 * x1) - 3. * (y = y1 * y1));
    xy.y = AU_M * y1 * (3. + 3. * x - y);
    return xy;
}
PJ *pj_august_setup(PJ *P) { P->inv = NULL; P->fwd = august_s_forward; P->es = 0.; return P; }

/* ---------------- larr ---------------- */
#define LR_SIXTH .16666666666666666
static PJ_XY larr_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    (void)P;
    xy.x = 0.5 * lp.lam * (1. + sqrt(cos(lp.phi)));
    xy.y = lp.phi / (cos(0.5 * lp.phi) * cos(LR_SIXTH * lp.lam));
    return xy;
}
PJ *pj_larr_setup(PJ *P) { P->es = 0; P->fwd = larr_s_forward; P->inv = NULL; return P; }

/* ---------------- lask ---------------- */
static PJ_XY lask_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    double l2, p2;
    (void)P;
    l2 = lp.lam * lp.lam;
    p2 = lp.phi * lp.phi;
    xy.x = lp.lam * (0.975534 + p2 * (-0.119161 + l2 * -0.0143059 + p2 * -0.0547009));
    xy.y = lp.phi * (1.00384 + l2 * (0.0802894 + p2 * -0.0285500 + l2 * 0.000199025) + p2 * (0.0998909 + p2 * -0.0491032));
    return xy;
}
PJ *pj_lask_setup(PJ *P) { P->fwd = lask_s_forward; P->inv = NULL; P->es = 0.; return P; }

/* ---------------- urm5 ---------------- */
struct urm5_data { double m, rmn, q3, n; };
static PJ_XY urm5_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct urm5_data *Q = (struct urm5_data *)P->opaque;
    double t;
    t = lp.phi = aasin(Q->n * sin(lp.phi));
    xy.x = Q->m * lp.lam * cos(lp.phi);
    t *= t;
    xy.y = lp.phi * (1. + t * Q->q3) * Q->rmn;
    return xy;
}
PJ *pj_urm5_setup(PJ *P) {
    double alpha, t;
    struct urm5_data *Q = (struct urm5_data *)calloc(1, sizeof(struct urm5_data));
    P->opaque = Q;
    if (pj_param(P->params, "tn").i) {
        Q->n = pj_param(P->params, "dn").f;
        if (Q->n <= 0. || Q->n > 1.) {
            proj_log_error(P, "Invalid value for n: it should be in ]0,1] range");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    } else {
        proj_log_error(P, "Missing parameter n.");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    Q->q3 = pj_param(P->params, "dq").f / 3.;
    alpha = pj_param(P->params, "ralpha").f;
    t = Q->n * sin(alpha);
    Q->m = cos(alpha) / sqrt(1. - t * t);
    Q->rmn = 1. / (Q->m * Q->n);
    P->es = 0.;
    P->inv = NULL;
    P->fwd = urm5_s_forward;
    return P;
}

/* ---------------- wink1 ---------------- */
struct wink1_data { double cosphi1; };
static PJ_XY wink1_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct wink1_data *Q = (struct wink1_data *)P->opaque;
    xy.x = .5 * lp.lam * (Q->cosphi1 + cos(lp.phi));
    xy.y = lp.phi;
    return xy;
}
static PJ_LP wink1_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct wink1_data *Q = (struct wink1_data *)P->opaque;
    lp.phi = xy.y;
    lp.lam = 2. * xy.x / (Q->cosphi1 + cos(lp.phi));
    return lp;
}
PJ *pj_wink1_setup(PJ *P) {
    struct wink1_data *Q = (struct wink1_data *)calloc(1, sizeof(struct wink1_data));
    P->opaque = Q;
    Q->cosphi1 = cos(pj_param(P->params, "rlat_ts").f);
    P->es = 0.;
    P->inv = wink1_s_inverse;
    P->fwd = wink1_s_forward;
    return P;
}

/* ---------------- wink2 ---------------- */
struct wink2_data { double cosphi1; };
#define WK2_MAX_ITER 10
#define WK2_LOOP_TOL 1e-7
static PJ_XY wink2_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct wink2_data *Q = (struct wink2_data *)P->opaque;
    double k, V;
    int i;
    xy.y = lp.phi * M_TWO_D_PI;
    k = M_PI * sin(lp.phi);
    lp.phi *= 1.8;
    for (i = WK2_MAX_ITER; i; --i) {
        lp.phi -= V = (lp.phi + sin(lp.phi) - k) / (1. + cos(lp.phi));
        if (fabs(V) < WK2_LOOP_TOL) break;
    }
    if (!i)
        lp.phi = (lp.phi < 0.) ? -M_HALFPI : M_HALFPI;
    else
        lp.phi *= 0.5;
    xy.x = 0.5 * lp.lam * (cos(lp.phi) + Q->cosphi1);
    xy.y = M_FORTPI * (sin(lp.phi) + xy.y);
    return xy;
}
static PJ_LP wink2_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct wink2_data *Q = (struct wink2_data *)P->opaque;
    double phi, theta, k, V, f, fder;
    int i, j;
    /* solve for phi: y = pi/4 (sin theta + 2 phi/pi), with theta from 2theta + sin 2theta = pi sin phi */
    phi = xy.y;
    for (j = 0; j < 100; ++j) {
        double t = phi, th;
        k = M_PI * sin(phi);
        t *= 1.8;
        for (i = WK2_MAX_ITER; i; --i) {
            t -= V = (t + sin(t) - k) / (1. + cos(t));
            if (fabs(V) < WK2_LOOP_TOL) break;
        }
        th = 0.5 * t;
        f = M_FORTPI * (sin(th) + phi * M_TWO_D_PI) - xy.y;
        /* derivative: d/dphi [pi/4 (sin th + 2 phi/pi)] = pi/4 (cos th dth/dphi) + 1/2, dth/dphi = pi cos phi /(2(1+cos 2th)) */
        fder = M_FORTPI * (cos(th) * M_PI * cos(phi) / (2. * (1. + cos(t)))) + 0.5;
        if (fder == 0) break;
        V = f / fder;
        phi -= V;
        if (fabs(V) < 1e-12) break;
    }
    lp.phi = phi;
    {
        double t = phi, th;
        k = M_PI * sin(phi);
        t *= 1.8;
        for (i = WK2_MAX_ITER; i; --i) {
            t -= V = (t + sin(t) - k) / (1. + cos(t));
            if (fabs(V) < WK2_LOOP_TOL) break;
        }
        th = 0.5 * t;
        theta = th;
    }
    lp.lam = 2. * xy.x / (cos(theta) + Q->cosphi1);
    return lp;
}
PJ *pj_wink2_setup(PJ *P) {
    struct wink2_data *Q = (struct wink2_data *)calloc(1, sizeof(struct wink2_data));
    P->opaque = Q;
    Q->cosphi1 = cos(pj_param(P->params, "rlat_1").f);
    P->es = 0.;
    P->inv = wink2_s_inverse;
    P->fwd = wink2_s_forward;
    return P;
}
