/* Miscellaneous spherical projections: aitoff/wintri, hammer, lagrng, airy, tpeqd, chamb, oea, vandg family, eqearth */
#include "proj.h"

enum Mode { N_POLE = 0, S_POLE = 1, EQUIT = 2, OBLIQ = 3 };

/* ---------------- aitoff / wintri ---------------- */
struct aitoff_data { double cosphi1; int mode; };
static PJ_XY aitoff_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct aitoff_data *Q = (struct aitoff_data *)P->opaque;
    double c, d;
    c = 0.5 * lp.lam;
    d = acos(cos(lp.phi) * cos(c));
    if (d != 0.0) {
        xy.x = 2. * d * cos(lp.phi) * sin(c) * (xy.y = 1. / sin(d));
        xy.y *= d * sin(lp.phi);
    } else
        xy.x = xy.y = 0.;
    if (Q->mode) {
        xy.x = (xy.x + lp.lam * Q->cosphi1) * 0.5;
        xy.y = (xy.y + lp.phi) * 0.5;
    }
    return xy;
}
static PJ_LP aitoff_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct aitoff_data *Q = (struct aitoff_data *)P->opaque;
    int iter, MAXITER = 10, MAXROUND = 20, round = 0;
    double EPSILON = 1e-12, D, C, f1, f2, f1p, f1l, f2p, f2l, dp, dl, sl, sp, cp, cl, x, y;
    if ((fabs(xy.x) < EPSILON) && (fabs(xy.y) < EPSILON)) {
        lp.phi = 0.;
        lp.lam = 0.;
        return lp;
    }
    lp.phi = xy.y;
    lp.lam = xy.x;
    do {
        iter = 0;
        do {
            sl = sin(lp.lam * 0.5);
            cl = cos(lp.lam * 0.5);
            sp = sin(lp.phi);
            cp = cos(lp.phi);
            D = cp * cl;
            C = 1. - D * D;
            D = acos(D) / pow(C, 1.5);
            f1 = 2. * D * C * cp * sl;
            f2 = D * C * sp;
            f1p = 2. * (sl * cl * sp * cp / C - D * sp * sl);
            f1l = cp * cp * sl * sl / C + D * cp * cl * sp * sp;
            f2p = sp * sp * cl / C + D * sl * sl * cp;
            f2l = 0.5 * (sp * cp * sl / C - D * sp * cp * cp * sl * cl);
            if (Q->mode) {
                f1 = 0.5 * (f1 + lp.lam * Q->cosphi1);
                f2 = 0.5 * (f2 + lp.phi);
                f1p *= 0.5;
                f1l = 0.5 * (f1l + Q->cosphi1);
                f2p = 0.5 * (f2p + 1.);
                f2l *= 0.5;
            }
            f1 -= xy.x;
            f2 -= xy.y;
            dl = (f2 * f1p - f1 * f2p) / (f1l * f2p - f2l * f1p);
            dp = (f1 - f1l * dl) / f1p;
            dp = fmod(dp, M_PI);
            dl = fmod(dl, M_PI);
            lp.phi -= dp;
            lp.lam -= dl;
        } while ((fabs(dp) > EPSILON || fabs(dl) > EPSILON) && (iter++ < MAXITER));
        if (lp.phi > M_PI_2) lp.phi -= 2. * (lp.phi - M_PI_2);
        if (lp.phi < -M_PI_2) lp.phi -= 2. * (lp.phi + M_PI_2);
        if ((fabs(fabs(lp.phi) - M_PI_2) < EPSILON) && (!Q->mode)) lp.lam = 0.;
        if ((D = acos(cos(lp.phi) * cos(C = 0.5 * lp.lam))) != 0.0) {
            x = 2. * D * cos(lp.phi) * sin(C) * (y = 1. / sin(D));
            y *= D * sin(lp.phi);
        } else
            x = y = 0.;
        if (Q->mode) {
            x = (x + lp.lam * Q->cosphi1) * 0.5;
            y = (y + lp.phi) * 0.5;
        }
    } while (((fabs(xy.x - x) > EPSILON) || (fabs(xy.y - y) > EPSILON)) && (round++ < MAXROUND));
    if (iter == MAXITER && round == MAXROUND) proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
    return lp;
}
static PJ *aitoff_setup(PJ *P) {
    P->inv = aitoff_s_inverse;
    P->fwd = aitoff_s_forward;
    P->es = 0.;
    return P;
}
PJ *pj_aitoff_setup(PJ *P) {
    struct aitoff_data *Q = (struct aitoff_data *)calloc(1, sizeof(struct aitoff_data));
    P->opaque = Q;
    Q->mode = 0;
    return aitoff_setup(P);
}
PJ *pj_wintri_setup(PJ *P) {
    struct aitoff_data *Q = (struct aitoff_data *)calloc(1, sizeof(struct aitoff_data));
    P->opaque = Q;
    Q->mode = 1;
    if (pj_param(P->params, "tlat_1").i) {
        if ((Q->cosphi1 = cos(pj_param(P->params, "rlat_1").f)) == 0.) {
            proj_log_error(P, "Invalid value for lat_1: |lat_1| should be < 90\xc2\xb0");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    } else
        Q->cosphi1 = 0.636619772367581343;
    return aitoff_setup(P);
}

/* ---------------- hammer ---------------- */
struct hammer_data { double w, m, rm; };
#define HM_EPS 1.0e-10
static PJ_XY hammer_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct hammer_data *Q = (struct hammer_data *)P->opaque;
    double cosphi, d;
    d = sqrt(2. / (1. + (cosphi = cos(lp.phi)) * cos(lp.lam *= Q->w)));
    xy.x = Q->m * d * cosphi * sin(lp.lam);
    xy.y = Q->rm * d * sin(lp.phi);
    return xy;
}
static PJ_LP hammer_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct hammer_data *Q = (struct hammer_data *)P->opaque;
    double z;
    z = sqrt(1. - 0.25 * Q->w * Q->w * xy.x * xy.x - 0.25 * xy.y * xy.y);
    if (fabs(2. * z * z - 1.) < HM_EPS) {
        lp.lam = HUGE_VAL;
        lp.phi = HUGE_VAL;
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
    } else {
        lp.lam = aatan2(Q->w * xy.x * z, 2. * z * z - 1) / Q->w;
        lp.phi = aasin(z * xy.y);
    }
    return lp;
}
PJ *pj_hammer_setup(PJ *P) {
    struct hammer_data *Q = (struct hammer_data *)calloc(1, sizeof(struct hammer_data));
    P->opaque = Q;
    if (pj_param(P->params, "tW").i) {
        if ((Q->w = fabs(pj_param(P->params, "dW").f)) <= 0.) {
            proj_log_error(P, "Invalid value for W: it should be > 0");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    } else
        Q->w = .5;
    if (pj_param(P->params, "tM").i) {
        if ((Q->m = fabs(pj_param(P->params, "dM").f)) <= 0.) {
            proj_log_error(P, "Invalid value for M: it should be > 0");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    } else
        Q->m = 1.;
    Q->rm = 1. / Q->m;
    Q->m /= Q->w;
    P->es = 0.;
    P->fwd = hammer_s_forward;
    P->inv = hammer_s_inverse;
    return P;
}

/* ---------------- lagrng ---------------- */
struct lagrng_data { double a1, hrw, rw; };
#define LG_TOL 1e-10
static PJ_XY lagrng_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct lagrng_data *Q = (struct lagrng_data *)P->opaque;
    double v, c;
    if (fabs(fabs(lp.phi) - M_HALFPI) < LG_TOL) {
        xy.x = 0;
        xy.y = lp.phi < 0 ? -2. : 2.;
    } else {
        lp.phi = sin(lp.phi);
        v = Q->a1 * pow((1. + lp.phi) / (1. - lp.phi), Q->hrw);
        if ((c = 0.5 * (v + 1. / v) + cos(lp.lam *= Q->rw)) < LG_TOL) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
        xy.x = 2. * sin(lp.lam) / c;
        xy.y = (v - 1. / v) / c;
    }
    return xy;
}
static PJ_LP lagrng_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct lagrng_data *Q = (struct lagrng_data *)P->opaque;
    double c, x2, y2p, y2m, v, t;
    if (fabs(fabs(xy.y) - 2.) < LG_TOL) {
        lp.lam = 0.0;
        lp.phi = xy.y < 0 ? -M_HALFPI : M_HALFPI;
        return lp;
    }
    x2 = xy.x * xy.x;
    y2p = 2. + xy.y;
    y2m = 2. - xy.y;
    c = (x2 + y2p * y2p) / (x2 + y2m * y2m);
    if (c <= 0) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    v = sqrt(c);
    lp.lam = atan2(xy.x, 1. - 0.25 * (x2 + xy.y * xy.y)) / Q->rw;
    t = pow(v / Q->a1, 1. / Q->hrw);
    lp.phi = aasin((t - 1.) / (t + 1.));
    return lp;
}
PJ *pj_lagrng_setup(PJ *P) {
    double phi1;
    struct lagrng_data *Q = (struct lagrng_data *)calloc(1, sizeof(struct lagrng_data));
    P->opaque = Q;
    Q->rw = pj_param(P->params, "dW").f;
    if (Q->rw == 0.0) Q->rw = 2.;
    if (Q->rw <= 0) {
        proj_log_error(P, "Invalid value for W: it should be > 0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    Q->rw = 1. / Q->rw;
    Q->hrw = 0.5 * Q->rw;
    phi1 = pj_param(P->params, "rlat_1").f;
    if (fabs(fabs(phi1 = sin(phi1)) - 1.) < LG_TOL) {
        proj_log_error(P, "Invalid value for lat_1: |lat_1| should be < 90\xc2\xb0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    Q->a1 = pow((1. - phi1) / (1. + phi1), Q->hrw);
    P->es = 0.;
    P->fwd = lagrng_s_forward;
    P->inv = lagrng_s_inverse;
    return P;
}

/* ---------------- airy ---------------- */
struct airy_data { double p_halfpi, sinph0, cosph0, Cb; enum Mode mode; int no_cut; };
#define AI_EPS 1.e-10
static PJ_XY airy_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct airy_data *Q = (struct airy_data *)P->opaque;
    double sinlam, coslam, cosphi, sinphi, t, s, Krho, cosz;
    sinlam = sin(lp.lam);
    coslam = cos(lp.lam);
    switch (Q->mode) {
    case EQUIT:
    case OBLIQ:
        sinphi = sin(lp.phi);
        cosphi = cos(lp.phi);
        cosz = cosphi * coslam;
        if (Q->mode == OBLIQ) cosz = Q->sinph0 * sinphi + Q->cosph0 * cosz;
        if (!Q->no_cut && cosz < -AI_EPS) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
        if (fabs(s = 1. - cosz) > AI_EPS) {
            t = 0.5 * (1. + cosz);
            if (t == 0) {
                proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
                return xy;
            }
            Krho = -log(t) / s - Q->Cb / t;
        } else
            Krho = 0.5 - Q->Cb;
        xy.x = Krho * cosphi * sinlam;
        if (Q->mode == OBLIQ)
            xy.y = Krho * (Q->cosph0 * sinphi - Q->sinph0 * cosphi * coslam);
        else
            xy.y = Krho * sinphi;
        break;
    case S_POLE:
    case N_POLE:
        lp.phi = fabs(Q->p_halfpi - lp.phi);
        if (!Q->no_cut && (lp.phi - AI_EPS) > M_HALFPI) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
        if ((lp.phi *= 0.5) > AI_EPS) {
            t = tan(lp.phi);
            Krho = -2. * (log(cos(lp.phi)) / t + t * Q->Cb);
            xy.x = Krho * sinlam;
            xy.y = Krho * coslam;
            if (Q->mode == N_POLE) xy.y = -xy.y;
        } else
            xy.x = xy.y = 0.;
    }
    return xy;
}
PJ *pj_airy_setup(PJ *P) {
    double beta;
    struct airy_data *Q = (struct airy_data *)calloc(1, sizeof(struct airy_data));
    P->opaque = Q;
    Q->no_cut = pj_param(P->params, "bno_cut").i;
    beta = 0.5 * (M_HALFPI - pj_param(P->params, "rlat_b").f);
    if (fabs(beta) < AI_EPS)
        Q->Cb = -0.5;
    else {
        Q->Cb = 1. / tan(beta);
        Q->Cb *= Q->Cb * log(cos(beta));
    }
    if (fabs(fabs(P->phi0) - M_HALFPI) < AI_EPS) {
        if (P->phi0 < 0.) {
            Q->p_halfpi = -M_HALFPI;
            Q->mode = S_POLE;
        } else {
            Q->p_halfpi = M_HALFPI;
            Q->mode = N_POLE;
        }
    } else {
        if (fabs(P->phi0) < AI_EPS)
            Q->mode = EQUIT;
        else {
            Q->mode = OBLIQ;
            Q->sinph0 = sin(P->phi0);
            Q->cosph0 = cos(P->phi0);
        }
    }
    P->fwd = airy_s_forward;
    P->inv = NULL;
    P->es = 0.;
    return P;
}

/* ---------------- tpeqd ---------------- */
struct tpeqd_data { double cp1, sp1, cp2, sp2, ccs, cs, sc, r2z0, z02, dlam2, hz0, thz0, rhshz0, ca, sa, lp, lamc; };
static PJ_XY tpeqd_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct tpeqd_data *Q = (struct tpeqd_data *)P->opaque;
    double t, z1, z2, dl1, dl2, sp, cp;
    sp = sin(lp.phi);
    cp = cos(lp.phi);
    z1 = aacos(Q->sp1 * sp + Q->cp1 * cp * cos(dl1 = lp.lam + Q->dlam2));
    z2 = aacos(Q->sp2 * sp + Q->cp2 * cp * cos(dl2 = lp.lam - Q->dlam2));
    z1 *= z1;
    z2 *= z2;
    xy.x = Q->r2z0 * (t = z1 - z2);
    t = Q->z02 - t;
    xy.y = Q->r2z0 * asqrt(4. * Q->z02 * z2 - t * t);
    if ((Q->ccs * sp - cp * (Q->cs * sin(dl1) - Q->sc * sin(dl2))) < 0.) xy.y = -xy.y;
    return xy;
}
static PJ_LP tpeqd_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct tpeqd_data *Q = (struct tpeqd_data *)P->opaque;
    double cz1, cz2, s, d, cp, sp;
    cz1 = cos(hypot(xy.y, xy.x + Q->hz0));
    cz2 = cos(hypot(xy.y, xy.x - Q->hz0));
    s = cz1 + cz2;
    d = cz1 - cz2;
    lp.lam = -atan2(d, (s * Q->thz0));
    lp.phi = aacos(hypot(Q->thz0 * s, d) * Q->rhshz0);
    if (xy.y < 0.) lp.phi = -lp.phi;
    sp = sin(lp.phi);
    cp = cos(lp.phi);
    lp.lam -= Q->lp;
    s = cos(lp.lam);
    lp.phi = aasin(Q->sa * sp + Q->ca * cp * s);
    lp.lam = atan2(cp * sin(lp.lam), Q->sa * cp * s - Q->ca * sp) + Q->lamc;
    return lp;
}
PJ *pj_tpeqd_setup(PJ *P) {
    double lam_1, lam_2, phi_1, phi_2, A12, pp;
    struct tpeqd_data *Q = (struct tpeqd_data *)calloc(1, sizeof(struct tpeqd_data));
    P->opaque = Q;
    lam_1 = pj_param(P->params, "rlon_1").f;
    phi_1 = pj_param(P->params, "rlat_1").f;
    lam_2 = pj_param(P->params, "rlon_2").f;
    phi_2 = pj_param(P->params, "rlat_2").f;
    if (phi_1 == phi_2 && lam_1 == lam_2) {
        proj_log_error(P, "Invalid value for lat_1/lon_1/lat_2/lon_2: the 2 points should be distinct.");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    P->lam0 = adjlon(0.5 * (lam_1 + lam_2));
    Q->dlam2 = adjlon(lam_2 - lam_1);
    Q->cp1 = cos(phi_1);
    Q->cp2 = cos(phi_2);
    Q->sp1 = sin(phi_1);
    Q->sp2 = sin(phi_2);
    Q->cs = Q->cp1 * Q->sp2;
    Q->sc = Q->sp1 * Q->cp2;
    Q->ccs = Q->cp1 * Q->cp2 * sin(Q->dlam2);
    Q->z02 = aacos(Q->sp1 * Q->sp2 + Q->cp1 * Q->cp2 * cos(Q->dlam2));
    if (Q->z02 == 0.0) {
        proj_log_error(P, "Invalid value for lat_1/lon_1/lat_2/lon_2: the 2 points should be distinct.");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    Q->hz0 = .5 * Q->z02;
    A12 = atan2(Q->cp2 * sin(Q->dlam2), Q->cp1 * Q->sp2 - Q->sp1 * Q->cp2 * cos(Q->dlam2));
    Q->ca = cos(pp = aasin(Q->cp1 * sin(A12)));
    Q->sa = sin(pp);
    Q->lp = adjlon(atan2(Q->cp1 * cos(A12), Q->sp1) - Q->hz0);
    Q->dlam2 *= .5;
    Q->lamc = M_HALFPI - atan2(sin(A12) * Q->sp1, cos(A12)) - Q->dlam2;
    Q->thz0 = tan(Q->hz0);
    Q->rhshz0 = .5 / sin(Q->hz0);
    Q->r2z0 = 0.5 / Q->z02;
    Q->z02 *= Q->z02;
    P->inv = tpeqd_s_inverse;
    P->fwd = tpeqd_s_forward;
    P->es = 0.;
    return P;
}

/* ---------------- chamb ---------------- */
typedef struct { double r, Az; } CH_VECT;
struct chamb_data {
    struct { double phi, lam, cosphi, sinphi; CH_VECT v; PJ_XY p; double Az; } c[3];
    PJ_XY p;
    double beta_0, beta_1, beta_2;
};
#define CH_THIRD 0.333333333333333333
#define CH_TOL 1e-9
static CH_VECT ch_vect(double dphi, double c1, double s1, double c2, double s2, double dlam) {
    CH_VECT v;
    double cdl, dp, dl;
    cdl = cos(dlam);
    if (fabs(dphi) > 1. || fabs(dlam) > 1.)
        v.r = aacos(s1 * s2 + c1 * c2 * cdl);
    else {
        dp = sin(.5 * dphi);
        dl = sin(.5 * dlam);
        v.r = 2. * aasin(sqrt(dp * dp + c1 * c2 * dl * dl));
    }
    if (fabs(v.r) > CH_TOL)
        v.Az = atan2(c2 * sin(dlam), c1 * s2 - s1 * c2 * cdl);
    else
        v.r = v.Az = 0.;
    return v;
}
static double ch_lc(double b, double c, double a) { return aacos(.5 * (b * b + c * c - a * a) / (b * c)); }
static PJ_XY chamb_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct chamb_data *Q = (struct chamb_data *)P->opaque;
    double sinphi, cosphi, a;
    CH_VECT v[3];
    int i, j;
    sinphi = sin(lp.phi);
    cosphi = cos(lp.phi);
    for (i = 0; i < 3; ++i) {
        v[i] = ch_vect(lp.phi - Q->c[i].phi, Q->c[i].cosphi, Q->c[i].sinphi, cosphi, sinphi, lp.lam - Q->c[i].lam);
        if (v[i].r == 0.0) break;
        v[i].Az = adjlon(v[i].Az - Q->c[i].v.Az);
    }
    if (i < 3)
        xy = Q->c[i].p;
    else {
        xy = Q->p;
        for (i = 0; i < 3; ++i) {
            j = i == 2 ? 0 : i + 1;
            a = ch_lc(Q->c[i].v.r, v[i].r, v[j].r);
            if (v[i].Az < 0.) a = -a;
            if (!i) {
                xy.x += v[i].r * cos(a);
                xy.y -= v[i].r * sin(a);
            } else if (i == 1) {
                a = Q->beta_1 - a;
                xy.x -= v[i].r * cos(a);
                xy.y -= v[i].r * sin(a);
            } else {
                a = Q->beta_2 - a;
                xy.x += v[i].r * cos(a);
                xy.y += v[i].r * sin(a);
            }
        }
        xy.x *= CH_THIRD;
        xy.y *= CH_THIRD;
    }
    return xy;
}
PJ *pj_chamb_setup(PJ *P) {
    int i, j;
    char line[10];
    struct chamb_data *Q = (struct chamb_data *)calloc(1, sizeof(struct chamb_data));
    P->opaque = Q;
    for (i = 0; i < 3; ++i) {
        (void)sprintf(line, "rlat_%d", i + 1);
        Q->c[i].phi = pj_param(P->params, line).f;
        (void)sprintf(line, "rlon_%d", i + 1);
        Q->c[i].lam = pj_param(P->params, line).f;
        Q->c[i].lam = adjlon(Q->c[i].lam - P->lam0);
        Q->c[i].cosphi = cos(Q->c[i].phi);
        Q->c[i].sinphi = sin(Q->c[i].phi);
    }
    for (i = 0; i < 3; ++i) {
        j = i == 2 ? 0 : i + 1;
        Q->c[i].v = ch_vect(Q->c[j].phi - Q->c[i].phi, Q->c[i].cosphi, Q->c[i].sinphi, Q->c[j].cosphi, Q->c[j].sinphi,
                            Q->c[j].lam - Q->c[i].lam);
        if (Q->c[i].v.r == 0.0) {
            proj_log_error(P, "Invalid value for control points: they should be distinct");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    }
    Q->beta_0 = ch_lc(Q->c[0].v.r, Q->c[2].v.r, Q->c[1].v.r);
    Q->beta_1 = ch_lc(Q->c[0].v.r, Q->c[1].v.r, Q->c[2].v.r);
    Q->beta_2 = M_PI - Q->beta_0;
    Q->p.y = 2. * (Q->c[0].p.y = Q->c[1].p.y = Q->c[2].v.r * sin(Q->beta_0));
    Q->c[2].p.y = 0.;
    Q->c[0].p.x = -(Q->c[1].p.x = .5 * Q->c[0].v.r);
    Q->p.x = Q->c[2].p.x = Q->c[0].p.x + Q->c[2].v.r * cos(Q->beta_0);
    P->es = 0.;
    P->fwd = chamb_s_forward;
    P->inv = NULL;
    return P;
}

/* ---------------- oea ---------------- */
struct oea_data { double theta, m, n, two_r_m, two_r_n, rm, rn, hm, hn, cp0, sp0; };
static PJ_XY oea_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct oea_data *Q = (struct oea_data *)P->opaque;
    double Az, M, N, cp, sp, cl, shz;
    cp = cos(lp.phi);
    sp = sin(lp.phi);
    cl = cos(lp.lam);
    Az = aatan2(cp * sin(lp.lam), Q->cp0 * sp - Q->sp0 * cp * cl) + Q->theta;
    shz = sin(0.5 * aacos(Q->sp0 * sp + Q->cp0 * cp * cl));
    M = aasin(shz * sin(Az));
    N = aasin(shz * cos(Az) * cos(M) / cos(M * Q->two_r_m));
    xy.y = Q->n * sin(N * Q->two_r_n);
    xy.x = Q->m * sin(M * Q->two_r_m) * cos(N) / cos(N * Q->two_r_n);
    return xy;
}
static PJ_LP oea_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct oea_data *Q = (struct oea_data *)P->opaque;
    double N, M, xp, yp, z, Az, cz, sz, cAz;
    N = Q->hn * aasin(xy.y * Q->rn);
    M = Q->hm * aasin(xy.x * Q->rm * cos(N * Q->two_r_n) / cos(N));
    xp = 2. * sin(M);
    yp = 2. * sin(N) * cos(M * Q->two_r_m) / cos(M);
    cAz = cos(Az = aatan2(xp, yp) - Q->theta);
    z = 2. * aasin(0.5 * hypot(xp, yp));
    sz = sin(z);
    cz = cos(z);
    lp.phi = aasin(Q->sp0 * cz + Q->cp0 * sz * cAz);
    lp.lam = aatan2(sz * sin(Az), Q->cp0 * cz - Q->sp0 * sz * cAz);
    return lp;
}
PJ *pj_oea_setup(PJ *P) {
    struct oea_data *Q = (struct oea_data *)calloc(1, sizeof(struct oea_data));
    P->opaque = Q;
    if (((Q->n = pj_param(P->params, "dn").f) <= 0.)) {
        proj_log_error(P, "Invalid value for n: it should be > 0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    if (((Q->m = pj_param(P->params, "dm").f) <= 0.)) {
        proj_log_error(P, "Invalid value for m: it should be > 0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    Q->theta = pj_param(P->params, "rtheta").f;
    Q->sp0 = sin(P->phi0);
    Q->cp0 = cos(P->phi0);
    Q->rn = 1. / Q->n;
    Q->rm = 1. / Q->m;
    Q->two_r_n = 2. * Q->rn;
    Q->two_r_m = 2. * Q->rm;
    Q->hm = 0.5 * Q->m;
    Q->hn = 0.5 * Q->n;
    P->fwd = oea_s_forward;
    P->inv = oea_s_inverse;
    P->es = 0.;
    return P;
}

/* ---------------- vandg ---------------- */
#define VG_TOL 1.e-10
#define VG_THIRD .33333333333333333333
#define VG_C2_27 .07407407407407407407
#define VG_PI4_3 4.18879020478639098458
#define VG_PISQ 9.86960440108935861869
#define VG_TPISQ 19.73920880217871723738
#define VG_HPISQ 4.93480220054467930934
static PJ_XY vandg_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    double al, al2, g, g2, p2;
    p2 = fabs(lp.phi / M_HALFPI);
    if ((p2 - VG_TOL) > 1.) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return xy;
    }
    if (p2 > 1.) p2 = 1.;
    if (fabs(lp.phi) <= VG_TOL) {
        xy.x = lp.lam;
        xy.y = 0.;
    } else if (fabs(lp.lam) <= VG_TOL || fabs(p2 - 1.) < VG_TOL) {
        xy.x = 0.;
        xy.y = M_PI * tan(.5 * asin(p2));
        if (lp.phi < 0.) xy.y = -xy.y;
    } else {
        al = .5 * fabs(M_PI / lp.lam - lp.lam / M_PI);
        al2 = al * al;
        g = sqrt(1. - p2 * p2);
        g = g / (p2 + g - 1.);
        g2 = g * g;
        p2 = g * (2. / p2 - 1.);
        p2 = p2 * p2;
        xy.x = g - p2;
        g = p2 + al2;
        xy.x = M_PI * (al * xy.x + sqrt(al2 * xy.x * xy.x - g * (g2 - p2))) / g;
        if (lp.lam < 0.) xy.x = -xy.x;
        xy.y = fabs(xy.x / M_PI);
        xy.y = 1. - xy.y * (xy.y + 2. * al);
        if (xy.y < -VG_TOL) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
        if (xy.y < 0.)
            xy.y = 0.;
        else
            xy.y = sqrt(xy.y) * (lp.phi < 0. ? -M_PI : M_PI);
    }
    return xy;
}
static PJ_LP vandg_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    double t, c0, c1, c2, c3, al, r2, r, m, d, ay, x2, y2, al_mul_m;
    x2 = xy.x * xy.x;
    if ((ay = fabs(xy.y)) < VG_TOL) {
        lp.phi = 0.;
        t = x2 * x2 + VG_TPISQ * (x2 + VG_HPISQ);
        lp.lam = fabs(xy.x) <= VG_TOL ? 0. : .5 * (x2 - VG_PISQ + sqrt(t)) / xy.x;
        return lp;
    }
    y2 = xy.y * xy.y;
    r = x2 + y2;
    r2 = r * r;
    c1 = -M_PI * ay * (r + VG_PISQ);
    c3 = r2 + M_TWOPI * (ay * r + M_PI * (y2 + M_PI * (ay + M_HALFPI)));
    c2 = c1 + VG_PISQ * (r - 3. * y2);
    c0 = M_PI * ay;
    c2 /= c3;
    al = c1 / c3 - VG_THIRD * c2 * c2;
    m = 2. * sqrt(-VG_THIRD * al);
    d = VG_C2_27 * c2 * c2 * c2 + (c0 * c0 - VG_THIRD * c2 * c1) / c3;
    al_mul_m = al * m;
    if (fabs(al_mul_m) < 1e-16) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    d = 3. * d / al_mul_m;
    t = fabs(d);
    if ((t - VG_TOL) <= 1.) {
        d = t > 1. ? (d > 0. ? 0. : M_PI) : acos(d);
        lp.phi = M_PI * (m * cos(d * VG_THIRD) - VG_THIRD * c2);
        if (xy.y < 0.) lp.phi = -lp.phi;
        t = r2 + VG_TPISQ * (x2 - y2 + VG_HPISQ);
        lp.lam = fabs(xy.x) <= VG_TOL ? 0. : .5 * (r - VG_PISQ + (t <= 0. ? 0. : sqrt(t))) / xy.x;
    } else {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    return lp;
}
PJ *pj_vandg_setup(PJ *P) { P->es = 0.; P->inv = vandg_s_inverse; P->fwd = vandg_s_forward; return P; }

/* ---------------- vandg2 / vandg3 ---------------- */
struct vandg2_data { int vdg3; };
#define V2_TOL 1e-10
#define V2_TWORPI 0.63661977236758134308
static PJ_XY vandg2_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct vandg2_data *Q = (struct vandg2_data *)P->opaque;
    double x1, at, bt, ct;
    bt = fabs(V2_TWORPI * lp.phi);
    if ((ct = 1. - bt * bt) < 0.)
        ct = 0.;
    else
        ct = sqrt(ct);
    if (fabs(lp.lam) < V2_TOL) {
        xy.x = 0.;
        xy.y = M_PI * (lp.phi < 0. ? -bt : bt) / (1. + ct);
    } else {
        at = 0.5 * fabs(M_PI / lp.lam - lp.lam / M_PI);
        if (Q->vdg3) {
            x1 = bt / (1. + ct);
            xy.x = M_PI * (sqrt(at * at + 1. - x1 * x1) - at);
            xy.y = M_PI * x1;
        } else {
            x1 = (ct * sqrt(1. + at * at) - at * ct * ct) / (1. + at * at * bt * bt);
            xy.x = M_PI * x1;
            xy.y = M_PI * sqrt(1. - x1 * (x1 + 2. * at) + V2_TOL);
        }
        if (lp.lam < 0.) xy.x = -xy.x;
        if (lp.phi < 0.) xy.y = -xy.y;
    }
    return xy;
}
static PJ *vandg2_common(PJ *P, int vdg3) {
    struct vandg2_data *Q = (struct vandg2_data *)calloc(1, sizeof(struct vandg2_data));
    P->opaque = Q;
    Q->vdg3 = vdg3;
    P->es = 0.;
    P->fwd = vandg2_s_forward;
    P->inv = NULL;
    return P;
}
PJ *pj_vandg2_setup(PJ *P) { return vandg2_common(P, 0); }
PJ *pj_vandg3_setup(PJ *P) { return vandg2_common(P, 1); }

/* ---------------- vandg4 ---------------- */
#define V4_TOL 1e-10
#define V4_TWORPI 0.63661977236758134308
static PJ_XY vandg4_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    double x1, t, bt, ct, ft, bt2, ct2, dt, dt2;
    (void)P;
    if (fabs(lp.phi) < V4_TOL) {
        xy.x = lp.lam;
        xy.y = 0.;
    } else if (fabs(lp.lam) < V4_TOL || fabs(fabs(lp.phi) - M_HALFPI) < V4_TOL) {
        xy.x = 0.;
        xy.y = lp.phi;
    } else {
        bt = fabs(V4_TWORPI * lp.phi);
        bt2 = bt * bt;
        ct = 0.5 * (bt * (8. - bt * (2. + bt2)) - 5.) / (bt2 * (bt - 1.));
        ct2 = ct * ct;
        dt = V4_TWORPI * lp.lam;
        dt = dt + 1. / dt;
        dt = sqrt(dt * dt - 4.);
        if ((fabs(lp.lam) - M_HALFPI) < 0.) dt = -dt;
        dt2 = dt * dt;
        x1 = bt + ct;
        x1 *= x1;
        t = bt + 3. * ct;
        ft = x1 * (bt2 + ct2 * dt2 - 1.) + (1. - bt2) * (bt2 * (t * t + 4. * ct2) + ct2 * (12. * bt * ct + 4. * ct2));
        x1 = (dt * (x1 + ct2 - 1.) + 2. * sqrt(ft)) / (4. * x1 + dt2);
        xy.x = M_HALFPI * x1;
        xy.y = M_HALFPI * sqrt(1. + dt * fabs(x1) - x1 * x1);
        if (lp.lam < 0.) xy.x = -xy.x;
        if (lp.phi < 0.) xy.y = -xy.y;
    }
    return xy;
}
PJ *pj_vandg4_setup(PJ *P) { P->es = 0.; P->fwd = vandg4_s_forward; P->inv = NULL; return P; }

/* ---------------- eqearth ---------------- */
struct eqearth_data { double qp, rqda; double *apa; };
#define EE_A1 1.340264
#define EE_A2 -0.081106
#define EE_A3 0.000893
#define EE_A4 0.003796
#define EE_M (sqrt(3.0) / 2.0)
#define EE_MAX_Y 1.3173627591574
#define EE_EPS 1e-11
#define EE_NITER 12
static void eqearth_destructor(PJ *P, int e) {
    if (P && P->opaque) { struct eqearth_data *Q = (struct eqearth_data *)P->opaque; if (Q->apa) free(Q->apa); }
    pj_default_destructor(P, e);
}
static PJ_XY eqearth_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct eqearth_data *Q = (struct eqearth_data *)P->opaque;
    double sbeta, psi, psi2, psi6;
    sbeta = sin(lp.phi);
    if (P->es != 0.0) {
        sbeta = pj_qsfn(sbeta, P->e, 1.0 - P->es) / Q->qp;
        if (fabs(sbeta) > 1) {
            if (fabs(sbeta) > 1 + 1e-10) {
                proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
                return xy;
            }
            sbeta = sbeta > 0 ? 1.0 : -1.0;
        }
    }
    psi = asin(EE_M * sbeta);
    psi2 = psi * psi;
    psi6 = psi2 * psi2 * psi2;
    xy.x = lp.lam * cos(psi) / (EE_M * (EE_A1 + 3 * EE_A2 * psi2 + psi6 * (7 * EE_A3 + 9 * EE_A4 * psi2)));
    xy.y = psi * (EE_A1 + EE_A2 * psi2 + psi6 * (EE_A3 + EE_A4 * psi2));
    xy.x *= Q->rqda;
    xy.y *= Q->rqda;
    return xy;
}
static PJ_LP eqearth_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct eqearth_data *Q = (struct eqearth_data *)P->opaque;
    double yc, tol, y2, y6, f, fder;
    int i;
    xy.x /= Q->rqda;
    xy.y /= Q->rqda;
    yc = xy.y;
    if (yc > EE_MAX_Y) yc = EE_MAX_Y;
    else if (yc < -EE_MAX_Y) yc = -EE_MAX_Y;
    for (i = EE_NITER; i; --i) {
        y2 = yc * yc;
        y6 = y2 * y2 * y2;
        f = yc * (EE_A1 + EE_A2 * y2 + y6 * (EE_A3 + EE_A4 * y2)) - xy.y;
        fder = EE_A1 + 3 * EE_A2 * y2 + y6 * (7 * EE_A3 + 9 * EE_A4 * y2);
        tol = f / fder;
        yc -= tol;
        if (fabs(tol) < EE_EPS) break;
    }
    if (i == 0) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    y2 = yc * yc;
    y6 = y2 * y2 * y2;
    lp.lam = EE_M * xy.x * (EE_A1 + 3 * EE_A2 * y2 + y6 * (7 * EE_A3 + 9 * EE_A4 * y2)) / cos(yc);
    lp.phi = asin(sin(yc) / EE_M);
    if (P->es != 0.0) lp.phi = pj_authlat(lp.phi, Q->apa);
    return lp;
}
PJ *pj_eqearth_setup(PJ *P) {
    struct eqearth_data *Q = (struct eqearth_data *)calloc(1, sizeof(struct eqearth_data));
    P->opaque = Q;
    P->destructor = eqearth_destructor;
    P->fwd = eqearth_e_forward;
    P->inv = eqearth_e_inverse;
    Q->rqda = 1.0;
    if (P->es != 0.0) {
        Q->apa = pj_authset(P->es);
        if (!Q->apa) return pj_default_destructor(P, PROJ_ERR_OTHER);
        Q->qp = pj_qsfn(1.0, P->e, P->one_es);
        Q->rqda = sqrt(0.5 * Q->qp);
    }
    return P;
}
