/* ---------------- oea ---------------- */
struct oea_data { double theta, m, n, two_r_m, two_r_n, rm, rn, hm, hn, cp0, sp0; };
static PJ_XY oea_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct oea_data *Q = (struct oea_data *)P->opaque;
    double Az, M, N, cp, sp, cl, shz;
    cp = cos(lp.phi);
    sp = sin(lp.phi);
    cl = cos(lp.lam);
    Az = aatan2(cp * sin(lp.lam), Q->cp0 * sp - Q->sp0 * cp * cl) + Q->theta;
    shz = sin(0.5 * aacos(Q->sp0 * sp + Q->cp0 * cp * cl));
    M = aasin(shz * sin(Az));
    N = aasin(shz * cos(Az) * cos(M) / cos(M * Q->two_r_m));
    xy.y = Q->n * sin(N * Q->two_r_n);
    xy.x = Q->m * sin(M * Q->two_r_m) * cos(N) / cos(N * Q->two_r_n);
    return xy;
}
static PJ_LP oea_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct oea_data *Q = (struct oea_data *)P->opaque;
    double N, M, xp, yp, z, Az, cz, sz, cAz;
    N = Q->hn * aasin(xy.y * Q->rn);
    M = Q->hm * aasin(xy.x * Q->rm * cos(N * Q->two_r_n) / cos(N));
    xp = 2. * sin(M);
    yp = 2. * sin(N) * cos(M * Q->two_r_m) / cos(M);
    cAz = cos(Az = aatan2(xp, yp) - Q->theta);
    z = 2. * aasin(0.5 * hypot(xp, yp));
    sz = sin(z);
    cz = cos(z);
    lp.phi = aasin(Q->sp0 * cz + Q->cp0 * sz * cAz);
    lp.lam = aatan2(sz * sin(Az), Q->cp0 * cz - Q->sp0 * sz * cAz);
    return lp;
}
PJ *pj_oea_setup(PJ *P) {
    struct oea_data *Q = (struct oea_data *)calloc(1, sizeof(struct oea_data));
    P->opaque = Q;
    if (((Q->n = pj_param(P->params, "dn").f) <= 0.)) {
        proj_log_error(P, "Invalid value for n: it should be > 0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    if (((Q->m = pj_param(P->params, "dm").f) <= 0.)) {
        proj_log_error(P, "Invalid value for m: it should be > 0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    Q->theta = pj_param(P->params, "rtheta").f;
    Q->sp0 = sin(P->phi0);
    Q->cp0 = cos(P->phi0);
    Q->rn = 1. / Q->n;
    Q->rm = 1. / Q->m;
    Q->two_r_n = 2. * Q->rn;
    Q->two_r_m = 2. * Q->rm;
    Q->hm = 0.5 * Q->m;
    Q->hn = 0.5 * Q->n;
    P->fwd = oea_s_forward;
    P->inv = oea_s_inverse;
    P->es = 0.;
    return P;
}

/* ---------------- vandg ---------------- */
#define VG_TOL 1.e-10
#define VG_THIRD .33333333333333333333
#define VG_C2_27 .07407407407407407407
#define VG_PI4_3 4.18879020478639098458
#define VG_PISQ 9.86960440108935861869
#define VG_TPISQ 19.73920880217871723738
#define VG_HPISQ 4.93480220054467930934
static PJ_XY vandg_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    double al, al2, g, g2, p2;
    p2 = fabs(lp.phi / M_HALFPI);
    if ((p2 - VG_TOL) > 1.) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return xy;
    }
    if (p2 > 1.) p2 = 1.;
    if (fabs(lp.phi) <= VG_TOL) {
        xy.x = lp.lam;
        xy.y = 0.;
    } else if (fabs(lp.lam) <= VG_TOL || fabs(p2 - 1.) < VG_TOL) {
        xy.x = 0.;
        xy.y = M_PI * tan(.5 * asin(p2));
        if (lp.phi < 0.) xy.y = -xy.y;
    } else {
        al = .5 * fabs(M_PI / lp.lam - lp.lam / M_PI);
        al2 = al * al;
        g = sqrt(1. - p2 * p2);
        g = g / (p2 + g - 1.);
        g2 = g * g;
        p2 = g * (2. / p2 - 1.);
        p2 = p2 * p2;
        xy.x = g - p2;
        g = p2 + al2;
        xy.x = M_PI * (al * xy.x + sqrt(al2 * xy.x * xy.x - g * (g2 - p2))) / g;
        if (lp.lam < 0.) xy.x = -xy.x;
        xy.y = fabs(xy.x / M_PI);
        xy.y = 1. - xy.y * (xy.y + 2. * al);
        if (xy.y < -VG_TOL) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
        if (xy.y < 0.)
            xy.y = 0.;
        else
            xy.y = sqrt(xy.y) * (lp.phi < 0. ? -M_PI : M_PI);
    }
    return xy;
}
static PJ_LP vandg_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    double t, c0, c1, c2, c3, al, r2, r, m, d, ay, x2, y2, al_mul_m;
    x2 = xy.x * xy.x;
    if ((ay = fabs(xy.y)) < VG_TOL) {
        lp.phi = 0.;
        t = x2 * x2 + VG_TPISQ * (x2 + VG_HPISQ);
        lp.lam = fabs(xy.x) <= VG_TOL ? 0. : .5 * (x2 - VG_PISQ + sqrt(t)) / xy.x;
        return lp;
    }
    y2 = xy.y * xy.y;
    r = x2 + y2;
    r2 = r * r;
    c1 = -M_PI * ay * (r + VG_PISQ);
    c3 = r2 + M_TWOPI * (ay * r + M_PI * (y2 + M_PI * (ay + M_HALFPI)));
    c2 = c1 + VG_PISQ * (r - 3. * y2);
    c0 = M_PI * ay;
    c2 /= c3;
    al = c1 / c3 - VG_THIRD * c2 * c2;
    m = 2. * sqrt(-VG_THIRD * al);
    d = VG_C2_27 * c2 * c2 * c2 + (c0 * c0 - VG_THIRD * c2 * c1) / c3;
    al_mul_m = al * m;
    if (fabs(al_mul_m) < 1e-16) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    d = 3. * d / al_mul_m;
    t = fabs(d);
    if ((t - VG_TOL) <= 1.) {
        d = t > 1. ? (d > 0. ? 0. : M_PI) : acos(d);
        lp.phi = M_PI * (m * cos(d * VG_THIRD) - VG_THIRD * c2);
        if (xy.y < 0.) lp.phi = -lp.phi;
        t = r2 + VG_TPISQ * (x2 - y2 + VG_HPISQ);
        lp.lam = fabs(xy.x) <= VG_TOL ? 0. : .5 * (r - VG_PISQ + (t <= 0. ? 0. : sqrt(t))) / xy.x;
    } else {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    return lp;
}
PJ *pj_vandg_setup(PJ *P) { P->es = 0.; P->inv = vandg_s_inverse; P->fwd = vandg_s_forward; return P; }

/* ---------------- vandg2 / vandg3 ---------------- */
struct vandg2_data { int vdg3; };
#define V2_TOL 1e-10
#define V2_TWORPI 0.63661977236758134308
static PJ_XY vandg2_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct vandg2_data *Q = (struct vandg2_data *)P->opaque;
    double x1, at, bt, ct;
    bt = fabs(V2_TWORPI * lp.phi);
    if ((ct = 1. - bt * bt) < 0.)
        ct = 0.;
    else
        ct = sqrt(ct);
    if (fabs(lp.lam) < V2_TOL) {
        xy.x = 0.;
        xy.y = M_PI * (lp.phi < 0. ? -bt : bt) / (1. + ct);
    } else {
        at = 0.5 * fabs(M_PI / lp.lam - lp.lam / M_PI);
        if (Q->vdg3) {
            x1 = bt / (1. + ct);
            xy.x = M_PI * (sqrt(at * at + 1. - x1 * x1) - at);
            xy.y = M_PI * x1;
        } else {
            x1 = (ct * sqrt(1. + at * at) - at * ct * ct) / (1. + at * at * bt * bt);
            xy.x = M_PI * x1;
            xy.y = M_PI * sqrt(1. - x1 * (x1 + 2. * at) + V2_TOL);
        }
        if (lp.lam < 0.) xy.x = -xy.x;
        if (lp.phi < 0.) xy.y = -xy.y;
    }
    return xy;
}
static PJ *vandg2_common(PJ *P, int vdg3) {
    struct vandg2_data *Q = (struct vandg2_data *)calloc(1, sizeof(struct vandg2_data));
    P->opaque = Q;
    Q->vdg3 = vdg3;
    P->es = 0.;
    P->fwd = vandg2_s_forward;
    P->inv = NULL;
    return P;
}
PJ *pj_vandg2_setup(PJ *P) { return vandg2_common(P, 0); }
PJ *pj_vandg3_setup(PJ *P) { return vandg2_common(P, 1); }

/* ---------------- vandg4 ---------------- */
#define V4_TOL 1e-10
#define V4_TWORPI 0.63661977236758134308
static PJ_XY vandg4_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    double x1, t, bt, ct, ft, bt2, ct2, dt, dt2;
    (void)P;
    if (fabs(lp.phi) < V4_TOL) {
        xy.x = lp.lam;
        xy.y = 0.;
    } else if (fabs(lp.lam) < V4_TOL || fabs(fabs(lp.phi) - M_HALFPI) < V4_TOL) {
        xy.x = 0.;
        xy.y = lp.phi;
    } else {
        bt = fabs(V4_TWORPI * lp.phi);
        bt2 = bt * bt;
        ct = 0.5 * (bt * (8. - bt * (2. + bt2)) - 5.) / (bt2 * (bt - 1.));
        ct2 = ct * ct;
        dt = V4_TWORPI * lp.lam;
        dt = dt + 1. / dt;
        dt = sqrt(dt * dt - 4.);
        if ((fabs(lp.lam) - M_HALFPI) < 0.) dt = -dt;
        dt2 = dt * dt;
        x1 = bt + ct;
        x1 *= x1;
        t = bt + 3. * ct;
        ft = x1 * (bt2 + ct2 * dt2 - 1.) + (1. - bt2) * (bt2 * (t * t + 4. * ct2) + ct2 * (12. * bt * ct + 4. * ct2));
        x1 = (dt * (x1 + ct2 - 1.) + 2. * sqrt(ft)) / (4. * x1 + dt2);
        xy.x = M_HALFPI * x1;
        xy.y = M_HALFPI * sqrt(1. + dt * fabs(x1) - x1 * x1);
        if (lp.lam < 0.) xy.x = -xy.x;
        if (lp.phi < 0.) xy.y = -xy.y;
    }
    return xy;
}
PJ *pj_vandg4_setup(PJ *P) { P->es = 0.; P->fwd = vandg4_s_forward; P->inv = NULL; return P; }

/* ---------------- eqearth ---------------- */
struct eqearth_data { double qp, rqda; double *apa; };
#define EE_A1 1.340264
#define EE_A2 -0.081106
#define EE_A3 0.000893
#define EE_A4 0.003796
#define EE_M (sqrt(3.0) / 2.0)
#define EE_MAX_Y 1.3173627591574
#define EE_EPS 1e-11
#define EE_NITER 12
static void eqearth_destructor(PJ *P, int e) {
    if (P && P->opaque) { struct eqearth_data *Q = (struct eqearth_data *)P->opaque; if (Q->apa) free(Q->apa); }
    pj_default_destructor(P, e);
}
static PJ_XY eqearth_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct eqearth_data *Q = (struct eqearth_data *)P->opaque;
    double sbeta, psi, psi2, psi6;
    sbeta = sin(lp.phi);
    if (P->es != 0.0) {
        sbeta = pj_qsfn(sbeta, P->e, 1.0 - P->es) / Q->qp;
        if (fabs(sbeta) > 1) {
            if (fabs(sbeta) > 1 + 1e-10) {
                proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
                return xy;
            }
            sbeta = sbeta > 0 ? 1.0 : -1.0;
        }
    }
    psi = asin(EE_M * sbeta);
    psi2 = psi * psi;
    psi6 = psi2 * psi2 * psi2;
    xy.x = lp.lam * cos(psi) / (EE_M * (EE_A1 + 3 * EE_A2 * psi2 + psi6 * (7 * EE_A3 + 9 * EE_A4 * psi2)));
    xy.y = psi * (EE_A1 + EE_A2 * psi2 + psi6 * (EE_A3 + EE_A4 * psi2));
    xy.x *= Q->rqda;
    xy.y *= Q->rqda;
    return xy;
}
static PJ_LP eqearth_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct eqearth_data *Q = (struct eqearth_data *)P->opaque;
    double yc, tol, y2, y6, f, fder;
    int i;
    xy.x /= Q->rqda;
    xy.y /= Q->rqda;
    yc = xy.y;
    if (yc > EE_MAX_Y) yc = EE_MAX_Y;
    else if (yc < -EE_MAX_Y) yc = -EE_MAX_Y;
    for (i = EE_NITER; i; --i) {
        y2 = yc * yc;
        y6 = y2 * y2 * y2;
        f = yc * (EE_A1 + EE_A2 * y2 + y6 * (EE_A3 + EE_A4 * y2)) - xy.y;
        fder = EE_A1 + 3 * EE_A2 * y2 + y6 * (7 * EE_A3 + 9 * EE_A4 * y2);
        tol = f / fder;
        yc -= tol;
        if (fabs(tol) < EE_EPS) break;
    }
    if (i == 0) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    y2 = yc * yc;
    y6 = y2 * y2 * y2;
    lp.lam = EE_M * xy.x * (EE_A1 + 3 * EE_A2 * y2 + y6 * (7 * EE_A3 + 9 * EE_A4 * y2)) / cos(yc);
    lp.phi = asin(sin(yc) / EE_M);
    if (P->es != 0.0) lp.phi = pj_authlat(lp.phi, Q->apa);
    return lp;
}
PJ *pj_eqearth_setup(PJ *P) {
    struct eqearth_data *Q = (struct eqearth_data *)calloc(1, sizeof(struct eqearth_data));
    P->opaque = Q;
    P->destructor = eqearth_destructor;
    P->fwd = eqearth_e_forward;
    P->inv = eqearth_e_inverse;
    Q->rqda = 1.0;
    if (P->es != 0.0) {
        Q->apa = pj_authset(P->es);
        if (!Q->apa) return pj_default_destructor(P, PROJ_ERR_OTHER);
        Q->qp = pj_qsfn(1.0, P->e, P->one_es);
        Q->rqda = sqrt(0.5 * Q->qp);
    }
    return P;
}
