            t = lp; t.phi += h; fa = aitoff_s_forward(t, P);
            t = lp; t.lam += h; fb = aitoff_s_forward(t, P);
            f1p = (fa.x - f0.x) / h; f2p = (fa.y - f0.y) / h;
            f1l = (fb.x - f0.x) / h; f2l = (fb.y - f0.y) / h;
            f1 = f0.x - xy.x;
            f2 = f0.y - xy.y;
            det = f1p * f2l - f1l * f2p;
            if (det == 0) break;
            dp = (f1 * f2l - f2 * f1l) / det;
            dl = (f1p * f2 - f2p * f1) / det;
            dp = fmod(dp, M_PI);
            dl = fmod(dl, M_PI);
            lp.phi -= dp;
            lp.lam -= dl;
        } while ((fabs(dp) > EPSILON || fabs(dl) > EPSILON) && (iter++ < MAXITER));
        if (lp.phi > M_PI_2) lp.phi -= 2. * (lp.phi - M_PI_2);
        if (lp.phi < -M_PI_2) lp.phi -= 2. * (lp.phi + M_PI_2);
        {
            struct aitoff_data *Q = (struct aitoff_data *)P->opaque;
            if ((fabs(fabs(lp.phi) - M_PI_2) < EPSILON) && (!Q->mode)) lp.lam = 0.;
        }
