            PJ_XY f0 = aitoff_s_forward(lp, P);
            x = f0.x;
            y = f0.y;
        }
    } while (((fabs(xy.x - x) > EPSILON) || (fabs(xy.y - y) > EPSILON)) && (round++ < MAXROUND));
    if (iter == MAXITER && round == MAXROUND) proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
    return lp;
}
