        no_off = pj_param(P->params, "tno_off").i || pj_param(P->params, "tno_uoff").i;
        if (no_off) {
            pj_param(P->params, "sno_uoff");
            pj_param(P->params, "sno_off");
        }
    } else {
        lam1 = pj_param(P->params, "rlon_1").f;
        phi1 = pj_param(P->params, "rlat_1").f;
        lam2 = pj_param(P->params, "rlon_2").f;
        phi2 = pj_param(P->params, "rlat_2").f;
        if (fabs(phi1 - phi2) <= OM_TOL) {
            proj_log_error(P, "Invalid value for lat_1/lat_2: lat_1 should be different from lat_2");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
