    Q->v_pole_s = Q->ArB * log(tan(M_FORTPI + F));
    P->inv = omerc_e_inverse;
    P->fwd = omerc_e_forward;
    return P;
}

/* ---------------- ocea ---------------- */
struct ocea_data { double rok, rtk, sinphi, cosphi, singam, cosgam; };
static PJ_XY ocea_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct ocea_data *Q = (struct ocea_data *)P->opaque;
    double t;
    xy.y = sin(lp.phi);
    t = cos(lp.phi);
    xy.x = atan((tan(lp.phi) * Q->cosphi + Q->sinphi * sin(lp.lam)) / cos(lp.lam));
    if (cos(lp.lam) < 0.) xy.x += M_PI;
    xy.x *= Q->rtk;
    xy.y = Q->rok * (Q->sinphi * xy.y - Q->cosphi * t * sin(lp.lam));
    return xy;
}
static PJ_LP ocea_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct ocea_data *Q = (struct ocea_data *)P->opaque;
    double t, s;
    xy.y /= Q->rok;
    xy.x /= Q->rtk;
    t = sqrt(1. - xy.y * xy.y);
    s = sin(xy.x);
    lp.phi = asin(xy.y * Q->sinphi + t * Q->cosphi * s);
    lp.lam = atan2(t * Q->sinphi * s - xy.y * Q->cosphi, t * cos(xy.x));
    return lp;
}
PJ *pj_ocea_setup(PJ *P) {
    double phi_1, phi_2, lam_1, lam_2, lonz, alpha;
    struct ocea_data *Q = (struct ocea_data *)calloc(1, sizeof(struct ocea_data));
    P->opaque = Q;
    Q->rok = 1. / P->k0;
    Q->rtk = P->k0;
    if (pj_param(P->params, "talpha").i) {
        alpha = M_PI + pj_param(P->params, "ralpha").f;
        lonz = pj_param(P->params, "rlonc").f;
        Q->singam = atan(-cos(alpha) / (-sin(P->phi0) * sin(alpha))) + lonz;
        Q->sinphi = asin(cos(P->phi0) * sin(alpha));
