/* ---------------- labrd ---------------- */
struct labrd_data { double Az, kRg, p0s, A, C, Ca, Cb, Cc, Cd; };
#define LB_EPS 1.e-10
static PJ_XY labrd_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct labrd_data *Q = (struct labrd_data *)P->opaque;
