PJ *pj_labrd_setup(PJ *P) {
    double sinp, t, cosp2;
    struct labrd_data *Q = (struct labrd_data *)calloc(1, sizeof(struct labrd_data));
    P->opaque = Q;
    if (P->phi0 == 0.) {
        proj_log_error(P, "Invalid value for lat_0: lat_0 should be different from 0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    Q->Az = pj_param(P->params, "razi").f;
    sinp = sin(P->phi0);
    t = 1. - P->es * sinp * sinp;
    Q->kRg = P->k0 * sqrt(P->one_es) / t;
    cosp2 = cos(P->phi0);
    cosp2 *= cosp2;
    Q->A = sqrt(1. + P->es * cosp2 * cosp2 / P->one_es);
    Q->p0s = asin(sinp / Q->A);
    t = tan(M_FORTPI + .5 * Q->p0s);
    Q->C = log(t) - Q->A * (log(tan(M_FORTPI + .5 * P->phi0)) - .5 * P->e * log((1. + P->e * sinp) / (1. - P->e * sinp)));
