/* ---------------- nzmg ---------------- */
#define NZ_EPSLN 1e-10
#define NZ_SEC5_TO_RAD 0.4848136811095359935899141023
#define NZ_RAD_TO_SEC5 2.062648062470963551564733573
static const COMPLEX nz_bf[] = {{.7557853228, 0.0}, {.249204646, .003371507}, {-.001541739, .041058560},
                                {-.10162907, .01727609}, {-.26623489, -.36249218}, {-.6870983, -1.1651967}};
static const double nz_tphi[] = {1.5627014243, .5185406398, -.03333098, -.1052906, -.0368594, .007317, .01220, .00394, -.0013};
static const double nz_tpsi[] = {.6399175073, -.1358797613, .063294409, -.02526853, .0117879, -.0055161, .0026906, -.001333, .00067, -.00034};
#define NZ_Nbf 5
#define NZ_Ntpsi 9
#define NZ_Ntphi 8
static PJ_XY nzmg_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    COMPLEX p;
    const double *C;
    int i;
    lp.phi = (lp.phi - P->phi0) * NZ_RAD_TO_SEC5;
    for (p.r = *(C = nz_tpsi + (i = NZ_Ntpsi)); i; --i) p.r = *--C + lp.phi * p.r;
    p.r *= lp.phi;
    p.i = lp.lam;
    p = pj_zpoly1(p, nz_bf, NZ_Nbf);
    xy.x = p.i;
    xy.y = p.r;
    return xy;
}
static PJ_LP nzmg_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    int nn, i;
    COMPLEX p, f, fp, dp;
    double den;
    const double *C;
    p.r = xy.y;
    p.i = xy.x;
    for (nn = 20; nn; --nn) {
        f = pj_zpolyd1(p, nz_bf, NZ_Nbf, &fp);
        f.r -= xy.y;
        f.i -= xy.x;
        den = fp.r * fp.r + fp.i * fp.i;
        p.r += dp.r = -(f.r * fp.r + f.i * fp.i) / den;
        p.i += dp.i = -(f.i * fp.r - f.r * fp.i) / den;
        if ((fabs(dp.r) + fabs(dp.i)) <= NZ_EPSLN) break;
    }
    if (nn) {
        lp.lam = p.i;
