cat > /workspace/src/pj_omerc.c <<'EOF'
/* Oblique Mercator, oblique cylindrical equal area, Laborde, NZMG */
#include "proj.h"

/* ---------------- omerc ---------------- */
struct omerc_data { double A, B, E, AB, ArB, BrA, rB, singam, cosgam, sinrot, cosrot, v_pole_n, v_pole_s, u_0; int no_rot; };
#define OM_TOL 1.e-7
#define OM_EPS 1.e-10
static PJ_XY omerc_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct omerc_data *Q = (struct omerc_data *)P->opaque;
    double S, T, U, V, W, temp, u, v;
    if (fabs(fabs(lp.phi) - M_HALFPI) > OM_EPS) {
        W = Q->E / pow(pj_tsfn(lp.phi, sin(lp.phi), P->e), Q->B);
        temp = 1. / W;
        S = .5 * (W - temp);
        T = .5 * (W + temp);
        V = sin(Q->B * lp.lam);
        U = (S * Q->singam - V * Q->cosgam) / T;
        if (fabs(fabs(U) - 1.0) < OM_EPS) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return xy;
        }
        v = 0.5 * Q->ArB * log((1. - U) / (1. + U));
        temp = cos(Q->B * lp.lam);
        if (fabs(temp) < OM_TOL) {
            u = Q->A * lp.lam;
        } else {
            u = Q->ArB * atan2((S * Q->cosgam + V * Q->singam), temp);
        }
    } else {
        v = lp.phi > 0 ? Q->v_pole_n : Q->v_pole_s;
        u = Q->ArB * lp.phi;
    }
    if (Q->no_rot) {
        xy.x = u;
        xy.y = v;
    } else {
        u -= Q->u_0;
        xy.x = v * Q->cosrot + u * Q->sinrot;
        xy.y = u * Q->cosrot - v * Q->sinrot;
    }
    return xy;
}
static PJ_LP omerc_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct omerc_data *Q = (struct omerc_data *)P->opaque;
    double u, v, Qp, Sp, Tp, Vp, Up;
    if (Q->no_rot) {
        v = xy.y;
        u = xy.x;
    } else {
        v = xy.x * Q->cosrot - xy.y * Q->sinrot;
        u = xy.y * Q->cosrot + xy.x * Q->sinrot + Q->u_0;
    }
    Qp = exp(-Q->BrA * v);
    if (Qp == 0) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    Sp = .5 * (Qp - 1. / Qp);
    Tp = .5 * (Qp + 1. / Qp);
    Vp = sin(Q->BrA * u);
    Up = (Vp * Q->cosgam + Sp * Q->singam) / Tp;
    if (fabs(fabs(Up) - 1.) < OM_EPS) {
        lp.lam = 0.;
        lp.phi = Up < 0. ? -M_HALFPI : M_HALFPI;
    } else {
        lp.phi = Q->E / sqrt((1. + Up) / (1. - Up));
        if ((lp.phi = pj_phi2(pow(lp.phi, 1. / Q->B), P->e)) == HUGE_VAL) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            return lp;
        }
        lp.lam = -Q->rB * atan2((Sp * Q->cosgam - Vp * Q->singam), cos(Q->BrA * u));
    }
    return lp;
}
PJ *pj_omerc_setup(PJ *P) {
    double con, com, cosph0, D, F, H, L, sinph0, p, J, gamma = 0, gamma0, lamc = 0, lam1 = 0, lam2 = 0, phi1 = 0,
                                                       phi2 = 0, alpha_c = 0;
    int alp, gam, no_off = 0;
    struct omerc_data *Q = (struct omerc_data *)calloc(1, sizeof(struct omerc_data));
    P->opaque = Q;
    Q->no_rot = pj_param(P->params, "bno_rot").i;
    if ((alp = pj_param(P->params, "talpha").i) != 0) alpha_c = pj_param(P->params, "ralpha").f;
    if ((gam = pj_param(P->params, "tgamma").i) != 0) gamma = pj_param(P->params, "rgamma").f;
    if (alp || gam) {
        lamc = pj_param(P->params, "rlonc").f;
        no_off = pj_param(P->params, "tno_off").i || pj_param(P->params, "tno_uoff").i;
        if (no_off) {
            pj_param(P->params, "sno_uoff");
            pj_param(P->params, "sno_off");
        }
    } else {
        lam1 = pj_param(P->params, "rlon_1").f;
        phi1 = pj_param(P->params, "rlat_1").f;
        lam2 = pj_param(P->params, "rlon_2").f;
        phi2 = pj_param(P->params, "rlat_2").f;
        if (fabs(phi1 - phi2) <= OM_TOL) {
            proj_log_error(P, "Invalid value for lat_1/lat_2: lat_1 should be different from lat_2");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        con = fabs(phi1);
        if (con <= OM_TOL) {
            proj_log_error(P, "Invalid value for lat_1: lat_1 should be different from 0");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        if (fabs(con - M_HALFPI) <= OM_TOL) {
            proj_log_error(P, "Invalid value for lat_1: lat_1 should be different from 90\xc2\xb0");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        if (fabs(fabs(phi2) - M_HALFPI) <= OM_TOL) {
            proj_log_error(P, "Invalid value for lat_2: lat_2 should be different from 90\xc2\xb0");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        if (fabs(fabs(P->phi0) - M_HALFPI) <= OM_TOL) {
            proj_log_error(P, "Invalid value for lat_0: lat_0 should be different from 90\xc2\xb0");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    }
    com = sqrt(P->one_es);
    if (fabs(P->phi0) > OM_EPS) {
        sinph0 = sin(P->phi0);
        cosph0 = cos(P->phi0);
        con = 1. - P->es * sinph0 * sinph0;
        Q->B = cosph0 * cosph0;
        Q->B = sqrt(1. + P->es * Q->B * Q->B / P->one_es);
        Q->A = Q->B * P->k0 * com / con;
        D = Q->B * com / (cosph0 * sqrt(con));
        if ((F = D * D - 1.) <= 0.)
            F = 0.;
        else {
            F = sqrt(F);
            if (P->phi0 < 0.) F = -F;
        }
        Q->E = F += D;
        Q->E *= pow(pj_tsfn(P->phi0, sinph0, P->e), Q->B);
    } else {
        Q->B = 1. / com;
        Q->A = P->k0;
        Q->E = D = F = 1.;
    }
    if (alp || gam) {
        if (alp) {
            gamma0 = aasin(sin(alpha_c) / D);
            if (!gam) gamma = alpha_c;
        } else
            alpha_c = aasin(D * sin(gamma0 = gamma));
        P->lam0 = lamc - aasin(.5 * (F - 1. / F) * tan(gamma0)) / Q->B;
    } else {
        H = pow(pj_tsfn(phi1, sin(phi1), P->e), Q->B);
        L = pow(pj_tsfn(phi2, sin(phi2), P->e), Q->B);
        F = Q->E / H;
        p = (L - H) / (L + H);
        if (p == 0) {
            proj_log_error(P, "Invalid value for eccentricity");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        J = Q->E * Q->E;
        J = (J - L * H) / (J + L * H);
        if ((con = lam1 - lam2) < -M_PI)
            lam2 -= M_TWOPI;
        else if (con > M_PI)
            lam2 += M_TWOPI;
        P->lam0 = adjlon(.5 * (lam1 + lam2) - atan(J * tan(.5 * Q->B * (lam1 - lam2)) / p) / Q->B);
        gamma0 = atan(2. * sin(Q->B * adjlon(lam1 - P->lam0)) / (F - 1. / F));
        gamma = alpha_c = aasin(D * sin(gamma0));
    }
    Q->singam = sin(gamma0);
    Q->cosgam = cos(gamma0);
    Q->sinrot = sin(gamma);
    Q->cosrot = cos(gamma);
    Q->BrA = 1. / (Q->ArB = Q->A * (Q->rB = 1. / Q->B));
    Q->AB = Q->A * Q->B;
    if (no_off)
        Q->u_0 = 0;
    else {
        Q->u_0 = fabs(Q->ArB * atan(sqrt(D * D - 1.) / cos(alpha_c)));
        if (P->phi0 < 0.) Q->u_0 = -Q->u_0;
    }
    F = 0.5 * gamma0;
    Q->v_pole_n = Q->ArB * log(tan(M_FORTPI - F));
    Q->v_pole_s = Q->ArB * log(tan(M_FORTPI + F));
    P->inv = omerc_e_inverse;
    P->fwd = omerc_e_forward;
    return P;
}

/* ---------------- ocea ---------------- */
struct ocea_data { double rok, rtk, sinphi, cosphi, singam, cosgam; };
static PJ_XY ocea_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct ocea_data *Q = (struct ocea_data *)P->opaque;
    double t;
    xy.y = sin(lp.phi);
    t = cos(lp.phi);
    xy.x = atan((tan(lp.phi) * Q->cosphi + Q->sinphi * sin(lp.lam)) / cos(lp.lam));
    if (cos(lp.lam) < 0.) xy.x += M_PI;
    xy.x *= Q->rtk;
    xy.y = Q->rok * (Q->sinphi * xy.y - Q->cosphi * t * sin(lp.lam));
    return xy;
}
static PJ_LP ocea_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct ocea_data *Q = (struct ocea_data *)P->opaque;
    double t, s;
    xy.y /= Q->rok;
    xy.x /= Q->rtk;
    t = sqrt(1. - xy.y * xy.y);
    s = sin(xy.x);
    lp.phi = asin(xy.y * Q->sinphi + t * Q->cosphi * s);
    lp.lam = atan2(t * Q->sinphi * s - xy.y * Q->cosphi, t * cos(xy.x));
    return lp;
}
PJ *pj_ocea_setup(PJ *P) {
    double phi_1, phi_2, lam_1, lam_2, lonz, alpha;
    struct ocea_data *Q = (struct ocea_data *)calloc(1, sizeof(struct ocea_data));
    P->opaque = Q;
    Q->rok = 1. / P->k0;
    Q->rtk = P->k0;
    if (pj_param(P->params, "talpha").i) {
        alpha = M_PI + pj_param(P->params, "ralpha").f;
        lonz = pj_param(P->params, "rlonc").f;
        Q->singam = atan(-cos(alpha) / (-sin(P->phi0) * sin(alpha))) + lonz;
        Q->sinphi = asin(cos(P->phi0) * sin(alpha));
    } else {
        phi_1 = pj_param(P->params, "rlat_1").f;
        phi_2 = pj_param(P->params, "rlat_2").f;
        lam_1 = pj_param(P->params, "rlon_1").f;
        lam_2 = pj_param(P->params, "rlon_2").f;
        Q->singam = atan2(cos(phi_1) * sin(phi_2) * cos(lam_1) - sin(phi_1) * cos(phi_2) * cos(lam_2),
                          sin(phi_1) * cos(phi_2) * sin(lam_2) - cos(phi_1) * sin(phi_2) * sin(lam_1));
        Q->sinphi = atan(-cos(Q->singam - lam_1) / tan(phi_1));
    }
    P->lam0 = Q->singam + M_HALFPI;
    Q->cosphi = cos(Q->sinphi);
    Q->sinphi = sin(Q->sinphi);
    Q->cosgam = cos(Q->singam);
    Q->singam = sin(Q->singam);
    P->inv = ocea_s_inverse;
    P->fwd = ocea_s_forward;
    P->es = 0.;
    return P;
}

/* ---------------- labrd ---------------- */
struct labrd_data { double Az, kRg, p0s, A, C, Ca, Cb, Cc, Cd; };
#define LB_EPS 1.e-10
static PJ_XY labrd_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct labrd_data *Q = (struct labrd_data *)P->opaque;
    double V1, V2, ps, sinps, cosps, sinps2, cosps2, I1, I2, I3, I4, I5, I6, x2, y2, t;
    V1 = Q->A * log(tan(M_FORTPI + .5 * lp.phi));
    t = P->e * sin(lp.phi);
    V2 = .5 * P->e * Q->A * log((1. + t) / (1. - t));
    ps = 2. * (atan(exp(V1 - V2 + Q->C)) - M_FORTPI);
    I1 = ps - Q->p0s;
    cosps = cos(ps);
    cosps2 = cosps * cosps;
    sinps = sin(ps);
    sinps2 = sinps * sinps;
    I4 = Q->A * cosps;
    I2 = .5 * Q->A * I4 * sinps;
    I3 = I2 * Q->A * Q->A * (5. * cosps2 - sinps2) / 12.;
    I6 = I4 * Q->A * Q->A;
    I5 = I6 * (cosps2 - sinps2) / 6.;
    I6 *= Q->A * Q->A * (5. * cosps2 * cosps2 + sinps2 * (sinps2 - 18. * cosps2)) / 120.;
    t = lp.lam * lp.lam;
    xy.x = Q->kRg * lp.lam * (I4 + t * (I5 + t * I6));
    xy.y = Q->kRg * (I1 + t * (I2 + t * I3));
    x2 = xy.x * xy.x;
    y2 = xy.y * xy.y;
    V1 = 3. * xy.x * y2 - xy.x * x2;
    V2 = xy.y * y2 - 3. * x2 * xy.y;
    xy.x += Q->Ca * V1 + Q->Cb * V2;
    xy.y += Q->Ca * V2 - Q->Cb * V1;
    return xy;
}
static PJ_LP labrd_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct labrd_data *Q = (struct labrd_data *)P->opaque;
    double x2, y2, V1, V2, V3, V4, t, t2, ps, pe, tpe, s, d, Re, I7, I8, I9, I10, I11;
    int i;
    x2 = xy.x * xy.x;
    y2 = xy.y * xy.y;
    V1 = 3. * xy.x * y2 - xy.x * x2;
    V2 = xy.y * y2 - 3. * x2 * xy.y;
    V3 = xy.x * (5. * y2 * y2 + x2 * (-10. * y2 + x2));
    V4 = xy.y * (5. * x2 * x2 + y2 * (-10. * x2 + y2));
    xy.x += -Q->Ca * V1 - Q->Cb * V2 + Q->Cc * V3 + Q->Cd * V4;
    xy.y += Q->Cb * V1 - Q->Ca * V2 - Q->Cd * V3 + Q->Cc * V4;
    ps = Q->p0s + xy.y / Q->kRg;
    pe = ps + P->phi0 - Q->p0s;
    for (i = 20; i; --i) {
        V1 = Q->A * log(tan(M_FORTPI + .5 * pe));
        tpe = P->e * sin(pe);
        V2 = .5 * P->e * Q->A * log((1. + tpe) / (1. - tpe));
        t = ps - 2. * (atan(exp(V1 - V2 + Q->C)) - M_FORTPI);
        pe += t;
        if (fabs(t) < LB_EPS) break;
    }
    t = P->e * sin(pe);
    t = 1. - t * t;
    Re = P->one_es / (t * sqrt(t));
    t = tan(ps);
    t2 = t * t;
    s = Q->kRg * Q->kRg;
    d = Re * P->k0 * Q->kRg;
    I7 = t / (2. * d);
    I8 = t * (5. + 3. * t2) / (24. * d * s);
    d = cos(ps) * Q->kRg * Re;
    I9 = 1. / d;
    d *= s;
    I10 = (1. + 2. * t2) / (6. * d);
    I11 = (5. + t2 * (28. + 24. * t2)) / (120. * d * s);
    x2 = xy.x * xy.x;
    lp.phi = pe + x2 * (-I7 + I8 * x2);
    lp.lam = xy.x * (I9 + x2 * (-I10 + x2 * I11));
    return lp;
}
PJ *pj_labrd_setup(PJ *P) {
    double sinp, t, cosp2;
    struct labrd_data *Q = (struct labrd_data *)calloc(1, sizeof(struct labrd_data));
    P->opaque = Q;
    if (P->phi0 == 0.) {
        proj_log_error(P, "Invalid value for lat_0: lat_0 should be different from 0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    Q->Az = pj_param(P->params, "razi").f;
    sinp = sin(P->phi0);
    t = 1. - P->es * sinp * sinp;
    Q->kRg = P->k0 * sqrt(P->one_es) / t;
    cosp2 = cos(P->phi0);
    cosp2 *= cosp2;
    Q->A = sqrt(1. + P->es * cosp2 * cosp2 / P->one_es);
    Q->p0s = asin(sinp / Q->A);
    t = tan(M_FORTPI + .5 * Q->p0s);
    Q->C = log(t) - Q->A * (log(tan(M_FORTPI + .5 * P->phi0)) - .5 * P->e * log((1. + P->e * sinp) / (1. - P->e * sinp)));
    t = Q->Az + Q->Az;
    Q->Ca = (1. - cos(t)) * (Q->Cb = 1. / (12. * Q->kRg * Q->kRg));
    Q->Cb *= sin(t);
    Q->Cc = 3. * (Q->Ca * Q->Ca - Q->Cb * Q->Cb);
    Q->Cd = 6. * Q->Ca * Q->Cb;
    P->inv = labrd_e_inverse;
    P->fwd = labrd_e_forward;
    return P;
}

/* ---------------- nzmg ---------------- */
#define NZ_EPSLN 1e-10
#define NZ_SEC5_TO_RAD 0.4848136811095359935899141023
#define NZ_RAD_TO_SEC5 2.062648062470963551564733573
static const COMPLEX nz_bf[] = {{.7557853228, 0.0}, {.249204646, .003371507}, {-.001541739, .041058560},
                                {-.10162907, .01727609}, {-.26623489, -.36249218}, {-.6870983, -1.1651967}};
static const double nz_tphi[] = {1.5627014243, .5185406398, -.03333098, -.1052906, -.0368594, .007317, .01220, .00394, -.0013};
static const double nz_tpsi[] = {.6399175073, -.1358797613, .063294409, -.02526853, .0117879, -.0055161, .0026906, -.001333, .00067, -.00034};
#define NZ_Nbf 5
#define NZ_Ntpsi 9
#define NZ_Ntphi 8
static PJ_XY nzmg_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    COMPLEX p;
    const double *C;
    int i;
    lp.phi = (lp.phi - P->phi0) * NZ_RAD_TO_SEC5;
    for (p.r = *(C = nz_tpsi + (i = NZ_Ntpsi)); i; --i) p.r = *--C + lp.phi * p.r;
    p.r *= lp.phi;
    p.i = lp.lam;
    p = pj_zpoly1(p, nz_bf, NZ_Nbf);
    xy.x = p.i;
    xy.y = p.r;
    return xy;
}
static PJ_LP nzmg_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    int nn, i;
    COMPLEX p, f, fp, dp;
    double den;
    const double *C;
    p.r = xy.y;
    p.i = xy.x;
    for (nn = 20; nn; --nn) {
        f = pj_zpolyd1(p, nz_bf, NZ_Nbf, &fp);
        f.r -= xy.y;
        f.i -= xy.x;
        den = fp.r * fp.r + fp.i * fp.i;
        p.r += dp.r = -(f.r * fp.r + f.i * fp.i) / den;
        p.i += dp.i = -(f.i * fp.r - f.r * fp.i) / den;
        if ((fabs(dp.r) + fabs(dp.i)) <= NZ_EPSLN) break;
    }
    if (nn) {
        lp.lam = p.i;
        for (lp.phi = *(C = nz_tphi + (i = NZ_Ntphi)); i; --i) lp.phi = *--C + p.r * lp.phi;
        lp.phi = P->phi0 + p.r * lp.phi * NZ_SEC5_TO_RAD;
