        sav = lampp;
        lamtp = lp.lam + Q->p22 * lampp;
        cl = cos(lamtp);
        if (fabs(cl) < SOM_TOL) lamtp -= SOM_TOL;
        if (cl < 0) fac = lampp + sin(lampp) * M_HALFPI;
        else fac = lampp - sin(lampp) * M_HALFPI;
