            lamt = lp.lam + Q->p22 * sav;
            c = cos(lamt);
            if (fabs(c) < SOM_TOL) lamt -= SOM_TOL;
            xlam = (P->one_es * tanphi * Q->sa + sin(lamt) * Q->ca) / c;
            lamdp = atan(xlam) + fac;
            if (fabs(fabs(sav) - fabs(lamdp)) < SOM_TOL) break;
            sav = lamdp;
        }
