}

static PJ *som_setup(PJ *P, double alf) {
    struct som_data *Q = (struct som_data *)P->opaque;
    double esc, ess, lam;
    Q->sa = sin(alf);
    Q->ca = cos(alf);
    if (fabs(Q->ca) < 1e-9) Q->ca = 1e-9;
    esc = P->es * Q->ca * Q->ca;
    ess = P->es * Q->sa * Q->sa;
    Q->w = (1. - esc) * P->rone_es;
    Q->w = Q->w * Q->w - 1.;
    Q->q = ess * P->rone_es;
    Q->t = ess * (2. - P->es) * P->rone_es * P->rone_es;
    Q->u = esc * P->rone_es;
    Q->xj = P->one_es * P->one_es * P->one_es;
    Q->rlm = M_PI * (1. / 248. + .5161290322580645);
    Q->rlm2 = Q->rlm + M_TWOPI;
    Q->a2 = Q->a4 = Q->b = Q->c1 = Q->c3 = 0.;
    seraz0(0., 1., P);
    for (lam = 9.; lam <= 81.0001; lam += 18.) seraz0(lam, 4., P);
    for (lam = 18; lam <= 72.0001; lam += 18.) seraz0(lam, 2., P);
    seraz0(90., 1., P);
    Q->a2 /= 30.;
    Q->a4 /= 60.;
    Q->b /= 30.;
    Q->c1 /= 15.;
    Q->c3 /= 45.;
    P->inv = som_e_inverse;
    P->fwd = som_e_forward;
    return P;
}

PJ *pj_som_setup(PJ *P) {
    double alf, ps_rev;
    struct som_data *Q = (struct som_data *)calloc(1, sizeof(struct som_data));
    P->opaque = Q;
    alf = pj_param(P->params, "rinc_angle").f;
    ps_rev = pj_param(P->params, "dps_rev").f;
    P->lam0 = pj_param(P->params, "rasc_lon").f;
    Q->p22 = ps_rev;
    return som_setup(P, alf);
}

PJ *pj_lsat_setup(PJ *P) {
    int land, path;
    double alf;
    struct som_data *Q = (struct som_data *)calloc(1, sizeof(struct som_data));
    P->opaque = Q;
    land = pj_param(P->params, "ilsat").i;
    if (land <= 0 || land > 5) {
        proj_log_error(P, "Invalid value for lsat: lsat should be in [1, 5] range");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    path = pj_param(P->params, "ipath").i;
    if (path <= 0 || path > (land <= 3 ? 251 : 233)) {
        proj_log_error(P, "Invalid value for path: path should be in [1, %d] range", land <= 3 ? 251 : 233);
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    if (land <= 3) {
        P->lam0 = DEG_TO_RAD * 128.87 - M_TWOPI / 251. * path;
        Q->p22 = 103.2669323;
        alf = DEG_TO_RAD * 99.092;
    } else {
        P->lam0 = DEG_TO_RAD * 129.3 - M_TWOPI / 233. * path;
        Q->p22 = 98.8841202;
        alf = DEG_TO_RAD * 98.2;
    }
    Q->p22 /= 1440.;
    return som_setup(P, alf);
}

PJ *pj_misrsom_setup(PJ *P) {
    int path;
    double alf;
    struct som_data *Q = (struct som_data *)calloc(1, sizeof(struct som_data));
    P->opaque = Q;
    path = pj_param(P->params, "ipath").i;
    if (path <= 0 || path > 233) {
        proj_log_error(P, "Invalid value for path: path should be in [1, 233] range");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    P->lam0 = DEG_TO_RAD * 129.3056 - M_TWOPI / 233. * path;
    Q->p22 = 98.88 / 1440.0;
    alf = DEG_TO_RAD * 98.30382;
    return som_setup(P, alf);
}
