            theta = -lon + M_HALFPI;
        } else if (lon < M_FORTPI && lon >= -M_FORTPI) {
            area = AREA_1;
            theta = -lon;
        } else if (lon < -M_FORTPI && lon >= -(M_HALFPI + M_FORTPI)) {
            area = AREA_2;
            theta = -lon - M_HALFPI;
        } else {
            area = AREA_3;
            theta = (lon > 0.0 ? -lon + M_PI : -lon - M_PI);
        }
    } else {
        double q, r, s;
        double sinlat, coslat, sinlon, coslon;
        if (Q->face == FACE_RIGHT) lon = qsc_shift_lon_origin(lon, +M_HALFPI);
        else if (Q->face == FACE_BACK) lon = qsc_shift_lon_origin(lon, +M_PI);
        else if (Q->face == FACE_LEFT) lon = qsc_shift_lon_origin(lon, -M_HALFPI);
        sinlat = sin(lat);
        coslat = cos(lat);
        sinlon = sin(lon);
        coslon = cos(lon);
        q = coslat * coslon;
        r = coslat * sinlon;
        s = sinlat;
        if (Q->face == FACE_FRONT) {
            phi = acos(q);
            theta = qsc_fwd_equat_face_theta(phi, s, r, &area);
        } else if (Q->face == FACE_RIGHT) {
            phi = acos(r);
            theta = qsc_fwd_equat_face_theta(phi, s, -q, &area);
        } else if (Q->face == FACE_BACK) {
            phi = acos(-q);
            theta = qsc_fwd_equat_face_theta(phi, s, -r, &area);
        } else if (Q->face == FACE_LEFT) {
            phi = acos(-r);
            theta = qsc_fwd_equat_face_theta(phi, s, q, &area);
        } else {
            phi = theta = 0.0;
            area = AREA_0;
        }
    }
    mu = atan((12.0 / M_PI) * (theta + acos(sin(theta) * cos(M_FORTPI)) - M_HALFPI));
    t = sqrt((1.0 - cos(phi)) / (cos(mu) * cos(mu)) / (1.0 - cos(atan(1.0 / cos(theta)))));
    if (area == AREA_1) mu += M_HALFPI;
    else if (area == AREA_2) mu += M_PI;
    else if (area == AREA_3) mu += M_PI_HALFPI;
    xy.x = t * cos(mu);
    xy.y = t * sin(mu);
    return xy;
}
static PJ_LP qsc_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct qsc_data *Q = (struct qsc_data *)P->opaque;
    double mu, nu, cosmu, tannu, tantheta, theta, cosphi, phi, t;
    int area;
    nu = atan(sqrt(xy.x * xy.x + xy.y * xy.y));
    mu = atan2(xy.y, xy.x);
    if (xy.x >= 0.0 && xy.x >= fabs(xy.y))
        area = AREA_0;
    else if (xy.y >= 0.0 && xy.y >= fabs(xy.x)) {
        area = AREA_1;
        mu -= M_HALFPI;
    } else if (xy.x < 0.0 && -xy.x >= fabs(xy.y)) {
        area = AREA_2;
        mu = (mu < 0.0 ? mu + M_PI : mu - M_PI);
    } else {
        area = AREA_3;
        mu += M_HALFPI;
    }
    t = (M_PI / 12.0) * tan(mu);
    tantheta = sin(t) / (cos(t) - (1.0 / sqrt(2.0)));
    theta = atan(tantheta);
    cosmu = cos(mu);
    tannu = tan(nu);
    cosphi = 1.0 - cosmu * cosmu * tannu * tannu * (1.0 - cos(atan(1.0 / cos(theta))));
    if (cosphi < -1.0) cosphi = -1.0;
    else if (cosphi > +1.0) cosphi = +1.0;
    if (Q->face == FACE_TOP) {
        phi = acos(cosphi);
        lp.phi = M_HALFPI - phi;
        if (area == AREA_0) lp.lam = theta + M_HALFPI;
        else if (area == AREA_1) lp.lam = (theta < 0.0 ? theta + M_PI : theta - M_PI);
        else if (area == AREA_2) lp.lam = theta - M_HALFPI;
        else lp.lam = theta;
    } else if (Q->face == FACE_BOTTOM) {
        phi = acos(cosphi);
        lp.phi = phi - M_HALFPI;
        if (area == AREA_0) lp.lam = -theta + M_HALFPI;
        else if (area == AREA_1) lp.lam = -theta;
        else if (area == AREA_2) lp.lam = -theta - M_HALFPI;
        else lp.lam = (theta < 0.0 ? -theta - M_PI : -theta + M_PI);
    } else {
        double q, r, s;
        q = cosphi;
        t = q * q;
        if (t >= 1.0) s = 0.0;
        else s = sqrt(1.0 - t) * sin(theta);
        t += s * s;
        if (t >= 1.0) r = 0.0;
        else r = sqrt(1.0 - t);
        if (area == AREA_1) { t = r; r = -s; s = t; }
        else if (area == AREA_2) { r = -r; s = -s; }
        else if (area == AREA_3) { t = r; r = s; s = -t; }
        if (Q->face == FACE_RIGHT) { t = q; q = -r; r = t; }
        else if (Q->face == FACE_BACK) { q = -q; r = -r; }
        else if (Q->face == FACE_LEFT) { t = q; q = r; r = -t; }
        lp.phi = acos(-s) - M_HALFPI;
        lp.lam = atan2(r, q);
        if (Q->face == FACE_RIGHT) lp.lam = qsc_shift_lon_origin(lp.lam, -M_HALFPI);
        else if (Q->face == FACE_BACK) lp.lam = qsc_shift_lon_origin(lp.lam, -M_PI);
        else if (Q->face == FACE_LEFT) lp.lam = qsc_shift_lon_origin(lp.lam, +M_HALFPI);
    }
    if (P->es != 0.0) {
        int invert_sign;
        double tanphi, xa;
        invert_sign = (lp.phi < 0.0 ? 1 : 0);
        tanphi = tan(lp.phi);
        xa = Q->b / sqrt(tanphi * tanphi + Q->one_minus_f_squared);
        lp.phi = atan(sqrt(P->a * P->a - xa * xa) / (Q->one_minus_f * xa));
        if (invert_sign) lp.phi = -lp.phi;
    }
    return lp;
}
PJ *pj_qsc_setup(PJ *P) {
    struct qsc_data *Q = (struct qsc_data *)calloc(1, sizeof(struct qsc_data));
    P->opaque = Q;
    P->inv = qsc_e_inverse;
    P->fwd = qsc_e_forward;
    if (P->phi0 >= M_HALFPI - M_FORTPI / 2.0) Q->face = FACE_TOP;
    else if (P->phi0 <= -(M_HALFPI - M_FORTPI / 2.0)) Q->face = FACE_BOTTOM;
    else if (fabs(P->lam0) <= M_FORTPI) Q->face = FACE_FRONT;
    else if (fabs(P->lam0) <= M_HALFPI + M_FORTPI) Q->face = (P->lam0 > 0.0 ? FACE_RIGHT : FACE_LEFT);
    else Q->face = FACE_BACK;
    if (P->es != 0.0) {
        Q->a_squared = P->a * P->a;
        Q->b = P->a * sqrt(1.0 - P->es);
        Q->one_minus_f = 1.0 - (P->a - Q->b) / P->a;
        Q->one_minus_f_squared = Q->one_minus_f * Q->one_minus_f;
    }
    return P;
}

/* ---------------- rouss ---------------- */
struct rouss_data { double s0, A1, A2, A3, A4, A5, A6, B1, B2, B3, B4, B5, B6, B7, B8; double *en; };
static void rouss_destructor(PJ *P, int e) {
    if (P && P->opaque) { struct rouss_data *Q = (struct rouss_data *)P->opaque; if (Q->en) free(Q->en); }
    pj_default_destructor(P, e);
}
static PJ_XY rouss_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct rouss_data *Q = (struct rouss_data *)P->opaque;
    double s, al, cp, sp, al2, s2;
    cp = cos(lp.phi);
    sp = sin(lp.phi);
    s = pj_mlfn(lp.phi, sp, cp, Q->en) - Q->s0;
    s2 = s * s;
    al = lp.lam * cp / sqrt(1. - P->es * sp * sp);
    al2 = al * al;
    xy.x = P->k0 * al * (1. + s2 * (Q->A1 + s2 * Q->A4) - al2 * (Q->A2 + s * Q->A3 + s2 * Q->A5 + al2 * Q->A6));
    xy.y = P->k0 * (al2 * (Q->B1 + al2 * Q->B4) +
                    s * (1. + al2 * (Q->B3 - al2 * Q->B6) + s2 * (Q->B2 + s2 * Q->B8) + s * al2 * (Q->B5 + s * Q->B7)));
    return xy;
}
static PJ_LP rouss_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct rouss_data *Q = (struct rouss_data *)P->opaque;
    double s, al, x = xy.x / P->k0, y = xy.y / P->k0;
    int k;
    /* first estimate, then Newton iterations on the forward */
    s = Q->s0 + y;
    lp.phi = pj_inv_mlfn(s, Q->en);
    s = sin(lp.phi);
    al = x;
    lp.lam = al * sqrt(1. - P->es * s * s) / cos(lp.phi);
    for (k = 0; k < 15; ++k) {
        PJ_XY f = rouss_e_forward(lp, P), fa, fb;
        PJ_LP t;
        double h = 1e-8, dxdl, dxdp, dydl, dydp, det, dl, dp;
        t = lp; t.lam += h; fa = rouss_e_forward(t, P);
        t = lp; t.phi += h; fb = rouss_e_forward(t, P);
        dxdl = (fa.x - f.x) / h; dydl = (fa.y - f.y) / h;
        dxdp = (fb.x - f.x) / h; dydp = (fb.y - f.y) / h;
        det = dxdl * dydp - dxdp * dydl;
        if (det == 0) break;
        dl = ((xy.x - f.x) * dydp - (xy.y - f.y) * dxdp) / det;
        dp = ((xy.y - f.y) * dxdl - (xy.x - f.x) * dydl) / det;
        lp.lam += dl;
        lp.phi += dp;
        if (fabs(dl) < 1e-14 && fabs(dp) < 1e-14) break;
    }
    return lp;
}
PJ *pj_rouss_setup(PJ *P) {
    double N0, es2, t, t2, R_R0_2, R_R0_4;
    struct rouss_data *Q = (struct rouss_data *)calloc(1, sizeof(struct rouss_data));
    P->opaque = Q;
    P->destructor = rouss_destructor;
    if (!((Q->en = pj_enfn(P->n)))) return pj_default_destructor(P, PROJ_ERR_OTHER);
    es2 = sin(P->phi0);
    Q->s0 = pj_mlfn(P->phi0, es2, cos(P->phi0), Q->en);
    t = 1. - (es2 = P->es * es2 * es2);
    N0 = 1. / sqrt(t);
    R_R0_2 = t * t / P->one_es;
    R_R0_4 = R_R0_2 * R_R0_2;
    t = tan(P->phi0);
    t2 = t * t;
    Q->A1 = R_R0_2 / 4.;
    Q->A2 = R_R0_2 * (2 * t2 - 1. - 2. * es2) / 12.;
    Q->A3 = R_R0_2 * t * (1. + 4. * t2) / (12. * N0);
    Q->A4 = R_R0_4 / 24.;
    Q->A5 = R_R0_4 * (-1. + t2 * (11. + 12. * t2)) / 24.;
    Q->A6 = R_R0_4 * (-2. + t2 * (11. - 2. * t2)) / 240.;
    Q->B1 = t / (2. * N0);
    Q->B2 = R_R0_2 / 12.;
    Q->B3 = R_R0_2 * (1. + 2. * t2 - 2. * es2) / 4.;
    Q->B4 = R_R0_2 * t * (2. - t2) / (6. * N0);
    Q->B5 = R_R0_2 * t * (5. + 4. * t2) / (6. * N0);
    Q->B6 = R_R0_4 * (-2. + t2 * (-5. + 6. * t2)) / 48.;
    Q->B7 = R_R0_4 * (5. + t2 * (19. + 12. * t2)) / 24.;
    Q->B8 = R_R0_4 / 120.;
    P->fwd = rouss_e_forward;
    P->inv = rouss_e_inverse;
    return P;
}
