    static const double C[] = {-8.58691003636495e-07, 2.02692115653689e-07, 3.12960480765314e-05, 5.30394739921063e-05,
                               -0.0012804644680613, -0.00575574836830288, 0.0914203033408211};
    double y = phi * M_TWO_D_PI;
    double y2, d1 = 0.0, d2 = 0.0;
    size_t i;
    y = 2. * y * y - 1.;
    y2 = 2. * y;
    for (i = 0; i < sizeof(C) / sizeof(C[0]); ++i) {
        double temp = d1;
        d1 = y2 * d1 - d2 + C[i];
        d2 = temp;
    }
    return phi * (y * d1 - d2 + 0.5 * C0);
}

static PJ_XY adams_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct adams_data *Q = (struct adams_data *)P->opaque;
    double a = 0., b = 0., m, n;
    int sm = 0, sn = 0;
    switch (Q->mode) {
    case GUYOU:
        if ((fabs(lp.lam) - AD_TOL) > M_PI_2) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            xy.x = xy.y = HUGE_VAL;
            return xy;
        }
        if (fabs(fabs(lp.phi) - M_PI_2) < AD_TOL) {
            xy.x = 0;
            xy.y = lp.phi < 0 ? -1.85407 : 1.85407;
            return xy;
        } else {
            const double sl = sin(lp.lam);
            const double sp = sin(lp.phi);
            const double cp = cos(lp.phi);
            a = aacos((cp * sl - sp) * RSQRT2);
            b = aacos((cp * sl + sp) * RSQRT2);
            sm = lp.lam < 0.;
            sn = lp.phi < 0.;
        }
        break;
    case PEIRCE_Q: {
        const double sl = sin(lp.lam);
        const double cl = cos(lp.lam);
        const double cp = cos(lp.phi);
        a = aacos(cp * (sl + cl) * RSQRT2);
        b = aacos(cp * (sl - cl) * RSQRT2);
        sm = sl < 0.;
        sn = cl > 0.;
    } break;
    case ADAMS_HEMI: {
        const double sp = sin(lp.phi);
        if ((fabs(lp.lam) - AD_TOL) > M_PI_2) {
            proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
            xy.x = xy.y = HUGE_VAL;
            return xy;
        }
        a = cos(lp.phi) * sin(lp.lam);
        sm = (sp + a) < 0.;
        sn = (sp - a) < 0.;
        a = aacos(a);
        b = M_PI_2 - lp.phi;
    } break;
    case ADAMS_WS1: {
        const double sp = tan(0.5 * lp.phi);
        b = cos(aasin(sp)) * sin(0.5 * lp.lam);
        a = aacos((b - sp) * RSQRT2);
        b = aacos((b + sp) * RSQRT2);
        sm = lp.lam < 0.;
        sn = lp.phi < 0.;
    } break;
    case ADAMS_WS2: {
        const double spp = tan(0.5 * lp.phi);
        a = cos(aasin(spp)) * sin(0.5 * lp.lam);
        sm = (spp + a) < 0.;
        sn = (spp - a) < 0.;
        b = aacos(spp);
        a = aacos(a);
    } break;
    }
    {
        double cab = cos(a + b), camb = cos(a - b);
        m = aasin(sqrt((1. + (cab < 0.0 ? cab : 0.0))));
        if (sm) m = -m;
        n = aasin(sqrt(fabs(1. - (camb > 0.0 ? camb : 0.0))));
        if (sn) n = -n;
    }
    xy.x = ell_int_5(m);
    xy.y = ell_int_5(n);
    if (Q->mode == PEIRCE_Q) {
        if (Q->pqshape == PQ_SQUARE) {
            const double temp = xy.x;
            xy.x = RSQRT2 * (xy.x - xy.y);
            xy.y = RSQRT2 * (temp + xy.y);
        } else if (Q->pqshape == PQ_NHEMISPHERE) {
            if (lp.phi < 0) {
                proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
                xy.x = xy.y = HUGE_VAL;
                return xy;
            }
        } else if (Q->pqshape == PQ_SHEMISPHERE) {
            if (lp.phi > 0) {
                proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
                xy.x = xy.y = HUGE_VAL;
                return xy;
            }
        } else if (Q->pqshape == PQ_HORIZONTAL) {
            if (lp.phi < 0) {
                /* southern hemisphere: unfold into the adjacent square */
                const double shift = 2. * 1.8540746773013719;
                if (xy.x < 0 && xy.y < 0) { xy.x = -xy.x - shift * 0; }
                xy.x = xy.x < 0 ? xy.x + shift : xy.x - shift;
                xy.y = -xy.y;
            }
            xy.x += Q->scrollx * 2. * 1.8540746773013719;
        } else if (Q->pqshape == PQ_VERTICAL) {
            if (lp.phi < 0) {
                const double shift = 2. * 1.8540746773013719;
                xy.y = xy.y < 0 ? xy.y + shift : xy.y - shift;
                xy.x = -xy.x;
            }
            xy.y += Q->scrolly * 2. * 1.8540746773013719;
        }
    }
    if (Q->mode == ADAMS_HEMI || Q->mode == ADAMS_WS2) {
        const double temp = xy.x;
        xy.x = RSQRT2 * (xy.x - xy.y);
        xy.y = RSQRT2 * (temp + xy.y);
    }
    return xy;
}

static PJ *adams_setup(PJ *P, enum adams_type mode) {
    struct adams_data *Q = (struct adams_data *)calloc(1, sizeof(struct adams_data));
    P->opaque = Q;
    P->es = 0;
    P->fwd = adams_forward;
    P->inv = NULL;
    Q->mode = mode;
    return P;
}
PJ *pj_guyou_setup(PJ *P) { return adams_setup(P, GUYOU); }
PJ *pj_adams_hemi_setup(PJ *P) { return adams_setup(P, ADAMS_HEMI); }
PJ *pj_adams_ws1_setup(PJ *P) { return adams_setup(P, ADAMS_WS1); }
PJ *pj_adams_ws2_setup(PJ *P) { return adams_setup(P, ADAMS_WS2); }
PJ *pj_peirce_q_setup(PJ *P) {
    const char *pqshape;
    struct adams_data *Q;
    P = adams_setup(P, PEIRCE_Q);
    Q = (struct adams_data *)P->opaque;
    pqshape = pj_param(P->params, "sshape").s;
    if (!pqshape || !strcmp("square", pqshape)) Q->pqshape = PQ_SQUARE;
    else if (!strcmp("diamond", pqshape)) Q->pqshape = PQ_DIAMOND;
    else if (!strcmp("nhemisphere", pqshape)) Q->pqshape = PQ_NHEMISPHERE;
    else if (!strcmp("shemisphere", pqshape)) Q->pqshape = PQ_SHEMISPHERE;
    else if (!strcmp("horizontal", pqshape)) Q->pqshape = PQ_HORIZONTAL;
    else if (!strcmp("vertical", pqshape)) Q->pqshape = PQ_VERTICAL;
    else {
        proj_log_error(P, "peirce_q: invalid value for 'shape' parameter");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    if (Q->pqshape == PQ_HORIZONTAL) {
        Q->scrollx = pj_param(P->params, "dscrollx").f;
        if (Q->scrollx > 1 || Q->scrollx < -1) {
            proj_log_error(P, "peirce_q: scrollx must be in the range [-1,1]");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    } else if (Q->pqshape == PQ_VERTICAL) {
        Q->scrolly = pj_param(P->params, "dscrolly").f;
        if (Q->scrolly > 1 || Q->scrolly < -1) {
            proj_log_error(P, "peirce_q: scrolly must be in the range [-1,1]");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    }
    return P;
}
EOF
