/* bertin1953, calcofi, col_urban, geoc, healpix, rhealpix, s2 */
#include "proj.h"

/* ---------------- bertin1953 ---------------- */
struct bertin_data { double cos_delta_phi, sin_delta_phi, cos_delta_gamma, sin_delta_gamma, deltaLambda; };
static PJ_XY bertin1953_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct bertin_data *Q = (struct bertin_data *)P->opaque;
    double fu = 1.4, k = 12., w = 1.68, d;
    double cosphi, x, y, z, z0;
    lp.lam += Q->deltaLambda;
    cosphi = cos(lp.phi);
    x = cos(lp.lam) * cosphi;
    y = sin(lp.lam) * cosphi;
    z = sin(lp.phi);
    z0 = z * Q->cos_delta_phi + x * Q->sin_delta_phi;
    lp.lam = atan2(y * Q->cos_delta_gamma - z0 * Q->sin_delta_gamma, x * Q->cos_delta_phi - z * Q->sin_delta_phi);
    z0 = z0 * Q->cos_delta_gamma + y * Q->sin_delta_gamma;
    lp.phi = asin(z0);
    lp.lam = adjlon(lp.lam);
    if (lp.lam + lp.phi < -fu) {
        d = (lp.lam - lp.phi + 1.6) * (lp.lam + lp.phi + fu) / 8.;
        lp.lam += d;
        lp.phi -= 0.8 * d * sin(lp.phi + M_PI / 2.);
    }
    cosphi = cos(lp.phi);
    d = sqrt(2. / (1. + cosphi * cos(lp.lam / 2.)));
    xy.x = w * d * cosphi * sin(lp.lam / 2.);
    xy.y = d * sin(lp.phi);
    d = (1. - cos(lp.lam * lp.phi)) / k;
    if (xy.y < 0.) xy.x *= 1. + d;
    if (xy.y > 0.) xy.x *= 1. + d / 1.5 * xy.x * xy.x;
    return xy;
}
PJ *pj_bertin1953_setup(PJ *P) {
    struct bertin_data *Q = (struct bertin_data *)calloc(1, sizeof(struct bertin_data));
    P->opaque = Q;
    P->lam0 = 0;
    P->phi0 = DEG_TO_RAD * -42;
    Q->cos_delta_phi = cos(P->phi0);
    Q->sin_delta_phi = sin(P->phi0);
    Q->cos_delta_gamma = 1.;
    Q->sin_delta_gamma = 0.;
    Q->deltaLambda = DEG_TO_RAD * -16.5;
    P->es = 0.;
    P->fwd = bertin1953_s_forward;
    P->inv = NULL;
    return P;
}

/* ---------------- calcofi ---------------- */
#define CF_DEG_TO_LINE 5
#define CF_DEG_TO_STATION 15
#define CF_LINE_TO_RAD 0.0034906585
#define CF_STATION_TO_RAD 0.0011635528
#define CF_PT_O_LINE 80
#define CF_PT_O_STATION 60
#define CF_PT_O_LAMBDA -2.1144663887
#define CF_PT_O_PHI 0.59602993
#define CF_ROTATION_ANGLE 0.52359878
static PJ_XY calcofi_e_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    double oy, l1, l2, ry;
    lp.lam += P->lam0;
    if (fabs(fabs(lp.phi) - M_HALFPI) <= EPS10) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return xy;
    }
    xy.x = lp.lam;
    xy.y = -log(pj_tsfn(lp.phi, sin(lp.phi), P->e));
    oy = -log(pj_tsfn(CF_PT_O_PHI, sin(CF_PT_O_PHI), P->e));
    l1 = (xy.y - oy) * tan(CF_ROTATION_ANGLE);
    l2 = -xy.x - l1 + CF_PT_O_LAMBDA;
    ry = l2 * cos(CF_ROTATION_ANGLE) * sin(CF_ROTATION_ANGLE) + xy.y;
    ry = pj_phi2(exp(-ry), P->e);
    xy.x = CF_PT_O_LINE - RAD_TO_DEG * (ry - CF_PT_O_PHI) * CF_DEG_TO_LINE / cos(CF_ROTATION_ANGLE);
    xy.y = CF_PT_O_STATION + RAD_TO_DEG * (ry - lp.phi) * CF_DEG_TO_STATION / sin(CF_ROTATION_ANGLE);
    return xy;
}
static PJ_XY calcofi_s_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    double oy, l1, l2, ry;
    lp.lam += P->lam0;
    if (fabs(fabs(lp.phi) - M_HALFPI) <= EPS10) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return xy;
    }
    xy.x = lp.lam;
    xy.y = log(tan(M_FORTPI + .5 * lp.phi));
    oy = log(tan(M_FORTPI + .5 * CF_PT_O_PHI));
    l1 = (xy.y - oy) * tan(CF_ROTATION_ANGLE);
    l2 = -xy.x - l1 + CF_PT_O_LAMBDA;
    ry = l2 * cos(CF_ROTATION_ANGLE) * sin(CF_ROTATION_ANGLE) + xy.y;
    ry = M_HALFPI - 2. * atan(exp(-ry));
    xy.x = CF_PT_O_LINE - RAD_TO_DEG * (ry - CF_PT_O_PHI) * CF_DEG_TO_LINE / cos(CF_ROTATION_ANGLE);
    xy.y = CF_PT_O_STATION + RAD_TO_DEG * (ry - lp.phi) * CF_DEG_TO_STATION / sin(CF_ROTATION_ANGLE);
    return xy;
}
static PJ_LP calcofi_e_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
