    xy.x /= P->ra;
    xy.y /= P->ra;
    ry = CF_PT_O_PHI - CF_LINE_TO_RAD * (xy.x - CF_PT_O_LINE) * cos(CF_ROTATION_ANGLE);
    lp.phi = ry - CF_STATION_TO_RAD * (xy.y - CF_PT_O_STATION) * sin(CF_ROTATION_ANGLE);
    oymctr = -log(pj_tsfn(CF_PT_O_PHI, sin(CF_PT_O_PHI), P->e));
    rymctr = -log(pj_tsfn(ry, sin(ry), P->e));
    xymctr = -log(pj_tsfn(lp.phi, sin(lp.phi), P->e));
    l1 = (xymctr - oymctr) * tan(CF_ROTATION_ANGLE);
    l2 = (rymctr - xymctr) / (cos(CF_ROTATION_ANGLE) * sin(CF_ROTATION_ANGLE));
    lp.lam = CF_PT_O_LAMBDA - (l1 + l2);
    lp.lam -= P->lam0;
    return lp;
}
static PJ_LP calcofi_s_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    double ry, oymctr, rymctr, xymctr, l1, l2;
    xy.x /= P->ra;
    xy.y /= P->ra;
    ry = CF_PT_O_PHI - CF_LINE_TO_RAD * (xy.x - CF_PT_O_LINE) * cos(CF_ROTATION_ANGLE);
    lp.phi = ry - CF_STATION_TO_RAD * (xy.y - CF_PT_O_STATION) * sin(CF_ROTATION_ANGLE);
    oymctr = log(tan(M_FORTPI + .5 * CF_PT_O_PHI));
    rymctr = log(tan(M_FORTPI + .5 * ry));
    xymctr = log(tan(M_FORTPI + .5 * lp.phi));
    l1 = (xymctr - oymctr) * tan(CF_ROTATION_ANGLE);
    l2 = (rymctr - xymctr) / (cos(CF_ROTATION_ANGLE) * sin(CF_ROTATION_ANGLE));
    lp.lam = CF_PT_O_LAMBDA - (l1 + l2);
    lp.lam -= P->lam0;
    return lp;
}
PJ *pj_calcofi_setup(PJ *P) {
    P->lam0 = 0;
    P->ra = 1;
    P->a = 1;
    P->x0 = 0;
    P->y0 = 0;
    P->over = 1;
    if (P->es != 0.0) {
        P->inv = calcofi_e_inverse;
        P->fwd = calcofi_e_forward;
    } else {
        P->inv = calcofi_s_inverse;
        P->fwd = calcofi_s_forward;
    }
    return P;
}

/* ---------------- col_urban ---------------- */
struct col_urban_data { double h0, rho0, A, B, C, D; };
static PJ_XY col_urban_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy;
    struct col_urban_data *Q = (struct col_urban_data *)P->opaque;
    const double cosphi = cos(lp.phi);
    const double sinphi = sin(lp.phi);
    const double nu = 1. / sqrt(1 - P->es * sinphi * sinphi);
    const double lam_nu_cosphi = lp.lam * nu * cosphi;
    const double sinphi_m = sin(0.5 * (lp.phi + P->phi0));
    const double rho_m = (1 - P->es) / pow(1 - P->es * sinphi_m * sinphi_m, 1.5);
    const double G = 1 + Q->h0 / rho_m;
    xy.x = Q->A * lam_nu_cosphi;
    xy.y = G * Q->rho0 * ((lp.phi - P->phi0) + Q->B * lam_nu_cosphi * lam_nu_cosphi);
    return xy;
}
static PJ_LP col_urban_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp;
    struct col_urban_data *Q = (struct col_urban_data *)P->opaque;
    double sinphi, nu;
    lp.phi = P->phi0 + xy.y / Q->D - Q->B * (xy.x / Q->C) * (xy.x / Q->C);
    sinphi = sin(lp.phi);
    nu = 1. / sqrt(1 - P->es * sinphi * sinphi);
    lp.lam = xy.x / (Q->C * nu * cos(lp.phi));
