        if (testy > fmin(p1[1], p2[1]) && testy <= fmax(p1[1], p2[1]) && testx <= fmax(p1[0], p2[0]) && p1[1] != p2[1]) {
            xinters = (testy - p1[1]) * (p2[0] - p1[0]) / (p2[1] - p1[1]) + p1[0];
