                         {-M_HALFPI, -M_FORTPI - HP_EPS}, {-3 * M_FORTPI, -M_HALFPI - HP_EPS}, {-M_PI - HP_EPS, -M_FORTPI}};
        return pnpoly(18, v, x, y);
    } else {
