        xy.y = 3 * M_PI / 8 * sin(phi);
    } else {
        double lamc, sigma = sqrt(3 * (1 - fabs(sin(phi))));
        double cn = floor(2 * lam / M_PI + 2);
        if (cn >= 4) cn = 3;
        lamc = -3 * M_FORTPI + M_HALFPI * cn;
        xy.x = lamc + (lam - lamc) * sigma;
        xy.y = pj_sign(phi) * M_FORTPI * (2 - sigma);
    }
    return xy;
}
static PJ_LP healpix_sphere_inverse(PJ_XY xy) {
    double x = xy.x, y = xy.y, y0 = M_FORTPI;
    PJ_LP lp;
    if (fabs(y) <= y0) {
        lp.lam = x;
        lp.phi = asin(8 * y / (3 * M_PI));
    } else if (fabs(y) < M_HALFPI) {
        double cn = floor(2 * x / M_PI + 2), xc, tau;
        if (cn >= 4) cn = 3;
        xc = -3 * M_FORTPI + M_HALFPI * cn;
        tau = 2.0 - 4 * fabs(y) / M_PI;
        lp.lam = xc + (x - xc) / tau;
        lp.phi = pj_sign(y) * asin(1.0 - pow(tau, 2) / 3.0);
    } else {
        lp.lam = -M_PI;
        lp.phi = pj_sign(y) * M_HALFPI;
    }
    return lp;
}
static HP_CapMap hp_get_cap(double x, double y, int north_square, int south_square, int inverse) {
    HP_CapMap capmap;
    double c;
    capmap.x = x;
    capmap.y = y;
    if (inverse == 0) {
        if (y > M_FORTPI) {
            capmap.region = HP_NORTH;
            c = M_HALFPI;
        } else if (y < -M_FORTPI) {
            capmap.region = HP_SOUTH;
            c = -M_HALFPI;
        } else {
            capmap.region = HP_EQUATORIAL;
            capmap.cn = 0;
            return capmap;
        }
        if (x < -M_HALFPI) {
            capmap.cn = 0;
            capmap.x = (-3 * M_FORTPI);
            capmap.y = c;
        } else if (x >= -M_HALFPI && x < 0) {
            capmap.cn = 1;
            capmap.x = -M_FORTPI;
            capmap.y = c;
        } else if (x >= 0 && x < M_HALFPI) {
            capmap.cn = 2;
            capmap.x = M_FORTPI;
            capmap.y = c;
        } else {
            capmap.cn = 3;
            capmap.x = 3 * M_FORTPI;
            capmap.y = c;
        }
    } else {
        if (y > M_FORTPI) {
            capmap.region = HP_NORTH;
            capmap.x = -3 * M_FORTPI + north_square * M_HALFPI;
            capmap.y = M_PI / 2;
            x = x - north_square * M_HALFPI;
        } else if (y < -M_FORTPI) {
            capmap.region = HP_SOUTH;
            capmap.x = -3 * M_FORTPI + south_square * M_HALFPI;
            capmap.y = -M_PI / 2;
            x = x - south_square * M_HALFPI;
        } else {
            capmap.region = HP_EQUATORIAL;
            capmap.cn = 0;
            return capmap;
        }
        if (capmap.region == HP_NORTH) {
            if (y >= -x - M_FORTPI - HP_EPS && y < x + 5 * M_FORTPI - HP_EPS) capmap.cn = (north_square + 1) % 4;
            else if (y > -x - M_FORTPI + HP_EPS && y >= x + 5 * M_FORTPI - HP_EPS) capmap.cn = (north_square + 2) % 4;
            else if (y <= -x - M_FORTPI + HP_EPS && y > x + 5 * M_FORTPI + HP_EPS) capmap.cn = (north_square + 3) % 4;
            else capmap.cn = north_square;
        } else {
            if (y <= x + M_FORTPI + HP_EPS && y > -x - 5 * M_FORTPI + HP_EPS) capmap.cn = (south_square + 1) % 4;
            else if (y < x + M_FORTPI - HP_EPS && y <= -x - 5 * M_FORTPI + HP_EPS) capmap.cn = (south_square + 2) % 4;
            else if (y >= x + M_FORTPI - HP_EPS && y < -x - 5 * M_FORTPI - HP_EPS) capmap.cn = (south_square + 3) % 4;
            else capmap.cn = south_square;
        }
    }
    return capmap;
}
static int hp_get_rotate_index(int index) {
    switch (index) {
    case 0: return 0;
    case 1: return 1;
    case 2: return 2;
    case 3: return 3;
    case -1: return 3;
    case -2: return 2;
    case -3: return 1;
    }
    return 0;
}
static PJ_XY hp_combine_caps(double x, double y, int north_square, int south_square, int inverse) {
    PJ_XY xy;
    double v[2], c[2], aa[2], v_min_c[2], ret_dot[2], vector[2];
    const double (*tmpRot)[2];
    HP_CapMap capmap = hp_get_cap(x, y, north_square, south_square, inverse);
    if (capmap.region == HP_EQUATORIAL) {
        xy.x = capmap.x;
        xy.y = capmap.y;
        return xy;
    }
    v[0] = x; v[1] = y;
    c[0] = capmap.x; c[1] = capmap.y;
    if (inverse == 0) {
        if (capmap.region == HP_NORTH) {
            int pole = north_square;
            tmpRot = hp_rot[hp_get_rotate_index(capmap.cn - pole)];
            aa[0] = -3 * M_FORTPI + pole * M_HALFPI;
            aa[1] = M_HALFPI;
        } else {
            int pole = south_square;
            tmpRot = hp_rot[hp_get_rotate_index(-1 * (capmap.cn - pole))];
            aa[0] = -3 * M_FORTPI + pole * M_HALFPI;
            aa[1] = -M_HALFPI;
        }
    } else {
        if (capmap.region == HP_NORTH) {
            int pole = north_square;
            tmpRot = hp_rot[hp_get_rotate_index(-1 * (capmap.cn - pole))];
            aa[0] = -3 * M_FORTPI + capmap.cn * M_HALFPI;
            aa[1] = M_HALFPI;
        } else {
            int pole = south_square;
            tmpRot = hp_rot[hp_get_rotate_index(capmap.cn - pole)];
            aa[0] = -3 * M_FORTPI + capmap.cn * M_HALFPI;
            aa[1] = -M_HALFPI;
        }
    }
    v_min_c[0] = v[0] - c[0];
    v_min_c[1] = v[1] - c[1];
    ret_dot[0] = tmpRot[0][0] * v_min_c[0] + tmpRot[0][1] * v_min_c[1];
    ret_dot[1] = tmpRot[1][0] * v_min_c[0] + tmpRot[1][1] * v_min_c[1];
    vector[0] = ret_dot[0] + aa[0];
    vector[1] = ret_dot[1] + aa[1];
    xy.x = vector[0];
    xy.y = vector[1];
    return xy;
}
static PJ_XY hp_rotate(PJ_XY xy, double angle) {
    PJ_XY r;
    double c = cos(angle), s = sin(angle);
    r.x = xy.x * c - xy.y * s;
    r.y = xy.x * s + xy.y * c;
    return r;
}
static PJ_XY healpix_s_forward(PJ_LP lp, PJ *P) {
    struct healpix_data *Q = (struct healpix_data *)P->opaque;
    PJ_XY xy = healpix_sphere(lp);
    if (Q->rot_xy != 0.0) xy = hp_rotate(xy, Q->rot_xy);
    return xy;
}
static PJ_XY healpix_e_forward(PJ_LP lp, PJ *P) {
    struct healpix_data *Q = (struct healpix_data *)P->opaque;
    PJ_XY xy;
    lp.phi = hp_auth_lat(P, lp.phi, 0);
    xy = healpix_sphere(lp);
    if (Q->rot_xy != 0.0) xy = hp_rotate(xy, Q->rot_xy);
    return xy;
}
static PJ_LP healpix_s_inverse(PJ_XY xy, PJ *P) {
    struct healpix_data *Q = (struct healpix_data *)P->opaque;
    PJ_LP lp = {HUGE_VAL, HUGE_VAL};
    if (Q->rot_xy != 0.0) xy = hp_rotate(xy, -Q->rot_xy);
    if (hp_in_image(xy.x, xy.y, 0, 0, 0) == 0) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    return healpix_sphere_inverse(xy);
}
static PJ_LP healpix_e_inverse(PJ_XY xy, PJ *P) {
    struct healpix_data *Q = (struct healpix_data *)P->opaque;
    PJ_LP lp = {HUGE_VAL, HUGE_VAL};
    if (Q->rot_xy != 0.0) xy = hp_rotate(xy, -Q->rot_xy);
    if (hp_in_image(xy.x, xy.y, 0, 0, 0) == 0) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    lp = healpix_sphere_inverse(xy);
    lp.phi = hp_auth_lat(P, lp.phi, 1);
    return lp;
}
static PJ_XY rhealpix_s_forward(PJ_LP lp, PJ *P) {
    struct healpix_data *Q = (struct healpix_data *)P->opaque;
    PJ_XY xy = healpix_sphere(lp);
    return hp_combine_caps(xy.x, xy.y, Q->north_square, Q->south_square, 0);
}
static PJ_XY rhealpix_e_forward(PJ_LP lp, PJ *P) {
    struct healpix_data *Q = (struct healpix_data *)P->opaque;
    PJ_XY xy;
    lp.phi = hp_auth_lat(P, lp.phi, 0);
    xy = healpix_sphere(lp);
    return hp_combine_caps(xy.x, xy.y, Q->north_square, Q->south_square, 0);
}
static PJ_LP rhealpix_s_inverse(PJ_XY xy, PJ *P) {
    struct healpix_data *Q = (struct healpix_data *)P->opaque;
    PJ_LP lp = {HUGE_VAL, HUGE_VAL};
    if (hp_in_image(xy.x, xy.y, 1, Q->north_square, Q->south_square) == 0) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    xy = hp_combine_caps(xy.x, xy.y, Q->north_square, Q->south_square, 1);
    return healpix_sphere_inverse(xy);
}
static PJ_LP rhealpix_e_inverse(PJ_XY xy, PJ *P) {
    struct healpix_data *Q = (struct healpix_data *)P->opaque;
    PJ_LP lp = {HUGE_VAL, HUGE_VAL};
    if (hp_in_image(xy.x, xy.y, 1, Q->north_square, Q->south_square) == 0) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return lp;
    }
    xy = hp_combine_caps(xy.x, xy.y, Q->north_square, Q->south_square, 1);
    lp = healpix_sphere_inverse(xy);
    lp.phi = hp_auth_lat(P, lp.phi, 1);
    return lp;
}
static void healpix_destructor(PJ *P, int e) {
    if (P && P->opaque) { struct healpix_data *Q = (struct healpix_data *)P->opaque; if (Q->apa) free(Q->apa); }
    pj_default_destructor(P, e);
}
PJ *pj_healpix_setup(PJ *P) {
    struct healpix_data *Q = (struct healpix_data *)calloc(1, sizeof(struct healpix_data));
    P->opaque = Q;
    P->destructor = healpix_destructor;
    Q->rot_xy = pj_param(P->params, "drot_xy").f * DEG_TO_RAD;
    if (P->es != 0.0) {
        Q->apa = pj_authset(P->es);
        if (!Q->apa) return pj_default_destructor(P, PROJ_ERR_OTHER);
        Q->qp = pj_qsfn(1.0, P->e, P->one_es);
        P->a = P->a * sqrt(0.5 * Q->qp);
        P->ra = 1.0 / P->a;
        P->fwd = healpix_e_forward;
        P->inv = healpix_e_inverse;
    } else {
        P->fwd = healpix_s_forward;
        P->inv = healpix_s_inverse;
    }
    return P;
}
PJ *pj_rhealpix_setup(PJ *P) {
    struct healpix_data *Q = (struct healpix_data *)calloc(1, sizeof(struct healpix_data));
    P->opaque = Q;
    P->destructor = healpix_destructor;
    Q->north_square = pj_param(P->params, "inorth_square").i;
    Q->south_square = pj_param(P->params, "isouth_square").i;
    if (Q->north_square < 0 || Q->north_square > 3) {
        proj_log_error(P, "Invalid value for north_square: it should be in [0,3] range");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    if (Q->south_square < 0 || Q->south_square > 3) {
        proj_log_error(P, "Invalid value for south_square: it should be in [0,3] range");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
    }
    if (P->es != 0.0) {
        Q->apa = pj_authset(P->es);
        if (!Q->apa) return pj_default_destructor(P, PROJ_ERR_OTHER);
        Q->qp = pj_qsfn(1.0, P->e, P->one_es);
        P->a = P->a * sqrt(0.5 * Q->qp);
        P->ra = 1.0 / P->a;
        P->fwd = rhealpix_e_forward;
        P->inv = rhealpix_e_inverse;
    } else {
        P->fwd = rhealpix_s_forward;
        P->inv = rhealpix_s_inverse;
    }
    return P;
}

/* ---------------- s2 ---------------- */
enum s2_face { S2_FRONT = 0, S2_RIGHT = 1, S2_BACK = 2, S2_LEFT = 3, S2_TOP = 4, S2_BOTTOM = 5 };
enum s2_uvst { S2_LINEAR, S2_QUADRATIC, S2_TAN };
struct s2_data { enum s2_face face; enum s2_uvst mode; double a_squared, b, one_minus_f, one_minus_f_squared; };
static double s2_uv_to_st(double u, enum s2_uvst m) {
    switch (m) {
    case S2_LINEAR: return 0.5 * (u + 1);
    case S2_TAN: return (2 * M_1_PI) * (atan(u) + M_PI_4);
    default: return u >= 0 ? 0.5 * sqrt(1 + 3 * u) : 1 - 0.5 * sqrt(1 - 3 * u);
    }
}
static double s2_st_to_uv(double s, enum s2_uvst m) {
    switch (m) {
    case S2_LINEAR: return 2 * s - 1;
    case S2_TAN: return tan(M_PI_2 * s - M_PI_4);
    default: return s >= 0.5 ? (1 / 3.) * (4 * s * s - 1) : (1 / 3.) * (1 - 4 * (1 - s) * (1 - s));
    }
}
static PJ_XY s2_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct s2_data *Q = (struct s2_data *)P->opaque;
    double lat, lon, x, y, z, u, v;
    if (P->es != 0.0)
        lat = atan(Q->one_minus_f_squared * tan(lp.phi));
    else
        lat = lp.phi;
    lon = lp.lam;
    /* undo central meridian shift to work with absolute direction */
    if (Q->face == S2_RIGHT) lon += M_HALFPI;
    else if (Q->face == S2_BACK) lon += M_PI;
    else if (Q->face == S2_LEFT) lon -= M_HALFPI;
    x = cos(lat) * cos(lon);
    y = cos(lat) * sin(lon);
    z = sin(lat);
    switch (Q->face) {
    case S2_FRONT: u = y / x; v = z / x; break;
    case S2_RIGHT: u = -x / y; v = z / y; break;
    case S2_TOP: u = -x / z; v = -y / z; break;
    case S2_BACK: u = z / x; v = y / x; break;
    case S2_LEFT: u = z / y; v = -x / y; break;
    default: u = -y / z; v = -x / z; break;
    }
    xy.x = s2_uv_to_st(u, Q->mode);
    xy.y = s2_uv_to_st(v, Q->mode);
    return xy;
}
static PJ_LP s2_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct s2_data *Q = (struct s2_data *)P->opaque;
    double u = s2_st_to_uv(xy.x, Q->mode), v = s2_st_to_uv(xy.y, Q->mode), x, y, z;
    switch (Q->face) {
    case S2_FRONT: x = 1; y = u; z = v; break;
    case S2_RIGHT: x = -u; y = 1; z = v; break;
    case S2_TOP: x = -u; y = -v; z = 1; break;
    case S2_BACK: x = -1; y = -v; z = -u; break;
    case S2_LEFT: x = v; y = -1; z = -u; break;
    default: x = v; y = u; z = -1; break;
    }
    lp.lam = atan2(y, x);
    lp.phi = atan2(z, hypot(x, y));
    if (Q->face == S2_RIGHT) lp.lam -= M_HALFPI;
    else if (Q->face == S2_BACK) lp.lam -= M_PI;
    else if (Q->face == S2_LEFT) lp.lam += M_HALFPI;
    if (P->es != 0.0) lp.phi = atan(tan(lp.phi) / Q->one_minus_f_squared);
    return lp;
}
PJ *pj_s2_setup(PJ *P) {
    const char *s;
    struct s2_data *Q = (struct s2_data *)calloc(1, sizeof(struct s2_data));
    P->opaque = Q;
    P->inv = s2_inverse;
    P->fwd = s2_forward;
    P->right = PJ_IO_UNITS_PROJECTED;
    if (P->phi0 >= M_HALFPI - M_FORTPI / 2.0) Q->face = S2_TOP;
    else if (P->phi0 <= -(M_HALFPI - M_FORTPI / 2.0)) Q->face = S2_BOTTOM;
    else if (fabs(P->lam0) <= M_FORTPI) Q->face = S2_FRONT;
    else if (fabs(P->lam0) <= M_HALFPI + M_FORTPI) Q->face = (P->lam0 > 0.0 ? S2_RIGHT : S2_LEFT);
    else Q->face = S2_BACK;
    s = pj_param(P->params, "sUVtoST").s;
    Q->mode = S2_QUADRATIC;
    if (s) {
        if (!strcmp(s, "linear")) Q->mode = S2_LINEAR;
        else if (!strcmp(s, "quadratic")) Q->mode = S2_QUADRATIC;
        else if (!strcmp(s, "tangent")) Q->mode = S2_TAN;
        else {
            proj_log_error(P, "Invalid value for UVtoST: it should be linear, quadratic or tangent");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    }
    if (P->es != 0.0) {
        Q->a_squared = P->a * P->a;
        Q->b = P->a * sqrt(1.0 - P->es);
        Q->one_minus_f = 1.0 - (P->a - Q->b) / P->a;
        Q->one_minus_f_squared = Q->one_minus_f * Q->one_minus_f;
    }
    return P;
}
