/* ---------------- s2 ---------------- */
enum s2_face { S2_FRONT = 0, S2_RIGHT = 1, S2_BACK = 2, S2_LEFT = 3, S2_TOP = 4, S2_BOTTOM = 5 };
enum s2_uvst { S2_LINEAR, S2_QUADRATIC, S2_TAN };
struct s2_data { enum s2_face face; enum s2_uvst mode; double a_squared, b, one_minus_f, one_minus_f_squared; };
static double s2_uv_to_st(double u, enum s2_uvst m) {
    switch (m) {
    case S2_LINEAR: return 0.5 * (u + 1);
    case S2_TAN: return (2 * M_1_PI) * (atan(u) + M_PI_4);
    default: return u >= 0 ? 0.5 * sqrt(1 + 3 * u) : 1 - 0.5 * sqrt(1 - 3 * u);
    }
}
static double s2_st_to_uv(double s, enum s2_uvst m) {
    switch (m) {
    case S2_LINEAR: return 2 * s - 1;
    case S2_TAN: return tan(M_PI_2 * s - M_PI_4);
    default: return s >= 0.5 ? (1 / 3.) * (4 * s * s - 1) : (1 / 3.) * (1 - 4 * (1 - s) * (1 - s));
    }
}
static PJ_XY s2_forward(PJ_LP lp, PJ *P) {
    PJ_XY xy = {0.0, 0.0};
    struct s2_data *Q = (struct s2_data *)P->opaque;
    double lat, lon, x, y, z, u, v;
    if (P->es != 0.0)
        lat = atan(Q->one_minus_f_squared * tan(lp.phi));
    else
        lat = lp.phi;
    lon = lp.lam;
    /* undo central meridian shift to work with absolute direction */
    if (Q->face == S2_RIGHT) lon += M_HALFPI;
    else if (Q->face == S2_BACK) lon += M_PI;
    else if (Q->face == S2_LEFT) lon -= M_HALFPI;
    x = cos(lat) * cos(lon);
    y = cos(lat) * sin(lon);
    z = sin(lat);
    switch (Q->face) {
    case S2_FRONT: u = y / x; v = z / x; break;
    case S2_RIGHT: u = -x / y; v = z / y; break;
    case S2_TOP: u = -x / z; v = -y / z; break;
    case S2_BACK: u = z / x; v = y / x; break;
    case S2_LEFT: u = z / y; v = -x / y; break;
    default: u = -y / z; v = -x / z; break;
    }
    xy.x = s2_uv_to_st(u, Q->mode);
    xy.y = s2_uv_to_st(v, Q->mode);
    return xy;
}
static PJ_LP s2_inverse(PJ_XY xy, PJ *P) {
    PJ_LP lp = {0.0, 0.0};
    struct s2_data *Q = (struct s2_data *)P->opaque;
    double u = s2_st_to_uv(xy.x, Q->mode), v = s2_st_to_uv(xy.y, Q->mode), x, y, z;
    switch (Q->face) {
    case S2_FRONT: x = 1; y = u; z = v; break;
    case S2_RIGHT: x = -u; y = 1; z = v; break;
    case S2_TOP: x = -u; y = -v; z = 1; break;
    case S2_BACK: x = -1; y = -v; z = -u; break;
    case S2_LEFT: x = v; y = -1; z = -u; break;
    default: x = v; y = u; z = -1; break;
    }
    lp.lam = atan2(y, x);
    lp.phi = atan2(z, hypot(x, y));
    if (Q->face == S2_RIGHT) lp.lam -= M_HALFPI;
    else if (Q->face == S2_BACK) lp.lam -= M_PI;
    else if (Q->face == S2_LEFT) lp.lam += M_HALFPI;
    if (P->es != 0.0) lp.phi = atan(tan(lp.phi) / Q->one_minus_f_squared);
    return lp;
}
PJ *pj_s2_setup(PJ *P) {
    const char *s;
    struct s2_data *Q = (struct s2_data *)calloc(1, sizeof(struct s2_data));
    P->opaque = Q;
    P->inv = s2_inverse;
    P->fwd = s2_forward;
    P->right = PJ_IO_UNITS_PROJECTED;
    if (P->phi0 >= M_HALFPI - M_FORTPI / 2.0) Q->face = S2_TOP;
    else if (P->phi0 <= -(M_HALFPI - M_FORTPI / 2.0)) Q->face = S2_BOTTOM;
    else if (fabs(P->lam0) <= M_FORTPI) Q->face = S2_FRONT;
    else if (fabs(P->lam0) <= M_HALFPI + M_FORTPI) Q->face = (P->lam0 > 0.0 ? S2_RIGHT : S2_LEFT);
    else Q->face = S2_BACK;
    s = pj_param(P->params, "sUVtoST").s;
    Q->mode = S2_QUADRATIC;
    if (s) {
        if (!strcmp(s, "linear")) Q->mode = S2_LINEAR;
        else if (!strcmp(s, "quadratic")) Q->mode = S2_QUADRATIC;
        else if (!strcmp(s, "tangent")) Q->mode = S2_TAN;
        else {
            proj_log_error(P, "Invalid value for UVtoST: it should be linear, quadratic or tangent");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    }
    if (P->es != 0.0) {
        Q->a_squared = P->a * P->a;
        Q->b = P->a * sqrt(1.0 - P->es);
        Q->one_minus_f = 1.0 - (P->a - Q->b) / P->a;
        Q->one_minus_f_squared = Q->one_minus_f * Q->one_minus_f;
    }
    return P;
}
