    o.xyz.y = scale * (Q->R[1][0] * x + Q->R[1][1] * y + Q->R[1][2] * z) + Q->y + Q->py;
    o.xyz.z = scale * (Q->R[2][0] * x + Q->R[2][1] * y + Q->R[2][2] * z) + Q->z + Q->pz;
