/* ---------------- molodensky ---------------- */
struct molodensky_data { double dx, dy, dz, da, df; int abridged; };
static PJ_COORD molodensky_forward(PJ_COORD c, PJ *P) {
    struct molodensky_data *Q = (struct molodensky_data *)P->opaque;
    double lam = c.lpz.lam, phi = c.lpz.phi, h = c.lpz.z;
    double sphi = sin(phi), cphi = cos(phi), slam = sin(lam), clam = cos(lam);
