        dphi = (-Q->dx * sphi * clam - Q->dy * sphi * slam + Q->dz * cphi + (a * Q->df + f * Q->da) * sin(2 * phi)) / M;
        dlam = (-Q->dx * slam + Q->dy * clam) / (N * cphi);
        dh = Q->dx * cphi * clam + Q->dy * cphi * slam + Q->dz * sphi + (a * Q->df + f * Q->da) * sphi * sphi - Q->da;
        (void)adb;
    } else {
        dphi = (-Q->dx * sphi * clam - Q->dy * sphi * slam + Q->dz * cphi + Q->da * N * es * sphi * cphi / a +
                Q->df * (M * a / b + N * b / a) * sphi * cphi) / (M + h);
        dlam = (-Q->dx * slam + Q->dy * clam) / ((N + h) * cphi);
        dh = Q->dx * cphi * clam + Q->dy * cphi * slam + Q->dz * sphi - Q->da * a / N + Q->df * b / a * N * sphi * sphi;
    }
    c.lpz.lam += dlam;
    c.lpz.phi += dphi;
    c.lpz.z += dh;
    return c;
}
static PJ_COORD molodensky_reverse(PJ_COORD c, PJ *P) {
    struct molodensky_data *Q = (struct molodensky_data *)P->opaque;
    PJ_COORD t = c, r;
    Q->dx = -Q->dx; Q->dy = -Q->dy; Q->dz = -Q->dz; Q->da = -Q->da; Q->df = -Q->df;
    r = molodensky_forward(t, P);
    Q->dx = -Q->dx; Q->dy = -Q->dy; Q->dz = -Q->dz; Q->da = -Q->da; Q->df = -Q->df;
    return r;
}
PJ *pj_molodensky_setup(PJ *P) {
    struct molodensky_data *Q = (struct molodensky_data *)calloc(1, sizeof(struct molodensky_data));
    P->opaque = Q;
    P->fwd4d = molodensky_forward;
    P->inv4d = molodensky_reverse;
    P->left = PJ_IO_UNITS_RADIANS;
    P->right = PJ_IO_UNITS_RADIANS;
    if (!pj_param_exists(P->params, "dx")) {
        proj_log_error(P, "missing dx");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    if (!pj_param_exists(P->params, "dy")) {
        proj_log_error(P, "missing dy");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    if (!pj_param_exists(P->params, "dz")) {
        proj_log_error(P, "missing dz");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    if (!pj_param_exists(P->params, "da")) {
        proj_log_error(P, "missing da");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    if (!pj_param_exists(P->params, "df")) {
        proj_log_error(P, "missing df");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    Q->dx = pj_param(P->params, "ddx").f;
    Q->dy = pj_param(P->params, "ddy").f;
    Q->dz = pj_param(P->params, "ddz").f;
    Q->da = pj_param(P->params, "dda").f;
    Q->df = pj_param(P->params, "ddf").f;
    Q->abridged = pj_param(P->params, "babridged").i;
    return P;
}

