/* ---------------- push / pop / set ---------------- */
static double pj_stack[4][64];
static int pj_stack_n[4];
struct push_data { int v[4]; };
static PJ_COORD push_forward(PJ_COORD c, PJ *P) {
    struct push_data *Q = (struct push_data *)P->opaque;
    int i;
    for (i = 0; i < 4; ++i)
        if (Q->v[i] && pj_stack_n[i] < 64) pj_stack[i][pj_stack_n[i]++] = c.v[i];
    return c;
}
static PJ_COORD pop_forward(PJ_COORD c, PJ *P) {
    struct push_data *Q = (struct push_data *)P->opaque;
    int i;
    for (i = 0; i < 4; ++i)
        if (Q->v[i] && pj_stack_n[i] > 0) c.v[i] = pj_stack[i][--pj_stack_n[i]];
    return c;
}
static PJ *push_pop_common(PJ *P, int is_push) {
    struct push_data *Q = (struct push_data *)calloc(1, sizeof(struct push_data));
    P->opaque = Q;
    Q->v[0] = pj_param_exists(P->params, "v_1");
    Q->v[1] = pj_param_exists(P->params, "v_2");
    Q->v[2] = pj_param_exists(P->params, "v_3");
    Q->v[3] = pj_param_exists(P->params, "v_4");
    (void)pj_param(P->params, "tv_1"); (void)pj_param(P->params, "tv_2");
    (void)pj_param(P->params, "tv_3"); (void)pj_param(P->params, "tv_4");
    P->left = PJ_IO_UNITS_WHATEVER;
    P->right = PJ_IO_UNITS_WHATEVER;
    if (is_push) {
        P->fwd4d = push_forward;
        P->inv4d = pop_forward;
    } else {
        P->fwd4d = pop_forward;
        P->inv4d = push_forward;
    }
    return P;
}
PJ *pj_push_setup(PJ *P) { return push_pop_common(P, 1); }
PJ *pj_pop_setup(PJ *P) { return push_pop_common(P, 0); }

struct set_data { int set[4]; double val[4]; };
static PJ_COORD set_op(PJ_COORD c, PJ *P) {
    struct set_data *Q = (struct set_data *)P->opaque;
    int i;
    for (i = 0; i < 4; ++i)
        if (Q->set[i]) c.v[i] = Q->val[i];
    return c;
}
PJ *pj_set_setup(PJ *P) {
    struct set_data *Q = (struct set_data *)calloc(1, sizeof(struct set_data));
    const char *keys[4] = {"v_1", "v_2", "v_3", "v_4"};
    int i;
    P->opaque = Q;
    for (i = 0; i < 4; ++i) {
        if (pj_param_exists(P->params, keys[i])) {
            char k[8];
            Q->set[i] = 1;
            sprintf(k, "d%s", keys[i]);
            Q->val[i] = pj_param(P->params, k).f;
        }
    }
    P->fwd4d = set_op;
    P->inv4d = set_op;
    P->left = PJ_IO_UNITS_WHATEVER;
    P->right = PJ_IO_UNITS_WHATEVER;
    return P;
}

