/* Non-projection operations: affine, geogoffset, helmert, molodensky, horner, vertoffset, push/pop/set, grid ops, topocentric, sch, ob_tran */
#include "proj.h"

/* ---------------- affine ---------------- */
struct affine_data { double xoff, yoff, zoff, toff, s11, s12, s13, s21, s22, s23, s31, s32, s33, tscale; int inverted; };
static PJ_COORD affine_forward_4d(PJ_COORD c, PJ *P) {
    struct affine_data *Q = (struct affine_data *)P->opaque;
    PJ_COORD o;
    o.v[0] = Q->xoff + Q->s11 * c.v[0] + Q->s12 * c.v[1] + Q->s13 * c.v[2];
    o.v[1] = Q->yoff + Q->s21 * c.v[0] + Q->s22 * c.v[1] + Q->s23 * c.v[2];
    o.v[2] = Q->zoff + Q->s31 * c.v[0] + Q->s32 * c.v[1] + Q->s33 * c.v[2];
    o.v[3] = Q->toff + Q->tscale * c.v[3];
    return o;
}
static PJ_COORD affine_reverse_4d(PJ_COORD c, PJ *P) {
    struct affine_data *Q = (struct affine_data *)P->opaque;
    PJ_COORD o;
    double x = c.v[0] - Q->xoff, y = c.v[1] - Q->yoff, z = c.v[2] - Q->zoff;
    double det = Q->s11 * (Q->s22 * Q->s33 - Q->s23 * Q->s32) - Q->s12 * (Q->s21 * Q->s33 - Q->s23 * Q->s31) +
                 Q->s13 * (Q->s21 * Q->s32 - Q->s22 * Q->s31);
    if (det == 0) {
        proj_errno_set(P, PROJ_ERR_COORD_TRANSFM_OUTSIDE_PROJECTION_DOMAIN);
        return proj_coord_error();
    }
    o.v[0] = ((Q->s22 * Q->s33 - Q->s23 * Q->s32) * x - (Q->s12 * Q->s33 - Q->s13 * Q->s32) * y + (Q->s12 * Q->s23 - Q->s13 * Q->s22) * z) / det;
    o.v[1] = (-(Q->s21 * Q->s33 - Q->s23 * Q->s31) * x + (Q->s11 * Q->s33 - Q->s13 * Q->s31) * y - (Q->s11 * Q->s23 - Q->s13 * Q->s21) * z) / det;
    o.v[2] = ((Q->s21 * Q->s32 - Q->s22 * Q->s31) * x - (Q->s11 * Q->s32 - Q->s12 * Q->s31) * y + (Q->s11 * Q->s22 - Q->s12 * Q->s21) * z) / det;
    o.v[3] = Q->tscale != 0 ? (c.v[3] - Q->toff) / Q->tscale : c.v[3];
    return o;
}
PJ *pj_affine_setup(PJ *P) {
    struct affine_data *Q = (struct affine_data *)calloc(1, sizeof(struct affine_data));
    P->opaque = Q;
    P->fwd4d = affine_forward_4d;
    P->inv4d = affine_reverse_4d;
    P->left = PJ_IO_UNITS_WHATEVER;
    P->right = PJ_IO_UNITS_WHATEVER;
    Q->s11 = Q->s22 = Q->s33 = Q->tscale = 1.0;
    if (pj_param_exists(P->params, "xoff")) Q->xoff = pj_param(P->params, "dxoff").f;
    if (pj_param_exists(P->params, "yoff")) Q->yoff = pj_param(P->params, "dyoff").f;
    if (pj_param_exists(P->params, "zoff")) Q->zoff = pj_param(P->params, "dzoff").f;
    if (pj_param_exists(P->params, "toff")) Q->toff = pj_param(P->params, "dtoff").f;
    if (pj_param_exists(P->params, "s11")) Q->s11 = pj_param(P->params, "ds11").f;
    if (pj_param_exists(P->params, "s12")) Q->s12 = pj_param(P->params, "ds12").f;
    if (pj_param_exists(P->params, "s13")) Q->s13 = pj_param(P->params, "ds13").f;
    if (pj_param_exists(P->params, "s21")) Q->s21 = pj_param(P->params, "ds21").f;
    if (pj_param_exists(P->params, "s22")) Q->s22 = pj_param(P->params, "ds22").f;
    if (pj_param_exists(P->params, "s23")) Q->s23 = pj_param(P->params, "ds23").f;
    if (pj_param_exists(P->params, "s31")) Q->s31 = pj_param(P->params, "ds31").f;
    if (pj_param_exists(P->params, "s32")) Q->s32 = pj_param(P->params, "ds32").f;
    if (pj_param_exists(P->params, "s33")) Q->s33 = pj_param(P->params, "ds33").f;
    if (pj_param_exists(P->params, "tscale")) Q->tscale = pj_param(P->params, "dtscale").f;
    return P;
}

/* ---------------- geogoffset ---------------- */
struct geogoffset_data { double dlon, dlat, dh; };
static PJ_COORD geogoffset_forward(PJ_COORD c, PJ *P) {
    struct geogoffset_data *Q = (struct geogoffset_data *)P->opaque;
    c.lpz.lam += Q->dlon;
    c.lpz.phi += Q->dlat;
    c.lpz.z += Q->dh;
    return c;
}
static PJ_COORD geogoffset_reverse(PJ_COORD c, PJ *P) {
    struct geogoffset_data *Q = (struct geogoffset_data *)P->opaque;
    c.lpz.lam -= Q->dlon;
    c.lpz.phi -= Q->dlat;
    c.lpz.z -= Q->dh;
    return c;
}
PJ *pj_geogoffset_setup(PJ *P) {
    struct geogoffset_data *Q = (struct geogoffset_data *)calloc(1, sizeof(struct geogoffset_data));
    P->opaque = Q;
    Q->dlon = pj_param(P->params, "ddlon").f * SEC_TO_RAD;
    Q->dlat = pj_param(P->params, "ddlat").f * SEC_TO_RAD;
    Q->dh = pj_param(P->params, "ddh").f;
    P->fwd4d = geogoffset_forward;
    P->inv4d = geogoffset_reverse;
    P->left = PJ_IO_UNITS_RADIANS;
    P->right = PJ_IO_UNITS_RADIANS;
    return P;
}

/* ---------------- vertoffset ---------------- */
struct vertoffset_data { double dh, slope_lat, slope_lon, lat0, lon0; };
static PJ_COORD vertoffset_forward(PJ_COORD c, PJ *P) {
    struct vertoffset_data *Q = (struct vertoffset_data *)P->opaque;
    c.lpz.z += Q->dh + Q->slope_lat * (c.lpz.phi - Q->lat0) + Q->slope_lon * (c.lpz.lam - Q->lon0) * cos(Q->lat0);
    return c;
}
static PJ_COORD vertoffset_reverse(PJ_COORD c, PJ *P) {
    struct vertoffset_data *Q = (struct vertoffset_data *)P->opaque;
    c.lpz.z -= Q->dh + Q->slope_lat * (c.lpz.phi - Q->lat0) + Q->slope_lon * (c.lpz.lam - Q->lon0) * cos(Q->lat0);
    return c;
}
PJ *pj_vertoffset_setup(PJ *P) {
    struct vertoffset_data *Q = (struct vertoffset_data *)calloc(1, sizeof(struct vertoffset_data));
    P->opaque = Q;
    Q->dh = pj_param(P->params, "ddh").f;
    Q->slope_lat = pj_param(P->params, "dslope_lat").f * 1e-6 * 6378137.0;
    Q->slope_lon = pj_param(P->params, "dslope_lon").f * 1e-6 * 6378137.0;
    Q->lat0 = pj_param(P->params, "rlat_0").f;
    Q->lon0 = pj_param(P->params, "rlon_0").f;
    P->lam0 = 0;
    P->phi0 = 0;
    P->fwd4d = vertoffset_forward;
    P->inv4d = vertoffset_reverse;
    P->left = PJ_IO_UNITS_RADIANS;
    P->right = PJ_IO_UNITS_RADIANS;
    return P;
}

/* ---------------- helmert / molobadekas ---------------- */
struct helmert_data { double x, y, z, rx, ry, rz, s, R[3][3]; double px, py, pz; int exact, position_vector; };
static void helmert_build_matrix(struct helmert_data *Q) {
    double f = Q->rx, g = Q->ry, h = Q->rz;
    if (Q->exact) {
        double sf = sin(f), cf = cos(f), sg = sin(g), cg = cos(g), sh = sin(h), ch = cos(h);
        Q->R[0][0] = cg * ch; Q->R[0][1] = cf * sh + sf * sg * ch; Q->R[0][2] = sf * sh - cf * sg * ch;
        Q->R[1][0] = -cg * sh; Q->R[1][1] = cf * ch - sf * sg * sh; Q->R[1][2] = sf * ch + cf * sg * sh;
        Q->R[2][0] = sg; Q->R[2][1] = -sf * cg; Q->R[2][2] = cf * cg;
    } else {
        Q->R[0][0] = 1; Q->R[0][1] = h; Q->R[0][2] = -g;
        Q->R[1][0] = -h; Q->R[1][1] = 1; Q->R[1][2] = f;
        Q->R[2][0] = g; Q->R[2][1] = -f; Q->R[2][2] = 1;
    }
    if (Q->position_vector) {
        double t;
        t = Q->R[0][1]; Q->R[0][1] = Q->R[1][0]; Q->R[1][0] = t;
        t = Q->R[0][2]; Q->R[0][2] = Q->R[2][0]; Q->R[2][0] = t;
        t = Q->R[1][2]; Q->R[1][2] = Q->R[2][1]; Q->R[2][1] = t;
    }
}
static PJ_COORD helmert_forward(PJ_COORD c, PJ *P) {
    struct helmert_data *Q = (struct helmert_data *)P->opaque;
    PJ_COORD o = c;
    double x = c.xyz.x - Q->px, y = c.xyz.y - Q->py, z = c.xyz.z - Q->pz, scale = 1 + Q->s * 1e-6;
    o.xyz.x = scale * (Q->R[0][0] * x + Q->R[0][1] * y + Q->R[0][2] * z) + Q->x + Q->px;
    o.xyz.y = scale * (Q->R[1][0] * x + Q->R[1][1] * y + Q->R[1][2] * z) + Q->y + Q->py;
    o.xyz.z = scale * (Q->R[2][0] * x + Q->R[2][1] * y + Q->R[2][2] * z) + Q->z + Q->pz;
    return o;
}
static PJ_COORD helmert_reverse(PJ_COORD c, PJ *P) {
    struct helmert_data *Q = (struct helmert_data *)P->opaque;
    PJ_COORD o = c;
    double scale = 1 + Q->s * 1e-6;
    double x = (c.xyz.x - Q->x - Q->px) / scale, y = (c.xyz.y - Q->y - Q->py) / scale, z = (c.xyz.z - Q->z - Q->pz) / scale;
    o.xyz.x = Q->R[0][0] * x + Q->R[1][0] * y + Q->R[2][0] * z + Q->px;
    o.xyz.y = Q->R[0][1] * x + Q->R[1][1] * y + Q->R[2][1] * z + Q->py;
    o.xyz.z = Q->R[0][2] * x + Q->R[1][2] * y + Q->R[2][2] * z + Q->pz;
    return o;
}
static PJ *helmert_common(PJ *P, int badekas) {
    struct helmert_data *Q = (struct helmert_data *)calloc(1, sizeof(struct helmert_data));
    const char *conv;
    int has_rot;
    P->opaque = Q;
    P->fwd4d = helmert_forward;
    P->inv4d = helmert_reverse;
    P->left = PJ_IO_UNITS_CARTESIAN;
    P->right = PJ_IO_UNITS_CARTESIAN;
    Q->x = pj_param(P->params, "dx").f;
    Q->y = pj_param(P->params, "dy").f;
    Q->z = pj_param(P->params, "dz").f;
    Q->rx = pj_param(P->params, "drx").f * SEC_TO_RAD;
    Q->ry = pj_param(P->params, "dry").f * SEC_TO_RAD;
    Q->rz = pj_param(P->params, "drz").f * SEC_TO_RAD;
    Q->s = pj_param(P->params, "ds").f;
    Q->exact = pj_param(P->params, "texact").i;
    has_rot = pj_param_exists(P->params, "rx") || pj_param_exists(P->params, "ry") || pj_param_exists(P->params, "rz");
    if (badekas) {
        Q->px = pj_param(P->params, "dpx").f;
        Q->py = pj_param(P->params, "dpy").f;
        Q->pz = pj_param(P->params, "dpz").f;
    }
    conv = pj_param(P->params, "sconvention").s;
    if (has_rot || badekas) {
        if (!conv) {
            proj_log_error(P, "helmert: missing 'convention' argument");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
        }
        if (!strcmp(conv, "position_vector")) Q->position_vector = 1;
        else if (!strcmp(conv, "coordinate_frame")) Q->position_vector = 0;
        else {
            proj_log_error(P, "helmert: invalid value for 'convention' argument");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    } else if (conv) {
        if (!strcmp(conv, "position_vector")) Q->position_vector = 1;
        else if (!strcmp(conv, "coordinate_frame")) Q->position_vector = 0;
        else {
            proj_log_error(P, "helmert: invalid value for 'convention' argument");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
    }
    helmert_build_matrix(Q);
    return P;
}
PJ *pj_helmert_setup(PJ *P) { return helmert_common(P, 0); }
PJ *pj_molobadekas_setup(PJ *P) { return helmert_common(P, 1); }

/* ---------------- molodensky ---------------- */
struct molodensky_data { double dx, dy, dz, da, df; int abridged; };
static PJ_COORD molodensky_forward(PJ_COORD c, PJ *P) {
    struct molodensky_data *Q = (struct molodensky_data *)P->opaque;
    double lam = c.lpz.lam, phi = c.lpz.phi, h = c.lpz.z;
    double sphi = sin(phi), cphi = cos(phi), slam = sin(lam), clam = cos(lam);
    double es = P->es, a = P->a, f = P->f, b = P->b;
    double t = 1 - es * sphi * sphi, N = a / sqrt(t), M = a * (1 - es) / (t * sqrt(t));
    double dlam, dphi, dh;
    if (Q->abridged) {
        double adb = a / b;
        dphi = (-Q->dx * sphi * clam - Q->dy * sphi * slam + Q->dz * cphi + (a * Q->df + f * Q->da) * sin(2 * phi)) / M;
        dlam = (-Q->dx * slam + Q->dy * clam) / (N * cphi);
        dh = Q->dx * cphi * clam + Q->dy * cphi * slam + Q->dz * sphi + (a * Q->df + f * Q->da) * sphi * sphi - Q->da;
        (void)adb;
    } else {
        dphi = (-Q->dx * sphi * clam - Q->dy * sphi * slam + Q->dz * cphi + Q->da * N * es * sphi * cphi / a +
                Q->df * (M * a / b + N * b / a) * sphi * cphi) / (M + h);
        dlam = (-Q->dx * slam + Q->dy * clam) / ((N + h) * cphi);
        dh = Q->dx * cphi * clam + Q->dy * cphi * slam + Q->dz * sphi - Q->da * a / N + Q->df * b / a * N * sphi * sphi;
    }
    c.lpz.lam += dlam;
    c.lpz.phi += dphi;
    c.lpz.z += dh;
    return c;
}
static PJ_COORD molodensky_reverse(PJ_COORD c, PJ *P) {
    struct molodensky_data *Q = (struct molodensky_data *)P->opaque;
    PJ_COORD t = c, r;
    Q->dx = -Q->dx; Q->dy = -Q->dy; Q->dz = -Q->dz; Q->da = -Q->da; Q->df = -Q->df;
    r = molodensky_forward(t, P);
    Q->dx = -Q->dx; Q->dy = -Q->dy; Q->dz = -Q->dz; Q->da = -Q->da; Q->df = -Q->df;
    return r;
}
PJ *pj_molodensky_setup(PJ *P) {
    struct molodensky_data *Q = (struct molodensky_data *)calloc(1, sizeof(struct molodensky_data));
    P->opaque = Q;
    P->fwd4d = molodensky_forward;
    P->inv4d = molodensky_reverse;
    P->left = PJ_IO_UNITS_RADIANS;
    P->right = PJ_IO_UNITS_RADIANS;
    if (!pj_param_exists(P->params, "dx")) {
        proj_log_error(P, "missing dx");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    if (!pj_param_exists(P->params, "dy")) {
        proj_log_error(P, "missing dy");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    if (!pj_param_exists(P->params, "dz")) {
        proj_log_error(P, "missing dz");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    if (!pj_param_exists(P->params, "da")) {
        proj_log_error(P, "missing da");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    if (!pj_param_exists(P->params, "df")) {
        proj_log_error(P, "missing df");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    Q->dx = pj_param(P->params, "ddx").f;
    Q->dy = pj_param(P->params, "ddy").f;
    Q->dz = pj_param(P->params, "ddz").f;
    Q->da = pj_param(P->params, "dda").f;
    Q->df = pj_param(P->params, "ddf").f;
    Q->abridged = pj_param(P->params, "babridged").i;
    return P;
}

/* ---------------- horner ---------------- */
PJ *pj_horner_setup(PJ *P) {
    P->left = PJ_IO_UNITS_PROJECTED;
    P->right = PJ_IO_UNITS_PROJECTED;
    if (!pj_param_exists(P->params, "deg")) {
        proj_log_error(P, "Must specify polynomial degree, (+deg=n)");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    proj_log_error(P, "Polynomial coefficients not available");
    return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
}

/* ---------------- push / pop / set ---------------- */
static double pj_stack[4][64];
static int pj_stack_n[4];
struct push_data { int v[4]; };
static PJ_COORD push_forward(PJ_COORD c, PJ *P) {
    struct push_data *Q = (struct push_data *)P->opaque;
    int i;
    for (i = 0; i < 4; ++i)
        if (Q->v[i] && pj_stack_n[i] < 64) pj_stack[i][pj_stack_n[i]++] = c.v[i];
    return c;
}
static PJ_COORD pop_forward(PJ_COORD c, PJ *P) {
    struct push_data *Q = (struct push_data *)P->opaque;
    int i;
    for (i = 0; i < 4; ++i)
        if (Q->v[i] && pj_stack_n[i] > 0) c.v[i] = pj_stack[i][--pj_stack_n[i]];
    return c;
}
static PJ *push_pop_common(PJ *P, int is_push) {
    struct push_data *Q = (struct push_data *)calloc(1, sizeof(struct push_data));
    P->opaque = Q;
    Q->v[0] = pj_param_exists(P->params, "v_1");
    Q->v[1] = pj_param_exists(P->params, "v_2");
    Q->v[2] = pj_param_exists(P->params, "v_3");
    Q->v[3] = pj_param_exists(P->params, "v_4");
    (void)pj_param(P->params, "tv_1"); (void)pj_param(P->params, "tv_2");
    (void)pj_param(P->params, "tv_3"); (void)pj_param(P->params, "tv_4");
    P->left = PJ_IO_UNITS_WHATEVER;
    P->right = PJ_IO_UNITS_WHATEVER;
    if (is_push) {
        P->fwd4d = push_forward;
        P->inv4d = pop_forward;
    } else {
        P->fwd4d = pop_forward;
        P->inv4d = push_forward;
    }
    return P;
}
PJ *pj_push_setup(PJ *P) { return push_pop_common(P, 1); }
PJ *pj_pop_setup(PJ *P) { return push_pop_common(P, 0); }

struct set_data { int set[4]; double val[4]; };
static PJ_COORD set_op(PJ_COORD c, PJ *P) {
    struct set_data *Q = (struct set_data *)P->opaque;
    int i;
    for (i = 0; i < 4; ++i)
        if (Q->set[i]) c.v[i] = Q->val[i];
    return c;
}
PJ *pj_set_setup(PJ *P) {
    struct set_data *Q = (struct set_data *)calloc(1, sizeof(struct set_data));
    const char *keys[4] = {"v_1", "v_2", "v_3", "v_4"};
    int i;
    P->opaque = Q;
    for (i = 0; i < 4; ++i) {
        if (pj_param_exists(P->params, keys[i])) {
            char k[8];
            Q->set[i] = 1;
            sprintf(k, "d%s", keys[i]);
            Q->val[i] = pj_param(P->params, k).f;
        }
    }
    P->fwd4d = set_op;
    P->inv4d = set_op;
    P->left = PJ_IO_UNITS_WHATEVER;
    P->right = PJ_IO_UNITS_WHATEVER;
    return P;
}

