/* ---------------- topocentric ---------------- */
struct topocentric_data { double X0, Y0, Z0, sinphi0, cosphi0, sinlam0, coslam0; };
static PJ_COORD topocentric_fwd(PJ_COORD c, PJ *P) {
    struct topocentric_data *Q = (struct topocentric_data *)P->opaque;
    PJ_COORD o = c;
    double dx = c.xyz.x - Q->X0, dy = c.xyz.y - Q->Y0, dz = c.xyz.z - Q->Z0;
    o.xyz.x = -Q->sinlam0 * dx + Q->coslam0 * dy;
    o.xyz.y = -Q->sinphi0 * Q->coslam0 * dx - Q->sinphi0 * Q->sinlam0 * dy + Q->cosphi0 * dz;
    o.xyz.z = Q->cosphi0 * Q->coslam0 * dx + Q->cosphi0 * Q->sinlam0 * dy + Q->sinphi0 * dz;
    return o;
}
static PJ_COORD topocentric_inv(PJ_COORD c, PJ *P) {
    struct topocentric_data *Q = (struct topocentric_data *)P->opaque;
    PJ_COORD o = c;
    double u = c.xyz.x, v = c.xyz.y, w = c.xyz.z;
    o.xyz.x = Q->X0 - Q->sinlam0 * u - Q->sinphi0 * Q->coslam0 * v + Q->cosphi0 * Q->coslam0 * w;
    o.xyz.y = Q->Y0 + Q->coslam0 * u - Q->sinphi0 * Q->sinlam0 * v + Q->cosphi0 * Q->sinlam0 * w;
    o.xyz.z = Q->Z0 + Q->cosphi0 * v + Q->sinphi0 * w;
    return o;
}
PJ *pj_topocentric_setup(PJ *P) {
    struct topocentric_data *Q = (struct topocentric_data *)calloc(1, sizeof(struct topocentric_data));
    double lam0, phi0;
    P->opaque = Q;
    P->left = PJ_IO_UNITS_CARTESIAN;
    P->right = PJ_IO_UNITS_CARTESIAN;
    if (pj_param_exists(P->params, "X_0")) {
        PJ_XYZ xyz;
        PJ_LPZ lpz;
        if (!pj_param_exists(P->params, "Y_0") || !pj_param_exists(P->params, "Z_0")) {
            proj_log_error(P, "missing Y_0 or Z_0");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
        }
        if (pj_param_exists(P->params, "lon_0") || pj_param_exists(P->params, "lat_0") || pj_param_exists(P->params, "h_0")) {
            proj_log_error(P, "X_0, Y_0, Z_0 and lon_0, lat_0, h_0 are mutually exclusive");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MUTUALLY_EXCLUSIVE_ARGS);
        }
        Q->X0 = pj_param(P->params, "dX_0").f;
        Q->Y0 = pj_param(P->params, "dY_0").f;
        Q->Z0 = pj_param(P->params, "dZ_0").f;
        xyz.x = Q->X0; xyz.y = Q->Y0; xyz.z = Q->Z0;
        lpz = pj_geocentric_to_geodetic(xyz, P->a, P->es);
        lam0 = lpz.lam;
        phi0 = lpz.phi;
    } else if (pj_param_exists(P->params, "lon_0")) {
        PJ_LPZ lpz;
        PJ_XYZ xyz;
        if (!pj_param_exists(P->params, "lat_0")) {
            proj_log_error(P, "missing lat_0");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
        }
        lam0 = P->lam0;
        phi0 = P->phi0;
        lpz.lam = lam0; lpz.phi = phi0; lpz.z = pj_param(P->params, "dh_0").f;
        xyz = pj_geodetic_to_geocentric(lpz, P->a, P->es);
        Q->X0 = xyz.x; Q->Y0 = xyz.y; Q->Z0 = xyz.z;
    } else {
        proj_log_error(P, "missing X_0 or lon_0");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    Q->sinphi0 = sin(phi0);
    Q->cosphi0 = cos(phi0);
    Q->sinlam0 = sin(lam0);
    Q->coslam0 = cos(lam0);
    P->lam0 = 0;
    P->phi0 = 0;
    P->fwd4d = topocentric_fwd;
    P->inv4d = topocentric_inv;
    return P;
}

/* ---------------- sch ---------------- */
struct sch_data { double plat, plon, phdg, h0, rcurv, xyzoff[3], rot[9]; };
static PJ_XYZ sch_forward3d(PJ_LPZ lpz, PJ *P) {
    struct sch_data *Q = (struct sch_data *)P->opaque;
    PJ_XYZ xyz = pj_geodetic_to_geocentric(lpz, P->a, P->es);
    double pxyz[3], x, y, z;
    PJ_LPZ loc;
    x = xyz.x - Q->xyzoff[0];
    y = xyz.y - Q->xyzoff[1];
    z = xyz.z - Q->xyzoff[2];
    pxyz[0] = Q->rot[0] * x + Q->rot[3] * y + Q->rot[6] * z;
    pxyz[1] = Q->rot[1] * x + Q->rot[4] * y + Q->rot[7] * z;
    pxyz[2] = Q->rot[2] * x + Q->rot[5] * y + Q->rot[8] * z;
    xyz.x = pxyz[0]; xyz.y = pxyz[1]; xyz.z = pxyz[2];
    loc = pj_geocentric_to_geodetic(xyz, Q->rcurv, 0.0);
    xyz.x = loc.phi * Q->rcurv / P->a;
    xyz.y = loc.lam * Q->rcurv / P->a;
    xyz.z = loc.z;
    return xyz;
}
static PJ_LPZ sch_inverse3d(PJ_XYZ xyz, PJ *P) {
    struct sch_data *Q = (struct sch_data *)P->opaque;
    PJ_LPZ loc;
    PJ_XYZ g;
    double pxyz[3];
    loc.phi = xyz.x * P->a / Q->rcurv;
    loc.lam = xyz.y * P->a / Q->rcurv;
    loc.z = xyz.z;
    g = pj_geodetic_to_geocentric(loc, Q->rcurv, 0.0);
    pxyz[0] = Q->rot[0] * g.x + Q->rot[1] * g.y + Q->rot[2] * g.z + Q->xyzoff[0];
    pxyz[1] = Q->rot[3] * g.x + Q->rot[4] * g.y + Q->rot[5] * g.z + Q->xyzoff[1];
    pxyz[2] = Q->rot[6] * g.x + Q->rot[7] * g.y + Q->rot[8] * g.z + Q->xyzoff[2];
    g.x = pxyz[0]; g.y = pxyz[1]; g.z = pxyz[2];
    return pj_geocentric_to_geodetic(g, P->a, P->es);
}
PJ *pj_sch_setup(PJ *P) {
    struct sch_data *Q = (struct sch_data *)calloc(1, sizeof(struct sch_data));
    double clt, slt, clo, slo, chdg, shdg, temp, reast, rnorth;
    PJ_LPZ peg;
    PJ_XYZ pxyz;
    P->opaque = Q;
    if (!pj_param_exists(P->params, "plat_0")) {
        proj_log_error(P, "Missing parameter plat_0.");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    if (!pj_param_exists(P->params, "plon_0")) {
        proj_log_error(P, "Missing parameter plon_0.");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    if (!pj_param_exists(P->params, "phdg_0")) {
        proj_log_error(P, "Missing parameter phdg_0.");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    Q->plat = pj_param(P->params, "rplat_0").f;
    Q->plon = pj_param(P->params, "rplon_0").f;
    Q->phdg = pj_param(P->params, "rphdg_0").f;
    Q->h0 = pj_param(P->params, "dh_0").f;
    clt = cos(Q->plat); slt = sin(Q->plat);
    clo = cos(Q->plon); slo = sin(Q->plon);
    chdg = cos(Q->phdg); shdg = sin(Q->phdg);
    temp = sqrt(1.0 - (P->es) * slt * slt);
    reast = (P->a) / temp;
    rnorth = (P->a) * (1.0 - (P->es)) / pow(temp, 3);
    Q->rcurv = Q->h0 + (reast * rnorth) / (reast * chdg * chdg + rnorth * shdg * shdg);
    Q->rot[0] = clt * clo;
    Q->rot[1] = -shdg * slo - slt * clo * chdg;
    Q->rot[2] = slo * chdg - slt * clo * shdg;
    Q->rot[3] = clt * slo;
    Q->rot[4] = clo * shdg - slt * slo * chdg;
    Q->rot[5] = -clo * chdg - slt * slo * shdg;
    Q->rot[6] = slt;
    Q->rot[7] = clt * chdg;
    Q->rot[8] = clt * shdg;
    peg.lam = Q->plon; peg.phi = Q->plat; peg.z = Q->h0;
    pxyz = pj_geodetic_to_geocentric(peg, P->a, P->es);
    Q->xyzoff[0] = pxyz.x - (Q->rcurv) * clt * clo;
    Q->xyzoff[1] = pxyz.y - (Q->rcurv) * clt * slo;
    Q->xyzoff[2] = pxyz.z - (Q->rcurv) * slt;
    P->fwd3d = sch_forward3d;
    P->inv3d = sch_inverse3d;
    P->left = PJ_IO_UNITS_RADIANS;
    P->right = PJ_IO_UNITS_CLASSIC;
    return P;
}

/* ---------------- ob_tran ---------------- */
struct ob_tran_data { PJ *link; double lamp, cphip, sphip; };
#define OT_TOL 1e-10
static void ob_tran_destructor(PJ *P, int e) {
    if (P && P->opaque) { struct ob_tran_data *Q = (struct ob_tran_data *)P->opaque; if (Q->link) pj_free(Q->link); }
    pj_default_destructor(P, e);
}
static PJ_XY ob_tran_o_forward(PJ_LP lp, PJ *P) {
    struct ob_tran_data *Q = (struct ob_tran_data *)P->opaque;
    double coslam, sinphi, cosphi;
    coslam = cos(lp.lam);
    sinphi = sin(lp.phi);
    cosphi = cos(lp.phi);
    lp.lam = adjlon(aatan2(cosphi * sin(lp.lam), Q->sphip * cosphi * coslam + Q->cphip * sinphi) + Q->lamp);
    lp.phi = aasin(Q->sphip * sinphi - Q->cphip * cosphi * coslam);
    return Q->link->fwd(lp, Q->link);
}
static PJ_XY ob_tran_t_forward(PJ_LP lp, PJ *P) {
    struct ob_tran_data *Q = (struct ob_tran_data *)P->opaque;
    double cosphi, coslam;
    cosphi = cos(lp.phi);
    coslam = cos(lp.lam);
    lp.lam = adjlon(aatan2(cosphi * sin(lp.lam), sin(lp.phi)) + Q->lamp);
    lp.phi = aasin(-cosphi * coslam);
    return Q->link->fwd(lp, Q->link);
}
static PJ_LP ob_tran_o_inverse(PJ_XY xy, PJ *P) {
    struct ob_tran_data *Q = (struct ob_tran_data *)P->opaque;
    double coslam, sinphi, cosphi;
    PJ_LP lp = Q->link->inv(xy, Q->link);
    if (lp.lam != HUGE_VAL) {
        coslam = cos(lp.lam -= Q->lamp);
        sinphi = sin(lp.phi);
        cosphi = cos(lp.phi);
        lp.phi = aasin(Q->sphip * sinphi + Q->cphip * cosphi * coslam);
        lp.lam = aatan2(cosphi * sin(lp.lam), Q->sphip * cosphi * coslam - Q->cphip * sinphi);
    }
    return lp;
}
static PJ_LP ob_tran_t_inverse(PJ_XY xy, PJ *P) {
    struct ob_tran_data *Q = (struct ob_tran_data *)P->opaque;
    double cosphi, t;
    PJ_LP lp = Q->link->inv(xy, Q->link);
    if (lp.lam != HUGE_VAL) {
        cosphi = cos(lp.phi);
        t = lp.lam - Q->lamp;
        lp.lam = aatan2(cosphi * sin(t), -sin(lp.phi));
        lp.phi = aasin(cosphi * cos(t));
    }
    return lp;
}
extern PJ *pj_create_from_tokens(char **tokens, int ntok, int append_break);
PJ *pj_ob_tran_setup(PJ *P) {
    double phip;
    const char *name;
    struct ob_tran_data *Q = (struct ob_tran_data *)calloc(1, sizeof(struct ob_tran_data));
    paralist *t;
    char *toks[512];
    int n = 0;
    P->opaque = Q;
    P->destructor = ob_tran_destructor;
    if (!(name = pj_param(P->params, "so_proj").s)) {
        proj_log_error(P, "Missing parameter: o_proj");
        return pj_default_destructor(P, PROJ_ERR_INVALID_OP_MISSING_ARG);
    }
    /* build the parameters of the target projection */
    for (t = P->params; t && n < 500; t = t->next) {
        if (!strncmp(t->param, "o_proj=", 7)) {
            char *s = (char *)malloc(strlen(t->param) + 2);
            strcpy(s, "proj=");
            strcat(s, t->param + 7);
            toks[n++] = s;
        } else if (!strncmp(t->param, "proj=", 5) || !strcmp(t->param, "inv") || !strcmp(t->param, "break_cs2cs_recursion")) {
            continue;
        } else {
            toks[n++] = pj_strdup(t->param);
        }
    }
    toks[n++] = pj_strdup("break_cs2cs_recursion");
    {
        int e = pj_ctx_errno;
        Q->link = pj_create_from_tokens(toks, n, 0);
        if (!Q->link) {
            int e2 = pj_ctx_errno;
            proj_log_error(P, "Failed to create sub-projection %s", name);
            return pj_default_destructor(P, e2 ? e2 : PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        pj_ctx_set_errno(e);
    }
    /* mark the sub projection's parameters as used in our list */
    for (t = P->params; t; t = t->next) {
        paralist *u = pj_get_param(Q->link->params, t->param);
        char key[256];
        const char *eq = strchr(t->param, '=');
        size_t kl = eq ? (size_t)(eq - t->param) : strlen(t->param);
        if (kl >= sizeof(key)) kl = sizeof(key) - 1;
        memcpy(key, t->param, kl);
        key[kl] = 0;
        u = pj_get_param(Q->link->params, key);
        if (u && u->used) t->used = 1;
    }
    if (pj_param(P->params, "to_alpha").i) {
        double lamc, phic, alpha;
        lamc = pj_param(P->params, "ro_lon_c").f;
        phic = pj_param(P->params, "ro_lat_c").f;
        alpha = pj_param(P->params, "ro_alpha").f;
        if (fabs(fabs(phic) - M_HALFPI) <= OT_TOL) {
            proj_log_error(P, "Invalid value for lat_c: |lat_c| should be < 90\xc2\xb0");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        Q->lamp = lamc + aatan2(-cos(alpha), -sin(alpha) * sin(phic));
        phip = aasin(cos(phic) * sin(alpha));
    } else if (pj_param(P->params, "to_lat_p").i) {
        Q->lamp = pj_param(P->params, "ro_lon_p").f;
        phip = pj_param(P->params, "ro_lat_p").f;
    } else {
        double lam1, lam2, phi1, phi2, con;
        lam1 = pj_param(P->params, "ro_lon_1").f;
        phi1 = pj_param(P->params, "ro_lat_1").f;
        lam2 = pj_param(P->params, "ro_lon_2").f;
        phi2 = pj_param(P->params, "ro_lat_2").f;
        con = fabs(phi1);
        if (fabs(phi1 - phi2) <= OT_TOL) {
            proj_log_error(P, "Invalid value for lat_1 and lat_2: lat_1 should be different from lat_2");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        if (con <= OT_TOL) {
            proj_log_error(P, "Invalid value for lat_1: it should be different from 0");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        if (fabs(con - M_HALFPI) <= OT_TOL) {
            proj_log_error(P, "Invalid value for lat_1: |lat_1| should be < 90\xc2\xb0");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        if (fabs(fabs(phi2) - M_HALFPI) <= OT_TOL) {
            proj_log_error(P, "Invalid value for lat_2: |lat_2| should be < 90\xc2\xb0");
            return pj_default_destructor(P, PROJ_ERR_INVALID_OP_ILLEGAL_ARG_VALUE);
        }
        Q->lamp = atan2(cos(phi1) * sin(phi2) * cos(lam1) - sin(phi1) * cos(phi2) * cos(lam2),
                        sin(phi1) * cos(phi2) * sin(lam2) - cos(phi1) * sin(phi2) * sin(lam1));
        phip = atan(-cos(Q->lamp - lam1) / tan(phi1));
    }
    if (fabs(phip) > OT_TOL) {
        Q->cphip = cos(phip);
        Q->sphip = sin(phip);
        P->fwd = Q->link->fwd ? ob_tran_o_forward : NULL;
        P->inv = Q->link->inv ? ob_tran_o_inverse : NULL;
    } else {
        P->fwd = Q->link->fwd ? ob_tran_t_forward : NULL;
        P->inv = Q->link->inv ? ob_tran_t_inverse : NULL;
    }
    if (Q->link->right == PJ_IO_UNITS_RADIANS) P->right = PJ_IO_UNITS_PROJECTED;
    return P;
}
