/* geographic CRS codes: must be projected */
static const int geographic_codes[] = {4326, 4258, 4269, 4267, 4230, 4277, 4283, 4149, 4150, 4171, 4167, 4674, 4275, 4314, 4312, 4322, 4324, 4979, 4978, 4936, 4937, 4617, 4618, 4745, 4746, 4759, 4807, 4809, 3819, 4176, 7844, 6318, 7912, 9000, 0};

static int utm_def(const char *auth, int code, char *buf, size_t n) {
    int zone;
    if (strcmp(auth, "EPSG")) return 0;
    if (code >= 32601 && code <= 32660) { zone = code - 32600; snprintf(buf, n, "proj=utm zone=%d ellps=WGS84", zone); return 1; }
    if (code >= 32701 && code <= 32760) { zone = code - 32700; snprintf(buf, n, "proj=utm zone=%d south ellps=WGS84", zone); return 1; }
    if (code >= 32201 && code <= 32260) { zone = code - 32200; snprintf(buf, n, "proj=utm zone=%d ellps=WGS72", zone); return 1; }
    if (code >= 32301 && code <= 32360) { zone = code - 32300; snprintf(buf, n, "proj=utm zone=%d south ellps=WGS72", zone); return 1; }
    if (code >= 25828 && code <= 25838) { zone = code - 25800; snprintf(buf, n, "proj=utm zone=%d ellps=GRS80", zone); return 1; }
    if (code >= 26901 && code <= 26923) { zone = code - 26900; snprintf(buf, n, "proj=utm zone=%d ellps=GRS80", zone); return 1; }
    if (code >= 26701 && code <= 26722) { zone = code - 26700; snprintf(buf, n, "proj=utm zone=%d ellps=clrk66", zone); return 1; }
    if (code >= 23028 && code <= 23038) { zone = code - 23000; snprintf(buf, n, "proj=utm zone=%d ellps=intl", zone); return 1; }
    if (code >= 28348 && code <= 28358) { zone = code - 28300; snprintf(buf, n, "proj=utm zone=%d south ellps=GRS80", zone); return 1; }
    if (code >= 7846 && code <= 7859) { zone = code - 7800; snprintf(buf, n, "proj=utm zone=%d south ellps=GRS80", zone); return 1; }
    if (code >= 2041 && code <= 2051) { zone = code - 2000; snprintf(buf, n, "proj=utm zone=%d ellps=GRS80", zone); return 1; }
    if (code >= 3154 && code <= 3160) { zone = code - 3147; snprintf(buf, n, "proj=utm zone=%d ellps=GRS80", zone); return 1; }
    return 0;
}

static int lookup(const char *auth, int code, char *buf, size_t n) {
    const CRS_ENTRY *e;
    for (e = crs_table; e->auth; ++e)
        if (!strcmp(e->auth, auth) && e->code == code) {
            snprintf(buf, n, "%s", e->def);
            return 1;
        }
    return utm_def(auth, code, buf, n);
}

PJ *pj_create_from_epsg(const char *s, const char **msg) {
    static char buf[1024];
    static char errbuf[512];
    char auth[32];
    const char *p = s, *colon;
    int code, i;
    char *tokens[128];
    int ntok = 0;
    char work[1024];
    char *tok;
    PJ *P;

    *msg = NULL;
    if (!strncmp(s, "urn:ogc:def:crs:", 16)) {
        /* urn:ogc:def:crs:EPSG::32632 */
        const char *q = s + 16;
        const char *c1 = strchr(q, ':');
        if (!c1) goto notfound;
        snprintf(auth, sizeof(auth), "%.*s", (int)(c1 - q), q);
        c1 = strrchr(q, ':');
        code = atoi(c1 + 1);
    } else {
        colon = strchr(p, ':');
        if (!colon) goto notfound;
        snprintf(auth, sizeof(auth), "%.*s", (int)(colon - p), p);
        for (i = 0; auth[i]; ++i) auth[i] = (char)toupper((unsigned char)auth[i]);
        code = atoi(colon + 1);
        {
            const char *e = colon + 1;
            while (isdigit((unsigned char)*e)) ++e;
            if (*e != '\0' && *e != '+') goto notfound;
        }
    }
    for (i = 0; geographic_codes[i]; ++i)
        if (!strcmp(auth, "EPSG") && geographic_codes[i] == code) {
            *msg = "CRS must be projected";
            return NULL;
        }
    if (!lookup(auth, code, buf, sizeof(buf))) goto notfound;
    strncpy(work, buf, sizeof(work) - 1);
    work[sizeof(work) - 1] = 0;
    tok = strtok(work, " ");
    while (tok && ntok < 128) {
        tokens[ntok++] = pj_strdup(tok);
        tok = strtok(NULL, " ");
    }
    pj_log_capture_begin();
    P = pj_create_from_tokens(tokens, ntok, 0);
    {
        const char *m = pj_log_capture_end();
        if (!P) {
            int e = pj_ctx_errno;
            if (m) snprintf(errbuf, sizeof(errbuf), "proj_create: Error %d (%s): %s", e, proj_errno_string(e), m);
            else snprintf(errbuf, sizeof(errbuf), "proj_create: Error %d (%s)", e, proj_errno_string(e));
            *msg = errbuf;
            return NULL;
        }
    }
    return P;
notfound:
    snprintf(errbuf, sizeof(errbuf), "proj_create: crs not found: %s", s);
    *msg = errbuf;
    return NULL;
}
EOF
