    double lat_c = -49.56371678*DEG_TO_RAD, lon_c = 66.94970198*DEG_TO_RAD, azi0 = 40.17823482*DEG_TO_RAD, rot = 45*DEG_TO_RAD;
    double lon = 12*DEG_TO_RAD, lat = 55*DEG_TO_RAD;
    int v; double offs[] = {0, M_HALFPI, -M_HALFPI, M_PI};
    for (v = 0; v < 1024; v++) {
        int use_conf = v & 1;
        double phi = use_conf ? conf(lat, e) : lat;
        double pc = use_conf ? conf(lat_c, e) : lat_c;
        double azi = azi0 + offs[(v >> 7) & 3];
        double sa = (v & 2) ? -sin(azi) : sin(azi), ca = cos(azi);
        double lamp, phip; PJ_LP lp, lpc; PJ_XY xy; double X, Y, r = (v & 4) ? -rot : rot;
        int sub = (v >> 9) & 1;
        lamp = lon_c + atan2(-ca, -sa * sin(pc));
        if (v & 8) lamp = lon_c + atan2(ca, sa*sin(pc));
        phip = asin(cos(pc) * sa);
        if (v & 32) phip = -phip;
        {
            double coslam = cos(lon), sinphi = sin(phi), cosphi = cos(phi);
            lp.lam = adjlon(atan2(cosphi*sin(lon), sin(phip)*cosphi*coslam + cos(phip)*sinphi) + ((v & 16) ? lamp : -lamp));
            lp.phi = asin(sin(phip)*sinphi - cos(phip)*cosphi*coslam);
            coslam = cos(lon_c); sinphi = sin(pc); cosphi = cos(pc);
            lpc.lam = adjlon(atan2(cosphi*sin(lon_c), sin(phip)*cosphi*coslam + cos(phip)*sinphi) + ((v & 16) ? lamp : -lamp));
            if (sub) lp.lam = adjlon(lp.lam - lpc.lam);
            if (v & 64) lp.lam = -lp.lam;
            if (v & 256) lp.phi = -lp.phi;
        }
        xy = A->fwd(lp, A);
        X = cos(r)*xy.x - sin(r)*xy.y; Y = sin(r)*xy.x + cos(r)*xy.y;
